	(42, '0001', 'am_web_001', '0100109106-998', 'DECLARATION', 9, '03122701605089CEB6A4AD4E0EAE8FA7424FD45B06', 'RECEIVED', 0, '', '2026-06-26 13:20:57', '2026-06-26 13:21:05'),
	(43, '0001', 'am_web_001', '0100109106-998', 'INVOICE', 66, '0312270160B9D0EC3A6598443DA26BB3132136EADF', 'RECEIVED', 0, '', '2026-08-19 11:25:33', '2026-08-19 11:25:41'),
	(44, '0001', 'am_web_001', '0100109106-998', 'INVOICE', 67, '0312270160E4A2E1FB74904D8486DA0989C44E235A', 'RECEIVED', 0, '', '2026-08-19 13:23:33', '2026-08-19 13:23:42'),
	(45, '0001', 'am_web_001', '0100109106-998', 'INVOICE', 68, '03122701606CE47B62186D4733A66104977456D380', 'RECEIVED', 0, '', '2026-08-19 13:24:17', '2026-08-19 13:24:20'),
	(46, '0001', 'am_web_001', '0100109106-998', 'INVOICE', 71, '031227016098D1D6A4E6BA4F48942372FB6D070CCA', 'RECEIVED', 0, '', '2026-09-03 14:38:11', '2026-09-03 14:38:18'),
	(47, '0001', 'am_web_001', '0100109106-998', 'PIT_DECLARATION', 1, '0312270160B4B2579E5EF540D9BFBA569FF038D652', 'RECEIVED', 0, '', '2026-09-15 17:55:11', '2026-09-15 17:55:18'),
	(48, '0001', 'am_web_001', '0100109106-998', 'PIT_DECLARATION', 1, '03122701609C07ADAF89564FFFB99E5D0063A7AF48', 'RECEIVED', 0, '1000 TKhai/DLTKhai/TTChung/PBan : Phiên bản không hợp lệ', '2026-09-16 07:39:17', '2026-09-16 07:39:27');
INSERT INTO `einvoice_template` (`TEMPLATE_ID`, `TEMPLATE_TYPE`, `TEMPLATE_CD`, `TEMPLATE_NM`, `SUBJECT`, `CONTENT`, `IS_ACTIVE`, `ISDEL`, `XSL_FTP_PATH`) VALUES
	(1, 'XSL', '01/ĐKTĐ-HĐĐT', '', NULL, '<?xml version="1.0" encoding="UTF-8"?>\r\n<xsl:stylesheet version="2.0"\r\n  xmlns:xsl="http://www.w3.org/1999/XSL/Transform"\r\n  xmlns:xs="http://www.w3.org/2001/XMLSchema"\r\n  xmlns:f="urn:amnote:einvoice:declaration"\r\n  exclude-result-prefixes="xs f">\r\n\r\n  <xsl:output method="html" encoding="UTF-8" indent="yes"/>\r\n\r\n  <xsl:function name="f:child" as="xs:string">\r\n    <xsl:param name="node" as="node()?"/>\r\n    <xsl:param name="name" as="xs:string"/>\r\n    <xsl:sequence select="normalize-space(string(($node/*[local-name() = $name])[1]))"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:any" as="xs:string">\r\n    <xsl:param name="node" as="node()?"/>\r\n    <xsl:param name="names" as="xs:string*"/>\r\n    <xsl:variable name="matches" select="$node/*[local-name() = $names]"/>\r\n    <xsl:sequence select="normalize-space(string(($matches[string-length(normalize-space(string(.))) &gt; 0][1], $matches[1])[1]))"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:flag" as="xs:boolean">\r\n    <xsl:param name="node" as="node()?"/>\r\n    <xsl:param name="name" as="xs:string"/>\r\n    <xsl:variable name="value" select="upper-case(f:child($node, $name))"/>\r\n    <xsl:sequence select="$value = (\'1\', \'TRUE\', \'Y\', \'YES\', \'X\')"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:any-flag" as="xs:boolean">\r\n    <xsl:param name="node" as="node()?"/>\r\n    <xsl:param name="names" as="xs:string*"/>\r\n    <xsl:sequence select="some $name in $names satisfies f:flag($node, $name)"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:box" as="xs:string">\r\n    <xsl:param name="selected" as="xs:boolean"/>\r\n    <xsl:sequence select="if ($selected) then \'☑\' else \'□\'"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\')">\r\n        <xsl:sequence select="concat(substring($text, 9, 2), \'/\', substring($text, 6, 2), \'/\', substring($text, 1, 4))"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date-part" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:param name="part" as="xs:string"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'day\'">\r\n        <xsl:sequence select="substring($text, 9, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'month\'">\r\n        <xsl:sequence select="substring($text, 6, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'year\'">\r\n        <xsl:sequence select="substring($text, 1, 4)"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="\'......\'"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:gender" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$text = \'1\'">\r\n        <xsl:sequence select="\'Nam\'"/>\r\n      </xsl:when>\r\n      <xsl:when test="$text = \'0\'">\r\n        <xsl:sequence select="\'Nữ\'"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:certificate-method" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$text = \'1\'">\r\n        <xsl:sequence select="\'Thêm mới\'"/>\r\n      </xsl:when>\r\n      <xsl:when test="$text = \'2\'">\r\n        <xsl:sequence select="\'Gia hạn\'"/>\r\n      </xsl:when>\r\n      <xsl:when test="$text = \'3\'">\r\n        <xsl:sequence select="\'Ngừng sử dụng\'"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:template match="/">\r\n    <xsl:variable name="root" select="/*[local-name() = \'TKhai\']"/>\r\n    <xsl:variable name="dl" select="$root/*[local-name() = \'DLTKhai\']"/>\r\n    <xsl:variable name="tt" select="$dl/*[local-name() = \'TTChung\']"/>\r\n    <xsl:variable name="nd" select="$dl/*[local-name() = \'NDTKhai\']"/>\r\n    <xsl:variable name="hthdon" select="$nd/*[local-name() = \'HTHDon\']"/>\r\n    <xsl:variable name="htgd" select="$nd/*[local-name() = \'HTGDLHDDT\']"/>\r\n    <xsl:variable name="pthuc" select="$nd/*[local-name() = \'PThuc\']"/>\r\n    <xsl:variable name="lhdsdung" select="$nd/*[local-name() = \'LHDSDung\']"/>\r\n    <xsl:variable name="ctsRows" select="$nd/*[local-name() = \'DSCTSSDung\']/*[local-name() = \'CTS\']"/>\r\n    <xsl:variable name="tcgpRows" select="$nd/*[local-name() = \'TTTCGP\']/*[local-name() = \'TCGP\']"/>\r\n    <xsl:variable name="tctnRows" select="$nd/*[local-name() = \'TTTCTN\']/*[local-name() = \'TCTN\']"/>\r\n    <xsl:variable name="delegateRows" select="$nd//*[local-name() = (\'UNhiem\', \'UQHDon\', \'DKUNhiem\')]"/>\r\n    <xsl:variable name="dependentRows" select="$nd//*[local-name() = (\'DVHToan\', \'DVPhuThuoc\', \'DonViHachToan\')]"/>\r\n    <xsl:variable name="pauseRows" select="$nd//*[local-name() = (\'TNgung\', \'TamNgung\', \'DNTNgung\')]"/>\r\n    <xsl:variable name="integrateRows" select="$nd//*[local-name() = (\'THop\', \'TichHop\', \'DKTHop\')]"/>\r\n    <xsl:variable name="hasNntSignature" select="exists($root/*[local-name() = \'DSCKS\']/*[local-name() = \'NNT\']/*[local-name() = \'Signature\']/*)"/>\r\n\r\n    <html>\r\n      <head>\r\n        <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>\r\n        <title>01/ĐKTĐ-HĐĐT</title>\r\n        <style>\r\n          @page {\r\n            size: A4 portrait;\r\n            margin: 0;\r\n          }\r\n\r\n          * {\r\n            box-sizing: border-box;\r\n          }\r\n\r\n          body {\r\n            margin: 0;\r\n            background: #f3f4f6;\r\n            color: #000;\r\n            font-family: "Times New Roman", Times, serif;\r\n            font-size: 12px;\r\n            line-height: 1.15;\r\n          }\r\n\r\n          .page {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            margin: 0 auto 14px;\r\n            padding: 14mm 15mm 16mm;\r\n            background: #fff;\r\n            page-break-after: always;\r\n          }\r\n\r\n          .page:last-child {\r\n            page-break-after: auto;\r\n          }\r\n\r\n          .national {\r\n            margin-top: 2mm;\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .national .line {\r\n            display: inline-block;\r\n            min-width: 150px;\r\n            border-top: 1px solid #000;\r\n            margin-top: 3px;\r\n          }\r\n\r\n          .title {\r\n            margin: 26px 0 12px;\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .title .main {\r\n            font-size: 14px;\r\n            text-transform: uppercase;\r\n          }\r\n\r\n          .form-option {\r\n            margin: 20px 0 26px;\r\n            text-align: center;\r\n          }\r\n\r\n          table {\r\n            width: 100%;\r\n            border-collapse: collapse;\r\n          }\r\n\r\n          td,\r\n          th {\r\n            border: 1px solid #000;\r\n            padding: 2px 4px;\r\n            vertical-align: middle;\r\n          }\r\n\r\n          th {\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .info-table td {\r\n            height: 21px;\r\n          }\r\n\r\n          .label {\r\n            width: 26%;\r\n          }\r\n\r\n          .right-label {\r\n            width: 24%;\r\n          }\r\n\r\n          .value {\r\n            min-height: 16px;\r\n          }\r\n\r\n          .intro {\r\n            padding: 6px 8px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .section-title {\r\n            border: 1px solid #000;\r\n            border-top: 0;\r\n            padding: 5px 6px;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .section-box {\r\n            border: 1px solid #000;\r\n            border-top: 0;\r\n            padding: 8px 8px 10px;\r\n          }\r\n\r\n          .checkbox-line {\r\n            margin: 2px 0;\r\n            padding-left: 32px;\r\n            text-indent: -16px;\r\n          }\r\n\r\n          .checkbox-block {\r\n            margin-top: 6px;\r\n          }\r\n\r\n          .small-text {\r\n            font-size: 11.5px;\r\n          }\r\n\r\n          .narrow-table th,\r\n          .narrow-table td {\r\n            padding: 3px 3px;\r\n            text-align: center;\r\n          }\r\n\r\n          .narrow-table td.text-left,\r\n          .narrow-table th.text-left {\r\n            text-align: left;\r\n          }\r\n\r\n          .section-heading-row td {\r\n            padding: 4px 6px;\r\n            font-weight: 700;\r\n            text-align: left;\r\n          }\r\n\r\n          .note {\r\n            margin-top: 18px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .signature {\r\n            margin-top: 30px;\r\n            text-align: center;\r\n          }\r\n\r\n          .signature .date-line {\r\n            font-style: italic;\r\n          }\r\n\r\n          .signature .name {\r\n            margin-top: 3px;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .signature .hint {\r\n            font-style: italic;\r\n          }\r\n\r\n          .signed {\r\n            margin-top: 8px;\r\n            font-style: italic;\r\n            font-weight: 700;\r\n          }\r\n\r\n          @media print {\r\n            body {\r\n              background: #fff;\r\n            }\r\n\r\n            .page {\r\n              margin: 0;\r\n              box-shadow: none;\r\n            }\r\n          }\r\n        </style>\r\n      </head>\r\n      <body>\r\n        <div class="page">\r\n          <div class="national">\r\n            CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM<br/>\r\n            Độc lập - Tự do - Hạnh phúc<br/>\r\n            <span class="line"></span>\r\n          </div>\r\n\r\n          <div class="title">\r\n            <div class="main">TỜ KHAI</div>\r\n            <div>\r\n              <xsl:value-of select="if (f:child($tt, \'Ten\') != \'\') then f:child($tt, \'Ten\') else \'Đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử\'"/>\r\n            </div>\r\n            <div>---------</div>\r\n          </div>\r\n\r\n          <div class="form-option">\r\n            <div><xsl:value-of select="f:box(f:child($tt, \'HThuc\') = \'1\')"/> Đăng ký mới</div>\r\n            <div><xsl:value-of select="f:box(f:child($tt, \'HThuc\') = \'2\')"/> Thay đổi thông tin</div>\r\n          </div>\r\n\r\n          <table class="info-table">\r\n            <tr>\r\n              <td class="label">Tên người nộp thuế:</td>\r\n              <td colspan="3" class="value"><xsl:value-of select="f:child($tt, \'TNNT\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Mã số thuế:</td>\r\n              <td colspan="3" class="value"><xsl:value-of select="f:child($tt, \'MST\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Cơ quan thuế quản lý:</td>\r\n              <td colspan="3" class="value"><xsl:value-of select="f:child($tt, \'CQTQLy\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Người liên hệ:<br/>(Đại diện theo pháp luật/Hộ, cá nhân kinh doanh)</td>\r\n              <td class="value"><xsl:value-of select="f:child($tt, \'TNDDPLuat\')"/></td>\r\n              <td class="right-label">Điện thoại liên hệ:<br/>(Đại diện theo pháp luật/Hộ, cá nhân kinh doanh)</td>\r\n              <td class="value"><xsl:value-of select="f:child($tt, \'DTDDPLuat\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Số CCCD/Số định danh/Hộ chiếu (*)...</td>\r\n              <td class="value">\r\n                <xsl:value-of select="if (f:child($tt, \'CCCDan\') != \'\') then f:child($tt, \'CCCDan\') else f:child($tt, \'SHChieu\')"/>\r\n              </td>\r\n              <td class="right-label">Ngày tháng năm sinh:</td>\r\n              <td class="value"><xsl:value-of select="f:date(f:child($tt, \'NSDDPLuat\'))"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Giới tính</td>\r\n              <td class="value"><xsl:value-of select="f:gender(f:child($tt, \'GTinh\'))"/></td>\r\n              <td class="right-label"></td>\r\n              <td class="value"></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Địa chỉ liên hệ của NNT</td>\r\n              <td class="value"><xsl:value-of select="f:child($tt, \'DCLHe\')"/></td>\r\n              <td class="right-label">Thư điện tử....<br/>của NNT</td>\r\n              <td class="value"><xsl:value-of select="f:child($tt, \'DCTDTu\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td colspan="4" class="intro">\r\n                Theo Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 của Chính phủ, chúng tôi/tôi thuộc đối tượng sử dụng hóa đơn điện tử. Chúng tôi/tôi đăng ký thay đổi thông tin đã đăng ký với cơ quan thuế về việc sử dụng hóa đơn điện tử như sau:\r\n              </td>\r\n            </tr>\r\n          </table>\r\n\r\n          <div class="section-title">1. Hình thức hóa đơn:</div>\r\n          <div class="section-box">\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($hthdon, \'CMa\'))"/> Có mã của cơ quan thuế</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($hthdon, \'CMTMTTien\'))"/> Hóa đơn khởi tạo từ Máy tính tiền</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($hthdon, \'KCMa\'))"/> Không có mã của cơ quan thuế</div>\r\n          </div>\r\n\r\n          <div class="section-title">2. Hình thức gửi dữ liệu hóa đơn điện tử:</div>\r\n          <div class="section-box small-text">\r\n            <p>\r\n              a. <xsl:value-of select="f:box(f:any-flag($htgd, (\'NNTDBKKhan\', \'NNTKTDNUBND\', \'CQXLTSCong\')))"/>\r\n              Trường hợp sử dụng hóa đơn điện tử có mã trên Cổng thông tin điện tử của Tổng cục Thuế hoặc tổ chức cung cấp dịch vụ hóa đơn điện tử được Tổng cục Thuế ủy thác\r\n            </p>\r\n            <div class="checkbox-block">\r\n              <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($htgd, \'NNTDBKKhan\'))"/> Doanh nghiệp nhỏ và vừa, hợp tác xã, hộ, cá nhân kinh doanh tại địa bàn có điều kiện kinh tế xã hội khó khăn, địa bàn có điều kiện kinh tế xã hội đặc biệt khó khăn.</div>\r\n              <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($htgd, \'NNTKTDNUBND\'))"/> Doanh nghiệp nhỏ và vừa khác theo đề nghị của Ủy ban nhân dân tỉnh, thành phố trực thuộc trung ương gửi Bộ Tài chính trừ doanh nghiệp hoạt động tại các khu kinh tế, khu công nghiệp, khu công nghệ cao.</div>\r\n              <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($htgd, \'CQXLTSCong\'))"/> Cơ quan thuế hoặc cơ quan được giao nhiệm vụ tổ chức, xử lý tài sản công theo quy định pháp luật về quản lý, sử dụng tài sản công.</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class="page">\r\n          <div class="section-box small-text" style="border-top: 1px solid #000;">\r\n            <p>\r\n              <b>b. <xsl:value-of select="f:box(f:any-flag($htgd, (\'CDLTTDCQT\', \'CDLQTCTN\', \'NCCNN\')))"/>\r\n              Trường hợp sử dụng hóa đơn điện tử không có mã của cơ quan thuế:</b>\r\n            </p>\r\n            <div class="checkbox-block">\r\n              <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($htgd, \'CDLTTDCQT\'))"/> Gửi trực tiếp đến cơ quan thuế (điểm b1, khoản 3, Điều 22 của Nghị định).</div>\r\n              <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($htgd, \'CDLQTCTN\'))"/> Gửi đến cơ quan thuế thông qua tổ chức cung cấp dịch vụ hóa đơn điện tử (điểm b2, khoản 3, Điều 22 Nghị định).</div>\r\n              <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($htgd, \'NCCNN\'))"/> Nhà cung cấp ở nước ngoài không có cơ sở thường trú tại Việt Nam hoạt động thương mại điện tử, kinh doanh trên nền tảng số và các dịch vụ khác tại Việt Nam.</div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="section-title">3. Phương thức chuyển dữ liệu hóa đơn điện tử:</div>\r\n          <div class="section-box">\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($pthuc, \'CDDu\'))"/> Chuyển đầy đủ nội dung từng hóa đơn</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($pthuc, \'CBTHop\'))"/> Chuyển dữ liệu hóa đơn điện tử theo Bảng tổng hợp dữ liệu hóa đơn điện tử theo Mẫu số 01/TH-HĐĐT.</div>\r\n          </div>\r\n\r\n          <div class="section-title">4. Loại hóa đơn sử dụng:</div>\r\n          <div class="section-box">\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'HDGTGT\'))"/> Hóa đơn GTGT</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'HDGTGTTHBLai\'))"/> Hóa đơn GTGT tích hợp biên lai thu thuế, phí, lệ phí</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'HDBHang\'))"/> Hóa đơn bán hàng</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'HDBHTHBLai\'))"/> Hóa đơn bán hàng tích hợp biên lai thu thuế, phí, lệ phí</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'HDTMai\'))"/> Hóa đơn thương mại</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:any-flag($lhdsdung, (\'HDNCCNN\', \'HDNCCNNKCTT\')))"/> Hóa đơn nhà cung cấp ở nước ngoài không có cơ sở thường trú tại Việt Nam</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'HDBTSCong\'))"/> Hóa đơn bán tài sản công</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'HDBHDTQGia\'))"/> Hóa đơn bán hàng dự trữ quốc gia</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'HDKhac\'))"/> Các loại hóa đơn khác</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhdsdung, \'CTu\'))"/> Các chứng từ được in, phát hành, sử dụng và quản lý như hóa đơn.</div>\r\n          </div>\r\n\r\n          <table class="narrow-table">\r\n            <tr class="section-heading-row">\r\n              <td colspan="6">5. Danh sách chứng thư số sử dụng:</td>\r\n            </tr>\r\n            <tr>\r\n              <th rowspan="2" style="width: 7%;">STT</th>\r\n              <th rowspan="2" style="width: 30%;">Tên tổ chức cơ quan chứng thực/cấp/công nhận chữ ký số, chữ ký điện tử</th>\r\n              <th rowspan="2" style="width: 16%;">Số sê-ri chứng thư</th>\r\n              <th colspan="2" style="width: 30%;">Thời hạn sử dụng chứng thư số</th>\r\n              <th rowspan="2" style="width: 17%;">Hình thức đăng ký<br/>(Thêm mới, gia hạn, ngừng sử dụng)</th>\r\n            </tr>\r\n            <tr>\r\n              <th>Từ ngày</th>\r\n              <th>Đến ngày</th>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$ctsRows">\r\n                <xsl:for-each select="$ctsRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:child(., \'STT\') != \'\') then f:child(., \'STT\') else position()"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:child(., \'TTChuc\')"/></td>\r\n                    <td><xsl:value-of select="f:child(., \'Seri\')"/></td>\r\n                    <td><xsl:value-of select="f:date(f:child(., \'TNgay\'))"/></td>\r\n                    <td><xsl:value-of select="f:date(f:child(., \'DNgay\'))"/></td>\r\n                    <td><xsl:value-of select="f:certificate-method(f:child(., \'HThuc\'))"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n\r\n          <table class="narrow-table">\r\n            <tr class="section-heading-row">\r\n              <td colspan="8">6. Đăng ký ủy nhiệm lập hóa đơn</td>\r\n            </tr>\r\n            <tr>\r\n              <th>STT</th>\r\n              <th>Tên loại hóa đơn ủy nhiệm</th>\r\n              <th>Ký hiệu mẫu hóa đơn</th>\r\n              <th>Ký hiệu hóa đơn ủy nhiệm</th>\r\n              <th>Tên tổ chức được/nhận ủy nhiệm</th>\r\n              <th>Mục đích ủy nhiệm</th>\r\n              <th>Thời hạn ủy nhiệm</th>\r\n              <th>Phương thức thanh toán hóa đơn ủy nhiệm</th>\r\n            </tr>\r\n            <tr>\r\n              <td>(1)</td><td>(2)</td><td>(3)</td><td>(4)</td><td>(5)</td><td>(6)</td><td>(7)</td><td>(8)</td>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$delegateRows">\r\n                <xsl:for-each select="$delegateRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:any(., (\'STT\')) != \'\') then f:any(., (\'STT\')) else position()"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:any(., (\'TLHDonUNhiem\', \'TenLHDonUNhiem\', \'TenLHDon\', \'TLHDon\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'KHMSHDon\', \'KHMSHDON\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'KHHDonUNhiem\', \'KHHDon\', \'KHHON\'))"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:any(., (\'TTChucUNhiem\', \'TTChuc\', \'TenTChuc\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'MDichUNhiem\', \'MDich\', \'MucDich\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'THanUNhiem\', \'THan\', \'ThoiHan\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'PThucTT\', \'PThucTToan\', \'PTTToan\'))"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n\r\n          <table class="narrow-table">\r\n            <tr class="section-heading-row">\r\n              <td colspan="6">7. Tổ chức cung cấp dịch vụ</td>\r\n            </tr>\r\n            <tr>\r\n              <th rowspan="2" style="width: 7%;">STT</th>\r\n              <th rowspan="2">Tên tổ chức cung cấp dịch vụ</th>\r\n              <th rowspan="2" style="width: 22%;">Mã số thuế</th>\r\n              <th colspan="2" style="width: 24%;">Thời hạn</th>\r\n              <th rowspan="2" style="width: 14%;">Ghi chú</th>\r\n            </tr>\r\n            <tr>\r\n              <th>Từ ngày</th>\r\n              <th>Đến ngày</th>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$tcgpRows">\r\n                <xsl:for-each select="$tcgpRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:child(., \'STT\') != \'\') then f:child(., \'STT\') else position()"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:child(., \'TTCGP\')"/></td>\r\n                    <td><xsl:value-of select="f:child(., \'MSTTCGP\')"/></td>\r\n                    <td><xsl:value-of select="f:date(f:child(., \'TNgay\'))"/></td>\r\n                    <td><xsl:value-of select="f:date(f:child(., \'DNgay\'))"/></td>\r\n                    <td><xsl:value-of select="f:child(., \'GChu\')"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n\r\n          <table class="narrow-table">\r\n            <tr class="section-heading-row">\r\n              <td colspan="6">8. Thông tin đơn vị truyền nhận</td>\r\n            </tr>\r\n            <tr>\r\n              <th rowspan="2" style="width: 7%;">STT</th>\r\n              <th rowspan="2">Tên đơn vị truyền nhận</th>\r\n              <th rowspan="2" style="width: 22%;">Mã số thuế</th>\r\n              <th colspan="2" style="width: 24%;">Thời hạn</th>\r\n              <th rowspan="2" style="width: 14%;">Ghi chú</th>\r\n            </tr>\r\n            <tr>\r\n              <th>Từ ngày</th>\r\n              <th>Đến ngày</th>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$tctnRows">\r\n                <xsl:for-each select="$tctnRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:child(., \'STT\') != \'\') then f:child(., \'STT\') else position()"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:child(., \'TTCTN\')"/></td>\r\n                    <td><xsl:value-of select="f:child(., \'MSTTCTN\')"/></td>\r\n                    <td><xsl:value-of select="f:date(f:child(., \'TNgay\'))"/></td>\r\n                    <td><xsl:value-of select="f:date(f:child(., \'DNgay\'))"/></td>\r\n                    <td><xsl:value-of select="f:child(., \'GChu\')"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n        </div>\r\n\r\n        <div class="page">\r\n          <table class="narrow-table">\r\n            <tr class="section-heading-row">\r\n              <td colspan="6">9. Thông tin đơn vị hạch toán phụ thuộc cần cấp quyền tra cứu hóa đơn</td>\r\n            </tr>\r\n            <tr>\r\n              <th rowspan="2" style="width: 7%;">STT</th>\r\n              <th rowspan="2">Tên đơn vị</th>\r\n              <th rowspan="2" style="width: 24%;">Mã số thuế</th>\r\n              <th colspan="2" style="width: 24%;">Thời hạn</th>\r\n              <th rowspan="2" style="width: 16%;">Ghi chú</th>\r\n            </tr>\r\n            <tr>\r\n              <th>Từ ngày</th>\r\n              <th>Đến ngày</th>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$dependentRows">\r\n                <xsl:for-each select="$dependentRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:any(., (\'STT\')) != \'\') then f:any(., (\'STT\')) else position()"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:any(., (\'TDonVi\', \'TenDonVi\', \'TDV\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'MST\', \'MSTDonVi\', \'MSTDV\'))"/></td>\r\n                    <td><xsl:value-of select="f:date(f:any(., (\'TNgay\', \'TuNgay\')))"/></td>\r\n                    <td><xsl:value-of select="f:date(f:any(., (\'DNgay\', \'DenNgay\')))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'GChu\', \'GhiChu\'))"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n\r\n          <div class="section-title">10. Đề nghị tạm ngừng sử dụng hóa đơn điện tử</div>\r\n          <div class="section-box">\r\n            Trong quá trình sử dụng hóa đơn điện tử, chúng tôi xin phép tạm ngừng sử dụng hóa đơn điện tử cụ thể như sau:\r\n          </div>\r\n          <table class="narrow-table">\r\n            <tr>\r\n              <th rowspan="2" style="width: 7%;">STT</th>\r\n              <th colspan="2" style="width: 25%;">Thời gian tạm ngừng sử dụng hóa đơn điện tử</th>\r\n              <th rowspan="2">Tổ chức cung cấp dịch vụ</th>\r\n              <th rowspan="2" style="width: 18%;">Số sê-ri chứng thư</th>\r\n              <th rowspan="2" style="width: 16%;">Ghi chú</th>\r\n            </tr>\r\n            <tr>\r\n              <th>Từ ngày</th>\r\n              <th>Đến ngày</th>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$pauseRows">\r\n                <xsl:for-each select="$pauseRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:any(., (\'STT\')) != \'\') then f:any(., (\'STT\')) else position()"/></td>\r\n                    <td><xsl:value-of select="f:date(f:any(., (\'TNgay\', \'TuNgay\')))"/></td>\r\n                    <td><xsl:value-of select="f:date(f:any(., (\'DNgay\', \'DenNgay\')))"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:any(., (\'TCCapDVu\', \'TTCGP\', \'TCTN\', \'TenTChuc\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'Seri\', \'SERI\', \'SoSeri\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'GChu\', \'GhiChu\'))"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n\r\n          <table class="narrow-table">\r\n            <tr class="section-heading-row">\r\n              <td colspan="8">11. Đăng ký tích hợp hóa đơn điện tử với chứng từ điện tử</td>\r\n            </tr>\r\n            <tr>\r\n              <th>STT</th>\r\n              <th>Tên loại hóa đơn tích hợp</th>\r\n              <th>Ký hiệu mẫu hóa đơn tích hợp</th>\r\n              <th>Ký hiệu hóa đơn tích hợp</th>\r\n              <th>Tên tổ chức được/nhận tích hợp hóa đơn</th>\r\n              <th>Mục đích tích hợp</th>\r\n              <th>Thời hạn tích hợp</th>\r\n              <th>Ghi chú</th>\r\n            </tr>\r\n            <tr>\r\n              <td>(1)</td><td>(2)</td><td>(3)</td><td>(4)</td><td>(5)</td><td>(6)</td><td>(7)</td><td>(8)</td>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$integrateRows">\r\n                <xsl:for-each select="$integrateRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:any(., (\'STT\')) != \'\') then f:any(., (\'STT\')) else position()"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:any(., (\'TLHDonTichHop\', \'TenLHDonTichHop\', \'TenLHDon\', \'TLHDon\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'KHMSHDon\', \'KHMSHDON\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'KHHDonTichHop\', \'KHHDon\'))"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:any(., (\'TTChucTichHop\', \'TTChuc\', \'TenTChuc\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'MDichTichHop\', \'MDich\', \'MucDich\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'THanTichHop\', \'THan\', \'ThoiHan\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'GChu\', \'GhiChu\'))"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n\r\n          <div class="note">\r\n            Chúng tôi cam kết hoàn toàn chịu trách nhiệm trước pháp luật về tính chính xác, trung thực của nội dung nêu trên và thực hiện theo đúng quy định của pháp luật.\r\n          </div>\r\n          <div class="note">\r\n            <i>Ghi chú:</i><br/>\r\n            (*) Đối với người đại diện là người Việt Nam điền thông tin Số CC/CCCD/số định danh. Việc sử dụng CC/CCCD/số định danh theo quy định pháp luật về căn cước.\r\n          </div>\r\n\r\n          <div class="signature">\r\n            <div class="date-line">\r\n              <xsl:value-of select="if (f:child($tt, \'DDanh\') != \'\') then f:child($tt, \'DDanh\') else \'......\'"/>,\r\n              ngày <xsl:value-of select="f:date-part(f:child($tt, \'NLap\'), \'day\')"/>\r\n              tháng <xsl:value-of select="f:date-part(f:child($tt, \'NLap\'), \'month\')"/>\r\n              năm <xsl:value-of select="f:date-part(f:child($tt, \'NLap\'), \'year\')"/>\r\n            </div>\r\n            <div class="name">NGƯỜI NỘP THUẾ hoặc<br/>ĐẠI DIỆN HỢP PHÁP CỦA NGƯỜI NỘP THUẾ</div>\r\n            <div class="hint">(Chữ ký số, chữ ký điện tử của người nộp thuế)</div>\r\n            <xsl:if test="$hasNntSignature">\r\n              <div class="signed">Đã ký điện tử</div>\r\n            </xsl:if>\r\n          </div>\r\n        </div>\r\n      </body>\r\n    </html>\r\n  </xsl:template>\r\n</xsl:stylesheet>\r\n', 1, 0, '/home/WEB/amnoteweb/ElectronicDocuments/shared/xsl/5d/8030d25fe0c146dab72340804c431724/5dac212af27564fffca78ddf22bde0e70640e0ed894e60fb72127619093318c5.xsl'),
	(2, 'XSL', '04/SS-HĐĐT', '', NULL, '<?xml version="1.0" encoding="utf-8"?>\r\n<xsl:stylesheet version="2.0"\r\n  xmlns:xsl="http://www.w3.org/1999/XSL/Transform"\r\n  xmlns:xs="http://www.w3.org/2001/XMLSchema"\r\n  exclude-result-prefixes="xs">\r\n\r\n  <xsl:output method="html" encoding="utf-8" indent="yes" omit-xml-declaration="yes"/>\r\n\r\n  <xsl:template match="/">\r\n    <xsl:variable name="root" select="/*[local-name() = \'TBao\']"/>\r\n    <xsl:variable name="tt" select="$root/*[local-name() = \'DLTBao\']/*[local-name() = \'TTChung\']"/>\r\n    <xsl:variable name="rows" select="$root/*[local-name() = \'DLTBao\']/*[local-name() = \'DSHDon\']/*[local-name() = \'HDon\']"/>\r\n\r\n    <html lang="vi">\r\n      <head>\r\n        <meta charset="utf-8"/>\r\n        <title>\r\n          <xsl:call-template name="valueOrDefault">\r\n            <xsl:with-param name="value" select="$tt/*[local-name() = \'Ten\']"/>\r\n            <xsl:with-param name="fallback" select="\'Thông báo hóa đơn điện tử đã lập sai\'"/>\r\n          </xsl:call-template>\r\n        </title>\r\n        <style>\r\n          @page {\r\n            size: A4 landscape;\r\n            margin: 0;\r\n          }\r\n\r\n          * {\r\n            box-sizing: border-box;\r\n          }\r\n\r\n          html,\r\n          body {\r\n            margin: 0;\r\n            padding: 0;\r\n            background: #e8e8e8;\r\n            color: #000;\r\n            font-family: "Times New Roman", Times, serif;\r\n            font-size: 13px;\r\n            line-height: 1.2;\r\n          }\r\n\r\n          .page {\r\n            width: 297mm;\r\n            min-height: 210mm;\r\n            margin: 0 auto;\r\n            padding: 10mm 12mm 8mm;\r\n            background: #fff;\r\n          }\r\n\r\n          .form-number {\r\n            text-align: right;\r\n            font-size: 14px;\r\n            font-weight: bold;\r\n          }\r\n\r\n          .national {\r\n            margin-top: 2mm;\r\n            text-align: center;\r\n            font-size: 14px;\r\n            font-weight: bold;\r\n            text-transform: uppercase;\r\n          }\r\n\r\n          .motto {\r\n            text-align: center;\r\n            font-size: 14px;\r\n            font-weight: bold;\r\n          }\r\n\r\n          .title {\r\n            margin-top: 4mm;\r\n            text-align: center;\r\n            font-size: 15px;\r\n            font-weight: bold;\r\n            text-transform: uppercase;\r\n          }\r\n\r\n          .recipient {\r\n            margin-top: 2mm;\r\n            text-align: center;\r\n            font-size: 14px;\r\n          }\r\n\r\n          .recipient .label {\r\n            font-style: italic;\r\n            font-weight: bold;\r\n          }\r\n\r\n          .info {\r\n            margin-top: 2mm;\r\n          }\r\n\r\n          .info-row {\r\n            display: grid;\r\n            grid-template-columns: auto 1fr;\r\n            align-items: end;\r\n            column-gap: 5px;\r\n            min-height: 20px;\r\n            font-size: 14px;\r\n          }\r\n\r\n          .info-value {\r\n            min-height: 20px;\r\n            border-bottom: 1px dotted #000;\r\n            padding: 0 4px 2px;\r\n          }\r\n\r\n          .intro {\r\n            margin-top: 3mm;\r\n            font-size: 14px;\r\n          }\r\n\r\n          table.notice-table {\r\n            width: 100%;\r\n            margin-top: 2mm;\r\n            border-collapse: collapse;\r\n            table-layout: fixed;\r\n            font-size: 13px;\r\n          }\r\n\r\n          .notice-table th,\r\n          .notice-table td {\r\n            border: 1px solid #000;\r\n            padding: 4px 3px;\r\n            vertical-align: middle;\r\n            word-wrap: break-word;\r\n          }\r\n\r\n          .notice-table th {\r\n            height: 16mm;\r\n            text-align: center;\r\n            font-weight: bold;\r\n          }\r\n\r\n          .notice-table td {\r\n            min-height: 8mm;\r\n          }\r\n\r\n          .notice-table .center {\r\n            text-align: center;\r\n          }\r\n\r\n          .notice-table .small {\r\n            font-size: 13px;\r\n          }\r\n\r\n          .col-stt { width: 7.5%; }\r\n          .col-mcqt { width: 10.5%; }\r\n          .col-khmshdon { width: 10.5%; }\r\n          .col-khhdon { width: 10.5%; }\r\n          .col-shdon { width: 9.5%; }\r\n          .col-ngay { width: 10.5%; }\r\n          .col-loai { width: 12.5%; }\r\n          .col-tbao { width: 14%; }\r\n          .col-ldo { width: 14.5%; }\r\n\r\n          .notes {\r\n            margin-top: 2mm;\r\n            font-size: 12px;\r\n          }\r\n\r\n          .notes-title {\r\n            font-weight: bold;\r\n            font-style: italic;\r\n            text-decoration: underline;\r\n          }\r\n\r\n          .note-line {\r\n            margin-top: 2mm;\r\n          }\r\n\r\n          .sign-date {\r\n            margin-top: 4mm;\r\n            margin-left: auto;\r\n            width: 40%;\r\n            text-align: center;\r\n            font-style: italic;\r\n          }\r\n\r\n          .signatures {\r\n            display: grid;\r\n            grid-template-columns: 1fr 1fr;\r\n            gap: 10mm;\r\n            margin-top: 2mm;\r\n            text-align: center;\r\n          }\r\n\r\n          .signature-title {\r\n            font-size: 15px;\r\n            font-weight: bold;\r\n            text-transform: uppercase;\r\n          }\r\n\r\n          .signature-subtitle {\r\n            font-size: 14px;\r\n            font-style: italic;\r\n          }\r\n\r\n          .signed-info {\r\n            margin-top: 6mm;\r\n            min-height: 14mm;\r\n            font-size: 13px;\r\n          }\r\n\r\n          @media print {\r\n            html,\r\n            body {\r\n              background: #fff;\r\n            }\r\n\r\n            .page {\r\n              margin: 0;\r\n              box-shadow: none;\r\n            }\r\n          }\r\n        </style>\r\n      </head>\r\n      <body>\r\n        <div class="page">\r\n          <div class="form-number">\r\n            Mẫu số:\r\n            <xsl:text> </xsl:text>\r\n            <xsl:call-template name="valueOrDefault">\r\n              <xsl:with-param name="value" select="$tt/*[local-name() = \'MSo\']"/>\r\n              <xsl:with-param name="fallback" select="\'04/SS-HĐĐT\'"/>\r\n            </xsl:call-template>\r\n          </div>\r\n\r\n          <div class="national">CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</div>\r\n          <div class="motto">Độc lập - Tự do - Hạnh phúc</div>\r\n\r\n          <div class="title">\r\n            <xsl:call-template name="valueOrDefault">\r\n              <xsl:with-param name="value" select="$tt/*[local-name() = \'Ten\']"/>\r\n              <xsl:with-param name="fallback" select="\'THÔNG BÁO HÓA ĐƠN ĐIỆN TỬ ĐÃ LẬP SAI\'"/>\r\n            </xsl:call-template>\r\n          </div>\r\n\r\n          <div class="recipient">\r\n            <span class="label">Kính gửi:</span>\r\n            <xsl:text> (</xsl:text>\r\n            <xsl:call-template name="valueOrDefault">\r\n              <xsl:with-param name="value" select="$tt/*[local-name() = \'TCQT\']"/>\r\n              <xsl:with-param name="fallback" select="\'Cơ quan thuế\'"/>\r\n            </xsl:call-template>\r\n            <xsl:text>)</xsl:text>\r\n          </div>\r\n\r\n          <div class="info">\r\n            <div class="info-row">\r\n              <div>Tên người nộp thuế:</div>\r\n              <div class="info-value">\r\n                <xsl:value-of select="$tt/*[local-name() = \'TNNT\']"/>\r\n              </div>\r\n            </div>\r\n            <div class="info-row">\r\n              <div>Mã số thuế:</div>\r\n              <div class="info-value">\r\n                <xsl:value-of select="$tt/*[local-name() = \'MST\']"/>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="intro">\r\n            Người nộp thuế thông báo về việc hóa đơn điện tử đã lập sai như sau:\r\n          </div>\r\n\r\n          <table class="notice-table">\r\n            <colgroup>\r\n              <col class="col-stt"/>\r\n              <col class="col-mcqt"/>\r\n              <col class="col-khmshdon"/>\r\n              <col class="col-khhdon"/>\r\n              <col class="col-shdon"/>\r\n              <col class="col-ngay"/>\r\n              <col class="col-loai"/>\r\n              <col class="col-tbao"/>\r\n              <col class="col-ldo"/>\r\n            </colgroup>\r\n            <thead>\r\n              <tr>\r\n                <th>STT</th>\r\n                <th>Mã CQT cấp</th>\r\n                <th>Ký hiệu mẫu hóa đơn</th>\r\n                <th>Ký hiệu hóa đơn</th>\r\n                <th>Số hóa đơn điện tử</th>\r\n                <th>Ngày lập hóa đơn</th>\r\n                <th>Loại hóa đơn điện tử</th>\r\n                <th>Thông báo/ Giải trình</th>\r\n                <th>Lý do/Thông báo của CQT</th>\r\n              </tr>\r\n              <tr class="small">\r\n                <td class="center">(1)</td>\r\n                <td class="center">(2)</td>\r\n                <td class="center">(3)</td>\r\n                <td class="center">(4)</td>\r\n                <td class="center">(5)</td>\r\n                <td class="center">(6)</td>\r\n                <td class="center">(7)</td>\r\n                <td class="center">(8)</td>\r\n                <td class="center">(9)</td>\r\n              </tr>\r\n            </thead>\r\n            <tbody>\r\n              <xsl:choose>\r\n                <xsl:when test="$rows">\r\n                  <xsl:for-each select="$rows">\r\n                    <tr>\r\n                      <td class="center">\r\n                        <xsl:choose>\r\n                          <xsl:when test="normalize-space(*[local-name() = \'STT\']) != \'\'">\r\n                            <xsl:value-of select="*[local-name() = \'STT\']"/>\r\n                          </xsl:when>\r\n                          <xsl:otherwise>\r\n                            <xsl:value-of select="position()"/>\r\n                          </xsl:otherwise>\r\n                        </xsl:choose>\r\n                      </td>\r\n                      <td><xsl:value-of select="*[local-name() = \'MCCQT\']"/></td>\r\n                      <td class="center"><xsl:value-of select="*[local-name() = \'KHMSHDon\']"/></td>\r\n                      <td class="center"><xsl:value-of select="*[local-name() = \'KHHDon\']"/></td>\r\n                      <td class="center"><xsl:value-of select="*[local-name() = \'SHDon\']"/></td>\r\n                      <td class="center">\r\n                        <xsl:call-template name="formatDate">\r\n                          <xsl:with-param name="date" select="*[local-name() = \'Ngay\']"/>\r\n                        </xsl:call-template>\r\n                      </td>\r\n                      <td>\r\n                        <xsl:call-template name="invoiceTypeText">\r\n                          <xsl:with-param name="value" select="*[local-name() = \'LADHDDT\']"/>\r\n                        </xsl:call-template>\r\n                      </td>\r\n                      <td class="center">\r\n                        <xsl:call-template name="noticeTypeText">\r\n                          <xsl:with-param name="value" select="$tt/*[local-name() = \'Loai\']"/>\r\n                        </xsl:call-template>\r\n                      </td>\r\n                      <td><xsl:value-of select="*[local-name() = \'LDo\']"/></td>\r\n                    </tr>\r\n                  </xsl:for-each>\r\n                </xsl:when>\r\n                <xsl:otherwise>\r\n                  <tr>\r\n                    <td class="center">&#160;</td>\r\n                    <td>&#160;</td>\r\n                    <td>&#160;</td>\r\n                    <td>&#160;</td>\r\n                    <td>&#160;</td>\r\n                    <td>&#160;</td>\r\n                    <td>&#160;</td>\r\n                    <td>&#160;</td>\r\n                    <td>&#160;</td>\r\n                  </tr>\r\n                </xsl:otherwise>\r\n              </xsl:choose>\r\n            </tbody>\r\n          </table>\r\n\r\n          <div class="notes">\r\n            <div class="notes-title">Ghi chú:</div>\r\n            <div class="note-line">\r\n              (2). Mã CQT cấp đối với hóa đơn có mã của CQT, hóa đơn không có mã của CQT để trống.\r\n            </div>\r\n            <div class="note-line">\r\n              (8) Trường hợp HĐĐT đã lập sai và người bán thực hiện Thông báo.\r\n            </div>\r\n            <div class="note-line">\r\n              Trường hợp CQT thông báo NNT giải trình.\r\n            </div>\r\n          </div>\r\n\r\n          <div class="sign-date">\r\n            <xsl:call-template name="valueOrDefault">\r\n              <xsl:with-param name="value" select="$tt/*[local-name() = \'DDanh\']"/>\r\n              <xsl:with-param name="fallback" select="\'.........\'"/>\r\n            </xsl:call-template>\r\n            <xsl:text>, ngày </xsl:text>\r\n            <xsl:call-template name="datePart">\r\n              <xsl:with-param name="date" select="$tt/*[local-name() = \'NTBao\']"/>\r\n              <xsl:with-param name="part" select="\'day\'"/>\r\n            </xsl:call-template>\r\n            <xsl:text> tháng </xsl:text>\r\n            <xsl:call-template name="datePart">\r\n              <xsl:with-param name="date" select="$tt/*[local-name() = \'NTBao\']"/>\r\n              <xsl:with-param name="part" select="\'month\'"/>\r\n            </xsl:call-template>\r\n            <xsl:text> năm </xsl:text>\r\n            <xsl:call-template name="datePart">\r\n              <xsl:with-param name="date" select="$tt/*[local-name() = \'NTBao\']"/>\r\n              <xsl:with-param name="part" select="\'year\'"/>\r\n            </xsl:call-template>\r\n          </div>\r\n\r\n          <div class="signatures">\r\n            <div>\r\n              <div class="signature-title">NGƯỜI MUA</div>\r\n              <div class="signature-subtitle">(Chữ ký số của người mua nếu có)</div>\r\n              <xsl:if test="$root/*[local-name() = \'DSCKS\']/*[local-name() = \'NMua\']/*[local-name() = \'Signature\']">\r\n                <div class="signed-info">Đã ký điện tử</div>\r\n              </xsl:if>\r\n            </div>\r\n            <div>\r\n              <div class="signature-title">NGƯỜI NỘP THUẾ hoặc</div>\r\n              <div class="signature-title">ĐẠI DIỆN HỢP PHÁP CỦA NGƯỜI NỘP THUẾ</div>\r\n              <div class="signature-subtitle">(Chữ ký số, chữ ký điện tử của người nộp thuế)</div>\r\n              <xsl:if test="$root/*[local-name() = \'DSCKS\']/*[local-name() = \'NNT\']/*[local-name() = \'Signature\']">\r\n                <div class="signed-info">\r\n                  <div>Đã ký điện tử</div>\r\n                  <div>\r\n                    <xsl:value-of select="$tt/*[local-name() = \'TNNT\']"/>\r\n                  </div>\r\n                </div>\r\n              </xsl:if>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </body>\r\n    </html>\r\n  </xsl:template>\r\n\r\n  <xsl:template name="valueOrDefault">\r\n    <xsl:param name="value"/>\r\n    <xsl:param name="fallback" select="\'\'"/>\r\n    <xsl:variable name="text" select="normalize-space(string(($value)[1]))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$text != \'\'">\r\n        <xsl:value-of select="$text"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:value-of select="$fallback"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:template>\r\n\r\n  <xsl:template name="formatDate">\r\n    <xsl:param name="date"/>\r\n    <xsl:variable name="text" select="normalize-space(string(($date)[1]))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="string-length($text) &gt;= 10">\r\n        <xsl:value-of select="concat(substring($text, 9, 2), \'/\', substring($text, 6, 2), \'/\', substring($text, 1, 4))"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:value-of select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:template>\r\n\r\n  <xsl:template name="datePart">\r\n    <xsl:param name="date"/>\r\n    <xsl:param name="part"/>\r\n    <xsl:variable name="text" select="normalize-space(string(($date)[1]))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="string-length($text) &gt;= 10 and $part = \'day\'">\r\n        <xsl:value-of select="substring($text, 9, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="string-length($text) &gt;= 10 and $part = \'month\'">\r\n        <xsl:value-of select="substring($text, 6, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="string-length($text) &gt;= 10 and $part = \'year\'">\r\n        <xsl:value-of select="substring($text, 1, 4)"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>.....</xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:template>\r\n\r\n  <xsl:template name="noticeTypeText">\r\n    <xsl:param name="value"/>\r\n    <xsl:variable name="text" select="normalize-space(string(($value)[1]))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$text = \'2\'">Giải trình</xsl:when>\r\n      <xsl:otherwise>Thông báo</xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:template>\r\n\r\n  <xsl:template name="invoiceTypeText">\r\n    <xsl:param name="value"/>\r\n    <xsl:variable name="text" select="normalize-space(string(($value)[1]))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$text = \'1\'">Hóa đơn GTGT</xsl:when>\r\n      <xsl:when test="$text = \'2\'">Hóa đơn bán hàng</xsl:when>\r\n      <xsl:when test="$text = \'3\'">Hóa đơn bán tài sản công</xsl:when>\r\n      <xsl:when test="$text = \'4\'">Hóa đơn bán hàng dự trữ quốc gia</xsl:when>\r\n      <xsl:when test="$text = \'5\'">Hóa đơn khác</xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:value-of select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:template>\r\n</xsl:stylesheet>\r\n', 1, 0, '/home/WEB/amnoteweb/ElectronicDocuments/shared/xsl/01/fcddc99af36c4327a875c07f69c18c43/01894f06854c4f499de430899166f837ed34e6a0ab13bc7e116f92fd0a9c00f3.xsl'),
	(3, 'XSL', '01/TB-TNĐT', '', NULL, '<?xml version="1.0" encoding="UTF-8"?>\r\n<xsl:stylesheet version="2.0"\r\n  xmlns:xsl="http://www.w3.org/1999/XSL/Transform"\r\n  xmlns:xs="http://www.w3.org/2001/XMLSchema"\r\n  xmlns:f="urn:amnote:einvoice:receive-notice"\r\n  exclude-result-prefixes="xs f">\r\n\r\n  <xsl:output method="html" encoding="UTF-8" indent="yes"/>\r\n\r\n  <xsl:function name="f:first-desc" as="xs:string">\r\n    <xsl:param name="nodes" as="node()*"/>\r\n    <xsl:param name="names" as="xs:string*"/>\r\n    <xsl:variable name="matches" select="$nodes/descendant-or-self::*[local-name() = $names]"/>\r\n    <xsl:sequence select="normalize-space(string(($matches[string-length(normalize-space(string(.))) &gt; 0][1], $matches[1])[1]))"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:child" as="xs:string">\r\n    <xsl:param name="node" as="node()?"/>\r\n    <xsl:param name="names" as="xs:string*"/>\r\n    <xsl:variable name="matches" select="$node/*[local-name() = $names]"/>\r\n    <xsl:sequence select="normalize-space(string(($matches[string-length(normalize-space(string(.))) &gt; 0][1], $matches[1])[1]))"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\')">\r\n        <xsl:sequence select="concat(substring($text, 9, 2), \'/\', substring($text, 6, 2), \'/\', substring($text, 1, 4))"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date-part" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:param name="part" as="xs:string"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'day\'">\r\n        <xsl:sequence select="substring($text, 9, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'month\'">\r\n        <xsl:sequence select="substring($text, 6, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'year\'">\r\n        <xsl:sequence select="substring($text, 1, 4)"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="\'.....\'"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:case-text" as="xs:string">\r\n    <xsl:param name="thop" as="xs:string"/>\r\n    <xsl:param name="case" as="xs:string"/>\r\n    <xsl:param name="value" as="xs:string"/>\r\n    <xsl:sequence select="if ($thop = \'\' or $thop = $case) then $value else \'\'"/>\r\n  </xsl:function>\r\n\r\n  <xsl:template name="field">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:param name="width" as="xs:string" select="\'220px\'"/>\r\n    <span class="fill" style="min-width: {$width};">\r\n      <xsl:value-of select="normalize-space(string($value))"/>\r\n    </span>\r\n  </xsl:template>\r\n\r\n  <xsl:template name="line-field">\r\n    <xsl:param name="label" as="xs:string"/>\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <div class="field-line">\r\n      - <xsl:value-of select="$label"/>:\r\n      <xsl:call-template name="field">\r\n        <xsl:with-param name="value" select="$value"/>\r\n        <xsl:with-param name="width" select="\'360px\'"/>\r\n      </xsl:call-template>\r\n    </div>\r\n  </xsl:template>\r\n\r\n  <xsl:template name="case-block">\r\n    <xsl:param name="caseNo" as="xs:string"/>\r\n    <xsl:param name="title" as="xs:string"/>\r\n    <xsl:param name="body" as="node()*"/>\r\n    <div class="case-title">\r\n      &lt;Trường hợp <xsl:value-of select="$caseNo"/>: <xsl:value-of select="$title"/>&gt;\r\n    </div>\r\n    <div class="para">\r\n      <xsl:copy-of select="$body"/>\r\n    </div>\r\n  </xsl:template>\r\n\r\n  <xsl:template match="/">\r\n    <xsl:variable name="root" select="/*[local-name() = (\'TBao\', \'DLTBao\')]"/>\r\n    <xsl:variable name="dl" select="if (local-name($root) = \'TBao\') then $root/*[local-name() = \'DLTBao\'] else $root"/>\r\n    <xsl:variable name="tt" select="$dl/*[local-name() = \'TTChung\']"/>\r\n    <xsl:variable name="nd" select="$dl/*[local-name() = (\'NDTBao\', \'NDTB\', \'NDBao\')]"/>\r\n    <xsl:variable name="scope" select="($dl, $tt, $nd)"/>\r\n    <xsl:variable name="reasonFields" select="$dl//*[local-name() = \'LDo\']//*[local-name() = (\'MLoi\', \'MTa\', \'MTLoi\', \'HDXLy\')]"/>\r\n    <xsl:variable name="reasonTexts" as="xs:string*" select="for $item in $reasonFields return normalize-space(string($item))"/>\r\n    <xsl:variable name="plainReasons" as="xs:string*" select="for $item in $dl//*[local-name() = \'LDo\'][not(*)] return normalize-space(string($item))"/>\r\n\r\n    <xsl:variable name="formCodeRaw" select="f:first-desc($tt, (\'MSo\', \'MSO\'))"/>\r\n    <xsl:variable name="formCode" select="if ($formCodeRaw != \'\') then $formCodeRaw else \'01/TB-TNĐT\'"/>\r\n    <xsl:variable name="noticeNo" select="f:first-desc($tt, (\'So\', \'STBao\', \'SoTBao\', \'SBTBao\'))"/>\r\n    <xsl:variable name="place" select="f:first-desc($tt, (\'DDanh\', \'DDBao\', \'DiaDanh\'))"/>\r\n    <xsl:variable name="noticeDate" select="f:first-desc($tt, (\'NTBao\', \'NTB\', \'NLap\', \'NgayTBao\'))"/>\r\n    <xsl:variable name="taxParent" select="f:first-desc($tt, (\'TCQTCTren\', \'TCQTCapTren\', \'CQTCapTren\'))"/>\r\n    <xsl:variable name="taxAuthority" select="f:first-desc($scope, (\'TCQT\', \'TCTBao\', \'CQT\', \'CQTQLy\', \'TCCQT\'))"/>\r\n    <xsl:variable name="taxAuthorityCode" select="f:first-desc($scope, (\'MCQT\', \'MCQTQLy\', \'MCQTQLY\'))"/>\r\n    <xsl:variable name="taxpayerName" select="f:first-desc($scope, (\'TNNT\', \'TNNNT\', \'TenNNT\'))"/>\r\n    <xsl:variable name="taxCode" select="f:first-desc($scope, (\'MST\', \'MSTNNT\'))"/>\r\n    <xsl:variable name="thop" select="f:first-desc($scope, (\'THop\', \'THTBao\', \'THopTBao\'))"/>\r\n    <xsl:variable name="declarationNameRaw" select="f:first-desc($nd, (\'TenTKhai\', \'TTKhai\', \'TenToKhai\', \'TTenTKhai\'))"/>\r\n    <xsl:variable name="declarationName" select="if ($declarationNameRaw != \'\') then $declarationNameRaw else \'Tờ khai đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử\'"/>\r\n    <xsl:variable name="transactionCodeFromAttribute" select="normalize-space(string(($dl/@Id, $dl/@id)[1]))"/>\r\n    <xsl:variable name="transactionCode" select="if (f:first-desc($scope, (\'MGDDTu\', \'MGDichDTu\', \'MGiaoDichDTu\', \'MTDiep\', \'MTDTChieu\')) != \'\') then f:first-desc($scope, (\'MGDDTu\', \'MGDichDTu\', \'MGiaoDichDTu\', \'MTDiep\', \'MTDTChieu\')) else $transactionCodeFromAttribute"/>\r\n    <xsl:variable name="sentDate" select="f:first-desc($scope, (\'NTNhan\', \'NNhan\', \'NTGui\', \'NGui\', \'NLapTKhai\', \'NLap\'))"/>\r\n    <xsl:variable name="reason" select="string-join(($reasonTexts[string-length(.) &gt; 0], $plainReasons[string-length(.) &gt; 0]), \'; \')"/>\r\n    <xsl:variable name="processContactRaw" select="f:first-desc($scope, (\'DMXLy\', \'DauMoiXLy\', \'DMLHe\', \'DauMoiLienHe\'))"/>\r\n    <xsl:variable name="processContact" select="if ($processContactRaw != \'\') then $processContactRaw else f:first-desc($dl//*[local-name() = \'LDo\'], (\'HDXLy\'))"/>\r\n    <xsl:variable name="hasTaxSignature" select="exists($root//*[local-name() = \'Signature\']/*)"/>\r\n    <xsl:variable name="documentKind" select="if (contains(lower-case($declarationName), \'chứng từ\')) then \'chứng từ điện tử\' else \'hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế\'"/>\r\n\r\n    <html>\r\n      <head>\r\n        <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>\r\n        <title>01/TB-TNĐT</title>\r\n        <style>\r\n          @page {\r\n            size: A4 portrait;\r\n            margin: 0;\r\n          }\r\n\r\n          * {\r\n            box-sizing: border-box;\r\n          }\r\n\r\n          body {\r\n            margin: 0;\r\n            background: #f3f4f6;\r\n            color: #000;\r\n            font-family: "Times New Roman", Times, serif;\r\n            font-size: 14px;\r\n            line-height: 1.18;\r\n          }\r\n\r\n          .page {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            margin: 0 auto 14px;\r\n            padding: 14mm 16mm 16mm;\r\n            background: #fff;\r\n            page-break-after: always;\r\n          }\r\n\r\n          .page:last-child {\r\n            page-break-after: auto;\r\n          }\r\n\r\n          .form-code {\r\n            text-align: right;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .header {\r\n            display: grid;\r\n            grid-template-columns: 33% 67%;\r\n            gap: 8px;\r\n            margin-top: 6px;\r\n          }\r\n\r\n          .tax-head,\r\n          .national {\r\n            text-align: center;\r\n          }\r\n\r\n          .tax-head .strong,\r\n          .national .strong {\r\n            font-weight: 700;\r\n          }\r\n\r\n          .short-line {\r\n            display: inline-block;\r\n            min-width: 84px;\r\n            border-top: 1px solid #000;\r\n            margin-top: 3px;\r\n          }\r\n\r\n          .doc-row {\r\n            display: grid;\r\n            grid-template-columns: 1fr 1fr;\r\n            margin-top: 28px;\r\n          }\r\n\r\n          .date {\r\n            text-align: right;\r\n            font-style: italic;\r\n          }\r\n\r\n          .title {\r\n            margin-top: 8px;\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .title .main {\r\n            font-size: 16px;\r\n          }\r\n\r\n          .title .subject {\r\n            max-width: 540px;\r\n            margin: 0 auto;\r\n          }\r\n\r\n          .greeting {\r\n            margin-top: 10px;\r\n            text-align: center;\r\n          }\r\n\r\n          .greeting .name {\r\n            margin-top: 3px;\r\n            font-style: italic;\r\n          }\r\n\r\n          .case-title {\r\n            margin-top: 24px;\r\n            font-style: italic;\r\n          }\r\n\r\n          .para {\r\n            margin-top: 7px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .field-line {\r\n            margin: 7px 0;\r\n          }\r\n\r\n          .fill {\r\n            display: inline-block;\r\n            min-height: 16px;\r\n            border-bottom: 1px dotted #000;\r\n            vertical-align: baseline;\r\n          }\r\n\r\n          .small-fill {\r\n            min-width: 70px;\r\n          }\r\n\r\n          .page-continued {\r\n            padding-top: 14mm;\r\n          }\r\n\r\n          .tail {\r\n            margin-top: 24px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .signature {\r\n            margin-top: 22px;\r\n            text-align: right;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .signed {\r\n            margin-top: 8px;\r\n            font-style: italic;\r\n          }\r\n\r\n          .note {\r\n            margin-top: 24px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .note-title {\r\n            font-weight: 700;\r\n            font-style: italic;\r\n            text-decoration: underline;\r\n          }\r\n\r\n          @media print {\r\n            body {\r\n              background: #fff;\r\n            }\r\n\r\n            .page {\r\n              margin: 0;\r\n            }\r\n          }\r\n        </style>\r\n      </head>\r\n      <body>\r\n        <div class="page">\r\n          <div class="form-code">Mẫu số: <xsl:value-of select="$formCode"/></div>\r\n\r\n          <div class="header">\r\n            <div class="tax-head">\r\n              <div>\r\n                <xsl:value-of select="if ($taxParent != \'\') then $taxParent else \'TÊN CƠ QUAN THUẾ CẤP TRÊN\'"/>\r\n              </div>\r\n              <div class="strong">\r\n                <xsl:value-of select="if ($taxAuthority != \'\') then $taxAuthority else \'TÊN CƠ QUAN BAN HÀNH VĂN BẢN\'"/>\r\n              </div>\r\n              <div><span class="short-line"></span></div>\r\n            </div>\r\n            <div class="national">\r\n              <div class="strong">CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</div>\r\n              <div class="strong">Độc lập - Tự do - Hạnh phúc</div>\r\n              <div><span class="short-line"></span></div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="doc-row">\r\n            <div>Số: <xsl:value-of select="if ($noticeNo != \'\') then $noticeNo else \'.....\'"/>/TB-HĐCĐT</div>\r\n            <div class="date">\r\n              <xsl:value-of select="if ($place != \'\') then $place else \'......\'"/>,\r\n              ngày <span class="small-fill"><xsl:value-of select="f:date-part($noticeDate, \'day\')"/></span>\r\n              tháng <span class="small-fill"><xsl:value-of select="f:date-part($noticeDate, \'month\')"/></span>\r\n              năm <span class="small-fill"><xsl:value-of select="f:date-part($noticeDate, \'year\')"/></span>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="title">\r\n            <div class="main">THÔNG BÁO</div>\r\n            <div class="subject">Về việc tiếp nhận/không tiếp nhận &lt;tờ khai đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử/chứng từ điện tử&gt;</div>\r\n          </div>\r\n\r\n          <div class="greeting">\r\n            <div>Kính gửi:</div>\r\n            <div class="name">&lt;<xsl:value-of select="if ($taxpayerName != \'\') then $taxpayerName else \'Tên người nộp thuế\'"/>: ...&gt;</div>\r\n            <div class="name">&lt;<xsl:value-of select="if ($taxCode != \'\') then concat(\'Mã số thuế của NNT: \', $taxCode) else \'Mã số thuế của NNT...\'"/>&gt;</div>\r\n          </div>\r\n\r\n          <xsl:call-template name="case-block">\r\n            <xsl:with-param name="caseNo" select="\'1\'"/>\r\n            <xsl:with-param name="title" select="\'Trường hợp tiếp nhận Tờ khai đăng ký sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử\'"/>\r\n            <xsl:with-param name="body">\r\n              <div>\r\n                Căn cứ &lt;Tờ khai đăng ký sử dụng <xsl:value-of select="$documentKind"/>&gt; - Mẫu số 01 - Ban hành kèm theo Nghị định số ...NĐ-CP&gt; của người nộp thuế (NNT) gửi tới cơ quan thuế lúc\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:date($sentDate)"/>\r\n                  <xsl:with-param name="width" select="\'120px\'"/>\r\n                </xsl:call-template>,\r\n                cơ quan thuế tiếp nhận &lt;Tờ khai Mẫu số 01 đăng ký sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'1\', $taxpayerName)"/>\r\n                  <xsl:with-param name="width" select="\'180px\'"/>\r\n                </xsl:call-template>&gt; của NNT, cụ thể như sau:\r\n              </div>\r\n              <xsl:call-template name="line-field">\r\n                <xsl:with-param name="label" select="\'Tên tờ khai\'"/>\r\n                <xsl:with-param name="value" select="f:case-text($thop, \'1\', $declarationName)"/>\r\n              </xsl:call-template>\r\n              <xsl:call-template name="line-field">\r\n                <xsl:with-param name="label" select="\'Mã giao dịch điện tử\'"/>\r\n                <xsl:with-param name="value" select="f:case-text($thop, \'1\', $transactionCode)"/>\r\n              </xsl:call-template>\r\n              <div>\r\n                Tờ khai đăng ký sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế của người nộp thuế đã được cơ quan thuế tiếp nhận vào lúc\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'1\', f:date($sentDate))"/>\r\n                  <xsl:with-param name="width" select="\'140px\'"/>\r\n                </xsl:call-template>.\r\n                Trong thời gian 01 ngày làm việc kể từ ngày cơ quan thuế tiếp nhận Tờ khai ghi trên thông báo này, cơ quan thuế sẽ trả Thông báo về việc chấp nhận hoặc không chấp nhận đăng ký của NNT, trường hợp không chấp nhận, cơ quan thuế nêu rõ lý do không chấp nhận.\r\n              </div>\r\n            </xsl:with-param>\r\n          </xsl:call-template>\r\n\r\n          <xsl:call-template name="case-block">\r\n            <xsl:with-param name="caseNo" select="\'2\'"/>\r\n            <xsl:with-param name="title" select="\'Trường hợp không tiếp nhận Tờ khai đăng ký sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử\'"/>\r\n            <xsl:with-param name="body">\r\n              <div>\r\n                Căn cứ &lt;Tờ khai đăng ký sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế - Mẫu số\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'2\', $formCode)"/>\r\n                  <xsl:with-param name="width" select="\'78px\'"/>\r\n                </xsl:call-template>\r\n                - Ban hành kèm theo Nghị định số ...NĐ-CP&gt; của người nộp thuế (NNT) gửi tới cơ quan thuế lúc\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'2\', f:date($sentDate))"/>\r\n                  <xsl:with-param name="width" select="\'120px\'"/>\r\n                </xsl:call-template>,\r\n                cơ quan thuế không tiếp nhận &lt;Tờ khai Mẫu số\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'2\', $formCode)"/>\r\n                  <xsl:with-param name="width" select="\'76px\'"/>\r\n                </xsl:call-template>\r\n                đăng ký sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'2\', $taxpayerName)"/>\r\n                  <xsl:with-param name="width" select="\'160px\'"/>\r\n                </xsl:call-template>&gt; của NNT, cụ thể như sau:\r\n              </div>\r\n            </xsl:with-param>\r\n          </xsl:call-template>\r\n        </div>\r\n\r\n        <div class="page page-continued">\r\n          <xsl:call-template name="line-field">\r\n            <xsl:with-param name="label" select="\'Tên tờ khai\'"/>\r\n            <xsl:with-param name="value" select="f:case-text($thop, \'2\', $declarationName)"/>\r\n          </xsl:call-template>\r\n          <xsl:call-template name="line-field">\r\n            <xsl:with-param name="label" select="\'Mã giao dịch điện tử\'"/>\r\n            <xsl:with-param name="value" select="f:case-text($thop, \'2\', $transactionCode)"/>\r\n          </xsl:call-template>\r\n          <xsl:call-template name="line-field">\r\n            <xsl:with-param name="label" select="\'Lý do không tiếp nhận\'"/>\r\n            <xsl:with-param name="value" select="f:case-text($thop, \'2\', $reason)"/>\r\n          </xsl:call-template>\r\n          <xsl:call-template name="line-field">\r\n            <xsl:with-param name="label" select="\'Đầu mối xử lý\'"/>\r\n            <xsl:with-param name="value" select="f:case-text($thop, \'2\', $processContact)"/>\r\n          </xsl:call-template>\r\n\r\n          <xsl:call-template name="case-block">\r\n            <xsl:with-param name="caseNo" select="\'3\'"/>\r\n            <xsl:with-param name="title" select="\'Trường hợp tiếp nhận Tờ khai đăng ký thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử\'"/>\r\n            <xsl:with-param name="body">\r\n              <div>\r\n                Căn cứ &lt;Tờ khai đăng ký thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'3\', $declarationName)"/>\r\n                  <xsl:with-param name="width" select="\'160px\'"/>\r\n                </xsl:call-template>\r\n                - Mẫu số ........ - Ban hành kèm theo Nghị định số .../NĐ-CP&gt; của người nộp thuế (NNT) gửi tới cơ quan thuế lúc\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'3\', f:date($sentDate))"/>\r\n                  <xsl:with-param name="width" select="\'120px\'"/>\r\n                </xsl:call-template>,\r\n                cơ quan thuế tiếp nhận &lt;Tờ khai Mẫu số ........ đăng ký thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'3\', $taxpayerName)"/>\r\n                  <xsl:with-param name="width" select="\'160px\'"/>\r\n                </xsl:call-template>&gt; của NNT, cụ thể như sau:\r\n              </div>\r\n              <xsl:call-template name="line-field">\r\n                <xsl:with-param name="label" select="\'Tên tờ khai\'"/>\r\n                <xsl:with-param name="value" select="f:case-text($thop, \'3\', $declarationName)"/>\r\n              </xsl:call-template>\r\n              <xsl:call-template name="line-field">\r\n                <xsl:with-param name="label" select="\'Mã giao dịch điện tử\'"/>\r\n                <xsl:with-param name="value" select="f:case-text($thop, \'3\', $transactionCode)"/>\r\n              </xsl:call-template>\r\n              <div>\r\n                Tờ khai đăng ký thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế của người nộp thuế đã được cơ quan thuế tiếp nhận vào lúc\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'3\', f:date($sentDate))"/>\r\n                  <xsl:with-param name="width" select="\'140px\'"/>\r\n                </xsl:call-template>.\r\n                Tờ khai đăng ký thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế ........ của người nộp thuế sẽ được cơ quan thuế tiếp tục kiểm tra.\r\n              </div>\r\n              <div class="para">\r\n                Cơ quan thuế sẽ trả Thông báo Mẫu số ... ban hành kèm theo Nghị định số .... về việc chấp nhận hoặc không chấp nhận đăng ký của NNT, trường hợp không chấp nhận, cơ quan thuế nêu rõ lý do không chấp nhận.\r\n              </div>\r\n            </xsl:with-param>\r\n          </xsl:call-template>\r\n\r\n          <xsl:call-template name="case-block">\r\n            <xsl:with-param name="caseNo" select="\'4\'"/>\r\n            <xsl:with-param name="title" select="\'Trường hợp không tiếp nhận Tờ khai đăng ký thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử\'"/>\r\n            <xsl:with-param name="body">\r\n              <div>\r\n                Căn cứ &lt;Tờ khai đăng ký thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'4\', $declarationName)"/>\r\n                  <xsl:with-param name="width" select="\'160px\'"/>\r\n                </xsl:call-template>\r\n                - Mẫu số .... - Ban hành kèm theo Nghị định số.../NĐ-CP&gt; của người nộp thuế (NNT) gửi tới cơ quan thuế lúc\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'4\', f:date($sentDate))"/>\r\n                  <xsl:with-param name="width" select="\'120px\'"/>\r\n                </xsl:call-template>,\r\n                cơ quan thuế không tiếp nhận &lt;Tờ khai Mẫu số ........ đăng ký thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử khấu trừ thuế của người nộp thuế\r\n                <xsl:call-template name="field">\r\n                  <xsl:with-param name="value" select="f:case-text($thop, \'4\', $taxpayerName)"/>\r\n                  <xsl:with-param name="width" select="\'160px\'"/>\r\n                </xsl:call-template>&gt; của NNT, cụ thể như sau:\r\n              </div>\r\n              <xsl:call-template name="line-field">\r\n                <xsl:with-param name="label" select="\'Tên tờ khai\'"/>\r\n                <xsl:with-param name="value" select="f:case-text($thop, \'4\', $declarationName)"/>\r\n              </xsl:call-template>\r\n              <xsl:call-template name="line-field">\r\n                <xsl:with-param name="label" select="\'Mã giao dịch điện tử\'"/>\r\n                <xsl:with-param name="value" select="f:case-text($thop, \'4\', $transactionCode)"/>\r\n              </xsl:call-template>\r\n              <xsl:call-template name="line-field">\r\n                <xsl:with-param name="label" select="\'Lý do không chấp nhận\'"/>\r\n                <xsl:with-param name="value" select="f:case-text($thop, \'4\', $reason)"/>\r\n              </xsl:call-template>\r\n              <xsl:call-template name="line-field">\r\n                <xsl:with-param name="label" select="\'Đầu mối xử lý\'"/>\r\n                <xsl:with-param name="value" select="f:case-text($thop, \'4\', $processContact)"/>\r\n              </xsl:call-template>\r\n            </xsl:with-param>\r\n          </xsl:call-template>\r\n        </div>\r\n\r\n        <div class="page page-continued">\r\n          <div class="tail">\r\n            Trường hợp NNT/Quý đơn vị cần biết thêm thông tin chi tiết, xin vui lòng truy cập theo đường dẫn &lt;http://www.xxx.gdt.gov.vn&gt; hoặc liên hệ với &lt;tên cơ quan thuế giải quyết hồ sơ&gt; để được hỗ trợ.\r\n          </div>\r\n          <div class="tail">Cơ quan thuế thông báo để người nộp thuế biết và thực hiện.</div>\r\n\r\n          <div class="signature">\r\n            &lt;Chữ ký số của cơ quan thuế&gt;\r\n            <xsl:if test="$hasTaxSignature">\r\n              <div class="signed">Đã ký điện tử</div>\r\n            </xsl:if>\r\n          </div>\r\n\r\n          <div class="note">\r\n            <div class="note-title">Ghi chú:</div>\r\n            <div>Chữ in nghiêng trong dấu &lt;&gt; nhằm mục đích giải thích rõ.</div>\r\n            <div>NNT, CQT chọn trường hợp thông báo tương ứng.</div>\r\n          </div>\r\n        </div>\r\n      </body>\r\n    </html>\r\n  </xsl:template>\r\n</xsl:stylesheet>\r\n', 1, 0, '/home/WEB/amnoteweb/ElectronicDocuments/shared/xsl/bf/e3a680237ef1406eb366cedec547db84/bf044beb16b6403b884fe185b50492f22bffe09d37cf9b6ae06090667adadeb3.xsl'),
	(4, 'XSL', '01/TB-ĐKĐT', '', NULL, '<?xml version="1.0" encoding="UTF-8"?>\r\n<xsl:stylesheet version="2.0"\r\n  xmlns:xsl="http://www.w3.org/1999/XSL/Transform"\r\n  xmlns:xs="http://www.w3.org/2001/XMLSchema"\r\n  xmlns:f="urn:amnote:einvoice:accept-notice"\r\n  exclude-result-prefixes="xs f">\r\n\r\n  <xsl:output method="html" encoding="UTF-8" indent="yes"/>\r\n\r\n  <xsl:function name="f:first-desc" as="xs:string">\r\n    <xsl:param name="nodes" as="node()*"/>\r\n    <xsl:param name="names" as="xs:string*"/>\r\n    <xsl:variable name="matches" select="$nodes/descendant-or-self::*[local-name() = $names]"/>\r\n    <xsl:sequence select="normalize-space(string(($matches[string-length(normalize-space(string(.))) &gt; 0][1], $matches[1])[1]))"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\')">\r\n        <xsl:sequence select="concat(substring($text, 9, 2), \'/\', substring($text, 6, 2), \'/\', substring($text, 1, 4))"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date-part" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:param name="part" as="xs:string"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'day\'">\r\n        <xsl:sequence select="substring($text, 9, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'month\'">\r\n        <xsl:sequence select="substring($text, 6, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'year\'">\r\n        <xsl:sequence select="substring($text, 1, 4)"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="\'.....\'"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:notice-result" as="xs:string">\r\n    <xsl:param name="thop" as="xs:string"/>\r\n    <xsl:param name="ttxncqt" as="xs:string"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$ttxncqt = \'1\' or $thop = (\'1\', \'3\')">\r\n        <xsl:sequence select="\'chấp nhận\'"/>\r\n      </xsl:when>\r\n      <xsl:when test="$ttxncqt = \'2\' or $thop = (\'2\', \'4\')">\r\n        <xsl:sequence select="\'không chấp nhận\'"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="\'chấp nhận/không chấp nhận\'"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:register-change-text" as="xs:string">\r\n    <xsl:param name="thop" as="xs:string"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$thop = (\'3\', \'4\')">\r\n        <xsl:sequence select="\'thay đổi thông tin\'"/>\r\n      </xsl:when>\r\n      <xsl:when test="$thop = (\'1\', \'2\')">\r\n        <xsl:sequence select="\'đăng ký\'"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="\'đăng ký/thay đổi thông tin\'"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:template name="field">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:param name="width" as="xs:string" select="\'90px\'"/>\r\n    <span class="fill" style="min-width: {$width};">\r\n      <xsl:value-of select="normalize-space(string($value))"/>\r\n    </span>\r\n  </xsl:template>\r\n\r\n  <xsl:template match="/">\r\n    <xsl:variable name="root" select="/*[local-name() = (\'TBao\', \'DLTBao\')]"/>\r\n    <xsl:variable name="dl" select="if (local-name($root) = \'TBao\') then $root/*[local-name() = \'DLTBao\'] else $root"/>\r\n    <xsl:variable name="tt" select="$dl/*[local-name() = \'TTChung\']"/>\r\n    <xsl:variable name="nd" select="$dl/*[local-name() = (\'NDTBao\', \'NDTB\', \'NDBao\')]"/>\r\n    <xsl:variable name="scope" select="($dl, $tt, $nd)"/>\r\n\r\n    <xsl:variable name="formCodeRaw" select="f:first-desc($tt, (\'MSo\', \'MSO\'))"/>\r\n    <xsl:variable name="formCode" select="if ($formCodeRaw != \'\') then $formCodeRaw else \'01/TB-ĐKĐT\'"/>\r\n    <xsl:variable name="noticeNo" select="f:first-desc($tt, (\'So\', \'STBao\', \'SoTBao\', \'SBTBao\'))"/>\r\n    <xsl:variable name="place" select="f:first-desc($tt, (\'DDanh\', \'DDBao\', \'DiaDanh\'))"/>\r\n    <xsl:variable name="noticeDate" select="f:first-desc($tt, (\'NTBao\', \'NTB\', \'NLap\', \'NgayTBao\'))"/>\r\n    <xsl:variable name="taxParent" select="f:first-desc($tt, (\'TCQTCTren\', \'TCQTCapTren\', \'CQTCapTren\'))"/>\r\n    <xsl:variable name="taxAuthority" select="f:first-desc($scope, (\'TCQT\', \'TCTBao\', \'CQT\', \'CQTQLy\', \'TCCQT\'))"/>\r\n    <xsl:variable name="taxpayerName" select="f:first-desc($scope, (\'TNNT\', \'TNNNT\', \'TenNNT\'))"/>\r\n    <xsl:variable name="taxCode" select="f:first-desc($scope, (\'MST\', \'MSTNNT\'))"/>\r\n    <xsl:variable name="thop" select="f:first-desc($scope, (\'THop\', \'THTBao\', \'THopTBao\'))"/>\r\n    <xsl:variable name="ttxncqt" select="f:first-desc($scope, (\'TTXNCQT\', \'TTXN\'))"/>\r\n    <xsl:variable name="resultText" select="f:notice-result($thop, $ttxncqt)"/>\r\n    <xsl:variable name="actionText" select="f:register-change-text($thop)"/>\r\n    <xsl:variable name="declarationDateRaw" select="f:first-desc($nd, (\'NTKhai\', \'NgayTKhai\', \'NLapTKhai\', \'NTNhan\', \'NNhan\', \'NLap\'))"/>\r\n    <xsl:variable name="declarationDate" select="if ($declarationDateRaw != \'\') then $declarationDateRaw else $noticeDate"/>\r\n    <xsl:variable name="documentKind" select="if (contains(lower-case(f:first-desc($scope, (\'Ten\', \'TenTKhai\', \'TTKhai\'))), \'chứng từ\')) then \'chứng từ điện tử\' else \'hóa đơn điện tử/biên lai điện tử/chứng từ điện tử\'"/>\r\n    <xsl:variable name="reasonFields" select="$dl//*[local-name() = \'LDo\']//*[local-name() = (\'MLoi\', \'MTa\', \'MTLoi\', \'HDXLy\')]"/>\r\n    <xsl:variable name="reasonTexts" as="xs:string*" select="for $item in $reasonFields return normalize-space(string($item))"/>\r\n    <xsl:variable name="plainReasons" as="xs:string*" select="for $item in $dl//*[local-name() = \'LDo\'][not(*)] return normalize-space(string($item))"/>\r\n    <xsl:variable name="reason" select="string-join(($reasonTexts[string-length(.) &gt; 0], $plainReasons[string-length(.) &gt; 0]), \'; \')"/>\r\n    <xsl:variable name="providerName" select="f:first-desc($scope, (\'TCCapDVu\', \'TTCGP\', \'TTCTN\', \'TTCungCapDVu\', \'TCTDVu\'))"/>\r\n    <xsl:variable name="freeAccount" select="f:first-desc($scope, (\'TKTruyCap\', \'TKhoan\', \'TaiKhoan\', \'TenDangNhap\'))"/>\r\n    <xsl:variable name="hasTaxSignature" select="exists($root//*[local-name() = \'Signature\']/*)"/>\r\n\r\n    <html>\r\n      <head>\r\n        <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>\r\n        <title>01/TB-ĐKĐT</title>\r\n        <style>\r\n          @page {\r\n            size: A4 portrait;\r\n            margin: 0;\r\n          }\r\n\r\n          * {\r\n            box-sizing: border-box;\r\n          }\r\n\r\n          body {\r\n            margin: 0;\r\n            background: #f3f4f6;\r\n            color: #000;\r\n            font-family: "Times New Roman", Times, serif;\r\n            font-size: 14px;\r\n            line-height: 1.2;\r\n          }\r\n\r\n          .page {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            margin: 0 auto;\r\n            padding: 13mm 15mm 16mm;\r\n            background: #fff;\r\n          }\r\n\r\n          .form-code {\r\n            text-align: right;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .header {\r\n            display: grid;\r\n            grid-template-columns: 34% 66%;\r\n            gap: 8px;\r\n            margin-top: 10px;\r\n          }\r\n\r\n          .tax-head,\r\n          .national {\r\n            text-align: center;\r\n          }\r\n\r\n          .strong {\r\n            font-weight: 700;\r\n          }\r\n\r\n          .short-line {\r\n            display: inline-block;\r\n            min-width: 82px;\r\n            border-top: 1px solid #000;\r\n            margin-top: 4px;\r\n          }\r\n\r\n          .doc-row {\r\n            display: grid;\r\n            grid-template-columns: 1fr 1fr;\r\n            margin-top: 26px;\r\n          }\r\n\r\n          .date {\r\n            text-align: right;\r\n            font-style: italic;\r\n          }\r\n\r\n          .title {\r\n            margin-top: 8px;\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .title .main {\r\n            font-size: 16px;\r\n          }\r\n\r\n          .title .subject {\r\n            max-width: 520px;\r\n            margin: 0 auto;\r\n          }\r\n\r\n          .greeting {\r\n            margin-top: 10px;\r\n            text-align: center;\r\n          }\r\n\r\n          .para {\r\n            margin-top: 12px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .italic {\r\n            font-style: italic;\r\n          }\r\n\r\n          .fill {\r\n            display: inline-block;\r\n            min-height: 16px;\r\n            border-bottom: 1px solid #000;\r\n            vertical-align: baseline;\r\n            text-align: center;\r\n          }\r\n\r\n          .fill.dotted {\r\n            border-bottom-style: dotted;\r\n          }\r\n\r\n          .signature {\r\n            margin-top: 28px;\r\n            text-align: right;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .signature-inner {\r\n            display: inline-block;\r\n            min-width: 260px;\r\n            text-align: center;\r\n          }\r\n\r\n          .signature .hint {\r\n            font-weight: 400;\r\n            font-style: italic;\r\n          }\r\n\r\n          .signed {\r\n            margin-top: 8px;\r\n            font-style: italic;\r\n          }\r\n\r\n          .note {\r\n            margin-top: 24px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .note-title {\r\n            font-weight: 700;\r\n            font-style: italic;\r\n            text-decoration: underline;\r\n          }\r\n\r\n          .note-line {\r\n            margin-top: 7px;\r\n          }\r\n\r\n          @media print {\r\n            body {\r\n              background: #fff;\r\n            }\r\n\r\n            .page {\r\n              margin: 0;\r\n            }\r\n          }\r\n        </style>\r\n      </head>\r\n      <body>\r\n        <div class="page">\r\n          <div class="form-code">Mẫu số: <xsl:value-of select="$formCode"/></div>\r\n\r\n          <div class="header">\r\n            <div class="tax-head">\r\n              <div>\r\n                <xsl:value-of select="if ($taxParent != \'\') then $taxParent else \'TÊN CƠ QUAN THUẾ CẤP TRÊN\'"/>\r\n              </div>\r\n              <div class="strong">\r\n                <xsl:value-of select="if ($taxAuthority != \'\') then $taxAuthority else \'TÊN CƠ QUAN BAN HÀNH VĂN BẢN\'"/>\r\n              </div>\r\n              <div><span class="short-line"></span></div>\r\n            </div>\r\n            <div class="national">\r\n              <div class="strong">CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</div>\r\n              <div class="strong">Độc lập - Tự do - Hạnh phúc</div>\r\n              <div><span class="short-line"></span></div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="doc-row">\r\n            <div>\r\n              Số:\r\n              <xsl:value-of select="if ($noticeNo != \'\') then $noticeNo else \'... ...\'"/>/TB-... ... ...\r\n            </div>\r\n            <div class="date">\r\n              <xsl:value-of select="if ($place != \'\') then $place else \'........\'"/>,\r\n              ngày\r\n              <xsl:call-template name="field">\r\n                <xsl:with-param name="value" select="f:date-part($noticeDate, \'day\')"/>\r\n                <xsl:with-param name="width" select="\'34px\'"/>\r\n              </xsl:call-template>\r\n              tháng\r\n              <xsl:call-template name="field">\r\n                <xsl:with-param name="value" select="f:date-part($noticeDate, \'month\')"/>\r\n                <xsl:with-param name="width" select="\'34px\'"/>\r\n              </xsl:call-template>\r\n              năm\r\n              <xsl:call-template name="field">\r\n                <xsl:with-param name="value" select="f:date-part($noticeDate, \'year\')"/>\r\n                <xsl:with-param name="width" select="\'48px\'"/>\r\n              </xsl:call-template>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="title">\r\n            <div class="main">THÔNG BÁO</div>\r\n            <div class="subject">Về việc chấp nhận/không chấp nhận đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử/chứng từ điện tử</div>\r\n          </div>\r\n\r\n          <div class="greeting">\r\n            Kính gửi: (Họ tên người nộp thuế:\r\n            <span class="fill dotted" style="min-width: 130px;"><xsl:value-of select="$taxpayerName"/></span>)<br/>\r\n            (Mã số thuế của NNT:\r\n            <span class="fill dotted" style="min-width: 100px;"><xsl:value-of select="$taxCode"/></span>)\r\n          </div>\r\n\r\n          <div class="para">\r\n            Sau khi xem xét tờ khai <xsl:value-of select="$actionText"/> thông tin sử dụng <xsl:value-of select="$documentKind"/> ngày\r\n            <span class="fill dotted" style="min-width: 90px;"><xsl:value-of select="f:date($declarationDate)"/></span>\r\n          </div>\r\n\r\n          <div class="para">\r\n            Cơ quan thuế thông báo (<xsl:value-of select="$resultText"/>) đề nghị <xsl:value-of select="$actionText"/> thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử của đơn vị.\r\n          </div>\r\n\r\n          <div class="para">\r\n            (Trong trường hợp chấp nhận người nộp thuế đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử thì ghi:\r\n            Tài khoản đã được gửi đến hộp thư điện tử của người nộp thuế/điện thoại liên hệ, đề nghị người nộp thuế thực hiện khai báo các thông tin liên quan theo nội dung hướng dẫn của cơ quan thuế tại thư điện tử này).\r\n          </div>\r\n\r\n          <div class="para">\r\n            (Trong trường hợp không chấp nhận doanh nghiệp đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử thì ghi:\r\n            Cơ quan thuế không chấp nhận người nộp thuế đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử/biên lai điện tử/chứng từ điện tử.\r\n            Lý do:\r\n            <span class="fill dotted" style="min-width: 300px;"><xsl:value-of select="$reason"/></span>).\r\n          </div>\r\n\r\n          <div class="para">\r\n            (Trong trường hợp ủy thác qua tổ chức cung cấp dịch vụ hóa đơn điện tử thì cơ quan thuế thông báo người nộp thuế đăng ký giao dịch sử dụng hóa đơn điện tử miễn phí qua tổ chức cung cấp dịch vụ hóa đơn điện tử\r\n            <span class="fill dotted" style="min-width: 145px;"><xsl:value-of select="$providerName"/></span>\r\n            (<xsl:value-of select="if ($freeAccount != \'\') then concat(\'Tài khoản: \', $freeAccount) else \'Tên, địa chỉ đăng ký\'"/>).\r\n          </div>\r\n\r\n          <div class="para">Cơ quan thuế thông báo để người nộp thuế biết, thực hiện.</div>\r\n\r\n          <div class="signature">\r\n            <div class="signature-inner">\r\n              CƠ QUAN THUẾ/<br/>\r\n              THỦ TRƯỞNG CƠ QUAN THUẾ<br/>\r\n              <span class="hint">(Chữ ký số)</span>\r\n              <xsl:if test="$hasTaxSignature">\r\n                <div class="signed">Đã ký điện tử</div>\r\n              </xsl:if>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="note">\r\n            <div class="note-title">Ghi chú:</div>\r\n            <div class="note-line">- Trường hợp Cổng thông tin điện tử của Tổng cục Thuế tự động ra Thông báo thì “Chữ ký số” là chữ ký số của cơ quan thuế.</div>\r\n            <div class="note-line">- Trường hợp CQT ra Thông báo thì “Chữ ký số” là chữ ký số của Thủ trưởng cơ quan thuế.</div>\r\n          </div>\r\n        </div>\r\n      </body>\r\n    </html>\r\n  </xsl:template>\r\n</xsl:stylesheet>\r\n', 1, 0, '/home/WEB/amnoteweb/ElectronicDocuments/shared/xsl/b8/78b18f7490224d98a85c3308d2608996/b8d0eda23340a2a246b7964a9cd7d4e1f4c4fb2e763d037863492cc60def8e0c.xsl'),
	(5, 'XSL', '	\r\n01/TB-HĐSS', '', NULL, '<?xml version="1.0" encoding="UTF-8"?>\r\n<xsl:stylesheet version="2.0"\r\n  xmlns:xsl="http://www.w3.org/1999/XSL/Transform"\r\n  xmlns:xs="http://www.w3.org/2001/XMLSchema"\r\n  xmlns:f="urn:amnote:einvoice:error-process-notice"\r\n  exclude-result-prefixes="xs f">\r\n\r\n  <xsl:output method="html" encoding="UTF-8" indent="yes"/>\r\n\r\n  <xsl:function name="f:first-desc" as="xs:string">\r\n    <xsl:param name="nodes" as="node()*"/>\r\n    <xsl:param name="names" as="xs:string*"/>\r\n    <xsl:variable name="matches" select="$nodes/descendant-or-self::*[local-name() = $names]"/>\r\n    <xsl:sequence select="normalize-space(string(($matches[string-length(normalize-space(string(.))) &gt; 0][1], $matches[1])[1]))"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\')">\r\n        <xsl:sequence select="concat(substring($text, 9, 2), \'/\', substring($text, 6, 2), \'/\', substring($text, 1, 4))"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date-part" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:param name="part" as="xs:string"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'day\'">\r\n        <xsl:sequence select="substring($text, 9, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'month\'">\r\n        <xsl:sequence select="substring($text, 6, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'year\'">\r\n        <xsl:sequence select="substring($text, 1, 4)"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="\'.....\'"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:receive-result" as="xs:string">\r\n    <xsl:param name="thop" as="xs:string"/>\r\n    <xsl:param name="ttxncqt" as="xs:string"/>\r\n    <xsl:param name="hasRejectReason" as="xs:boolean"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$ttxncqt = \'2\' or $thop = (\'2\', \'4\') or $hasRejectReason">\r\n        <xsl:sequence select="\'không tiếp nhận\'"/>\r\n      </xsl:when>\r\n      <xsl:when test="$ttxncqt = \'1\' or $thop = (\'1\', \'3\')">\r\n        <xsl:sequence select="\'tiếp nhận\'"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="\'tiếp nhận/không tiếp nhận\'"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:is-accepted" as="xs:boolean">\r\n    <xsl:param name="result" as="xs:string"/>\r\n    <xsl:sequence select="$result = \'tiếp nhận\'"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:is-rejected" as="xs:boolean">\r\n    <xsl:param name="result" as="xs:string"/>\r\n    <xsl:sequence select="$result = \'không tiếp nhận\'"/>\r\n  </xsl:function>\r\n\r\n  <xsl:template name="field">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:param name="width" as="xs:string" select="\'90px\'"/>\r\n    <span class="fill" style="min-width: {$width};">\r\n      <xsl:value-of select="normalize-space(string($value))"/>\r\n    </span>\r\n  </xsl:template>\r\n\r\n  <xsl:template match="/">\r\n    <xsl:variable name="root" select="/*[local-name() = (\'TBao\', \'DLTBao\')]"/>\r\n    <xsl:variable name="dl" select="if (local-name($root) = \'TBao\') then $root/*[local-name() = \'DLTBao\'] else $root"/>\r\n    <xsl:variable name="tt" select="$dl/*[local-name() = \'TTChung\']"/>\r\n    <xsl:variable name="nd" select="$dl/*[local-name() = (\'NDTBao\', \'NDTB\', \'NDBao\')]"/>\r\n    <xsl:variable name="scope" select="($dl, $tt, $nd)"/>\r\n\r\n    <xsl:variable name="formCodeRaw" select="f:first-desc($tt, (\'MSo\', \'MSO\'))"/>\r\n    <xsl:variable name="formCode" select="if ($formCodeRaw != \'\') then $formCodeRaw else \'01/TB-HĐSS\'"/>\r\n    <xsl:variable name="noticeNo" select="f:first-desc($tt, (\'So\', \'STBao\', \'SoTBao\', \'SBTBao\'))"/>\r\n    <xsl:variable name="place" select="f:first-desc($tt, (\'DDanh\', \'DDBao\', \'DiaDanh\'))"/>\r\n    <xsl:variable name="noticeDate" select="f:first-desc($tt, (\'NTBao\', \'NTB\', \'NLap\', \'NgayTBao\'))"/>\r\n    <xsl:variable name="taxParent" select="f:first-desc($tt, (\'TCQTCTren\', \'TCQTCapTren\', \'CQTCapTren\'))"/>\r\n    <xsl:variable name="taxAuthority" select="f:first-desc($scope, (\'TCQT\', \'TCTBao\', \'CQT\', \'CQTQLy\', \'TCCQT\'))"/>\r\n    <xsl:variable name="taxpayerName" select="f:first-desc($scope, (\'TNNT\', \'TNNNT\', \'TenNNT\'))"/>\r\n    <xsl:variable name="taxCode" select="f:first-desc($scope, (\'MST\', \'MSTNNT\'))"/>\r\n    <xsl:variable name="thop" select="f:first-desc($scope, (\'THop\', \'THTBao\', \'THopTBao\'))"/>\r\n    <xsl:variable name="ttxncqt" select="f:first-desc($scope, (\'TTXNCQT\', \'TTXN\', \'TTTNhan\'))"/>\r\n    <xsl:variable name="sourceNoticeDateRaw" select="f:first-desc($nd, (\'NTBaoNNT\', \'NTBNNT\', \'NgayTBNNT\', \'NTBCCQT\', \'NTBao\', \'NLap\'))"/>\r\n    <xsl:variable name="sourceNoticeDate" select="if ($sourceNoticeDateRaw != \'\') then $sourceNoticeDateRaw else $noticeDate"/>\r\n\r\n    <xsl:variable name="reasonFields" select="$dl//*[local-name() = \'LDo\']//*[local-name() = (\'MLoi\', \'MTa\', \'MTLoi\', \'HDXLy\')]"/>\r\n    <xsl:variable name="reasonTexts" as="xs:string*" select="for $item in $reasonFields return normalize-space(string($item))"/>\r\n    <xsl:variable name="plainReasons" as="xs:string*" select="for $item in $dl//*[local-name() = \'LDo\'][not(*)] return normalize-space(string($item))"/>\r\n    <xsl:variable name="reason" select="string-join(($reasonTexts[string-length(.) &gt; 0], $plainReasons[string-length(.) &gt; 0]), \'; \')"/>\r\n    <xsl:variable name="hasRejectReason" select="exists($dl//*[local-name() = \'DSLDKTNhan\']/*[local-name() = \'LDo\']/*[local-name() = \'MLoi\']) or string-length($reason) &gt; 0 and ($ttxncqt = \'2\' or $thop = (\'2\', \'4\'))"/>\r\n    <xsl:variable name="resultText" select="f:receive-result($thop, $ttxncqt, $hasRejectReason)"/>\r\n    <xsl:variable name="hasTaxSignature" select="exists($root//*[local-name() = \'Signature\']/*)"/>\r\n\r\n    <html>\r\n      <head>\r\n        <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>\r\n        <title><xsl:value-of select="$formCode"/></title>\r\n        <style>\r\n          @page {\r\n            size: A4 portrait;\r\n            margin: 0;\r\n          }\r\n\r\n          * {\r\n            box-sizing: border-box;\r\n          }\r\n\r\n          body {\r\n            margin: 0;\r\n            background: #f3f4f6;\r\n            color: #000;\r\n            font-family: "Times New Roman", Times, serif;\r\n            font-size: 14px;\r\n            line-height: 1.2;\r\n          }\r\n\r\n          .page {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            margin: 0 auto;\r\n            padding: 13mm 15mm 16mm;\r\n            background: #fff;\r\n          }\r\n\r\n          .form-code {\r\n            text-align: right;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .header {\r\n            display: grid;\r\n            grid-template-columns: 34% 66%;\r\n            gap: 8px;\r\n            margin-top: 10px;\r\n          }\r\n\r\n          .tax-head,\r\n          .national {\r\n            text-align: center;\r\n          }\r\n\r\n          .strong {\r\n            font-weight: 700;\r\n          }\r\n\r\n          .short-line {\r\n            display: inline-block;\r\n            min-width: 82px;\r\n            border-top: 1px solid #000;\r\n            margin-top: 4px;\r\n          }\r\n\r\n          .doc-row {\r\n            display: grid;\r\n            grid-template-columns: 1fr 1fr;\r\n            margin-top: 26px;\r\n          }\r\n\r\n          .date {\r\n            text-align: right;\r\n            font-style: italic;\r\n          }\r\n\r\n          .title {\r\n            margin-top: 8px;\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .title .main {\r\n            font-size: 16px;\r\n          }\r\n\r\n          .title .subject {\r\n            max-width: 560px;\r\n            margin: 0 auto;\r\n          }\r\n\r\n          .greeting {\r\n            margin-top: 10px;\r\n            text-align: center;\r\n          }\r\n\r\n          .para {\r\n            margin-top: 12px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .field-line {\r\n            margin-top: 8px;\r\n          }\r\n\r\n          .italic {\r\n            font-style: italic;\r\n          }\r\n\r\n          .fill {\r\n            display: inline-block;\r\n            min-height: 16px;\r\n            border-bottom: 1px solid #000;\r\n            vertical-align: baseline;\r\n            text-align: center;\r\n          }\r\n\r\n          .fill.dotted {\r\n            border-bottom-style: dotted;\r\n          }\r\n\r\n          .signature {\r\n            margin-top: 28px;\r\n            text-align: right;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .signature-inner {\r\n            display: inline-block;\r\n            min-width: 260px;\r\n            text-align: center;\r\n          }\r\n\r\n          .signature .hint {\r\n            font-weight: 400;\r\n            font-style: italic;\r\n          }\r\n\r\n          .signed {\r\n            margin-top: 8px;\r\n            font-style: italic;\r\n          }\r\n\r\n          .note {\r\n            margin-top: 24px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .note-title {\r\n            font-weight: 700;\r\n            font-style: italic;\r\n            text-decoration: underline;\r\n          }\r\n\r\n          .note-line {\r\n            margin-top: 7px;\r\n          }\r\n\r\n          @media print {\r\n            body {\r\n              background: #fff;\r\n            }\r\n\r\n            .page {\r\n              margin: 0;\r\n            }\r\n          }\r\n        </style>\r\n      </head>\r\n      <body>\r\n        <div class="page">\r\n          <div class="form-code">Mẫu số: <xsl:value-of select="$formCode"/></div>\r\n\r\n          <div class="header">\r\n            <div class="tax-head">\r\n              <div>\r\n                <xsl:value-of select="if ($taxParent != \'\') then $taxParent else \'[TÊN CƠ QUAN THUẾ CẤP TRÊN]\'"/>\r\n              </div>\r\n              <div class="strong">\r\n                <xsl:value-of select="if ($taxAuthority != \'\') then $taxAuthority else \'TÊN CƠ QUAN BAN HÀNH VĂN BẢN\'"/>\r\n              </div>\r\n              <div><span class="short-line"></span></div>\r\n            </div>\r\n            <div class="national">\r\n              <div class="strong">CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</div>\r\n              <div class="strong">Độc lập - Tự do - Hạnh phúc</div>\r\n              <div><span class="short-line"></span></div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="doc-row">\r\n            <div>\r\n              Số:\r\n              <xsl:value-of select="if ($noticeNo != \'\') then $noticeNo else \'.../.../TB-...\'"/>\r\n            </div>\r\n            <div class="date">\r\n              <xsl:value-of select="if ($place != \'\') then $place else \'........\'"/>,\r\n              ngày\r\n              <xsl:call-template name="field">\r\n                <xsl:with-param name="value" select="f:date-part($noticeDate, \'day\')"/>\r\n                <xsl:with-param name="width" select="\'34px\'"/>\r\n              </xsl:call-template>\r\n              tháng\r\n              <xsl:call-template name="field">\r\n                <xsl:with-param name="value" select="f:date-part($noticeDate, \'month\')"/>\r\n                <xsl:with-param name="width" select="\'34px\'"/>\r\n              </xsl:call-template>\r\n              năm\r\n              <xsl:call-template name="field">\r\n                <xsl:with-param name="value" select="f:date-part($noticeDate, \'year\')"/>\r\n                <xsl:with-param name="width" select="\'48px\'"/>\r\n              </xsl:call-template>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="title">\r\n            <div class="main">THÔNG BÁO</div>\r\n            <div class="subject">Về việc tiếp nhận và kết quả xử lý về việc hóa đơn điện tử/chứng từ điện tử đã lập sai</div>\r\n          </div>\r\n\r\n          <div class="greeting">\r\n            Kính gửi: (Họ tên người nộp thuế:\r\n            <span class="fill dotted" style="min-width: 180px;"><xsl:value-of select="$taxpayerName"/></span>)<br/>\r\n            (Mã số thuế của NNT:\r\n            <span class="fill dotted" style="min-width: 140px;"><xsl:value-of select="$taxCode"/></span>)\r\n          </div>\r\n\r\n          <div class="para">\r\n            Sau khi xem xét Thông báo hóa đơn điện tử/chứng từ điện tử đã lập sai ngày\r\n            <span class="fill dotted" style="min-width: 100px;"><xsl:value-of select="f:date($sourceNoticeDate)"/></span>\r\n            của:\r\n          </div>\r\n\r\n          <div class="field-line">\r\n            Người nộp thuế\r\n            <span class="fill dotted" style="min-width: 420px;"><xsl:value-of select="$taxpayerName"/></span>\r\n          </div>\r\n          <div class="field-line">\r\n            Mã số thuế:\r\n            <span class="fill dotted" style="min-width: 420px;"><xsl:value-of select="$taxCode"/></span>\r\n          </div>\r\n\r\n          <div class="para">\r\n            Cơ quan thuế thông báo (<xsl:value-of select="$resultText"/>) hóa đơn điện tử/chứng từ điện tử đã lập sai.\r\n          </div>\r\n\r\n          <div class="para italic">\r\n            (Trong trường hợp tiếp nhận việc thông báo/giải trình hóa đơn điện tử/chứng từ điện tử đã lập sai thì ghi:\r\n            Cơ quan Thuế đã tiếp nhận Thông báo hóa đơn điện tử/chứng từ điện tử đã lập sai ngày\r\n            <span class="fill dotted" style="min-width: 100px;">\r\n              <xsl:value-of select="if (f:is-accepted($resultText)) then f:date($sourceNoticeDate) else \'\'"/>\r\n            </span>\r\n            của quý công ty).\r\n          </div>\r\n\r\n          <div class="para italic">\r\n            (Trong trường hợp không tiếp nhận việc thông báo/giải trình hóa đơn điện tử/chứng từ điện tử đã lập sai thì ghi:\r\n            Đề nghị quý công ty kiểm tra, đối chiếu hóa đơn điện tử/chứng từ điện tử đã lập sai do thông tin chưa chính xác\r\n            <xsl:if test="f:is-rejected($resultText) and $reason != \'\'">\r\n              <xsl:text>: </xsl:text>\r\n              <span class="fill dotted" style="min-width: 260px;"><xsl:value-of select="$reason"/></span>\r\n            </xsl:if>).\r\n          </div>\r\n\r\n          <div class="para">Cơ quan thuế thông báo để người nộp thuế biết, thực hiện.</div>\r\n\r\n          <div class="signature">\r\n            <div class="signature-inner">\r\n              CƠ QUAN THUẾ/<br/>\r\n              THỦ TRƯỞNG CƠ QUAN THUẾ<br/>\r\n              <span class="hint">(Chữ ký số)</span>\r\n              <xsl:if test="$hasTaxSignature">\r\n                <div class="signed">Đã ký điện tử</div>\r\n              </xsl:if>\r\n            </div>\r\n          </div>\r\n\r\n          <div class="note">\r\n            <div class="note-title">Ghi chú:</div>\r\n            <div class="note-line">- Trường hợp Cổng thông tin điện tử của Tổng cục Thuế tự động ra Thông báo thì “Chữ ký số” là chữ ký số của cơ quan thuế.</div>\r\n            <div class="note-line">- Trường hợp CQT ra Thông báo thì “Chữ ký số” là chữ ký số của Thủ trưởng cơ quan thuế.</div>\r\n          </div>\r\n        </div>\r\n      </body>\r\n    </html>\r\n  </xsl:template>\r\n</xsl:stylesheet>\r\n', 1, 0, NULL),
	(6, 'XSL', '01/TB-KTDL', '', NULL, '1', 1, 0, NULL),
	(7, 'EMAIL', 'EMAIL_SEND_INVOICE', 'Email gửi hóa đơn điện tử cho người mua', 'Hóa đơn điện tử {{DISPLAY_NO}} - {{SELLER_NM}}', '<!DOCTYPE html>\r\n<html lang="vi">\r\n<head>\r\n  <meta charset="utf-8" />\r\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\r\n  <title>Hóa đơn điện tử AMnote</title>\r\n</head>\r\n\r\n<body style="margin:0;padding:0;background-color:#f4f6f8;font-family:Arial,Helvetica,sans-serif;color:#1f2937;">\r\n  <table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f8;padding:24px 12px;">\r\n    <tr>\r\n      <td align="center">\r\n\r\n        <table width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">\r\n\r\n          <tr>\r\n            <td style="background:#0f766e;color:#ffffff;padding:22px 26px;">\r\n              <div style="font-size:20px;font-weight:bold;line-height:1.4;">\r\n                Hóa đơn điện tử AMnote\r\n              </div>\r\n              <div style="font-size:13px;margin-top:4px;opacity:0.95;">\r\n                Thông báo phát hành hóa đơn điện tử\r\n              </div>\r\n            </td>\r\n          </tr>\r\n\r\n          <tr>\r\n            <td style="padding:26px;">\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.7;">\r\n                Kính gửi Quý khách <strong>{{NMUA_TEN}}</strong>,\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.7;">\r\n                <strong>{{SELLER_NM}}</strong> trân trọng cảm ơn Quý khách đã tin tưởng sử dụng hàng hóa/dịch vụ trong thời gian qua.\r\n              </p>\r\n\r\n              <p style="margin:0 0 18px;font-size:15px;line-height:1.7;">\r\n                Thông qua hệ thống hóa đơn điện tử <strong>AMnote</strong>, chúng tôi xin thông báo hóa đơn điện tử của Quý khách đã được phát hành với các thông tin như sau:\r\n              </p>\r\n\r\n              <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 22px;font-size:14px;">\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;width:38%;">Ký hiệu mẫu số hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>{{KHMSHDON}}</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ký hiệu hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>{{KHHDON}}</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Số hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>{{SHDON}}</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ngày hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">{{NLAP}}</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Tổng tiền thanh toán</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">\r\n                    <strong>{{TGTTTBSO}} {{DVTTE}}</strong>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Mã tra cứu</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">\r\n                    <strong>{{MTRACUU}}</strong>\r\n                  </td>\r\n                </tr>\r\n              </table>\r\n\r\n              <p style="margin:0 0 18px;font-size:14px;line-height:1.7;">\r\n                Quý khách vui lòng truy cập đường dẫn bên dưới để xem và tải hóa đơn điện tử:\r\n              </p>\r\n\r\n              <p style="margin:0 0 22px;text-align:center;">\r\n                <a href="{{LOOKUP_URL}}" style="display:inline-block;background:#0f766e;color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:6px;font-size:14px;font-weight:bold;">\r\n                  Xem hóa đơn điện tử\r\n                </a>\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:14px;line-height:1.7;">\r\n                File PDF hóa đơn được đính kèm trong email này. Trường hợp cần kiểm tra lại thông tin hóa đơn, Quý khách có thể sử dụng mã tra cứu ở trên tại trang tra cứu hóa đơn của AMnote.\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:14px;line-height:1.7;">\r\n                Mọi thắc mắc liên quan đến nội dung hóa đơn, Quý khách vui lòng liên hệ trực tiếp với <strong>{{SELLER_NM}}</strong> để được hỗ trợ.\r\n              </p>\r\n\r\n              <p style="margin:0;font-size:14px;line-height:1.7;">\r\n                Trân trọng,<br />\r\n                <strong>{{SELLER_NM}}</strong>\r\n              </p>\r\n            </td>\r\n          </tr>\r\n\r\n          <tr>\r\n            <td style="padding:16px 26px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;line-height:1.6;">\r\n              Email này được gửi tự động từ hệ thống hóa đơn điện tử AMnote. Vui lòng không trả lời trực tiếp email này.<br />\r\n              Website: {{AMNOTE_WEBSITE}} | Email hỗ trợ: {{SUPPORT_EMAIL}} | Hotline: {{SUPPORT_PHONE}}\r\n            </td>\r\n          </tr>\r\n\r\n        </table>\r\n\r\n      </td>\r\n    </tr>\r\n  </table>\r\n</body>\r\n</html>', 1, 0, NULL),
	(8, 'XSL', 'BBDCTT', '', NULL, '<?xml version="1.0" encoding="utf-8"?>\r\n<xsl:stylesheet xmlns:xsl="http://www.w3.org/1999/XSL/Transform" version="1.0" xmlns:ds="http://www.w3.org/2000/09/xmldsig#">\r\n	<xsl:output method="html" encoding="UTF-8" indent="yes"/>\r\n	<xsl:decimal-format name="vndong" decimal-separator="." grouping-separator=","/>\r\n\r\n	<xsl:variable name="LoaiBienBan">\r\n		<xsl:choose>\r\n			<xsl:when test="/BBan/NDBBan/TTChung/TCHDon = \'1\'">thay thế</xsl:when>\r\n			<xsl:otherwise>điều chỉnh</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:variable>\r\n	<xsl:variable name="MSTNBan" select="normalize-space(/BBan/NDBBan/TTChung/MSTNBan)"/>\r\n	<xsl:variable name="hasNBanSignature" select="count(/BBan/DSCKS/NBan/*[local-name()=\'Signature\']/*) &gt; 0"/>\r\n	<xsl:variable name="hasNMuaSignature" select="count(/BBan/DSCKS/NMua/*[local-name()=\'Signature\']/*) &gt; 0"/>\r\n	<xsl:variable name="isNgoaiTe">\r\n		<xsl:choose>\r\n			<xsl:when test="normalize-space(/BBan/NDBBan/TTChung/DSHHDVuTruoc/HHDVu[1]/DVTTe) != \'\' and normalize-space(/BBan/NDBBan/TTChung/DSHHDVuTruoc/HHDVu[1]/DVTTe) != \'VND\'">true</xsl:when>\r\n			<xsl:when test="normalize-space(/BBan/NDBBan/TTChung/DSHHDVuSau/HHDVu[1]/DVTTe) != \'\' and normalize-space(/BBan/NDBBan/TTChung/DSHHDVuSau/HHDVu[1]/DVTTe) != \'VND\'">true</xsl:when>\r\n			<xsl:otherwise>false</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:variable>\r\n	<xsl:variable name="maxDecimalsDGia">\r\n		<xsl:call-template name="find-max-decimals">\r\n			<xsl:with-param name="nodes" select="//HHDVu/DGia"/>\r\n		</xsl:call-template>\r\n	</xsl:variable>\r\n	<xsl:variable name="maxDecimalsThTien">\r\n		<xsl:call-template name="find-max-decimals">\r\n			<xsl:with-param name="nodes" select="//HHDVu/ThTien"/>\r\n		</xsl:call-template>\r\n	</xsl:variable>\r\n\r\n	<xsl:template name="ten-chung-tu">\r\n		<xsl:param name="khms-hdon"/>\r\n		<xsl:param name="mode" select="\'lower\'"/>\r\n		<xsl:choose>\r\n			<xsl:when test="$khms-hdon = \'6\'">\r\n				<xsl:choose>\r\n					<xsl:when test="$mode = \'upper\'">PHIẾU XUẤT KHO</xsl:when>\r\n					<xsl:when test="$mode = \'sentence\'">Phiếu xuất kho</xsl:when>\r\n					<xsl:otherwise>phiếu xuất kho</xsl:otherwise>\r\n				</xsl:choose>\r\n			</xsl:when>\r\n			<xsl:when test="$khms-hdon = \'2\'">\r\n				<xsl:choose>\r\n					<xsl:when test="$mode = \'upper\'">HÓA ĐƠN BÁN HÀNG</xsl:when>\r\n					<xsl:when test="$mode = \'sentence\'">Hóa đơn bán hàng</xsl:when>\r\n					<xsl:otherwise>hóa đơn bán hàng</xsl:otherwise>\r\n				</xsl:choose>\r\n			</xsl:when>\r\n			<xsl:otherwise>\r\n				<xsl:choose>\r\n					<xsl:when test="$mode = \'upper\'">HÓA ĐƠN GTGT</xsl:when>\r\n					<xsl:when test="$mode = \'sentence\'">Hóa đơn GTGT</xsl:when>\r\n					<xsl:otherwise>hóa đơn GTGT</xsl:otherwise>\r\n				</xsl:choose>\r\n			</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="format-iso-date">\r\n		<xsl:param name="date"/>\r\n		<xsl:if test="normalize-space($date) != \'\'">\r\n			<xsl:value-of select="concat(substring($date,9,2),\'/\',substring($date,6,2),\'/\',substring($date,1,4))"/>\r\n		</xsl:if>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-national-header">\r\n		<div class="center bold">CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</div>\r\n		<div class="center bold">Độc lập - Tự do - Hạnh phúc</div>\r\n		<div class="center">---oOo---</div>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-bien-ban-title">\r\n		<xsl:param name="khms-hdon"/>\r\n		<xsl:param name="is-replacement"/>\r\n		<xsl:param name="continuation" select="\'\'"/>\r\n		<div class="title center">\r\n			<xsl:choose>\r\n				<xsl:when test="$is-replacement = \'true\'">BIÊN BẢN THAY THẾ </xsl:when>\r\n				<xsl:otherwise>BIÊN BẢN ĐIỀU CHỈNH </xsl:otherwise>\r\n			</xsl:choose>\r\n			<xsl:call-template name="ten-chung-tu">\r\n				<xsl:with-param name="khms-hdon" select="$khms-hdon"/>\r\n				<xsl:with-param name="mode" select="\'upper\'"/>\r\n			</xsl:call-template>\r\n			<xsl:if test="$continuation != \'\'">\r\n				<xsl:text> </xsl:text>\r\n				<xsl:value-of select="$continuation"/>\r\n			</xsl:if>\r\n		</div>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-items-colgroup">\r\n		<colgroup>\r\n			<col style="width: 8%"/>\r\n			<col style="width: 35%"/>\r\n			<col style="width: 10%"/>\r\n			<col style="width: 12%"/>\r\n			<col style="width: 17.5%"/>\r\n			<col style="width: 17.5%"/>\r\n		</colgroup>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-items-header-rows">\r\n		<tr>\r\n			<th>STT</th>\r\n			<th>Tên hàng</th>\r\n			<th>Đơn vị</th>\r\n			<th>Số lượng</th>\r\n			<th>Đơn giá</th>\r\n			<th>Thành tiền</th>\r\n		</tr>\r\n		<tr>\r\n			<td style="text-align:center">(1)</td>\r\n			<td style="text-align:center">(2)</td>\r\n			<td style="text-align:center">(3)</td>\r\n			<td style="text-align:center">(4)</td>\r\n			<td style="text-align:center">(5)</td>\r\n			<td style="text-align:center">(6)</td>\r\n		</tr>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-hang-hoa-row">\r\n		<tr>\r\n			<td style="text-align:center">\r\n				<xsl:value-of select="STT"/>\r\n			</td>\r\n			<td style="text-align:left">\r\n				<xsl:value-of select="THHDVu"/>\r\n			</td>\r\n			<td style="text-align:center">\r\n				<xsl:value-of select="DVTinh"/>\r\n			</td>\r\n			<td style="text-align:right">\r\n				<xsl:call-template name="format-vnd">\r\n					<xsl:with-param name="number" select="SLuong"/>\r\n				</xsl:call-template>\r\n			</td>\r\n			<td style="text-align:right">\r\n				<xsl:call-template name="format-with-decimals">\r\n					<xsl:with-param name="number" select="DGia"/>\r\n					<xsl:with-param name="decimal-places" select="$maxDecimalsDGia"/>\r\n				</xsl:call-template>\r\n			</td>\r\n			<td style="text-align:right">\r\n				<xsl:call-template name="format-with-decimals">\r\n					<xsl:with-param name="number" select="ThTien"/>\r\n					<xsl:with-param name="decimal-places" select="$maxDecimalsThTien"/>\r\n				</xsl:call-template>\r\n			</td>\r\n		</tr>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-amount-in-words">\r\n		<xsl:param name="amount"/>\r\n		<xsl:param name="words"/>\r\n		<xsl:param name="italic" select="\'false\'"/>\r\n		<xsl:param name="show-giam" select="\'false\'"/>\r\n		<xsl:choose>\r\n			<xsl:when test="$italic = \'true\'">\r\n				<span style="font-style: italic;">\r\n					Số tiền viết bằng chữ:\r\n					<xsl:if test="$show-giam = \'true\' and number($amount) &lt; 0">Giảm </xsl:if>\r\n					<xsl:value-of select="$words"/>\r\n				</span>\r\n			</xsl:when>\r\n			<xsl:otherwise>\r\n				Số tiền viết bằng chữ: <xsl:value-of select="$words"/>\r\n			</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-table-totals">\r\n		<xsl:param name="khms-hdon"/>\r\n		<xsl:param name="tg-tcthue"/>\r\n		<xsl:param name="tg-tthue"/>\r\n		<xsl:param name="tg-tttbso"/>\r\n		<xsl:param name="tg-tttbchu"/>\r\n		<xsl:param name="tax-rate"/>\r\n		<xsl:param name="dvtte"/>\r\n		<xsl:param name="bold" select="\'false\'"/>\r\n		<xsl:param name="italic-chu" select="\'false\'"/>\r\n		<xsl:param name="show-giam" select="\'false\'"/>\r\n		<xsl:variable name="cell-style">\r\n			<xsl:choose>\r\n				<xsl:when test="$bold = \'true\'">text-align:left; font-weight: bold;</xsl:when>\r\n				<xsl:otherwise>text-align:left</xsl:otherwise>\r\n			</xsl:choose>\r\n		</xsl:variable>\r\n		<xsl:if test="$khms-hdon = \'6\'">\r\n			<tr>\r\n				<td colspan="6" style="{$cell-style}">\r\n					Tổng tiền:\r\n					<xsl:call-template name="format-vnd">\r\n						<xsl:with-param name="number" select="$tg-tttbso"/>\r\n					</xsl:call-template>\r\n					&#160;\r\n					<xsl:value-of select="$dvtte"/>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td colspan="6" style="{$cell-style}">\r\n					<xsl:call-template name="render-amount-in-words">\r\n						<xsl:with-param name="amount" select="$tg-tttbso"/>\r\n						<xsl:with-param name="words" select="$tg-tttbchu"/>\r\n						<xsl:with-param name="italic" select="$italic-chu"/>\r\n						<xsl:with-param name="show-giam" select="$show-giam"/>\r\n					</xsl:call-template>\r\n				</td>\r\n			</tr>\r\n		</xsl:if>\r\n		<xsl:if test="$khms-hdon != \'6\' and $khms-hdon != \'2\'">\r\n			<tr>\r\n				<td colspan="6" style="{$cell-style}">\r\n					Cộng tiền hàng:\r\n					<xsl:call-template name="format-vnd">\r\n						<xsl:with-param name="number" select="$tg-tcthue"/>\r\n					</xsl:call-template>\r\n					&#160;\r\n					<xsl:value-of select="$dvtte"/>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td colspan="6" style="{$cell-style}">\r\n					Thuế suất GTGT: <xsl:value-of select="$tax-rate"/>\r\n					<xsl:text>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;</xsl:text>\r\n					Tiền thuế GTGT:\r\n					<xsl:call-template name="format-vnd">\r\n						<xsl:with-param name="number" select="$tg-tthue"/>\r\n					</xsl:call-template>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td colspan="6" style="{$cell-style}">\r\n					Tổng cộng tiền thanh toán:\r\n					<xsl:call-template name="format-vnd">\r\n						<xsl:with-param name="number" select="$tg-tttbso"/>\r\n					</xsl:call-template>\r\n					&#160;\r\n					<xsl:value-of select="$dvtte"/>\r\n					<br/>\r\n					<xsl:call-template name="render-amount-in-words">\r\n						<xsl:with-param name="amount" select="$tg-tttbso"/>\r\n						<xsl:with-param name="words" select="$tg-tttbchu"/>\r\n						<xsl:with-param name="italic" select="$italic-chu"/>\r\n						<xsl:with-param name="show-giam" select="$show-giam"/>\r\n					</xsl:call-template>\r\n				</td>\r\n			</tr>\r\n		</xsl:if>\r\n		<xsl:if test="$khms-hdon = \'2\'">\r\n			<tr>\r\n				<td colspan="6" style="{$cell-style}">\r\n					Cộng tiền hàng:\r\n					<xsl:call-template name="format-vnd">\r\n						<xsl:with-param name="number" select="$tg-tcthue"/>\r\n					</xsl:call-template>\r\n					&#160;\r\n					<xsl:value-of select="$dvtte"/>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td colspan="6" style="{$cell-style}">\r\n					Tổng cộng tiền thanh toán:\r\n					<xsl:call-template name="format-vnd">\r\n						<xsl:with-param name="number" select="$tg-tttbso"/>\r\n					</xsl:call-template>\r\n					&#160;\r\n					<xsl:value-of select="$dvtte"/>\r\n					<br/>\r\n					<xsl:call-template name="render-amount-in-words">\r\n						<xsl:with-param name="amount" select="$tg-tttbso"/>\r\n						<xsl:with-param name="words" select="$tg-tttbchu"/>\r\n						<xsl:with-param name="italic" select="$italic-chu"/>\r\n						<xsl:with-param name="show-giam" select="$show-giam"/>\r\n					</xsl:call-template>\r\n				</td>\r\n			</tr>\r\n		</xsl:if>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-signature-slot">\r\n		<xsl:param name="label"/>\r\n		<xsl:param name="has-signature"/>\r\n		<xsl:param name="side"/>\r\n		<xsl:param name="party-name"/>\r\n		<xsl:param name="representative-name"/>\r\n		<div>\r\n			<div class="sign-title">\r\n				<xsl:value-of select="$label"/>\r\n			</div>\r\n			<div class="sign-sub">(Ký đóng dấu và ghi rõ họ tên)</div>\r\n			<xsl:if test="$has-signature = \'true\'">\r\n				<xsl:call-template name="render-cks-block">\r\n					<xsl:with-param name="side" select="$side"/>\r\n					<xsl:with-param name="party-name" select="$party-name"/>\r\n				</xsl:call-template>\r\n			</xsl:if>\r\n			<xsl:if test="$has-signature != \'true\'">\r\n				<div class="sign-body">\r\n					<div class="signature-placeholder"/>\r\n					<div class="unsigned-name">\r\n						<xsl:value-of select="$representative-name"/>\r\n					</div>\r\n				</div>\r\n			</xsl:if>\r\n		</div>\r\n	</xsl:template>\r\n\r\n	<xsl:template match="/BBan">\r\n		<html>\r\n			<head>\r\n				<style>\r\n					@page {\r\n					size: A4 portrait;\r\n					margin: 0;\r\n					}\r\n					* { box-sizing: border-box; }\r\n					html, body {\r\n					margin: 0;\r\n					padding: 0;\r\n					font-family: "Times New Roman", Times, serif;\r\n					font-size: 12px;\r\n					font-style: normal;\r\n					font-weight: normal;\r\n					color: #000000;\r\n					background: #e8e8e8;\r\n					line-height: 1.45;\r\n					}\r\n					#main.minute-root {\r\n					margin: 0;\r\n					padding: 0;\r\n					}\r\n					.invoice-page {\r\n					width: 210mm;\r\n					min-height: 297mm;\r\n					position: relative;\r\n					margin: 0 auto 8px;\r\n					background-color: #fff;\r\n					border: 1px solid #000;\r\n					overflow: visible;\r\n					page-break-after: always;\r\n					}\r\n					.invoice-page:last-child,\r\n					.invoice-page.invoice-page-last {\r\n					page-break-after: auto;\r\n					margin-bottom: 0;\r\n					}\r\n					.invoice-page-body {\r\n					padding: 7mm 9mm 9mm;\r\n					}\r\n					.invoice-page.document-page {\r\n					page-break-after: auto;\r\n					}\r\n					.invoice-page.continuation-page {\r\n					page-break-before: always;\r\n					page-break-after: always;\r\n					margin: 8px -9mm;\r\n					width: calc(100% + 18mm);\r\n					min-height: auto;\r\n					border: 1px solid #000;\r\n					background-color: #fff;\r\n					}\r\n					.invoice-page.continuation-page:last-of-type {\r\n					page-break-after: auto;\r\n					margin-bottom: 0;\r\n					}\r\n					.center { text-align: center; }\r\n					.bold { font-weight: bold; }\r\n					.title { font-size: 16px; font-weight: bold; margin-bottom: 6px; }\r\n					.line { margin: 4px 0; text-align: left; }\r\n					.line-bullet { margin: 0; text-align: left; }\r\n					table.info-table { width: 100%; border-collapse: collapse; }\r\n					table.info-table td { vertical-align: top; padding: 2px 4px; }\r\n\r\n					.party-block { margin: 8px 0 10px 0; }\r\n					table.party-table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 12px; }\r\n					table.party-table td { vertical-align: top; padding: 3px 0; line-height: 1.4; }\r\n					.party-side-label { width: 92px; font-weight: bold; white-space: nowrap; padding-right: 8px; }\r\n					.party-field-label { width: 108px; white-space: nowrap; padding-right: 8px; color: #222; }\r\n					.party-field-label-right { width: 88px; white-space: nowrap; padding: 3px 8px 3px 16px; color: #222; }\r\n					.party-field-value { font-weight: bold; word-break: break-word; }\r\n					.party-field-value-normal { word-break: break-word; }\r\n					.party-name-value { font-weight: bold; word-break: break-word; }\r\n\r\n					table.items {\r\n					width: 100%;\r\n					border-collapse: collapse;\r\n					margin: 6px 0 12px 0;\r\n					font-size: 12px;\r\n					table-layout: fixed;\r\n					}\r\n					table.items thead { display: table-header-group; }\r\n					table.items th,\r\n					table.items td {\r\n					border: 1px solid #000;\r\n					padding: 3px 4px;\r\n					vertical-align: middle;\r\n					}\r\n					table.items th {\r\n					text-align: center;\r\n					font-weight: 700;\r\n					font-size: 11px;\r\n					line-height: 1.25;\r\n					background: #fff;\r\n					}\r\n					table.items td { text-align: left; }\r\n\r\n					.signatures {\r\n					display: table;\r\n					width: 100%;\r\n					margin: 30px 0 0 0;\r\n					table-layout: fixed;\r\n					page-break-inside: avoid;\r\n					}\r\n					.signatures > div {\r\n					display: table-cell;\r\n					vertical-align: top;\r\n					text-align: center;\r\n					padding: 0 10px;\r\n					width: 50%;\r\n					}\r\n					.sign-title {\r\n					font-weight: 700;\r\n					margin-bottom: 4px;\r\n					}\r\n					.sign-sub {\r\n					font-size: 12px;\r\n					}\r\n					.sign-body {\r\n					margin-top: 14px;\r\n					text-align: center;\r\n					font-size: 12px;\r\n					line-height: 1.5;\r\n					}\r\n					.signature-placeholder { height: 100px; }\r\n					.unsigned-name {\r\n					margin-top: 8px;\r\n					font-weight: 700;\r\n					text-transform: uppercase;\r\n					}\r\n					.esign-box {\r\n					display: inline-block;\r\n					margin-top: 8px;\r\n					border: 2px solid red !important;\r\n					padding: 6px 10px;\r\n					text-align: left;\r\n					font-size: 11px;\r\n					color: red !important;\r\n					max-width: 300px;\r\n					line-height: 1.4;\r\n					position: relative;\r\n					-webkit-print-color-adjust: exact;\r\n					print-color-adjust: exact;\r\n					}\r\n					.esign-box .check {\r\n					position: absolute;\r\n					right: 8px;\r\n					bottom: 8px;\r\n					width: 22px;\r\n					height: 22px;\r\n					border-radius: 50%;\r\n					background: #2e7d32;\r\n					color: #fff;\r\n					font-weight: 700;\r\n					text-align: center;\r\n					line-height: 22px;\r\n					font-size: 14px;\r\n					-webkit-print-color-adjust: exact;\r\n					print-color-adjust: exact;\r\n					}\r\n\r\n					.page-header {\r\n					margin-bottom: 12px;\r\n					text-align: center;\r\n					}\r\n					.table-container {\r\n					page-break-inside: avoid;\r\n					}\r\n					.keep-page-end {\r\n					page-break-inside: avoid;\r\n					}\r\n\r\n					@media print {\r\n					html, body {\r\n					background: #fff;\r\n					}\r\n					.invoice-page {\r\n					border: none;\r\n					margin: 0;\r\n					min-height: 0;\r\n					page-break-after: always;\r\n					}\r\n					.invoice-page:last-child,\r\n					.invoice-page.invoice-page-last {\r\n					page-break-after: auto;\r\n					}\r\n					.invoice-page.continuation-page {\r\n					page-break-before: always;\r\n					page-break-after: always;\r\n					margin: 0;\r\n					width: 210mm;\r\n					border: none;\r\n					}\r\n					.invoice-page.continuation-page:last-of-type {\r\n					page-break-after: auto;\r\n					}\r\n					table.items tr { page-break-inside: avoid; }\r\n					}\r\n				</style>\r\n			</head>\r\n			<body>\r\n				<div id="main" class="minute-root">\r\n					<div class="invoice-page document-page">\r\n						<div class="invoice-page-body">\r\n						<div id="header">\r\n							<xsl:call-template name="render-national-header"/>\r\n							<xsl:call-template name="render-bien-ban-title">\r\n								<xsl:with-param name="khms-hdon" select="NDBBan/TTChung/KHMSHDon"/>\r\n								<xsl:with-param name="is-replacement">\r\n									<xsl:choose>\r\n										<xsl:when test="NDBBan/TTChung/TCHDon = \'1\'">true</xsl:when>\r\n										<xsl:otherwise>false</xsl:otherwise>\r\n									</xsl:choose>\r\n								</xsl:with-param>\r\n							</xsl:call-template>\r\n						</div>\r\n						<p class="line">\r\n							-<xsl:text>&#160;&#160;&#160;</xsl:text>Căn cứ Điều 10 Nghị định số 123/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ;\r\n						</p>\r\n						<p class="line">\r\n							-<xsl:text>&#160;&#160;&#160;</xsl:text>Căn cứ Khoản 7 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 sửa đổi, bổ sung một số điều của Nghị định 123/2020/NĐ-CP;\r\n						</p>\r\n						<p class="line">\r\n							Hôm nay, ngày <xsl:call-template name="format-iso-date">\r\n								<xsl:with-param name="date" select="NDBBan/TTChung/NBBan"/>\r\n							</xsl:call-template>, đại diện hai bên gồm có:\r\n						</p>\r\n						<xsl:call-template name="render-party-info">\r\n							<xsl:with-param name="side-label">BÊN BÁN:</xsl:with-param>\r\n							<xsl:with-param name="party-name" select="NDBBan/TTChung/NBan"/>\r\n							<xsl:with-param name="address" select="NDBBan/TTChung/DCNban"/>\r\n							<xsl:with-param name="phone" select="NDBBan/TTChung/TTKhac/DTNDDBBan"/>\r\n							<xsl:with-param name="tax-code" select="NDBBan/TTChung/MSTNBan"/>\r\n							<xsl:with-param name="representative" select="NDBBan/TTChung/TTKhac/TNDDBBan"/>\r\n							<xsl:with-param name="position" select="NDBBan/TTChung/TTKhac/CVNDDBBan"/>\r\n						</xsl:call-template>\r\n						<xsl:call-template name="render-party-info">\r\n							<xsl:with-param name="side-label">BÊN MUA:</xsl:with-param>\r\n							<xsl:with-param name="party-name" select="NDBBan/TTChung/NMua"/>\r\n							<xsl:with-param name="address" select="NDBBan/TTChung/DCNmua"/>\r\n							<xsl:with-param name="phone" select="NDBBan/TTChung/TTKhac/DTNDDBMua"/>\r\n							<xsl:with-param name="tax-code" select="NDBBan/TTChung/MSTNMua"/>\r\n							<xsl:with-param name="representative" select="NDBBan/TTChung/TTKhac/TNDDBMua"/>\r\n							<xsl:with-param name="position" select="NDBBan/TTChung/TTKhac/CVNDDBMua"/>\r\n						</xsl:call-template>\r\n						<p class="line">\r\n							Chúng tôi cùng tiến hành lập biên bản <xsl:value-of select="$LoaiBienBan"/>\r\n							<xsl:text> </xsl:text>\r\n							<xsl:call-template name="ten-chung-tu">\r\n								<xsl:with-param name="khms-hdon" select="NDBBan/TTChung/KHMSHDon"/>\r\n								<xsl:with-param name="mode" select="\'lower\'"/>\r\n							</xsl:call-template>\r\n							sau:\r\n						</p>\r\n						<p class="line">\r\n							<span>\r\n								1. <xsl:call-template name="ten-chung-tu">\r\n									<xsl:with-param name="khms-hdon" select="NDBBan/TTChung/KHMSHDon"/>\r\n									<xsl:with-param name="mode" select="\'sentence\'"/>\r\n								</xsl:call-template>\r\n								trước <xsl:value-of select="$LoaiBienBan"/> có Ký hiệu mẫu số\r\n								<xsl:call-template name="ten-chung-tu">\r\n									<xsl:with-param name="khms-hdon" select="NDBBan/TTChung/KHMSHDon"/>\r\n									<xsl:with-param name="mode" select="\'lower\'"/>\r\n								</xsl:call-template>\r\n							</span>\r\n							<xsl:value-of select="NDBBan/TTChung/KHMSHDon"/>\r\n							<span>, ký hiệu </span>\r\n							<xsl:value-of select="NDBBan/TTChung/KHHDon"/>\r\n							<span>, số </span>\r\n							<xsl:value-of select="NDBBan/TTChung/SHDon"/>\r\n							<span>, phát hành ngày </span>\r\n							<xsl:choose>\r\n								<xsl:when test="normalize-space(NDBBan/TTChung/NLap) != \'\'">\r\n									<xsl:call-template name="format-iso-date">\r\n										<xsl:with-param name="date" select="NDBBan/TTChung/NLap"/>\r\n									</xsl:call-template>\r\n								</xsl:when>\r\n								<xsl:when test="normalize-space(NDBBan/TTChung/TTKhac/NHDon) != \'\'">\r\n									<xsl:call-template name="format-iso-date">\r\n										<xsl:with-param name="date" select="NDBBan/TTChung/TTKhac/NHDon"/>\r\n									</xsl:call-template>\r\n								</xsl:when>\r\n							</xsl:choose>\r\n						</p>\r\n						<p class="line">\r\n							2. Hàng hóa ghi trên <xsl:call-template name="ten-chung-tu">\r\n								<xsl:with-param name="khms-hdon" select="NDBBan/TTChung/KHMSHDon"/>\r\n								<xsl:with-param name="mode" select="\'lower\'"/>\r\n							</xsl:call-template>\r\n							trước <xsl:value-of select="$LoaiBienBan"/> gồm:\r\n						</p>\r\n						<table class="items">\r\n							<xsl:call-template name="render-items-colgroup"/>\r\n							<xsl:call-template name="render-items-header-rows"/>\r\n							<xsl:for-each select="NDBBan/TTChung/DSHHDVuTruoc/HHDVu[STT]">\r\n								<xsl:call-template name="render-hang-hoa-row"/>\r\n							</xsl:for-each>\r\n							<xsl:call-template name="render-table-totals">\r\n								<xsl:with-param name="khms-hdon" select="NDBBan/TTChung/KHMSHDon"/>\r\n								<xsl:with-param name="tg-tcthue" select="NDBBan/TTChung/TToan/TgTCThue"/>\r\n								<xsl:with-param name="tg-tthue" select="NDBBan/TTChung/TToan/TgTThue"/>\r\n								<xsl:with-param name="tg-tttbso" select="NDBBan/TTChung/TToan/TgTTTBSo"/>\r\n								<xsl:with-param name="tg-tttbchu" select="NDBBan/TTChung/TToan/TgTTTBChu"/>\r\n								<xsl:with-param name="tax-rate" select="NDBBan/TTChung/TToan/THTTLTSuat/LTSuat[TSuat != \'-999%\']/TSuat"/>\r\n								<xsl:with-param name="dvtte" select="NDBBan/TTChung/DSHHDVuTruoc/HHDVu/DVTTe"/>\r\n							</xsl:call-template>\r\n						</table>\r\n						<p class="line">\r\n							<xsl:choose>\r\n								<xsl:when test="NDBBan/TTChung/TCHDon = \'1\'">\r\n									<xsl:text>Lý do thay thế:</xsl:text>\r\n								</xsl:when>\r\n								<xsl:otherwise>\r\n									<xsl:text>Lý do điều chỉnh:</xsl:text>\r\n								</xsl:otherwise>\r\n							</xsl:choose>\r\n							<xsl:choose>\r\n								<xsl:when test="contains(NDBBan/TTChung/DSLDTDoi/LDo, \'&#10;\')">\r\n									<br/>\r\n									<xsl:call-template name="multi-line">\r\n										<xsl:with-param name="text" select="NDBBan/TTChung/DSLDTDoi/LDo"/>\r\n									</xsl:call-template>\r\n								</xsl:when>\r\n								<xsl:otherwise>\r\n									<span style="padding-left:4px; font-weight:bold;">\r\n										<xsl:value-of select="NDBBan/TTChung/DSLDTDoi/LDo"/>\r\n									</span>\r\n								</xsl:otherwise>\r\n							</xsl:choose>\r\n						</p>\r\n						<xsl:if test="string(NDBBan/TTChung/TTKhac/LDTruoc) and normalize-space(NDBBan/TTChung/TTKhac/LDTruoc) != \'\'">\r\n							<xsl:variable name="hasNewLineTruoc" select="contains(NDBBan/TTChung/TTKhac/LDTruoc, \'&#10;\')"/>\r\n							<p class="line-bullet">\r\n								-<xsl:text>&#160;&#160;&#160;</xsl:text>Trước <xsl:value-of select="$LoaiBienBan"/>:\r\n								<xsl:choose>\r\n									<xsl:when test="$hasNewLineTruoc">\r\n										<br/>\r\n										<xsl:call-template name="multi-line">\r\n											<xsl:with-param name="text" select="NDBBan/TTChung/TTKhac/LDTruoc"/>\r\n										</xsl:call-template>\r\n									</xsl:when>\r\n									<xsl:otherwise>\r\n										<span style="padding-left:4px; font-weight:bold;">\r\n											&#160;<xsl:value-of select="NDBBan/TTChung/TTKhac/LDTruoc"/>\r\n										</span>\r\n									</xsl:otherwise>\r\n								</xsl:choose>\r\n							</p>\r\n						</xsl:if>\r\n						<xsl:if test="string(NDBBan/TTChung/TTKhac/LDHTai) and normalize-space(NDBBan/TTChung/TTKhac/LDHTai) != \'\'">\r\n							<xsl:variable name="hasNewLineHTai" select="contains(NDBBan/TTChung/TTKhac/LDHTai, \'&#10;\')"/>\r\n							<p class="line-bullet">\r\n								-<xsl:text>&#160;&#160;&#160;</xsl:text>Nay <xsl:value-of select="$LoaiBienBan"/>:\r\n								<xsl:choose>\r\n									<xsl:when test="$hasNewLineHTai">\r\n										<br/>\r\n										<xsl:call-template name="multi-line">\r\n											<xsl:with-param name="text" select="NDBBan/TTChung/TTKhac/LDHTai"/>\r\n										</xsl:call-template>\r\n									</xsl:when>\r\n									<xsl:otherwise>\r\n										<span style="padding-left:4px; font-weight:bold;">\r\n											<xsl:value-of select="NDBBan/TTChung/TTKhac/LDHTai"/>\r\n										</span>\r\n									</xsl:otherwise>\r\n								</xsl:choose>\r\n							</p>\r\n						</xsl:if>\r\n						<!-- Bảng hàng hóa dịch vụ sau thay thế/điều chỉnh -->\r\n						<xsl:if test="count(NDBBan/TTChung/DSHHDVuSau/HHDVu[STT]) &gt; 0 and $MSTNBan != \'0315269974\'">\r\n							<p class="line">\r\n								3. Hàng hóa ghi trên <xsl:call-template name="ten-chung-tu">\r\n									<xsl:with-param name="khms-hdon" select="NDBBan/TTChung/KHMSHDon"/>\r\n									<xsl:with-param name="mode" select="\'lower\'"/>\r\n								</xsl:call-template>\r\n								sau <xsl:value-of select="$LoaiBienBan"/> gồm:\r\n							</p>\r\n							<xsl:call-template name="paginate-items">\r\n								<xsl:with-param name="items" select="NDBBan/TTChung/DSHHDVuSau/HHDVu[STT]"/>\r\n								<xsl:with-param name="page-size" select="25"/>\r\n								<xsl:with-param name="current-page" select="1"/>\r\n								<xsl:with-param name="is-first-page" select="true()"/>\r\n							</xsl:call-template>\r\n						</xsl:if>\r\n						<div class="keep-page-end">\r\n							<p class="line" style="padding-top: 20px;">\r\n								Chúng tôi cam kết và hoàn toàn chịu trách nhiệm về việc <xsl:value-of select="$LoaiBienBan"/>\r\n								<xsl:text> </xsl:text>\r\n								<xsl:call-template name="ten-chung-tu">\r\n									<xsl:with-param name="khms-hdon" select="NDBBan/TTChung/KHMSHDon"/>\r\n									<xsl:with-param name="mode" select="\'lower\'"/>\r\n								</xsl:call-template>\r\n								này.<br/>Biên bản này lập thành 02 bản, Bên bán giữ 01 bán, Bên mua giữ 01 bản.\r\n							</p>\r\n							<div class="signatures">\r\n								<xsl:call-template name="render-signature-slot">\r\n									<xsl:with-param name="label">ĐẠI DIỆN BÊN BÁN</xsl:with-param>\r\n									<xsl:with-param name="has-signature">\r\n										<xsl:choose>\r\n											<xsl:when test="$hasNBanSignature">true</xsl:when>\r\n											<xsl:otherwise>false</xsl:otherwise>\r\n										</xsl:choose>\r\n									</xsl:with-param>\r\n									<xsl:with-param name="side">NBan</xsl:with-param>\r\n									<xsl:with-param name="party-name" select="NDBBan/TTChung/NBan"/>\r\n									<xsl:with-param name="representative-name" select="NDBBan/TTChung/TTKhac/TNDDBBan"/>\r\n								</xsl:call-template>\r\n								<xsl:call-template name="render-signature-slot">\r\n									<xsl:with-param name="label">ĐẠI DIỆN BÊN MUA</xsl:with-param>\r\n									<xsl:with-param name="has-signature">\r\n										<xsl:choose>\r\n											<xsl:when test="$hasNMuaSignature">true</xsl:when>\r\n											<xsl:otherwise>false</xsl:otherwise>\r\n										</xsl:choose>\r\n									</xsl:with-param>\r\n									<xsl:with-param name="side">NMua</xsl:with-param>\r\n									<xsl:with-param name="party-name" select="NDBBan/TTChung/NMua"/>\r\n									<xsl:with-param name="representative-name" select="NDBBan/TTChung/TTKhac/TNDDBMua"/>\r\n								</xsl:call-template>\r\n							</div>\r\n						</div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</body>\r\n		</html>\r\n	</xsl:template>\r\n	<xsl:template name="render-party-info">\r\n		<xsl:param name="side-label"/>\r\n		<xsl:param name="party-name"/>\r\n		<xsl:param name="address"/>\r\n		<xsl:param name="phone"/>\r\n		<xsl:param name="tax-code"/>\r\n		<xsl:param name="representative"/>\r\n		<xsl:param name="position"/>\r\n		<div class="party-block">\r\n			<table class="party-table">\r\n				<colgroup>\r\n					<col style="width:92px"/>\r\n					<col style="width:108px"/>\r\n					<col style="width:34%"/>\r\n					<col style="width:88px"/>\r\n					<col/>\r\n				</colgroup>\r\n				<tr>\r\n					<td class="party-side-label">\r\n						<xsl:value-of select="$side-label"/>\r\n					</td>\r\n					<td colspan="4" class="party-name-value">\r\n						<xsl:value-of select="$party-name"/>\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td/>\r\n					<td class="party-field-label">Địa chỉ:</td>\r\n					<td colspan="3" class="party-field-value">\r\n						<xsl:value-of select="$address"/>\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td/>\r\n					<td class="party-field-label">Điện thoại:</td>\r\n					<td class="party-field-value-normal">\r\n						<xsl:value-of select="$phone"/>\r\n					</td>\r\n					<td class="party-field-label-right">MST:</td>\r\n					<td class="party-field-value">\r\n						<xsl:value-of select="$tax-code"/>\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td/>\r\n					<td class="party-field-label">Do Ông (Bà):</td>\r\n					<td class="party-field-value-normal">\r\n						<xsl:value-of select="$representative"/>\r\n					</td>\r\n					<td class="party-field-label-right">Chức vụ:</td>\r\n					<td class="party-field-value-normal">\r\n						<xsl:value-of select="$position"/>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n		</div>\r\n	</xsl:template>\r\n	<xsl:template name="render-cks-block">\r\n		<xsl:param name="side"/>\r\n		<xsl:param name="party-name"/>\r\n		<xsl:variable name="signing-time" select="/BBan/DSCKS/*[local-name()=$side]/*[local-name()=\'Signature\']//*[local-name()=\'SigningTime\'][1]"/>\r\n		<div class="esign-box">\r\n			<xsl:attribute name="id">\r\n				<xsl:value-of select="concat(\'CKS_\', $side)"/>\r\n			</xsl:attribute>\r\n			<div>\r\n				<strong>Ký điện tử bởi:</strong>\r\n			</div>\r\n			<div>\r\n				<xsl:value-of select="$party-name"/>\r\n			</div>\r\n			<div>\r\n				Ký ngày\r\n				<xsl:text> </xsl:text>\r\n				<xsl:call-template name="format-iso-date">\r\n					<xsl:with-param name="date" select="substring(normalize-space($signing-time), 1, 10)"/>\r\n				</xsl:call-template>\r\n			</div>\r\n			<div class="check">&#10003;</div>\r\n		</div>\r\n	</xsl:template>\r\n	<xsl:template name="multi-line">\r\n		<xsl:param name="text"/>\r\n		<xsl:choose>\r\n			<xsl:when test="contains($text, \'&#10;\')">\r\n				<span style="padding-left:24px; font-weight:bold;">\r\n					&#9;<xsl:value-of select="substring-before($text, \'&#10;\')"/>\r\n				</span>\r\n				<br/>\r\n				<xsl:call-template name="multi-line">\r\n					<xsl:with-param name="text" select="substring-after($text, \'&#10;\')"/>\r\n				</xsl:call-template>\r\n			</xsl:when>\r\n			<xsl:otherwise>\r\n				<span style="padding-left:24px; font-weight:bold;">\r\n					&#9;<xsl:value-of select="$text"/>\r\n				</span>\r\n			</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:template>\r\n	<!-- Template format số VNĐ: chỉ thêm dấu phẩy hàng nghìn, giữ nguyên phần thập phân -->\r\n	<xsl:template name="format-vnd">\r\n		<xsl:param name="number"/>\r\n		<xsl:choose>\r\n			<xsl:when test="contains($number, \'.\')">\r\n				<!-- Có phần thập phân -->\r\n				<xsl:variable name="integerPart" select="substring-before($number, \'.\')"/>\r\n				<xsl:variable name="decimalPart" select="substring-after($number, \'.\')"/>\r\n				<xsl:call-template name="format-integer-part">\r\n					<xsl:with-param name="num" select="$integerPart"/>\r\n				</xsl:call-template>\r\n				<xsl:choose>\r\n					<xsl:when test="$isNgoaiTe = \'true\'">\r\n						<xsl:text>,</xsl:text>\r\n					</xsl:when>\r\n					<xsl:otherwise>\r\n						<xsl:text>.</xsl:text>\r\n					</xsl:otherwise>\r\n				</xsl:choose>\r\n				<xsl:value-of select="$decimalPart"/>\r\n			</xsl:when>\r\n			<xsl:otherwise>\r\n				<!-- Không có phần thập phân -->\r\n				<xsl:call-template name="format-integer-part">\r\n					<xsl:with-param name="num" select="$number"/>\r\n				</xsl:call-template>\r\n			</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:template>\r\n	<!-- Template phụ để format phần nguyên -->\r\n	<xsl:template name="format-integer-part">\r\n		<xsl:param name="num"/>\r\n		<xsl:variable name="isNegative" select="starts-with($num, \'-\')"/>\r\n		<xsl:variable name="absNum">\r\n			<xsl:choose>\r\n				<xsl:when test="$isNegative">\r\n					<xsl:value-of select="substring($num, 2)"/>\r\n				</xsl:when>\r\n				<xsl:otherwise>\r\n					<xsl:value-of select="$num"/>\r\n				</xsl:otherwise>\r\n			</xsl:choose>\r\n		</xsl:variable>\r\n		<xsl:variable name="len" select="string-length($absNum)"/>\r\n		<xsl:if test="$isNegative">\r\n			<xsl:text>-</xsl:text>\r\n		</xsl:if>\r\n		<xsl:choose>\r\n			<xsl:when test="$len &gt; 3">\r\n				<xsl:call-template name="format-integer-part">\r\n					<xsl:with-param name="num" select="substring($absNum, 1, $len - 3)"/>\r\n				</xsl:call-template>\r\n				<xsl:choose>\r\n					<xsl:when test="$isNgoaiTe = \'true\'">\r\n						<xsl:text>.</xsl:text>\r\n					</xsl:when>\r\n					<xsl:otherwise>\r\n						<xsl:text>,</xsl:text>\r\n					</xsl:otherwise>\r\n				</xsl:choose>\r\n				<xsl:value-of select="substring($absNum, $len - 2, 3)"/>\r\n			</xsl:when>\r\n			<xsl:otherwise>\r\n				<xsl:value-of select="$absNum"/>\r\n			</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:template>\r\n\r\n	<!-- Template để đếm số chữ số thập phân -->\r\n	<xsl:template name="count-decimals">\r\n		<xsl:param name="number"/>\r\n		<xsl:choose>\r\n			<xsl:when test="contains($number, \'.\')">\r\n				<xsl:value-of select="string-length(substring-after($number, \'.\'))"/>\r\n			</xsl:when>\r\n			<xsl:otherwise>0</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:template>\r\n\r\n	<!-- Template để format số với số chữ số thập phân cố định -->\r\n	<xsl:template name="format-with-decimals">\r\n		<xsl:param name="number"/>\r\n		<xsl:param name="decimal-places"/>\r\n		<xsl:variable name="integerPart">\r\n			<xsl:choose>\r\n				<xsl:when test="contains($number, \'.\')">\r\n					<xsl:value-of select="substring-before($number, \'.\')"/>\r\n				</xsl:when>\r\n				<xsl:otherwise>\r\n					<xsl:value-of select="$number"/>\r\n				</xsl:otherwise>\r\n			</xsl:choose>\r\n		</xsl:variable>\r\n		<xsl:variable name="decimalPart">\r\n			<xsl:choose>\r\n				<xsl:when test="contains($number, \'.\')">\r\n					<xsl:value-of select="substring-after($number, \'.\')"/>\r\n				</xsl:when>\r\n				<xsl:otherwise></xsl:otherwise>\r\n			</xsl:choose>\r\n		</xsl:variable>\r\n		<!-- Format phần nguyên -->\r\n		<xsl:call-template name="format-integer-part">\r\n			<xsl:with-param name="num" select="$integerPart"/>\r\n		</xsl:call-template>\r\n		<!-- Thêm phần thập phân nếu cần -->\r\n		<xsl:if test="$decimal-places &gt; 0">\r\n			<xsl:choose>\r\n				<xsl:when test="$isNgoaiTe = \'true\'">\r\n					<xsl:text>,</xsl:text>\r\n				</xsl:when>\r\n				<xsl:otherwise>\r\n					<xsl:text>.</xsl:text>\r\n				</xsl:otherwise>\r\n			</xsl:choose>\r\n			<xsl:variable name="currentDecimals" select="string-length($decimalPart)"/>\r\n			<xsl:value-of select="$decimalPart"/>\r\n			<!-- Thêm số 0 nếu cần -->\r\n			<xsl:if test="$currentDecimals &lt; $decimal-places">\r\n				<xsl:call-template name="pad-zeros">\r\n					<xsl:with-param name="count" select="$decimal-places - $currentDecimals"/>\r\n				</xsl:call-template>\r\n			</xsl:if>\r\n		</xsl:if>\r\n	</xsl:template>\r\n\r\n	<!-- Template để thêm số 0 -->\r\n	<xsl:template name="pad-zeros">\r\n		<xsl:param name="count"/>\r\n		<xsl:if test="$count &gt; 0">\r\n			<xsl:text>0</xsl:text>\r\n			<xsl:call-template name="pad-zeros">\r\n				<xsl:with-param name="count" select="$count - 1"/>\r\n			</xsl:call-template>\r\n		</xsl:if>\r\n	</xsl:template>\r\n\r\n	<!-- Template để tìm số chữ số thập phân tối đa trong một tập hợp nodes -->\r\n	<xsl:template name="find-max-decimals">\r\n		<xsl:param name="nodes"/>\r\n		<xsl:param name="current-max" select="0"/>\r\n		<xsl:param name="position" select="1"/>\r\n		<xsl:choose>\r\n			<xsl:when test="$position &lt;= count($nodes)">\r\n				<xsl:variable name="current-decimals">\r\n					<xsl:call-template name="count-decimals">\r\n						<xsl:with-param name="number" select="$nodes[$position]"/>\r\n					</xsl:call-template>\r\n				</xsl:variable>\r\n				<xsl:variable name="new-max">\r\n					<xsl:choose>\r\n						<xsl:when test="$current-decimals &gt; $current-max">\r\n							<xsl:value-of select="$current-decimals"/>\r\n						</xsl:when>\r\n						<xsl:otherwise>\r\n							<xsl:value-of select="$current-max"/>\r\n						</xsl:otherwise>\r\n					</xsl:choose>\r\n				</xsl:variable>\r\n				<xsl:call-template name="find-max-decimals">\r\n					<xsl:with-param name="nodes" select="$nodes"/>\r\n					<xsl:with-param name="current-max" select="$new-max"/>\r\n					<xsl:with-param name="position" select="$position + 1"/>\r\n				</xsl:call-template>\r\n			</xsl:when>\r\n			<xsl:otherwise>\r\n				<xsl:value-of select="$current-max"/>\r\n			</xsl:otherwise>\r\n		</xsl:choose>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="render-paginate-table">\r\n		<xsl:param name="items"/>\r\n		<xsl:param name="start-index"/>\r\n		<xsl:param name="end-index"/>\r\n		<xsl:param name="has-more-pages"/>\r\n		<div class="table-container">\r\n			<table class="items">\r\n				<xsl:call-template name="render-items-colgroup"/>\r\n				<thead>\r\n					<xsl:call-template name="render-items-header-rows"/>\r\n				</thead>\r\n				<tbody>\r\n					<xsl:for-each select="$items[position() &gt;= $start-index and position() &lt;= $end-index]">\r\n						<xsl:call-template name="render-hang-hoa-row"/>\r\n					</xsl:for-each>\r\n				</tbody>\r\n				<xsl:if test="not($has-more-pages)">\r\n					<tbody>\r\n						<xsl:call-template name="render-table-totals">\r\n							<xsl:with-param name="khms-hdon" select="/BBan/NDBBan/TTChung/KHMSHDon"/>\r\n							<xsl:with-param name="tg-tcthue" select="/BBan/NDBBan/TTChung/ATToan/TgTCThue"/>\r\n							<xsl:with-param name="tg-tthue" select="/BBan/NDBBan/TTChung/ATToan/TgTThue"/>\r\n							<xsl:with-param name="tg-tttbso" select="/BBan/NDBBan/TTChung/ATToan/TgTTTBSo"/>\r\n							<xsl:with-param name="tg-tttbchu" select="/BBan/NDBBan/TTChung/ATToan/TgTTTBChu"/>\r\n							<xsl:with-param name="tax-rate" select="/BBan/NDBBan/TTChung/ATToan/THTTLTSuat/LTSuat[TSuat != \'-999%\']/TSuat"/>\r\n							<xsl:with-param name="dvtte" select="/BBan/NDBBan/TTChung/DSHHDVuSau/HHDVu/DVTTe"/>\r\n							<xsl:with-param name="bold" select="\'true\'"/>\r\n							<xsl:with-param name="italic-chu" select="\'true\'"/>\r\n							<xsl:with-param name="show-giam" select="\'true\'"/>\r\n						</xsl:call-template>\r\n					</tbody>\r\n				</xsl:if>\r\n			</table>\r\n		</div>\r\n	</xsl:template>\r\n\r\n	<xsl:template name="paginate-items">\r\n		<xsl:param name="items"/>\r\n		<xsl:param name="page-size" select="25"/>\r\n		<xsl:param name="current-page" select="1"/>\r\n		<xsl:param name="is-first-page" select="true()"/>\r\n		<xsl:variable name="total-items" select="count($items)"/>\r\n		<xsl:variable name="start-index" select="($current-page - 1) * $page-size + 1"/>\r\n		<xsl:variable name="end-index" select="$current-page * $page-size"/>\r\n		<xsl:variable name="has-more-pages" select="$total-items &gt; $end-index"/>\r\n		<xsl:choose>\r\n			<xsl:when test="not($is-first-page)">\r\n				<div class="invoice-page continuation-page">\r\n					<div class="invoice-page-body">\r\n						<div class="page-header">\r\n							<xsl:call-template name="render-national-header"/>\r\n							<xsl:call-template name="render-bien-ban-title">\r\n								<xsl:with-param name="khms-hdon" select="/BBan/NDBBan/TTChung/KHMSHDon"/>\r\n								<xsl:with-param name="is-replacement">\r\n									<xsl:choose>\r\n										<xsl:when test="/BBan/NDBBan/TTChung/TCHDon = \'1\'">true</xsl:when>\r\n										<xsl:otherwise>false</xsl:otherwise>\r\n									</xsl:choose>\r\n								</xsl:with-param>\r\n								<xsl:with-param name="continuation">(tiếp theo)</xsl:with-param>\r\n							</xsl:call-template>\r\n							<xsl:if test="count($items) &gt; 0 and $MSTNBan != \'0315269974\'">\r\n								<p class="line" style="margin-bottom: 12px;">\r\n									3. Hàng hóa ghi trên\r\n									<xsl:call-template name="ten-chung-tu">\r\n										<xsl:with-param name="khms-hdon" select="/BBan/NDBBan/TTChung/KHMSHDon"/>\r\n										<xsl:with-param name="mode" select="\'lower\'"/>\r\n									</xsl:call-template>\r\n									sau <xsl:value-of select="$LoaiBienBan"/> gồm: (tiếp theo)\r\n								</p>\r\n							</xsl:if>\r\n						</div>\r\n						<xsl:call-template name="render-paginate-table">\r\n							<xsl:with-param name="items" select="$items"/>\r\n							<xsl:with-param name="start-index" select="$start-index"/>\r\n							<xsl:with-param name="end-index" select="$end-index"/>\r\n							<xsl:with-param name="has-more-pages" select="$has-more-pages"/>\r\n						</xsl:call-template>\r\n					</div>\r\n				</div>\r\n			</xsl:when>\r\n			<xsl:otherwise>\r\n				<xsl:call-template name="render-paginate-table">\r\n					<xsl:with-param name="items" select="$items"/>\r\n					<xsl:with-param name="start-index" select="$start-index"/>\r\n					<xsl:with-param name="end-index" select="$end-index"/>\r\n					<xsl:with-param name="has-more-pages" select="$has-more-pages"/>\r\n				</xsl:call-template>\r\n			</xsl:otherwise>\r\n		</xsl:choose>\r\n		<xsl:if test="$has-more-pages">\r\n			<xsl:call-template name="paginate-items">\r\n				<xsl:with-param name="items" select="$items"/>\r\n				<xsl:with-param name="page-size" select="$page-size"/>\r\n				<xsl:with-param name="current-page" select="$current-page + 1"/>\r\n				<xsl:with-param name="is-first-page" select="false()"/>\r\n			</xsl:call-template>\r\n		</xsl:if>\r\n	</xsl:template>\r\n</xsl:stylesheet>', 1, 0, '/home/WEB/amnoteweb/ElectronicDocuments/shared/xsl/57/613b9b4f103c4fc5b41bb76ccdff3dc0/57983aec0891217ebf85ce75c8cb88324979d36fc48052652d6fd568643ce254.xsl'),
	(10, 'EMAIL', 'EMAIL_SEND_BBAN', 'Email gửi biên bản điều chỉnh/thay thế', 'Biên bản {{DISPLAY_NO}} - {{SELLER_NM}}', '<!DOCTYPE html>\r\n<html lang="vi">\r\n<head>\r\n  <meta charset="utf-8" />\r\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\r\n  <title>Biên bản hóa đơn điện tử</title>\r\n</head>\r\n<body style="margin:0;padding:0;background-color:#f4f6f8;font-family:Arial,Helvetica,sans-serif;color:#1f2937;">\r\n  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f8;padding:24px 12px;">\r\n    <tr>\r\n      <td align="center">\r\n        <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">\r\n          <tr>\r\n            <td style="background:#0f766e;color:#ffffff;padding:20px 24px;">\r\n              <div style="font-size:18px;font-weight:bold;">{{SELLER_NM}}</div>\r\n              <div style="font-size:13px;margin-top:4px;opacity:0.95;">MST: {{SELLER_MST}}</div>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <td style="padding:24px;">\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.6;">\r\n                Kính gửi <strong>{{NMUA_TEN}}</strong>,\r\n              </p>\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.6;">\r\n                Công ty chúng tôi xin gửi đến Quý khách <strong>{{TBBAN}}</strong> với thông tin như sau:\r\n              </p>\r\n              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 20px;font-size:14px;">\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;width:38%;">Số biên bản</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;"><strong>{{SBBAN}}</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ngày biên bản</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;">{{NBBAN}}</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Hóa đơn liên quan</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;">{{KHMSHDON}}/{{KHHDON}} - Số {{SHDON}}</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ngày lập HĐ gốc</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;">{{NLAP}}</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Mã tra cứu</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;"><strong>{{MTRACUU}}</strong></td>\r\n                </tr>\r\n              </table>\r\n              <p style="margin:0 0 16px;font-size:14px;line-height:1.6;">\r\n                File PDF biên bản được đính kèm trong email này.\r\n              </p>\r\n              <p style="margin:0 0 20px;font-size:14px;line-height:1.6;">\r\n                Quý khách có thể tra cứu biên bản trực tuyến tại:\r\n              </p>\r\n              <p style="margin:0 0 20px;text-align:center;">\r\n                <a href="http://localhost:5173/tra-cuu-bien-ban-amnote/{{SELLER_MST}}?mtracuu={{MTRACUU}}"\r\n                   style="display:inline-block;background:#0f766e;color:#ffffff;text-decoration:none;padding:12px 24px;border-radius:6px;font-size:14px;font-weight:bold;">\r\n                  Tra cứu biên bản\r\n                </a>\r\n              </p>\r\n              <p style="margin:0;font-size:14px;line-height:1.6;">\r\n                Trân trọng cảm ơn.<br />\r\n                <strong>{{SELLER_NM}}</strong>\r\n              </p>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <td style="padding:14px 24px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;line-height:1.5;">\r\n              Email này được gửi tự động từ hệ thống hóa đơn điện tử AMNOTE. Vui lòng không trả lời trực tiếp email này.\r\n            </td>\r\n          </tr>\r\n        </table>\r\n      </td>\r\n    </tr>\r\n  </table>\r\n</body>\r\n</html>', 1, 0, NULL),
	(11, 'EMAIL', 'EMAIL_SEND_TBAO', 'Email thông báo sai sót', 'Thông báo sai sót {{DISPLAY_NO}} - {{TNNT}}', '<!DOCTYPE html>\r\n<html lang="vi">\r\n<head>\r\n  <meta charset="utf-8" />\r\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\r\n  <title>Thông báo sai sót</title>\r\n</head>\r\n<body style="margin:0;padding:0;background-color:#f4f6f8;font-family:Arial,Helvetica,sans-serif;color:#1f2937;">\r\n  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f8;padding:24px 12px;">\r\n    <tr>\r\n      <td align="center">\r\n        <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">\r\n          <tr>\r\n            <td style="background:#1d4f7c;color:#ffffff;padding:20px 24px;">\r\n              <div style="font-size:18px;font-weight:bold;">{{TNNT}}</div>\r\n              <div style="font-size:13px;margin-top:4px;opacity:0.95;">MST: {{MST}}</div>\r\n            </td>\r\n          </tr>\r\n\r\n          <tr>\r\n            <td style="padding:24px;">\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.6;">\r\n                Kính gửi Quý khách,\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.6;">\r\n                Chúng tôi xin gửi đến Quý khách <strong>{{TEN}}</strong> với thông tin như sau:\r\n              </p>\r\n\r\n              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 20px;font-size:14px;">\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;width:38%;">Mẫu số</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;"><strong>{{MSO}}</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Số thông báo</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;">{{SO}}</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ngày thông báo</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;">{{NTBAO}}</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Cơ quan thuế</td>\r\n                  <td style="padding:10px 12px;border:1px solid #e5e7eb;">{{TCQT}}</td>\r\n                </tr>\r\n              </table>\r\n\r\n              <p style="margin:0 0 16px;font-size:14px;line-height:1.6;">\r\n                File PDF/XML của thông báo được đính kèm trong email này.\r\n              </p>\r\n\r\n              <p style="margin:0;font-size:14px;line-height:1.6;">\r\n                Trân trọng cảm ơn.<br />\r\n                <strong>{{TNNT}}</strong>\r\n              </p>\r\n            </td>\r\n          </tr>\r\n\r\n          <tr>\r\n            <td style="padding:14px 24px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;line-height:1.5;">\r\n              Email này được gửi tự động từ hệ thống hóa đơn điện tử. Vui lòng không trả lời trực tiếp email này.\r\n            </td>\r\n          </tr>\r\n        </table>\r\n      </td>\r\n    </tr>\r\n  </table>\r\n</body>\r\n</html>', 1, 0, NULL),
	(12, 'XSL', '01/ĐKTĐ-CTĐT', '', NULL, '<?xml version="1.0" encoding="UTF-8"?>\r\n<xsl:stylesheet version="2.0"\r\n  xmlns:xsl="http://www.w3.org/1999/XSL/Transform"\r\n  xmlns:xs="http://www.w3.org/2001/XMLSchema"\r\n  xmlns:f="urn:amnote:pit:declaration"\r\n  exclude-result-prefixes="xs f">\r\n\r\n  <xsl:output method="html" encoding="UTF-8" indent="yes"/>\r\n\r\n  <xsl:function name="f:child" as="xs:string">\r\n    <xsl:param name="node" as="node()?"/>\r\n    <xsl:param name="name" as="xs:string"/>\r\n    <xsl:sequence select="normalize-space(string(($node/*[local-name() = $name])[1]))"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:any" as="xs:string">\r\n    <xsl:param name="node" as="node()?"/>\r\n    <xsl:param name="names" as="xs:string*"/>\r\n    <xsl:variable name="matches" select="$node/*[local-name() = $names]"/>\r\n    <xsl:sequence select="normalize-space(string(($matches[string-length(normalize-space(string(.))) &gt; 0][1], $matches[1])[1]))"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:flag" as="xs:boolean">\r\n    <xsl:param name="node" as="node()?"/>\r\n    <xsl:param name="name" as="xs:string"/>\r\n    <xsl:variable name="value" select="upper-case(f:child($node, $name))"/>\r\n    <xsl:sequence select="$value = (\'1\', \'TRUE\', \'Y\', \'YES\', \'X\')"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:box" as="xs:string">\r\n    <xsl:param name="selected" as="xs:boolean"/>\r\n    <xsl:sequence select="if ($selected) then \'☑\' else \'□\'"/>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\')">\r\n        <xsl:sequence select="concat(substring($text, 9, 2), \'/\', substring($text, 6, 2), \'/\', substring($text, 1, 4))"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:date-part" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:param name="part" as="xs:string"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'day\'">\r\n        <xsl:sequence select="substring($text, 9, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'month\'">\r\n        <xsl:sequence select="substring($text, 6, 2)"/>\r\n      </xsl:when>\r\n      <xsl:when test="matches($text, \'^\\d{4}-\\d{2}-\\d{2}\') and $part = \'year\'">\r\n        <xsl:sequence select="substring($text, 1, 4)"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="\'......\'"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:function name="f:certificate-method" as="xs:string">\r\n    <xsl:param name="value" as="xs:string?"/>\r\n    <xsl:variable name="text" select="normalize-space(string($value))"/>\r\n    <xsl:choose>\r\n      <xsl:when test="$text = \'1\'">\r\n        <xsl:sequence select="\'Thêm mới\'"/>\r\n      </xsl:when>\r\n      <xsl:when test="$text = \'2\'">\r\n        <xsl:sequence select="\'Gia hạn\'"/>\r\n      </xsl:when>\r\n      <xsl:when test="$text = \'3\'">\r\n        <xsl:sequence select="\'Ngừng sử dụng\'"/>\r\n      </xsl:when>\r\n      <xsl:otherwise>\r\n        <xsl:sequence select="$text"/>\r\n      </xsl:otherwise>\r\n    </xsl:choose>\r\n  </xsl:function>\r\n\r\n  <xsl:template match="/">\r\n    <xsl:variable name="root" select="/*[local-name() = \'TKhai\']"/>\r\n    <xsl:variable name="dl" select="$root/*[local-name() = \'DLTKhai\']"/>\r\n    <xsl:variable name="tt" select="$dl/*[local-name() = \'TTChung\']"/>\r\n    <xsl:variable name="nd" select="$dl/*[local-name() = \'NDTKhai\']"/>\r\n    <xsl:variable name="dtphanh" select="$nd/*[local-name() = \'DTPHanh\']"/>\r\n    <xsl:variable name="lhsdung" select="$nd/*[local-name() = \'LHSDung\']"/>\r\n    <xsl:variable name="htgd" select="$nd/*[local-name() = (\'HTGDLCTDT\', \'HTGDLHDDT\')][1]"/>\r\n    <xsl:variable name="ctsRows" select="$nd/*[local-name() = \'DSCTSSDung\']/*[local-name() = \'CTS\']"/>\r\n    <xsl:variable name="delegateRows" select="$nd//*[local-name() = (\'DKTH\', \'UNhiem\', \'DKUNhiem\', \'DKBL\')]"/>\r\n    <xsl:variable name="hasNntSignature" select="exists($root/*[local-name() = \'DSCKS\']/*[local-name() = \'NNT\']/*[local-name() = \'Signature\']/*)"/>\r\n    <xsl:variable name="formCode" select="if (f:child($tt, \'MSo\') != \'\') then f:child($tt, \'MSo\') else \'01/ĐKTĐ-CTĐT\'"/>\r\n    <xsl:variable name="formTitle" select="if (f:child($tt, \'Ten\') != \'\') then f:child($tt, \'Ten\') else \'Đăng ký/thay đổi thông tin sử dụng chứng từ điện tử\'"/>\r\n\r\n    <html>\r\n      <head>\r\n        <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>\r\n        <title><xsl:value-of select="$formCode"/></title>\r\n        <style>\r\n          @page {\r\n            size: A4 portrait;\r\n            margin: 0;\r\n          }\r\n\r\n          * {\r\n            box-sizing: border-box;\r\n          }\r\n\r\n          body {\r\n            margin: 0;\r\n            background: #f3f4f6;\r\n            color: #000;\r\n            font-family: "Times New Roman", Times, serif;\r\n            font-size: 12px;\r\n            line-height: 1.15;\r\n          }\r\n\r\n          .page {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            margin: 0 auto 14px;\r\n            padding: 12mm 15mm 16mm;\r\n            background: #fff;\r\n            page-break-after: always;\r\n          }\r\n\r\n          .page:last-child {\r\n            page-break-after: auto;\r\n          }\r\n\r\n          .form-code {\r\n            font-weight: 700;\r\n          }\r\n\r\n          .national {\r\n            margin-top: 2mm;\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .national .line {\r\n            display: inline-block;\r\n            min-width: 150px;\r\n            border-top: 1px solid #000;\r\n            margin-top: 3px;\r\n          }\r\n\r\n          .title {\r\n            margin: 18px 0 10px;\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .title .main {\r\n            font-size: 14px;\r\n            text-transform: uppercase;\r\n          }\r\n\r\n          .form-option {\r\n            margin: 14px 0 18px;\r\n            text-align: center;\r\n          }\r\n\r\n          table {\r\n            width: 100%;\r\n            border-collapse: collapse;\r\n          }\r\n\r\n          td,\r\n          th {\r\n            border: 1px solid #000;\r\n            padding: 2px 4px;\r\n            vertical-align: middle;\r\n          }\r\n\r\n          th {\r\n            text-align: center;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .info-table td {\r\n            height: 21px;\r\n          }\r\n\r\n          .label {\r\n            width: 26%;\r\n          }\r\n\r\n          .right-label {\r\n            width: 24%;\r\n          }\r\n\r\n          .value {\r\n            min-height: 16px;\r\n          }\r\n\r\n          .intro {\r\n            padding: 6px 8px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .section-title {\r\n            border: 1px solid #000;\r\n            border-top: 0;\r\n            padding: 5px 6px;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .section-box {\r\n            border: 1px solid #000;\r\n            border-top: 0;\r\n            padding: 8px 8px 10px;\r\n          }\r\n\r\n          .checkbox-line {\r\n            margin: 2px 0;\r\n            padding-left: 32px;\r\n            text-indent: -16px;\r\n          }\r\n\r\n          .checkbox-sub {\r\n            margin: 2px 0 2px 28px;\r\n            padding-left: 32px;\r\n            text-indent: -16px;\r\n          }\r\n\r\n          .narrow-table th,\r\n          .narrow-table td {\r\n            padding: 3px 3px;\r\n            text-align: center;\r\n          }\r\n\r\n          .narrow-table td.text-left,\r\n          .narrow-table th.text-left {\r\n            text-align: left;\r\n          }\r\n\r\n          .section-heading-row td {\r\n            padding: 4px 6px;\r\n            font-weight: 700;\r\n            text-align: left;\r\n          }\r\n\r\n          .note {\r\n            margin-top: 18px;\r\n            text-align: justify;\r\n          }\r\n\r\n          .signature {\r\n            margin-top: 30px;\r\n            text-align: center;\r\n          }\r\n\r\n          .signature .date-line {\r\n            font-style: italic;\r\n          }\r\n\r\n          .signature .name {\r\n            margin-top: 3px;\r\n            font-weight: 700;\r\n          }\r\n\r\n          .signature .hint {\r\n            font-style: italic;\r\n          }\r\n\r\n          .signed {\r\n            margin-top: 8px;\r\n            font-style: italic;\r\n            font-weight: 700;\r\n          }\r\n\r\n          @media print {\r\n            body {\r\n              background: #fff;\r\n            }\r\n\r\n            .page {\r\n              margin: 0;\r\n              box-shadow: none;\r\n            }\r\n          }\r\n        </style>\r\n      </head>\r\n      <body>\r\n        <div class="page">\r\n          <div class="form-code">Mẫu số: <xsl:value-of select="$formCode"/></div>\r\n\r\n          <div class="national">\r\n            CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM<br/>\r\n            Độc lập - Tự do - Hạnh phúc<br/>\r\n            <span class="line"></span>\r\n          </div>\r\n\r\n          <div class="title">\r\n            <div class="main">TỜ KHAI</div>\r\n            <div><xsl:value-of select="$formTitle"/></div>\r\n            <div>---------</div>\r\n          </div>\r\n\r\n          <div class="form-option">\r\n            <div><xsl:value-of select="f:box(f:child($tt, \'HThuc\') = \'1\')"/> Đăng ký mới</div>\r\n            <div><xsl:value-of select="f:box(f:child($tt, \'HThuc\') = \'2\')"/> Thay đổi thông tin</div>\r\n          </div>\r\n\r\n          <table class="info-table">\r\n            <tr>\r\n              <td class="label">Tên người nộp thuế:</td>\r\n              <td colspan="3" class="value"><xsl:value-of select="f:child($tt, \'TNNT\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Mã số thuế:</td>\r\n              <td colspan="3" class="value"><xsl:value-of select="f:child($tt, \'MST\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Cơ quan thuế quản lý:</td>\r\n              <td colspan="3" class="value"><xsl:value-of select="f:child($tt, \'CQTQLy\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Người liên hệ:</td>\r\n              <td class="value"><xsl:value-of select="f:child($tt, \'NLHe\')"/></td>\r\n              <td class="right-label">Điện thoại liên hệ:</td>\r\n              <td class="value"><xsl:value-of select="f:child($tt, \'DTLHe\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td class="label">Địa chỉ liên hệ:</td>\r\n              <td class="value"><xsl:value-of select="f:child($tt, \'DCLHe\')"/></td>\r\n              <td class="right-label">Thư điện tử:</td>\r\n              <td class="value"><xsl:value-of select="f:child($tt, \'DCTDTu\')"/></td>\r\n            </tr>\r\n            <tr>\r\n              <td colspan="4" class="intro">\r\n                Theo Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 của Chính phủ, chúng tôi/tôi thuộc đối tượng sử dụng chứng từ điện tử. Chúng tôi/tôi đăng ký/thay đổi thông tin đã đăng ký với cơ quan thuế về việc sử dụng chứng từ điện tử như sau:\r\n              </td>\r\n            </tr>\r\n          </table>\r\n\r\n          <div class="section-title">1. Đối tượng phát hành</div>\r\n          <div class="section-box">\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($dtphanh, \'TCCNPHanh\'))"/> Tổ chức, cá nhân phát hành</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($dtphanh, \'CQTPHanh\'))"/> Cơ quan thuế phát hành</div>\r\n          </div>\r\n\r\n          <div class="section-title">2. Loại hình sử dụng</div>\r\n          <div class="section-box">\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhsdung, \'CTTNCNhan\'))"/> Chứng từ điện tử khấu trừ thuế thu nhập cá nhân</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhsdung, \'CTKTTTMDTu\'))"/> Chứng từ điện tử khấu trừ thuế đối với hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số</div>\r\n            <div class="checkbox-line"><xsl:value-of select="f:box(f:flag($lhsdung, \'BLTPLPKIn\') or f:flag($lhsdung, \'BLTPLPIn\') or f:flag($lhsdung, \'BLTTPLPhi\'))"/> Biên lai điện tử</div>\r\n            <div class="checkbox-sub"><xsl:value-of select="f:box(f:flag($lhsdung, \'BLTPLPKIn\'))"/> Biên lai thu thuế, phí, lệ phí không in sẵn mệnh giá</div>\r\n            <div class="checkbox-sub"><xsl:value-of select="f:box(f:flag($lhsdung, \'BLTPLPIn\'))"/> Biên lai thu thuế, phí, lệ phí in sẵn mệnh giá</div>\r\n            <div class="checkbox-sub"><xsl:value-of select="f:box(f:flag($lhsdung, \'BLTTPLPhi\'))"/> Biên lai thu thuế, phí, lệ phí</div>\r\n          </div>\r\n\r\n          <div class="section-title">3. Hình thức gửi dữ liệu:</div>\r\n          <div class="section-box">\r\n            <div class="checkbox-line">a. <xsl:value-of select="f:box(f:flag($htgd, \'CDLQCCQT\') or f:flag($htgd, \'CDLTTiep\'))"/> Trên Cổng thông tin điện tử của cơ quan thuế</div>\r\n            <div class="checkbox-line">b. <xsl:value-of select="f:box(f:flag($htgd, \'CDLQTCTN\'))"/> Thông qua tổ chức cung cấp dịch vụ hóa đơn điện tử</div>\r\n            <div class="checkbox-line">c. <xsl:value-of select="f:box(f:flag($htgd, \'CDLQTCTNUT\'))"/> Thông qua tổ chức cung cấp dịch vụ hóa đơn điện tử được Tổng cục Thuế ủy thác</div>\r\n          </div>\r\n\r\n          <table class="narrow-table">\r\n            <tr class="section-heading-row">\r\n              <td colspan="6">4. Danh sách chứng thư số sử dụng:</td>\r\n            </tr>\r\n            <tr>\r\n              <th rowspan="2" style="width: 7%;">STT</th>\r\n              <th rowspan="2" style="width: 30%;">Tên tổ chức cơ quan chứng thực/cấp/công nhận chữ ký số, chữ ký điện tử</th>\r\n              <th rowspan="2" style="width: 16%;">Số sê-ri chứng thư</th>\r\n              <th colspan="2" style="width: 30%;">Thời hạn sử dụng chứng thư số</th>\r\n              <th rowspan="2" style="width: 17%;">Hình thức đăng ký<br/>(Thêm mới, gia hạn, ngừng sử dụng)</th>\r\n            </tr>\r\n            <tr>\r\n              <th>Từ ngày</th>\r\n              <th>Đến ngày</th>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$ctsRows">\r\n                <xsl:for-each select="$ctsRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:child(., \'STT\') != \'\') then f:child(., \'STT\') else position()"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:child(., \'TTChuc\')"/></td>\r\n                    <td><xsl:value-of select="f:child(., \'Seri\')"/></td>\r\n                    <td><xsl:value-of select="f:date(f:child(., \'TNgay\'))"/></td>\r\n                    <td><xsl:value-of select="f:date(f:child(., \'DNgay\'))"/></td>\r\n                    <td><xsl:value-of select="f:certificate-method(f:child(., \'HThuc\'))"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td></tr>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n\r\n          <table class="narrow-table">\r\n            <tr class="section-heading-row">\r\n              <td colspan="8">5. Đăng ký ủy nhiệm lập biên lai</td>\r\n            </tr>\r\n            <tr>\r\n              <th>STT</th>\r\n              <th>Tên loại biên lai ủy nhiệm</th>\r\n              <th>Ký hiệu mẫu biên lai ủy nhiệm</th>\r\n              <th>Ký hiệu biên lai ủy nhiệm</th>\r\n              <th>Tên tổ chức được ủy nhiệm/tổ chức ủy nhiệm</th>\r\n              <th>Mục đích ủy nhiệm</th>\r\n              <th>Thời hạn ủy nhiệm</th>\r\n              <th>Phương thức thanh toán biên lai ủy nhiệm</th>\r\n            </tr>\r\n            <tr>\r\n              <td>(1)</td><td>(2)</td><td>(3)</td><td>(4)</td><td>(5)</td><td>(6)</td><td>(7)</td><td>(8)</td>\r\n            </tr>\r\n            <xsl:choose>\r\n              <xsl:when test="$delegateRows">\r\n                <xsl:for-each select="$delegateRows">\r\n                  <tr>\r\n                    <td><xsl:value-of select="if (f:any(., (\'STT\')) != \'\') then f:any(., (\'STT\')) else position()"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:any(., (\'TLHDon\', \'TenLHDon\', \'TLBLai\', \'TenLBLai\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'KHMSHDon\', \'KHMSBLai\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'KHHDon\', \'KHBLai\'))"/></td>\r\n                    <td class="text-left"><xsl:value-of select="f:any(., (\'Ten\', \'TTChuc\', \'TenTChuc\'))"/></td>\r\n                    <td><xsl:value-of select="f:any(., (\'MDich\', \'MucDich\'))"/></td>\r\n                    <td>\r\n                      <xsl:choose>\r\n                        <xsl:when test="f:any(., (\'TNgay\', \'DNgay\')) != \'\'">\r\n                          <xsl:value-of select="concat(f:date(f:any(., (\'TNgay\'))), \' - \', f:date(f:any(., (\'DNgay\'))))"/>\r\n                        </xsl:when>\r\n                        <xsl:otherwise>\r\n                          <xsl:value-of select="f:any(., (\'THan\', \'ThoiHan\'))"/>\r\n                        </xsl:otherwise>\r\n                      </xsl:choose>\r\n                    </td>\r\n                    <td><xsl:value-of select="f:any(., (\'PThucTT\', \'PThucTToan\', \'PTTToan\'))"/></td>\r\n                  </tr>\r\n                </xsl:for-each>\r\n              </xsl:when>\r\n              <xsl:otherwise>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n                <tr><td>&#160;</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n              </xsl:otherwise>\r\n            </xsl:choose>\r\n          </table>\r\n\r\n          <div class="note">\r\n            Chúng tôi cam kết hoàn toàn chịu trách nhiệm trước pháp luật về tính chính xác, trung thực của nội dung nêu trên và thực hiện theo đúng quy định của pháp luật.\r\n          </div>\r\n\r\n          <div class="signature">\r\n            <div class="date-line">\r\n              <xsl:value-of select="if (f:child($tt, \'DDanh\') != \'\') then f:child($tt, \'DDanh\') else \'......\'"/>,\r\n              ngày <xsl:value-of select="f:date-part(f:child($tt, \'NLap\'), \'day\')"/>\r\n              tháng <xsl:value-of select="f:date-part(f:child($tt, \'NLap\'), \'month\')"/>\r\n              năm <xsl:value-of select="f:date-part(f:child($tt, \'NLap\'), \'year\')"/>\r\n            </div>\r\n            <div class="name">NGƯỜI NỘP THUẾ hoặc<br/>ĐẠI DIỆN HỢP PHÁP CỦA NGƯỜI NỘP THUẾ</div>\r\n            <div class="hint">(Chữ ký số, chữ ký điện tử của người nộp thuế)</div>\r\n            <xsl:if test="$hasNntSignature">\r\n              <div class="signed">Đã ký điện tử</div>\r\n            </xsl:if>\r\n          </div>\r\n        </div>\r\n      </body>\r\n    </html>\r\n  </xsl:template>\r\n</xsl:stylesheet>\r\n', 1, 0, '/home/WEB/amnoteweb/ElectronicDocuments/shared/xsl/5d/99bf24d0dc9140bc8d5fec051991933d/5dac212af27564fffca78ddf22bde0e70640e0ed894e60fb72127619093318c5.xsl');
INSERT INTO `email_send_history` (`MAIL_ID`, `COMPANY_CD`, `DB_NAME`, `REF_TYPE`, `REF_ID`, `SEND_TYPE`, `SEND_STATUS`, `FROM_EMAIL`, `TO_EMAIL`, `CC_EMAIL`, `BCC_EMAIL`, `MAIL_SUBJECT`, `MAIL_BODY`, `ATTACHMENT_INFO`, `RETRY_COUNT`, `ERROR_MESSAGE`, `SEND_DT`, `CREATE_BY`, `CREATE_AT`, `UPDATE_AT`) VALUES
	(1, '0001', 'am_web_001', 'INVOICE', 59, 'EMAIL', 'SENT', 'e-invoice@amnote.com.vn', 'vanhanh0254@gmail.com', '', '', 'Hóa đơn điện tử 1C26TAA40 - Công ty TNHH AMNOTE Việt Nam', '<!DOCTYPE html>\r\n<html lang="vi">\r\n<head>\r\n  <meta charset="utf-8" />\r\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\r\n  <title>Hóa đơn điện tử AMnote</title>\r\n</head>\r\n\r\n<body style="margin:0;padding:0;background-color:#f4f6f8;font-family:Arial,Helvetica,sans-serif;color:#1f2937;">\r\n  <table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f8;padding:24px 12px;">\r\n    <tr>\r\n      <td align="center">\r\n\r\n        <table width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">\r\n\r\n          <tr>\r\n            <td style="background:#0f766e;color:#ffffff;padding:22px 26px;">\r\n              <div style="font-size:20px;font-weight:bold;line-height:1.4;">\r\n                Hóa đơn điện tử AMnote\r\n              </div>\r\n              <div style="font-size:13px;margin-top:4px;opacity:0.95;">\r\n                Thông báo phát hành hóa đơn điện tử\r\n              </div>\r\n            </td>\r\n          </tr>\r\n\r\n          <tr>\r\n            <td style="padding:26px;">\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.7;">\r\n                Kính gửi Quý khách <strong></strong>,\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.7;">\r\n                <strong>Công ty TNHH AMNOTE Việt Nam</strong> trân trọng cảm ơn Quý khách đã tin tưởng sử dụng hàng hóa/dịch vụ trong thời gian qua.\r\n              </p>\r\n\r\n              <p style="margin:0 0 18px;font-size:15px;line-height:1.7;">\r\n                Thông qua hệ thống hóa đơn điện tử <strong>AMnote</strong>, chúng tôi xin thông báo hóa đơn điện tử của Quý khách đã được phát hành với các thông tin như sau:\r\n              </p>\r\n\r\n              <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 22px;font-size:14px;">\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;width:38%;">Ký hiệu mẫu số hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>1</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ký hiệu hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>C26TAA</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Số hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>40</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ngày hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">26/06/2026</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Tổng tiền thanh toán</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">\r\n                    <strong>-111,111 VND</strong>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Mã tra cứu</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">\r\n                    <strong>TCML2XJE54HU35WG35Z2</strong>\r\n                  </td>\r\n                </tr>\r\n              </table>\r\n\r\n              <p style="margin:0 0 18px;font-size:14px;line-height:1.7;">\r\n                Quý khách vui lòng truy cập đường dẫn bên dưới để xem và tải hóa đơn điện tử:\r\n              </p>\r\n\r\n              <p style="margin:0 0 22px;text-align:center;">\r\n                <a href="http://localhost:5173/tra-cuu-einvoice-amnote/0100109106-998?mtracuu=TCML2XJE54HU35WG35Z2" style="display:inline-block;background:#0f766e;color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:6px;font-size:14px;font-weight:bold;">\r\n                  Xem hóa đơn điện tử\r\n                </a>\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:14px;line-height:1.7;">\r\n                File PDF hóa đơn được đính kèm trong email này. Trường hợp cần kiểm tra lại thông tin hóa đơn, Quý khách có thể sử dụng mã tra cứu ở trên tại trang tra cứu hóa đơn của AMnote.\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:14px;line-height:1.7;">\r\n                Mọi thắc mắc liên quan đến nội dung hóa đơn, Quý khách vui lòng liên hệ trực tiếp với <strong>Công ty TNHH AMNOTE Việt Nam</strong> để được hỗ trợ.\r\n              </p>\r\n\r\n              <p style="margin:0;font-size:14px;line-height:1.7;">\r\n                Trân trọng,<br />\r\n                <strong>Công ty TNHH AMNOTE Việt Nam</strong>\r\n              </p>\r\n            </td>\r\n          </tr>\r\n\r\n          <tr>\r\n            <td style="padding:16px 26px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;line-height:1.6;">\r\n              Email này được gửi tự động từ hệ thống hóa đơn điện tử AMnote. Vui lòng không trả lời trực tiếp email này.<br />\r\n              Website: http://localhost:5173 | Email hỗ trợ: hotro@amnote.vn | Hotline: \r\n            </td>\r\n          </tr>\r\n\r\n        </table>\r\n\r\n      </td>\r\n    </tr>\r\n  </table>\r\n</body>\r\n</html>', '[{"FileName":"EInvoice_1C26TAA40.pdf","ContentType":"application/pdf","Size":412791},{"FileName":"EInvoice_1C26TAA40.xml","ContentType":"application/xml","Size":5458}]', 0, '', '2026-06-26 16:20:30', 'admin', '2026-06-26 16:20:29', NULL),
	(2, '0001', 'am_web_001', 'INVOICE', 68, 'EMAIL', 'SENT', 'e-invoice@amnote.com.vn', 'vanhanh0254@gmail.com', '', '', 'Hóa đơn điện tử 1C26TAC3 - Công ty TNHH AMNOTE Việt Nam', '<!DOCTYPE html>\r\n<html lang="vi">\r\n<head>\r\n  <meta charset="utf-8" />\r\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\r\n  <title>Hóa đơn điện tử AMnote</title>\r\n</head>\r\n\r\n<body style="margin:0;padding:0;background-color:#f4f6f8;font-family:Arial,Helvetica,sans-serif;color:#1f2937;">\r\n  <table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f8;padding:24px 12px;">\r\n    <tr>\r\n      <td align="center">\r\n\r\n        <table width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">\r\n\r\n          <tr>\r\n            <td style="background:#0f766e;color:#ffffff;padding:22px 26px;">\r\n              <div style="font-size:20px;font-weight:bold;line-height:1.4;">\r\n                Hóa đơn điện tử AMnote\r\n              </div>\r\n              <div style="font-size:13px;margin-top:4px;opacity:0.95;">\r\n                Thông báo phát hành hóa đơn điện tử\r\n              </div>\r\n            </td>\r\n          </tr>\r\n\r\n          <tr>\r\n            <td style="padding:26px;">\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.7;">\r\n                Kính gửi Quý khách <strong></strong>,\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:15px;line-height:1.7;">\r\n                <strong>Công ty TNHH AMNOTE Việt Nam</strong> trân trọng cảm ơn Quý khách đã tin tưởng sử dụng hàng hóa/dịch vụ trong thời gian qua.\r\n              </p>\r\n\r\n              <p style="margin:0 0 18px;font-size:15px;line-height:1.7;">\r\n                Thông qua hệ thống hóa đơn điện tử <strong>AMnote</strong>, chúng tôi xin thông báo hóa đơn điện tử của Quý khách đã được phát hành với các thông tin như sau:\r\n              </p>\r\n\r\n              <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 22px;font-size:14px;">\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;width:38%;">Ký hiệu mẫu số hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>1</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ký hiệu hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>C26TAC</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Số hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;"><strong>3</strong></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Ngày hóa đơn</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">19/08/2026</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Tổng tiền thanh toán</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">\r\n                    <strong>22,000 VND</strong>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;background:#f9fafb;">Mã tra cứu</td>\r\n                  <td style="padding:11px 12px;border:1px solid #e5e7eb;">\r\n                    <strong>TCFKTNM8NS7J6LLRAT39</strong>\r\n                  </td>\r\n                </tr>\r\n              </table>\r\n\r\n              <p style="margin:0 0 18px;font-size:14px;line-height:1.7;">\r\n                Quý khách vui lòng truy cập đường dẫn bên dưới để xem và tải hóa đơn điện tử:\r\n              </p>\r\n\r\n              <p style="margin:0 0 22px;text-align:center;">\r\n                <a href="https://localhost:7108/tra-cuu-einvoice-amnote/0100109106-998?mtracuu=TCFKTNM8NS7J6LLRAT39" style="display:inline-block;background:#0f766e;color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:6px;font-size:14px;font-weight:bold;">\r\n                  Xem hóa đơn điện tử\r\n                </a>\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:14px;line-height:1.7;">\r\n                File PDF hóa đơn được đính kèm trong email này. Trường hợp cần kiểm tra lại thông tin hóa đơn, Quý khách có thể sử dụng mã tra cứu ở trên tại trang tra cứu hóa đơn của AMnote.\r\n              </p>\r\n\r\n              <p style="margin:0 0 16px;font-size:14px;line-height:1.7;">\r\n                Mọi thắc mắc liên quan đến nội dung hóa đơn, Quý khách vui lòng liên hệ trực tiếp với <strong>Công ty TNHH AMNOTE Việt Nam</strong> để được hỗ trợ.\r\n              </p>\r\n\r\n              <p style="margin:0;font-size:14px;line-height:1.7;">\r\n                Trân trọng,<br />\r\n                <strong>Công ty TNHH AMNOTE Việt Nam</strong>\r\n              </p>\r\n            </td>\r\n          </tr>\r\n\r\n          <tr>\r\n            <td style="padding:16px 26px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;line-height:1.6;">\r\n              Email này được gửi tự động từ hệ thống hóa đơn điện tử AMnote. Vui lòng không trả lời trực tiếp email này.<br />\r\n              Website: https://localhost:7108 | Email hỗ trợ: hotro@amnote.vn | Hotline: \r\n            </td>\r\n          </tr>\r\n\r\n        </table>\r\n\r\n      </td>\r\n    </tr>\r\n  </table>\r\n</body>\r\n</html>', '[{"FileName":"EInvoice_1C26TAC3.xml","ContentType":"application/xml","Size":9583}]', 0, '', '2026-08-20 16:34:26', 'admin', '2026-08-20 16:34:25', NULL);
