	('GK_TAB_WIP', '재공 비용', 'WIP cost', 'Chi phí dở dang', '仕掛費用', 'ต้นทุนงานระหว่างทำ', '在产品成本', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL),
	('GK_VALIDATE', '자료 점검', 'Validate data', 'Kiểm tra dữ liệu', 'データを検証', 'ตรวจสอบข้อมูล', '校验数据', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL),
