-- Dumping structure for procedure am_web_manager.changeUserProfilePassword
DROP PROCEDURE IF EXISTS `changeUserProfilePassword`;
DELIMITER //
CREATE PROCEDURE `changeUserProfilePassword`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USERID VARCHAR(50),
  IN p_PASSWD VARCHAR(255),
  IN p_MODIFIER_USERID VARCHAR(50)
)
BEGIN
  UPDATE user_info UI
  INNER JOIN user_company UC
    ON UC.USER_PK_ID = UI.USER_PK_ID
   AND UC.COMPANY_CD = TRIM(p_COMPANY_CD)
   AND IFNULL(UC.ISDEL, '0') <> '1'
  SET
    UI.PASSWD = p_PASSWD,
    UI.UPDATE_BY = COALESCE(NULLIF(p_MODIFIER_USERID, ''), '0'),
    UI.UPDATE_AT = NOW()
  WHERE UC.USERID = TRIM(COALESCE(p_USERID, ''))
    AND IFNULL(UI.ISDEL, '0') <> '1';

  IF ROW_COUNT() = 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'User not found';
  END IF;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.check_exists
DROP PROCEDURE IF EXISTS `check_exists`;
DELIMITER //
CREATE PROCEDURE `check_exists`(
    IN p_TABLE_NAME VARCHAR(100),
    IN p_COMPANY_FIELD VARCHAR(100),
    IN p_COMPANY_CD VARCHAR(50),
    IN p_CODE_FIELD VARCHAR(100),
    IN p_CODE_VALUE VARCHAR(255),
    IN p_ID_FIELD VARCHAR(100),
    IN p_EXCLUDE_ID BIGINT,
    OUT p_CNT INT
)
BEGIN
    SET @v_cnt = 0;

    SET @sql = CONCAT(
        'SELECT COUNT(*) INTO @v_cnt ',
        'FROM ', p_TABLE_NAME, ' ',
        'WHERE 1=1 '
    );

    IF IFNULL(p_COMPANY_FIELD, '') <> '' THEN
        SET @sql = CONCAT(@sql, ' AND ', p_COMPANY_FIELD, ' = ? ');
    END IF;

    SET @sql = CONCAT(@sql, ' AND ', p_CODE_FIELD, ' = ? ');

    IF IFNULL(p_ID_FIELD, '') <> '' THEN
        SET @sql = CONCAT(@sql, ' AND ', p_ID_FIELD, ' <> ? ');
    END IF;

    PREPARE stmt FROM @sql;

    IF IFNULL(p_COMPANY_FIELD, '') <> '' AND IFNULL(p_ID_FIELD, '') <> '' THEN
        SET @p1 = p_COMPANY_CD;
        SET @p2 = p_CODE_VALUE;
        SET @p3 = IFNULL(p_EXCLUDE_ID, 0);
        EXECUTE stmt USING @p1, @p2, @p3;
    ELSEIF IFNULL(p_COMPANY_FIELD, '') <> '' AND IFNULL(p_ID_FIELD, '') = '' THEN
        SET @p1 = p_COMPANY_CD;
        SET @p2 = p_CODE_VALUE;
        EXECUTE stmt USING @p1, @p2;
    ELSEIF IFNULL(p_COMPANY_FIELD, '') = '' AND IFNULL(p_ID_FIELD, '') <> '' THEN
        SET @p1 = p_CODE_VALUE;
        SET @p2 = IFNULL(p_EXCLUDE_ID, 0);
        EXECUTE stmt USING @p1, @p2;
    ELSE
        SET @p1 = p_CODE_VALUE;
        EXECUTE stmt USING @p1;
    END IF;

    DEALLOCATE PREPARE stmt;

    SET p_CNT = IFNULL(@v_cnt, 0);
END//
DELIMITER ;

