-- Dumping structure for procedure am_web_manager.claimEInvoiceMessageWorkQueuePendingReceive
DROP PROCEDURE IF EXISTS `claimEInvoiceMessageWorkQueuePendingReceive`;
DELIMITER //
CREATE PROCEDURE `claimEInvoiceMessageWorkQueuePendingReceive`(
  IN p_LIMIT INT
)
BEGIN
  DECLARE v_limit INT DEFAULT 50;

  IF p_LIMIT IS NULL OR p_LIMIT <= 0 THEN
    SET v_limit = 50;
  ELSE
    SET v_limit = p_LIMIT;
  END IF;

  DROP TEMPORARY TABLE IF EXISTS tmp_einvoice_claim_receive;
  CREATE TEMPORARY TABLE tmp_einvoice_claim_receive (
    WORK_ID BIGINT UNSIGNED NOT NULL PRIMARY KEY
  ) ENGINE=InnoDB;

  START TRANSACTION;

  SELECT w.WORK_ID
    FROM einvoice_message_work_queue w
   WHERE w.WORK_STATUS = 'WAIT_RESPONSE'
   ORDER BY w.CREATE_AT
   LIMIT v_limit
   FOR UPDATE SKIP LOCKED;

  UPDATE einvoice_message_work_queue w
   INNER JOIN tmp_einvoice_claim_receive t
      ON t.WORK_ID = w.WORK_ID
     SET w.WORK_STATUS = 'POLLING',
         w.UPDATE_AT = NOW()
   WHERE w.WORK_STATUS = 'WAIT_RESPONSE';

  COMMIT;

  SELECT
    w.WORK_ID,
    w.COMPANY_CD,
    w.DB_NAME,
    w.MST,
    w.TARGET_TYPE,
    w.TARGET_ID,
    w.SEND_MTDIEP,
    w.WORK_STATUS,
    w.RETRY_COUNT,
    w.ERROR_MESSAGE,
    w.CREATE_AT,
    w.UPDATE_AT
  FROM einvoice_message_work_queue w
  INNER JOIN tmp_einvoice_claim_receive t
    ON t.WORK_ID = w.WORK_ID
  WHERE w.WORK_STATUS = 'POLLING'
  ORDER BY w.CREATE_AT;

  DROP TEMPORARY TABLE IF EXISTS tmp_einvoice_claim_receive;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.claimEInvoiceMessageWorkQueuePendingSend
DROP PROCEDURE IF EXISTS `claimEInvoiceMessageWorkQueuePendingSend`;
DELIMITER //
CREATE PROCEDURE `claimEInvoiceMessageWorkQueuePendingSend`(
  IN p_LIMIT INT
)
BEGIN
  DECLARE v_limit INT DEFAULT 50;

  IF p_LIMIT IS NULL OR p_LIMIT <= 0 THEN
    SET v_limit = 50;
  ELSE
    SET v_limit = p_LIMIT;
  END IF;

  DROP TEMPORARY TABLE IF EXISTS tmp_einvoice_claim_send;
  CREATE TEMPORARY TABLE tmp_einvoice_claim_send (
    WORK_ID BIGINT UNSIGNED NOT NULL PRIMARY KEY
  ) ENGINE=InnoDB;

  START TRANSACTION;

  SELECT w.WORK_ID
    FROM einvoice_message_work_queue w
   INNER JOIN einvoice_message_send s
      ON s.COMPANY_CD = w.COMPANY_CD
     AND s.MTDIEP = w.SEND_MTDIEP
   WHERE w.WORK_STATUS = 'WAIT_SEND'
     AND s.REQUEST_XML IS NOT NULL
     AND TRIM(s.REQUEST_XML) <> ''
   ORDER BY w.CREATE_AT
   LIMIT v_limit
   FOR UPDATE SKIP LOCKED;

  UPDATE einvoice_message_work_queue w
   INNER JOIN tmp_einvoice_claim_send t
      ON t.WORK_ID = w.WORK_ID
     SET w.WORK_STATUS = 'SENDING',
         w.UPDATE_AT = NOW()
   WHERE w.WORK_STATUS = 'WAIT_SEND';

  COMMIT;

  SELECT
    w.WORK_ID,
    w.COMPANY_CD,
    w.DB_NAME,
    w.MST,
    w.TARGET_TYPE,
    w.TARGET_ID,
    w.SEND_MTDIEP,
    w.WORK_STATUS,
    w.RETRY_COUNT,
    w.ERROR_MESSAGE,
    w.CREATE_AT,
    w.UPDATE_AT,
    s.SEND_ID,
    s.REQUEST_XML
  FROM einvoice_message_work_queue w
  INNER JOIN tmp_einvoice_claim_send t
    ON t.WORK_ID = w.WORK_ID
  INNER JOIN einvoice_message_send s
    ON s.COMPANY_CD = w.COMPANY_CD
   AND s.MTDIEP = w.SEND_MTDIEP
  WHERE w.WORK_STATUS = 'SENDING'
  ORDER BY w.CREATE_AT;

  DROP TEMPORARY TABLE IF EXISTS tmp_einvoice_claim_send;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.clear_company_report_elements
DROP PROCEDURE IF EXISTS `clear_company_report_elements`;
DELIMITER //
CREATE PROCEDURE `clear_company_report_elements`(
    IN p_COMPANY_CD VARCHAR(50),
    IN p_REPORT_KEY VARCHAR(100)
)
BEGIN
    UPDATE company_report_element
    SET
        ISDEL = '1',
        UPDATE_AT = NOW()
    WHERE COMPANY_CD = TRIM(IFNULL(p_COMPANY_CD, ''))
      AND REPORT_KEY = TRIM(p_REPORT_KEY)
      AND IFNULL(ISDEL, '0') = '0';
END//
DELIMITER ;

