-- Dumping structure for procedure am_web_manager.del_sys_report_column_layout
DROP PROCEDURE IF EXISTS `del_sys_report_column_layout`;
DELIMITER //
CREATE PROCEDURE `del_sys_report_column_layout`(
    IN p_COMPANY_CD VARCHAR(50),
    IN p_REPORT_CODE VARCHAR(100),
    IN p_COLUMN_KEY VARCHAR(100),
    IN p_USERID VARCHAR(50)
)
BEGIN
    UPDATE sys_report_column_layout
    SET
        ISDEL = '1',
        UPDATE_BY = TRIM(IFNULL(p_USERID, '')),
        UPDATE_AT = NOW()
    WHERE COMPANY_CD = TRIM(IFNULL(p_COMPANY_CD, ''))
      AND REPORT_CODE = TRIM(p_REPORT_CODE)
      AND COLUMN_KEY = TRIM(p_COLUMN_KEY);
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.delCompanySignatureInfo
DROP PROCEDURE IF EXISTS `delCompanySignatureInfo`;
DELIMITER //
CREATE PROCEDURE `delCompanySignatureInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_ID BIGINT(20),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_sign_code VARCHAR(50);

  SELECT SIGN_CODE
    INTO v_sign_code
  FROM company_signature_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND ID = p_ID
  LIMIT 1;

  IF v_sign_code IN ('01', '02', '03', '04', '05', '06') THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Default SIGN_CODE cannot be deleted';
  END IF;

  DELETE FROM company_signature_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND ID = p_ID;

  SELECT ROW_COUNT() AS deleted;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.delMailSetting
DROP PROCEDURE IF EXISTS `delMailSetting`;
DELIMITER //
CREATE PROCEDURE `delMailSetting`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_MAIL_CD VARCHAR(50),
  IN p_USER_ID VARCHAR(50)
)
BEGIN
  DECLARE v_company_cd VARCHAR(20) DEFAULT '';
  DECLARE v_mail_cd VARCHAR(50) DEFAULT 'DEFAULT';
  DECLARE v_user_id VARCHAR(50) DEFAULT 'system';

  SET v_company_cd = IFNULL(TRIM(p_COMPANY_CD), '');
  SET v_mail_cd = UPPER(IFNULL(NULLIF(TRIM(p_MAIL_CD), ''), 'DEFAULT'));
  SET v_user_id = IFNULL(NULLIF(TRIM(p_USER_ID), ''), 'system');

  IF v_company_cd = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'System mail setting cannot be deleted';
  END IF;

  UPDATE mail_setting
  SET
    ISDEL = 1,
    UPDATE_BY = v_user_id,
    UPDATE_AT = CURRENT_TIMESTAMP
  WHERE IFNULL(TRIM(COMPANY_CD), '') = v_company_cd
    AND MAIL_CD = v_mail_cd
    AND IFNULL(ISDEL, 0) = 0;

  SELECT ROW_COUNT() AS deleted;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.delUserInfo
DROP PROCEDURE IF EXISTS `delUserInfo`;
DELIMITER //
CREATE PROCEDURE `delUserInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USER_PK_ID BIGINT(20),
  IN p_MODIFIER_USERID VARCHAR(50)
)
BEGIN
  UPDATE user_company
  SET
    ISDEL = '1',
    IS_ACTIVE = '0',
    UPDATE_BY = COALESCE(NULLIF(p_MODIFIER_USERID, ''), '0'),
    UPDATE_AT = NOW()
  WHERE COMPANY_CD = TRIM(p_COMPANY_CD)
    AND USER_PK_ID = p_USER_PK_ID;
END//
DELIMITER ;

