-- Dumping structure for function am_web_manager.fn_getLanguage
DROP FUNCTION IF EXISTS `fn_getLanguage`;
DELIMITER //
CREATE FUNCTION `fn_getLanguage`(
    p_key VARCHAR(50),
    p_lang VARCHAR(10),
    p_default_value VARCHAR(1000)
) RETURNS varchar(1000) CHARSET utf8mb3 COLLATE utf8mb3_unicode_ci
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE v_result VARCHAR(1000);
    set v_result = p_default_value;

    -- Lấy giá trị tương ứng với ngôn ngữ yêu cầu
    SELECT 
        CASE 
            WHEN p_lang = 'VIET' THEN VIET
            WHEN p_lang = 'ENG'  THEN ENG
            WHEN p_lang = 'KOR'  THEN KOR
            WHEN p_lang = 'CHINA' THEN CHN
            ELSE NULL -- Hoặc bạn có thể gán mặc định khác nếu ngôn ngữ không khớp
        END
    INTO v_result
    FROM am_web_manager.t_message_info
    WHERE `KEY` = p_key;

    -- Trả về giá trị tìm được, nếu NULL (không tìm thấy hoặc cột ngôn ngữ trống) thì trả về p_default_value
    RETURN IFNULL(v_result, p_default_value);
END//
DELIMITER ;

-- Dumping structure for function am_web_manager.fn_title_case
DROP FUNCTION IF EXISTS `fn_title_case`;
DELIMITER //
CREATE FUNCTION `fn_title_case`(input_str VARCHAR(1000)) RETURNS varchar(1000) CHARSET utf8mb3 COLLATE utf8mb3_unicode_ci
    DETERMINISTIC
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE len INT;
    DECLARE result VARCHAR(1000) DEFAULT '';
    DECLARE ch VARCHAR(1);
    DECLARE make_upper BOOLEAN DEFAULT TRUE;

    SET input_str = LOWER(TRIM(input_str));
    SET len = CHAR_LENGTH(input_str);

    WHILE i <= len DO
        SET ch = SUBSTRING(input_str, i, 1);

        IF ch = ' ' THEN
            SET result = CONCAT(result, ch);
            SET make_upper = TRUE;
        ELSE
            IF make_upper THEN
                SET result = CONCAT(result, UPPER(ch));
                SET make_upper = FALSE;
            ELSE
                SET result = CONCAT(result, ch);
            END IF;
        END IF;

        SET i = i + 1;
    END WHILE;

    RETURN result;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.get_company_database_name
DROP PROCEDURE IF EXISTS `get_company_database_name`;
DELIMITER //
CREATE PROCEDURE `get_company_database_name`(
  IN p_COMPANY_CD VARCHAR(20)
)
BEGIN
  SELECT
    DBG.DB_GROUP_NM
  FROM company_info CI
  INNER JOIN db_group DBG
    ON DBG.DB_GROUP_ID = CI.DB_GROUP_ID
  WHERE CI.COMPANY_CD = TRIM(p_COMPANY_CD)
    AND IFNULL(CI.ISDEL, '0') <> '1'
  LIMIT 1;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.get_company_report_config
DROP PROCEDURE IF EXISTS `get_company_report_config`;
DELIMITER //
CREATE PROCEDURE `get_company_report_config`(
    IN p_COMPANY_CD VARCHAR(50),
    IN p_REPORT_CODE VARCHAR(100),
    IN p_MENU_CODE VARCHAR(100)
)
BEGIN
    DECLARE v_report_code VARCHAR(100);
    DECLARE v_menu_code VARCHAR(100);
    DECLARE v_report_id BIGINT DEFAULT NULL;
    DECLARE v_sign_ids VARCHAR(100) DEFAULT NULL;
    DECLARE v_sign_codes VARCHAR(100) DEFAULT NULL;

    SET v_report_code = NULLIF(TRIM(IFNULL(p_REPORT_CODE, '')), '');
    SET v_menu_code = NULLIF(TRIM(IFNULL(p_MENU_CODE, '')), '');

    IF EXISTS (
        SELECT 1
        FROM company_report_mapping crm
        INNER JOIN sys_report_catalog src ON src.REPORT_ID = crm.REPORT_ID
        WHERE crm.COMPANY_CD = p_COMPANY_CD
          AND crm.ISDEL = '0'
          AND crm.IS_ACTIVE = '1'
          AND src.ISDEL = '0'
          AND src.IS_ACTIVE = '1'
          AND (
                (v_menu_code IS NOT NULL AND crm.REPORT_KEY = v_menu_code)
             OR (v_report_code IS NOT NULL AND crm.REPORT_KEY = v_report_code)
             OR (v_report_code IS NOT NULL AND src.REPORT_CODE = v_report_code)
          )
    ) THEN
        SELECT
            src.REPORT_ID,
            NULLIF(TRIM(IFNULL(crm.SIGN_IDS, '')), '')
          INTO v_report_id, v_sign_ids
        FROM company_report_mapping crm
        INNER JOIN sys_report_catalog src ON src.REPORT_ID = crm.REPORT_ID
        WHERE crm.COMPANY_CD = p_COMPANY_CD
          AND crm.ISDEL = '0'
          AND crm.IS_ACTIVE = '1'
          AND src.ISDEL = '0'
          AND src.IS_ACTIVE = '1'
          AND (
                (v_menu_code IS NOT NULL AND crm.REPORT_KEY = v_menu_code)
             OR (v_report_code IS NOT NULL AND crm.REPORT_KEY = v_report_code)
             OR (v_report_code IS NOT NULL AND src.REPORT_CODE = v_report_code)
          )
        ORDER BY
            CASE
                WHEN v_menu_code IS NOT NULL AND crm.REPORT_KEY = v_menu_code THEN 0
                WHEN v_report_code IS NOT NULL AND crm.REPORT_KEY = v_report_code THEN 1
                ELSE 2
            END,
            CASE WHEN crm.IS_DEFAULT = '1' THEN 0 ELSE 1 END,
            crm.ID DESC
        LIMIT 1;

        SELECT
            crm.ID AS MAPPING_ID,
            crm.COMPANY_CD,
            crm.REPORT_KEY,
            src.REPORT_ID,
            crm.SIGN_IDS,
            src.REPORT_CODE,
            src.LABEL_TEXT,
            src.CAPTION,
            src.REPORT_TYPE,
            src.VIEW_TYPE,
            src.REPORT_SOURCE,
            src.DATA_SOURCE_TYPE,
            src.DATA_SOURCE_REF,
            src.DATA_SET_NAME,
            src.PARAM_MODE,
            crm.IS_DEFAULT,
            crm.IS_ACTIVE AS MAPPING_IS_ACTIVE,
            src.IS_ACTIVE AS REPORT_IS_ACTIVE,
            crm.PAGE_ORIENTATION,
            crm.PAPER_KIND,
            crm.FONT_FAMILY,
            crm.FONT_SIZE,
            crm.TITLE_FONT_SIZE,
            crm.INFO_FONT_SIZE,
            crm.HEADER_FONT_SIZE,
            crm.DETAIL_FONT_SIZE,
            crm.FOOTER_FONT_SIZE,
            crm.MARGIN_LEFT,
            crm.MARGIN_RIGHT,
            crm.MARGIN_TOP,
            crm.MARGIN_BOTTOM
        FROM company_report_mapping crm
        INNER JOIN sys_report_catalog src ON src.REPORT_ID = crm.REPORT_ID
        WHERE crm.COMPANY_CD = p_COMPANY_CD
          AND crm.REPORT_ID = v_report_id
          AND crm.ISDEL = '0'
          AND crm.IS_ACTIVE = '1'
          AND src.ISDEL = '0'
          AND src.IS_ACTIVE = '1'
          AND (
                (v_menu_code IS NOT NULL AND crm.REPORT_KEY = v_menu_code)
             OR (v_report_code IS NOT NULL AND crm.REPORT_KEY = v_report_code)
             OR (v_report_code IS NOT NULL AND src.REPORT_CODE = v_report_code)
          )
        ORDER BY
            CASE
                WHEN v_menu_code IS NOT NULL AND crm.REPORT_KEY = v_menu_code THEN 0
                WHEN v_report_code IS NOT NULL AND crm.REPORT_KEY = v_report_code THEN 1
                ELSE 2
            END,
            CASE WHEN crm.IS_DEFAULT = '1' THEN 0 ELSE 1 END,
            crm.ID DESC
        LIMIT 1;
    ELSEIF v_report_code IS NOT NULL THEN
        SELECT src.REPORT_ID
          INTO v_report_id
        FROM sys_report_catalog src
        WHERE src.REPORT_CODE = v_report_code
          AND src.ISDEL = '0'
          AND src.IS_ACTIVE = '1'
        ORDER BY src.REPORT_ID DESC
        LIMIT 1;

        SELECT
            NULL AS MAPPING_ID,
            p_COMPANY_CD AS COMPANY_CD,
            IFNULL(v_menu_code, v_report_code) AS REPORT_KEY,
            src.REPORT_ID,
            NULL AS SIGN_IDS,
            src.REPORT_CODE,
            src.LABEL_TEXT,
            src.CAPTION,
            src.REPORT_TYPE,
            src.VIEW_TYPE,
            src.REPORT_SOURCE,
            src.DATA_SOURCE_TYPE,
            src.DATA_SOURCE_REF,
            src.DATA_SET_NAME,
            src.PARAM_MODE,
            '1' AS IS_DEFAULT,
            '1' AS MAPPING_IS_ACTIVE,
            src.IS_ACTIVE AS REPORT_IS_ACTIVE,
            'AUTO' AS PAGE_ORIENTATION,
            'AUTO' AS PAPER_KIND,
            'Arial' AS FONT_FAMILY,
            8.50 AS FONT_SIZE,
            16.00 AS TITLE_FONT_SIZE,
            9.00 AS INFO_FONT_SIZE,
            8.50 AS HEADER_FONT_SIZE,
            8.50 AS DETAIL_FONT_SIZE,
            8.00 AS FOOTER_FONT_SIZE,
            40 AS MARGIN_LEFT,
            40 AS MARGIN_RIGHT,
            25 AS MARGIN_TOP,
            25 AS MARGIN_BOTTOM
        FROM sys_report_catalog src
        WHERE src.REPORT_ID = v_report_id
        ORDER BY src.REPORT_ID DESC
        LIMIT 1;
    ELSE
        SELECT
            NULL AS MAPPING_ID,
            NULL AS COMPANY_CD,
            NULL AS REPORT_KEY,
            NULL AS REPORT_ID,
            NULL AS SIGN_IDS,
            NULL AS REPORT_CODE,
            NULL AS LABEL_TEXT,
            NULL AS CAPTION,
            NULL AS REPORT_TYPE,
            NULL AS VIEW_TYPE,
            NULL AS REPORT_SOURCE,
            NULL AS DATA_SOURCE_TYPE,
            NULL AS DATA_SOURCE_REF,
            NULL AS DATA_SET_NAME,
            NULL AS PARAM_MODE,
            NULL AS IS_DEFAULT,
            NULL AS MAPPING_IS_ACTIVE,
            NULL AS REPORT_IS_ACTIVE,
            NULL AS PAGE_ORIENTATION,
            NULL AS PAPER_KIND,
            NULL AS FONT_FAMILY,
            NULL AS FONT_SIZE,
            NULL AS TITLE_FONT_SIZE,
            NULL AS INFO_FONT_SIZE,
            NULL AS HEADER_FONT_SIZE,
            NULL AS DETAIL_FONT_SIZE,
            NULL AS FOOTER_FONT_SIZE,
            NULL AS MARGIN_LEFT,
            NULL AS MARGIN_RIGHT,
            NULL AS MARGIN_TOP,
            NULL AS MARGIN_BOTTOM
        FROM DUAL
        WHERE 1 = 0;
    END IF;

    IF v_sign_ids IS NOT NULL THEN
        SET v_sign_codes = NULLIF(REPLACE(REPLACE(v_sign_ids, '|', ','), ' ', ''), '');
    END IF;

    IF v_sign_codes IS NOT NULL THEN
        SELECT
            csi.ID,
            csi.COMPANY_CD,
            csi.SIGN_CODE,
            csi.DISPLAY_LABEL,
            csi.SIGN_NAME,
            csi.SIGN_TITLE,
            csi.SIGN_IMAGE_URL,
            csi.SORT_ORDER,
            FIND_IN_SET(csi.SIGN_CODE, v_sign_codes) AS SIGN_SEQUENCE
        FROM company_signature_info csi
        WHERE csi.COMPANY_CD IN (p_COMPANY_CD, '')
          AND IFNULL(csi.ISDEL, '0') = '0'
          AND IFNULL(csi.IS_ACTIVE, '1') = '1'
          AND (
              csi.COMPANY_CD = p_COMPANY_CD
              OR NOT EXISTS (
                  SELECT 1
                  FROM company_signature_info x
                  WHERE x.COMPANY_CD = p_COMPANY_CD
                    AND x.SIGN_CODE = csi.SIGN_CODE
                    AND IFNULL(x.ISDEL, '0') = '0'
              )
          )
          AND FIND_IN_SET(csi.SIGN_CODE, v_sign_codes) > 0
        ORDER BY
            SIGN_SEQUENCE,
            COALESCE(csi.SORT_ORDER, 999999),
            csi.SIGN_CODE,
            csi.ID;
    ELSE
        SELECT
            NULL AS ID,
            NULL AS COMPANY_CD,
            NULL AS SIGN_CODE,
            NULL AS DISPLAY_LABEL,
            NULL AS SIGN_NAME,
            NULL AS SIGN_TITLE,
            NULL AS SIGN_IMAGE_URL,
            NULL AS SORT_ORDER,
            NULL AS SIGN_SEQUENCE
        FROM DUAL
        WHERE 1 = 0;
    END IF;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.get_company_report_elements
DROP PROCEDURE IF EXISTS `get_company_report_elements`;
DELIMITER //
CREATE PROCEDURE `get_company_report_elements`(
    IN p_COMPANY_CD VARCHAR(50),
    IN p_REPORT_KEY VARCHAR(100),
    IN p_REPORT_CODE VARCHAR(100)
)
BEGIN
    DECLARE v_company_cd VARCHAR(50);
    DECLARE v_report_key VARCHAR(100);
    DECLARE v_report_code VARCHAR(100);

    SET v_company_cd = TRIM(IFNULL(p_COMPANY_CD, ''));
    SET v_report_key = NULLIF(TRIM(IFNULL(p_REPORT_KEY, '')), '');
    SET v_report_code = NULLIF(TRIM(IFNULL(p_REPORT_CODE, '')), '');

    SELECT
        element.ID,
        element.COMPANY_CD,
        element.REPORT_KEY,
        element.SECTION_TYPE,
        element.ELEMENT_TYPE,
        element.AREA_CODE,
        element.ITEM_KEY,
        element.LABEL_TEXT,
        element.CAPTION,
        element.VALUE_SOURCE,
        element.VALUE_FIELD,      
        element.ROW_NO,
        element.COL_NO,
        element.COL_SPAN,
        element.SORT_ORDER,
        element.VISIBLE_INDEX,
        element.WIDTH,
        element.WIDTH_PERCENT,
        element.ALIGN_HEADER,
        element.ALIGN_DATA,
        element.ALIGN,
        element.DATA_TYPE,
        element.FORMAT_STRING,
        element.IS_SUMMARY,
        element.SUMMARY_TYPE,
        element.FONT_SIZE,
        element.IS_BOLD,
        element.IS_ITALIC,
        element.IS_VISIBLE,
        element.ISDEL,
        element.CREATE_AT,
        element.UPDATE_AT
    FROM company_report_element element
    INNER JOIN (
        SELECT MIN(
            CASE
                WHEN source.COMPANY_CD = v_company_cd AND v_report_key IS NOT NULL AND source.REPORT_KEY = v_report_key THEN 0
                WHEN source.COMPANY_CD = v_company_cd AND v_report_code IS NOT NULL AND source.REPORT_KEY = v_report_code THEN 1
                WHEN source.COMPANY_CD = '' AND v_report_key IS NOT NULL AND source.REPORT_KEY = v_report_key THEN 2
                WHEN source.COMPANY_CD = '' AND v_report_code IS NOT NULL AND source.REPORT_KEY = v_report_code THEN 3
                ELSE 99
            END
        ) AS BEST_PRIORITY
        FROM company_report_element source
        WHERE IFNULL(source.ISDEL, '0') = '0'
          AND IFNULL(source.IS_VISIBLE, '1') = '1'
          AND UPPER(TRIM(IFNULL(source.ELEMENT_TYPE, ''))) <> 'SIGNATURE'
          AND (
                (source.COMPANY_CD = v_company_cd AND v_report_key IS NOT NULL AND source.REPORT_KEY = v_report_key)
             OR (source.COMPANY_CD = v_company_cd AND v_report_code IS NOT NULL AND source.REPORT_KEY = v_report_code)
             OR (source.COMPANY_CD = '' AND v_report_key IS NOT NULL AND source.REPORT_KEY = v_report_key)
             OR (source.COMPANY_CD = '' AND v_report_code IS NOT NULL AND source.REPORT_KEY = v_report_code)
          )
    ) selector ON selector.BEST_PRIORITY = CASE
                WHEN element.COMPANY_CD = v_company_cd AND v_report_key IS NOT NULL AND element.REPORT_KEY = v_report_key THEN 0
                WHEN element.COMPANY_CD = v_company_cd AND v_report_code IS NOT NULL AND element.REPORT_KEY = v_report_code THEN 1
                WHEN element.COMPANY_CD = '' AND v_report_key IS NOT NULL AND element.REPORT_KEY = v_report_key THEN 2
                WHEN element.COMPANY_CD = '' AND v_report_code IS NOT NULL AND element.REPORT_KEY = v_report_code THEN 3
                ELSE 99
            END
    WHERE IFNULL(element.ISDEL, '0') = '0'
      AND IFNULL(element.IS_VISIBLE, '1') = '1'
      AND UPPER(TRIM(IFNULL(element.ELEMENT_TYPE, ''))) <> 'SIGNATURE'
    ORDER BY element.SECTION_TYPE, element.ROW_NO, element.COL_NO, element.SORT_ORDER, element.ID;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.get_exchange_revaluation_history
DROP PROCEDURE IF EXISTS `get_exchange_revaluation_history`;
DELIMITER //
CREATE PROCEDURE `get_exchange_revaluation_history`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_MODULE_CD VARCHAR(10),
    IN p_RATE_DATE_FROM DATE,
    IN p_RATE_DATE_TO DATE,
    IN p_FC_TYPE VARCHAR(255)
)
BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_filter_fc_type;
    CREATE TEMPORARY TABLE tmp_filter_fc_type (
      CD VARCHAR(64) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    IF IFNULL(TRIM(IFNULL(p_FC_TYPE, '')), '') <> '' AND UPPER(IFNULL(TRIM(IFNULL(p_FC_TYPE, '')), '')) NOT IN ('ALL', '*') THEN
      SELECT DISTINCT TRIM(jt.val)
      FROM JSON_TABLE(
        CONCAT('["', REPLACE(REPLACE(REPLACE(TRIM(IFNULL(p_FC_TYPE, '')), '|', ','), ' ', ''), ',', '","'), '"]'),
        '$[*]' COLUMNS (val VARCHAR(64) PATH '$')
      ) jt
      WHERE NULLIF(TRIM(jt.val), '') IS NOT NULL
        AND UPPER(TRIM(jt.val)) NOT IN ('ALL', '*');
    END IF;

SELECT
        r.RESULT_ID,
        r.COMPANY_CD,
        r.MODULE_CD,
        r.CHIT_ID,
        r.CHITDETAIL_ID,
        r.CHIT_CD,
        r.CHIT_NO,
        r.CHIT_YMD,
        r.CHIT_TYPE,
        r.CHITDETAIL_CD,
        r.DEBIT,
        r.CREDIT,
        r.FC_TYPE,
        DATE_FORMAT(r.RATE_DATE, '%Y-%m-%d') AS RATE_DATE,
        r.FC_AMOUNT,
        r.OLD_RATE,
        r.NEW_RATE,
        r.OLD_AMOUNT,
        r.NEW_AMOUNT,
        r.EXCHANGE_DIFF,
        r.DIFF_TYPE,
        r.CREATE_BY,
        r.CREATE_AT
    FROM exchange_revaluation_result r
    WHERE r.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(r.ISDEL, '0') = '0'
      AND (IFNULL(p_MODULE_CD, '') = '' OR UPPER(p_MODULE_CD) = 'ALL' OR r.MODULE_CD = UPPER(p_MODULE_CD))
      AND (p_RATE_DATE_FROM IS NULL OR r.RATE_DATE >= p_RATE_DATE_FROM)
      AND (p_RATE_DATE_TO IS NULL OR r.RATE_DATE <= p_RATE_DATE_TO)
      AND (IFNULL(p_FC_TYPE, '') = '' OR EXISTS (SELECT 1 FROM tmp_filter_fc_type f WHERE f.CD = (TRIM(IFNULL(r.FC_TYPE, '')))))
    ORDER BY r.CREATE_AT DESC, r.RESULT_ID DESC;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.get_exchange_revaluation_preview
DROP PROCEDURE IF EXISTS `get_exchange_revaluation_preview`;
DELIMITER //
CREATE PROCEDURE `get_exchange_revaluation_preview`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_MODULE_CD VARCHAR(10),
    IN p_RATE_DATE DATE,
    IN p_FC_TYPE VARCHAR(255),
    IN p_CHIT_YMD_FROM VARCHAR(8),
    IN p_CHIT_YMD_TO VARCHAR(8)
)
BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_filter_fc_type;
    CREATE TEMPORARY TABLE tmp_filter_fc_type (
      CD VARCHAR(64) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    IF IFNULL(TRIM(IFNULL(p_FC_TYPE, '')), '') <> '' AND UPPER(IFNULL(TRIM(IFNULL(p_FC_TYPE, '')), '')) NOT IN ('ALL', '*') THEN
      SELECT DISTINCT TRIM(jt.val)
      FROM JSON_TABLE(
        CONCAT('["', REPLACE(REPLACE(REPLACE(TRIM(IFNULL(p_FC_TYPE, '')), '|', ','), ' ', ''), ',', '","'), '"]'),
        '$[*]' COLUMNS (val VARCHAR(64) PATH '$')
      ) jt
      WHERE NULLIF(TRIM(jt.val), '') IS NOT NULL
        AND UPPER(TRIM(jt.val)) NOT IN ('ALL', '*');
    END IF;

SELECT
        UPPER(IFNULL(h.INPUT_TYPE, '')) AS MODULE_CD,
        h.COMPANY_CD,
        h.CHIT_ID,
        d.CHITDETAIL_ID,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_TYPE,
        d.CHITDETAIL_CD,
        d.DEBIT,
        d.CREDIT,
        IFNULL(d.FC_TYPE, '') AS FC_TYPE,
        IFNULL(d.FC_AMOUNT, 0) AS FC_AMOUNT,
        IFNULL(d.FC_RATE, 0) AS OLD_RATE,
        IFNULL(d.AMOUNT, 0) AS OLD_AMOUNT,
        IFNULL(d.FC_RATE, 0) AS NEW_RATE,
        CAST(IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0) AS DECIMAL(18,2)) AS NEW_AMOUNT,
        CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) AS EXCHANGE_DIFF,
        CASE
            WHEN CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) > 0 THEN 'GAIN'
            WHEN CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) < 0 THEN 'LOSS'
            ELSE 'NONE'
        END AS DIFF_TYPE
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND UPPER(IFNULL(h.INPUT_TYPE, '')) IN ('AR', 'AP')
      AND (IFNULL(p_MODULE_CD, '') = '' OR UPPER(p_MODULE_CD) = 'ALL' OR UPPER(IFNULL(h.INPUT_TYPE, '')) = UPPER(p_MODULE_CD))
      AND (IFNULL(p_FC_TYPE, '') = '' OR EXISTS (SELECT 1 FROM tmp_filter_fc_type f WHERE f.CD = (TRIM(IFNULL(d.FC_TYPE, '')))))
      AND (IFNULL(p_CHIT_YMD_FROM, '') = '' OR IFNULL(h.CHIT_YMD, '') >= p_CHIT_YMD_FROM)
      AND (IFNULL(p_CHIT_YMD_TO, '') = '' OR IFNULL(h.CHIT_YMD, '') <= p_CHIT_YMD_TO)
      AND IFNULL(d.FC_AMOUNT, 0) <> 0
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0'
    ORDER BY h.CHIT_YMD, h.CHIT_NO, d.CHITDETAIL_ID;
END//
DELIMITER ;

