-- Dumping structure for procedure am_web_manager.get_sys_report_column_layout
DROP PROCEDURE IF EXISTS `get_sys_report_column_layout`;
DELIMITER //
CREATE PROCEDURE `get_sys_report_column_layout`(
    IN p_COMPANY_CD VARCHAR(50),
    IN p_REPORT_KEY VARCHAR(100),
    IN p_REPORT_CODE VARCHAR(100)
)
BEGIN
    DECLARE v_company_cd VARCHAR(50);
    DECLARE v_report_key VARCHAR(100);
    DECLARE v_report_code VARCHAR(100);

    SET v_company_cd = TRIM(IFNULL(p_COMPANY_CD, ''));
    SET v_report_key = NULLIF(TRIM(IFNULL(p_REPORT_KEY, '')), '');
    SET v_report_code = NULLIF(TRIM(IFNULL(p_REPORT_CODE, '')), '');

    SELECT
        layout.COLUMN_KEY,
        NULLIF(TRIM(IFNULL(layout.PARENT_KEY, '')), '') AS PARENT_KEY,
        NULLIF(TRIM(IFNULL(layout.FIELD_NAME, '')), '') AS FIELD_NAME,
        NULLIF(TRIM(IFNULL(layout.LABEL_TEXT, '')), '') AS LABEL_TEXT,
        layout.CAPTION,
        layout.ROW_INDEX,
        layout.COL_INDEX,
        layout.COL_SPAN,
        layout.ROW_SPAN,
        layout.WIDTH,
        layout.ALIGN,
        layout.FORMAT_TYPE,
        layout.SORT_ORDER
    FROM sys_report_column_layout layout
    INNER JOIN (
        SELECT MIN(
            CASE
                WHEN source.COMPANY_CD = v_company_cd AND v_report_key IS NOT NULL AND source.REPORT_CODE = v_report_key THEN 0
                WHEN source.COMPANY_CD = v_company_cd AND v_report_code IS NOT NULL AND source.REPORT_CODE = v_report_code THEN 1
                WHEN source.COMPANY_CD = '' AND v_report_key IS NOT NULL AND source.REPORT_CODE = v_report_key THEN 2
                WHEN source.COMPANY_CD = '' AND v_report_code IS NOT NULL AND source.REPORT_CODE = v_report_code THEN 3
                ELSE 99
            END
        ) AS BEST_PRIORITY
        FROM sys_report_column_layout source
        WHERE IFNULL(source.ISDEL, '0') = '0'
          AND IFNULL(source.IS_ACTIVE, '1') = '1'
          AND (
                (source.COMPANY_CD = v_company_cd AND v_report_key IS NOT NULL AND source.REPORT_CODE = v_report_key)
             OR (source.COMPANY_CD = v_company_cd AND v_report_code IS NOT NULL AND source.REPORT_CODE = v_report_code)
             OR (source.COMPANY_CD = '' AND v_report_key IS NOT NULL AND source.REPORT_CODE = v_report_key)
             OR (source.COMPANY_CD = '' AND v_report_code IS NOT NULL AND source.REPORT_CODE = v_report_code)
          )
    ) selector ON selector.BEST_PRIORITY = CASE
                WHEN layout.COMPANY_CD = v_company_cd AND v_report_key IS NOT NULL AND layout.REPORT_CODE = v_report_key THEN 0
                WHEN layout.COMPANY_CD = v_company_cd AND v_report_code IS NOT NULL AND layout.REPORT_CODE = v_report_code THEN 1
                WHEN layout.COMPANY_CD = '' AND v_report_key IS NOT NULL AND layout.REPORT_CODE = v_report_key THEN 2
                WHEN layout.COMPANY_CD = '' AND v_report_code IS NOT NULL AND layout.REPORT_CODE = v_report_code THEN 3
                ELSE 99
            END
    WHERE IFNULL(layout.ISDEL, '0') = '0'
      AND IFNULL(layout.IS_ACTIVE, '1') = '1'
    ORDER BY layout.SORT_ORDER, layout.ROW_INDEX, layout.COL_INDEX, layout.ID;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.get_sys_report_options
DROP PROCEDURE IF EXISTS `get_sys_report_options`;
DELIMITER //
CREATE PROCEDURE `get_sys_report_options`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_REPORT_GROUP_CODE VARCHAR(100)
)
BEGIN
    DECLARE v_company_cd VARCHAR(20);
    DECLARE v_report_group_code VARCHAR(100);
    DECLARE v_source_company_cd VARCHAR(20);

    SET v_company_cd = TRIM(IFNULL(p_COMPANY_CD, ''));
    SET v_report_group_code = NULLIF(TRIM(IFNULL(p_REPORT_GROUP_CODE, '')), '');

    IF v_report_group_code IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'reportGroupCode is required';
    END IF;

    SELECT option_source.COMPANY_CD
      INTO v_source_company_cd
    FROM sys_report_option option_source
    WHERE option_source.REPORT_GROUP_CODE = v_report_group_code
      AND option_source.COMPANY_CD IN (v_company_cd, '', '0000', '0001')
      AND IFNULL(option_source.IS_ACTIVE, '1') = '1'
      AND IFNULL(option_source.ISDEL, '0') = '0'
    ORDER BY CASE
        WHEN option_source.COMPANY_CD = v_company_cd THEN 0
        WHEN option_source.COMPANY_CD = '' THEN 1
        WHEN option_source.COMPANY_CD = '0000' THEN 2
        ELSE 3
    END
    LIMIT 1;

    IF v_source_company_cd IS NULL THEN
        SELECT
            NULL AS OPTION_ID,
            NULL AS COMPANY_CD,
            NULL AS REPORT_GROUP_CODE,
            NULL AS OPTION_CODE,
            NULL AS OPTION_NAME,
            NULL AS LABEL_TEXT,
            NULL AS CAPTION,
            NULL AS REPORT_CODE,
            NULL AS IS_DEFAULT,
            NULL AS SORT_ORDER
        FROM DUAL
        WHERE 1 = 0;
    ELSE
        SELECT
            option_item.OPTION_ID,
            option_item.COMPANY_CD,
            option_item.REPORT_GROUP_CODE,
            option_item.OPTION_CODE,
            option_item.OPTION_NAME,
            NULLIF(TRIM(option_item.LABEL_TEXT), '') AS LABEL_TEXT,
            COALESCE(NULLIF(TRIM(option_item.CAPTION), ''), option_item.OPTION_NAME) AS CAPTION,
            option_item.REPORT_CODE,
            IFNULL(option_item.IS_DEFAULT, '0') AS IS_DEFAULT,
            IFNULL(option_item.SORT_ORDER, 0) AS SORT_ORDER
        FROM sys_report_option option_item
        WHERE option_item.COMPANY_CD = v_source_company_cd
          AND option_item.REPORT_GROUP_CODE = v_report_group_code
          AND IFNULL(option_item.IS_ACTIVE, '1') = '1'
          AND IFNULL(option_item.ISDEL, '0') = '0'
        ORDER BY IFNULL(option_item.SORT_ORDER, 0), option_item.OPTION_ID;
    END IF;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.get_sys_user_permission
DROP PROCEDURE IF EXISTS `get_sys_user_permission`;
DELIMITER //
CREATE PROCEDURE `get_sys_user_permission`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_USERID VARCHAR(50)
)
BEGIN
  SET p_COMPANY_CD = TRIM(p_COMPANY_CD);
  SET p_USERID = TRIM(p_USERID);
    WITH RECURSIVE eligible AS (
    SELECT
        m.MENU_ID,
        m.MENU_CODE,
        m.MENU_NAME,
        NULLIF(TRIM(m.LABEL_TEXT), '') AS LABEL_TEXT,
        COALESCE(NULLIF(TRIM(m.CAPTION), ''), m.MENU_NAME) AS CAPTION,
        m.PARENT_ID,
        m.ROUTE_PATH,
        m.ICON,
        m.SORT_ORDER,
        m.IS_ACTIVE,
        CASE WHEN company_setting.ID IS NOT NULL
            THEN company_setting.IS_VISIBLE ELSE default_setting.IS_VISIBLE END AS IS_VISIBLE,
        CASE WHEN company_setting.ID IS NOT NULL
            THEN company_setting.IS_DISABLED ELSE default_setting.IS_DISABLED END AS IS_DISABLED
    FROM sys_menu m
    LEFT JOIN company_info company
        ON company.COMPANY_CD = p_COMPANY_CD
    LEFT JOIN sys_menu_company company_setting
        ON company_setting.MENU_ID = m.MENU_ID
       AND company_setting.COMPANY_CD = p_COMPANY_CD
    LEFT JOIN sys_menu_company default_setting
        ON default_setting.MENU_ID = m.MENU_ID
       AND default_setting.COMPANY_CD = ''
    -- Choose by row existence: a hidden/NULL company setting must not inherit default values.
    WHERE p_COMPANY_CD IS NOT NULL
      AND (
          p_COMPANY_CD = ''
          OR company.MENU_MODE = 'ALL'
          OR (company.MENU_MODE IN ('INVOICE', 'AMNOTE')
              AND (m.PRODUCT_SCOPE = 'COMMON' OR m.PRODUCT_SCOPE = company.MENU_MODE))
      )
      AND (company_setting.ID IS NOT NULL OR default_setting.ID IS NOT NULL)
      AND m.IS_ACTIVE = 1
      AND CASE WHEN company_setting.ID IS NOT NULL
          THEN company_setting.IS_VISIBLE ELSE default_setting.IS_VISIBLE END = 1
    ), reachable AS (
        SELECT root.* FROM eligible root WHERE root.PARENT_ID IS NULL
        UNION ALL
        SELECT child.*
        FROM eligible child
        INNER JOIN reachable parent ON child.PARENT_ID = parent.MENU_ID
    )
    SELECT
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.USER_PERMISSION_ID ELSE def.USER_PERMISSION_ID END AS USER_PERMISSION_ID,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.COMPANY_CD ELSE def.COMPANY_CD END AS COMPANY_CD,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.USERID ELSE def.USERID END AS USERID,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.MENU_CODE ELSE def.MENU_CODE END AS MENU_CODE,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.CAN_VIEW ELSE def.CAN_VIEW END AS CAN_VIEW,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.CAN_ADD ELSE def.CAN_ADD END AS CAN_ADD,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.CAN_EDIT ELSE def.CAN_EDIT END AS CAN_EDIT,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.CAN_DELETE ELSE def.CAN_DELETE END AS CAN_DELETE,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.CAN_PRINT ELSE def.CAN_PRINT END AS CAN_PRINT,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.CAN_EXPORT ELSE def.CAN_EXPORT END AS CAN_EXPORT,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.CAN_IMPORT ELSE def.CAN_IMPORT END AS CAN_IMPORT,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.CAN_APPROVE ELSE def.CAN_APPROVE END AS CAN_APPROVE,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN own.ISDEL ELSE def.ISDEL END AS ISDEL,
        CASE WHEN own.USER_PERMISSION_ID IS NOT NULL THEN 'COMPANY_USER' ELSE 'DEFAULT' END AS PERMISSION_SOURCE,
        def.CAN_VIEW AS DEFAULT_CAN_VIEW,
        def.CAN_ADD AS DEFAULT_CAN_ADD,
        def.CAN_EDIT AS DEFAULT_CAN_EDIT,
        def.CAN_DELETE AS DEFAULT_CAN_DELETE,
        def.CAN_PRINT AS DEFAULT_CAN_PRINT,
        def.CAN_EXPORT AS DEFAULT_CAN_EXPORT,
        def.CAN_IMPORT AS DEFAULT_CAN_IMPORT,
        def.CAN_APPROVE AS DEFAULT_CAN_APPROVE
    FROM reachable m
    -- A canonical default must exist. No implicit full rights or legacy permission catalog.
    INNER JOIN sys_user_permission def
        ON CONVERT(def.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(m.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci
       AND def.COMPANY_CD = '' AND def.USERID = '' AND def.ISDEL = '0'
    LEFT JOIN sys_user_permission own
        ON CONVERT(own.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(m.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci
       AND own.COMPANY_CD = TRIM(p_COMPANY_CD) AND own.USERID = TRIM(p_USERID)
       AND own.ISDEL = '0'
    WHERE NULLIF(TRIM(p_COMPANY_CD), '') IS NOT NULL
      AND NULLIF(TRIM(p_USERID), '') IS NOT NULL
      AND m.IS_DISABLED = 0
      AND EXISTS (
      SELECT 1 FROM user_company uc
      INNER JOIN user_info ui ON ui.USER_PK_ID = uc.USER_PK_ID
      WHERE uc.COMPANY_CD = TRIM(p_COMPANY_CD) AND uc.USERID = TRIM(p_USERID)
        AND uc.IS_ACTIVE = '1' AND uc.ISDEL = '0'
        AND ui.IS_ACTIVE = '1' AND ui.ISDEL = '0'
    )
    ORDER BY m.MENU_CODE;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.get_user_companies
DROP PROCEDURE IF EXISTS `get_user_companies`;
DELIMITER //
CREATE PROCEDURE `get_user_companies`(
  IN p_USER_PK_ID BIGINT(20)
)
BEGIN
  SELECT
    UI.USER_PK_ID,
    UC.USER_COMPANY_ID,
    UC.USERID,
    UC.COMPANY_CD,
    IFNULL(CI.COMPANY_NM, UC.COMPANY_CD) AS COMPANY_NM,
    UC.USERLV,
    UC.ROLE_CODE,
    IFNULL(UC.DEFAULT_YN, '0') AS DEFAULT_YN,
    IFNULL(UC.IS_ACTIVE, '1') AS IS_ACTIVE
  FROM user_info UI
  INNER JOIN user_company UC
    ON UC.USER_PK_ID = UI.USER_PK_ID
   AND IFNULL(UC.ISDEL, '0') <> '1'
   AND IFNULL(UC.IS_ACTIVE, '1') = '1'
  LEFT JOIN company_info CI
    ON CI.COMPANY_CD = UC.COMPANY_CD
   AND IFNULL(CI.ISDEL, '0') <> '1'
  WHERE UI.USER_PK_ID = p_USER_PK_ID
    AND IFNULL(UI.ISDEL, '0') <> '1'
    AND IFNULL(UI.IS_ACTIVE, '1') = '1'
  ORDER BY IFNULL(UC.DEFAULT_YN, '0') DESC, UC.COMPANY_CD;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.getall_company_report_config
DROP PROCEDURE IF EXISTS `getall_company_report_config`;
DELIMITER //
CREATE PROCEDURE `getall_company_report_config`(
    IN p_COMPANY_CD VARCHAR(50)
)
BEGIN
    DECLARE v_company_cd VARCHAR(50);
    SET v_company_cd = TRIM(IFNULL(p_COMPANY_CD, ''));

    SELECT
        crm.ID AS MAPPING_ID,
        crm.COMPANY_CD,
        crm.REPORT_KEY,
        src.REPORT_ID,
        crm.SIGN_IDS,
        src.REPORT_CODE,
        src.LABEL_TEXT,
        src.CAPTION,
        src.REPORT_TYPE,
        src.VIEW_TYPE,
        src.REPORT_SOURCE,
        src.DATA_SOURCE_TYPE,
        src.DATA_SOURCE_REF,
        src.DATA_SET_NAME,
        src.PARAM_MODE,
        crm.IS_DEFAULT,
        crm.IS_ACTIVE AS MAPPING_IS_ACTIVE,
        src.IS_ACTIVE AS REPORT_IS_ACTIVE,
        crm.PAGE_ORIENTATION,
        crm.PAPER_KIND,
        crm.FONT_FAMILY,
        crm.FONT_SIZE,
        crm.TITLE_FONT_SIZE,
        crm.INFO_FONT_SIZE,
        crm.HEADER_FONT_SIZE,
        crm.DETAIL_FONT_SIZE,
        crm.FOOTER_FONT_SIZE,
        crm.MARGIN_LEFT,
        crm.MARGIN_RIGHT,
        crm.MARGIN_TOP,
        crm.MARGIN_BOTTOM
    FROM company_report_mapping crm
    INNER JOIN sys_report_catalog src ON src.REPORT_ID = crm.REPORT_ID
    WHERE crm.COMPANY_CD IN (v_company_cd, '')
      AND crm.ISDEL = '0'
      AND crm.IS_ACTIVE = '1'
      AND src.ISDEL = '0'
      AND src.IS_ACTIVE = '1'
    UNION ALL
    SELECT
        NULL AS MAPPING_ID,
        v_company_cd AS COMPANY_CD,
        src.REPORT_CODE AS REPORT_KEY,
        src.REPORT_ID,
        NULL AS SIGN_IDS,
        src.REPORT_CODE,
        src.LABEL_TEXT,
        src.CAPTION,
        src.REPORT_TYPE,
        src.VIEW_TYPE,
        src.REPORT_SOURCE,
        src.DATA_SOURCE_TYPE,
        src.DATA_SOURCE_REF,
        src.DATA_SET_NAME,
        src.PARAM_MODE,
        '1' AS IS_DEFAULT,
        '1' AS MAPPING_IS_ACTIVE,
        src.IS_ACTIVE AS REPORT_IS_ACTIVE,
        NULL AS PAGE_ORIENTATION,
        NULL AS PAPER_KIND,
        NULL AS FONT_FAMILY,
        NULL AS FONT_SIZE,
        NULL AS TITLE_FONT_SIZE,
        NULL AS INFO_FONT_SIZE,
        NULL AS HEADER_FONT_SIZE,
        NULL AS DETAIL_FONT_SIZE,
        NULL AS FOOTER_FONT_SIZE,
        NULL AS MARGIN_LEFT,
        NULL AS MARGIN_RIGHT,
        NULL AS MARGIN_TOP,
        NULL AS MARGIN_BOTTOM
    FROM sys_report_catalog src
    WHERE src.ISDEL = '0'
      AND src.IS_ACTIVE = '1'
    ORDER BY REPORT_CODE, REPORT_KEY, MAPPING_ID DESC;

    SELECT
        crm.ID AS MAPPING_ID,
        csi.ID,
        csi.COMPANY_CD,
        csi.SIGN_CODE,
        csi.DISPLAY_LABEL,
        csi.SIGN_NAME,
        csi.SIGN_TITLE,
        csi.SIGN_IMAGE_URL,
        csi.SORT_ORDER,
        sign_ord.SEQ AS SIGN_SEQUENCE
    FROM company_report_mapping crm
    INNER JOIN sys_report_catalog src ON src.REPORT_ID = crm.REPORT_ID
    INNER JOIN JSON_TABLE(
        CONCAT('["', REPLACE(REPLACE(REPLACE(IFNULL(crm.SIGN_IDS, ''), '|', ','), ' ', ''), ',', '","'), '"]'),
        '$[*]' COLUMNS (
            SEQ FOR ORDINALITY,
            SIGN_CODE VARCHAR(64) PATH '$'
        )
    ) sign_ord
    INNER JOIN company_signature_info csi
      ON csi.SIGN_CODE = sign_ord.SIGN_CODE
     AND csi.COMPANY_CD IN (v_company_cd, '')
     AND (
         csi.COMPANY_CD = v_company_cd
         OR NOT EXISTS (
             SELECT 1
             FROM company_signature_info x
             WHERE x.COMPANY_CD = v_company_cd
               AND x.SIGN_CODE = csi.SIGN_CODE
         )
     )
    WHERE crm.COMPANY_CD IN (v_company_cd, '')
      AND crm.ISDEL = '0'
      AND crm.IS_ACTIVE = '1'
      AND src.ISDEL = '0'
      AND src.IS_ACTIVE = '1'
      AND IFNULL(csi.IS_ACTIVE, '1') = '1'
      AND NULLIF(REPLACE(REPLACE(IFNULL(crm.SIGN_IDS, ''), '|', ','), ' ', ''), '') IS NOT NULL
    ORDER BY
        crm.ID,
        SIGN_SEQUENCE,
        COALESCE(csi.SORT_ORDER, 999999),
        csi.SIGN_CODE,
        csi.ID;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.getall_company_report_elements
