    IN p_COMPANY_CD VARCHAR(50)
)
BEGIN
    DECLARE v_company_cd VARCHAR(50);

    SET v_company_cd = TRIM(IFNULL(p_COMPANY_CD, ''));

    SELECT
        element.ID,
        element.COMPANY_CD,
        element.REPORT_KEY,
        element.SECTION_TYPE,
        element.ELEMENT_TYPE,
        element.AREA_CODE,
        element.ITEM_KEY,
        element.LABEL_TEXT,
        element.CAPTION,
        element.VALUE_SOURCE,
        element.VALUE_FIELD,
        element.ROW_NO,
        element.COL_NO,
        element.COL_SPAN,
        element.SORT_ORDER,
        element.VISIBLE_INDEX,
        element.WIDTH,
        element.WIDTH_PERCENT,
        element.ALIGN_HEADER,
        element.ALIGN_DATA,
        element.ALIGN,
        element.DATA_TYPE,
        element.FORMAT_STRING,
        element.IS_SUMMARY,
        element.SUMMARY_TYPE,
        element.FONT_SIZE,
        element.IS_BOLD,
        element.IS_ITALIC,
        element.IS_VISIBLE,
        element.ISDEL,
        element.CREATE_AT,
        element.UPDATE_AT
    FROM company_report_element element
    WHERE IFNULL(element.ISDEL, '0') = '0'
      AND IFNULL(element.IS_VISIBLE, '1') = '1'
      AND UPPER(TRIM(IFNULL(element.ELEMENT_TYPE, ''))) <> 'SIGNATURE'
      AND (
            element.COMPANY_CD = v_company_cd
         OR element.COMPANY_CD = ''
      )
    ORDER BY element.COMPANY_CD DESC, element.REPORT_KEY, element.SECTION_TYPE, element.ROW_NO, element.COL_NO, element.SORT_ORDER, element.ID;
END//
DELIMITER ;

