-- Dumping structure for procedure am_web_manager.getallsys_grid_column_bundle
DROP PROCEDURE IF EXISTS `getallsys_grid_column_bundle`;
DELIMITER //
CREATE PROCEDURE `getallsys_grid_column_bundle`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USER_ID VARCHAR(50)
)
BEGIN
  DECLARE v_company_cd VARCHAR(20);
  DECLARE v_user_id VARCHAR(50);

  SET v_company_cd = TRIM(COALESCE(p_COMPANY_CD, ''));
  SET v_user_id = TRIM(COALESCE(p_USER_ID, ''));

  SELECT
    c.ID,
    c.GRID_ID,
    c.FIELD_NAME,
    c.LABEL_TEXT,
    c.CAPTION,
    c.IS_VISIBLE,
    c.VISIBLE_INDEX,
    c.COLUMN_WIDTH,
    c.IS_FIXED,
    c.FIXED_POSITION,
    c.ALLOW_HIDING,
    c.ALIGN,
    c.FORMAT_TYPE,
    c.SORT_ORDER,
    c.SORT_INDEX
  FROM sys_grid_column c
  WHERE c.ISDEL = '0'
  ORDER BY c.GRID_ID, CASE WHEN c.VISIBLE_INDEX IS NULL THEN 1 ELSE 0 END, c.VISIBLE_INDEX, c.FIELD_NAME;

  SELECT
    t.TEMPLATE_ID,
    t.COMPANY_CD,
    t.USER_ID,
    t.GRID_ID,
    t.TEMPLATE_NAME,
    t.IS_DEFAULT_TEMPLATE
  FROM sys_grid_template t
  WHERE t.COMPANY_CD = v_company_cd
    AND t.USER_ID = v_user_id
    AND t.ISDEL = '0'
  ORDER BY t.GRID_ID, t.IS_DEFAULT_TEMPLATE DESC, t.TEMPLATE_NAME, t.TEMPLATE_ID;

  SELECT
    s.ID,
    s.TEMPLATE_ID,
    s.GRID_ID,
    s.FIELD_NAME,
    s.LABEL_TEXT,
    s.CAPTION,
    s.IS_VISIBLE,
    s.VISIBLE_INDEX,
    s.COLUMN_WIDTH,
    s.IS_FIXED,
    s.FIXED_POSITION,
    s.ALLOW_HIDING,
    s.SORT_ORDER,
    s.SORT_INDEX
  FROM sys_grid_column_setting s
  INNER JOIN sys_grid_template t
    ON t.TEMPLATE_ID = s.TEMPLATE_ID
   AND t.ISDEL = '0'
  WHERE t.COMPANY_CD = v_company_cd
    AND t.USER_ID = v_user_id
    AND s.ISDEL = '0'
  ORDER BY s.GRID_ID, s.TEMPLATE_ID, CASE WHEN s.VISIBLE_INDEX IS NULL THEN 1 ELSE 0 END, s.VISIBLE_INDEX, s.FIELD_NAME;
END//
DELIMITER ;

