-- Dumping structure for procedure am_web_manager.getCompanySignatureInfo
DROP PROCEDURE IF EXISTS `getCompanySignatureInfo`;
DELIMITER //
CREATE PROCEDURE `getCompanySignatureInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_ID BIGINT(20),
  IN p_SIGN_CODE VARCHAR(50),
  IN p_IS_ACTIVE CHAR(1)
)
BEGIN
  SELECT
    c.ID,
    c.COMPANY_CD,
    c.SIGN_CODE,
    c.DISPLAY_LABEL,
    c.SIGN_NAME,
    c.SIGN_TITLE,
    c.SIGN_IMAGE_URL,
    c.SORT_ORDER,
    c.IS_ACTIVE,
    c.CREATE_BY,
    c.CREATE_AT,
    c.UPDATE_BY,
    c.UPDATE_AT
  FROM company_signature_info c
  WHERE c.COMPANY_CD IN (p_COMPANY_CD, '')
    AND (p_ID IS NULL OR p_ID = 0 OR c.ID = p_ID)
    AND (p_SIGN_CODE IS NULL OR p_SIGN_CODE = '' OR c.SIGN_CODE = p_SIGN_CODE)
    AND (p_IS_ACTIVE IS NULL OR p_IS_ACTIVE = '' OR c.IS_ACTIVE = p_IS_ACTIVE)
    AND (
      c.COMPANY_CD = p_COMPANY_CD
      OR (p_ID IS NOT NULL AND p_ID > 0 AND c.ID = p_ID)
      OR NOT EXISTS (
        SELECT 1
        FROM company_signature_info x
        WHERE x.COMPANY_CD = p_COMPANY_CD
          AND x.SIGN_CODE = c.SIGN_CODE
      )
    )
  ORDER BY
    CASE WHEN c.COMPANY_CD = p_COMPANY_CD THEN 0 ELSE 1 END,
    COALESCE(c.SORT_ORDER, 0),
    c.SIGN_CODE,
    c.ID;
END//
DELIMITER ;

