-- Dumping structure for procedure am_web_manager.getexcel_template_column
DROP PROCEDURE IF EXISTS `getexcel_template_column`;
DELIMITER //
CREATE PROCEDURE `getexcel_template_column`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_MODULE_CD VARCHAR(100)
)
BEGIN
    DECLARE v_COMPANY_CD VARCHAR(20) DEFAULT '';
    DECLARE v_MODULE_CD VARCHAR(100) DEFAULT '';

    SET v_COMPANY_CD = TRIM(IFNULL(p_COMPANY_CD, ''));
    SET v_MODULE_CD = TRIM(IFNULL(p_MODULE_CD, ''));

    SELECT
        c.ID,
        c.COMPANY_CD,
        c.MODULE_CD,
        c.COLUMN_KEY,
        c.COLUMN_LABEL,
        c.EXPLAIN_TABLE_QUERY,
--        c.EXPLAIN_COLUMN_CD,
--        c.EXPLAIN_COLUMN_NM,
--        c.EXPLAIN_WHERE,
        c.DATA_TYPE,
        c.IS_REQUIRED,
        c.ISUSE,
        c.SORT,
        c.NOTE,
        c.CREATE_BY,
        c.CREATE_DT,
        c.UPDATE_BY,
        c.UPDATE_DT,
        c.ISDEL
    FROM excel_template_column c
    WHERE 
        (
            c.COMPANY_CD = v_COMPANY_CD
            OR IFNULL(c.COMPANY_CD, '') = ''
        )
        AND c.MODULE_CD = v_MODULE_CD
        AND IFNULL(c.ISUSE, '1') = '1'
        AND IFNULL(c.ISDEL, '0') = '0'

        -- Nếu là dòng mặc định COMPANY_CD = ''
        -- thì chỉ lấy khi công ty chưa có dòng riêng cùng MODULE_CD + COLUMN_KEY
        AND (
            c.COMPANY_CD = v_COMPANY_CD
            OR NOT EXISTS (
                SELECT 1
                FROM excel_template_column x
                WHERE x.COMPANY_CD = v_COMPANY_CD
                  AND x.MODULE_CD = c.MODULE_CD
                  AND x.COLUMN_KEY = c.COLUMN_KEY
                  AND IFNULL(x.ISUSE, '1') = '1'
                  AND IFNULL(x.ISDEL, '0') = '0'
            )
        )
    ORDER BY
        IFNULL(c.SORT, 1),
        c.COLUMN_KEY,
        CASE 
            WHEN c.COMPANY_CD = v_COMPANY_CD THEN 0
            ELSE 1
        END,
        c.ID;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.getexcel_template_keys
