    m.SECURITY_TYPE,
    m.AUTH_TYPE,
    m.USERNAME,
    CASE
      WHEN m.PASSWORD_ENC IS NOT NULL AND TRIM(m.PASSWORD_ENC) <> '' THEN 1
      ELSE 0
    END AS HAS_PASSWORD,
    m.FROM_EMAIL,
    m.FROM_NAME,
    m.REPLY_TO_EMAIL,
    m.CONFIG_JSON,
    m.IS_DEFAULT,
    m.IS_ACTIVE,
    m.ISDEL,
    m.CREATE_BY,
    m.CREATE_AT,
    m.UPDATE_BY,
    m.UPDATE_AT
  FROM mail_setting m
  WHERE IFNULL(TRIM(m.COMPANY_CD), '') = v_company_cd
    AND m.MAIL_CD = v_mail_cd
    AND IFNULL(m.ISDEL, 0) = 0
  ORDER BY m.MAIL_ID DESC
  LIMIT 1;
END//
