    IN p_COMPANY_CD VARCHAR(20),
    IN p_CONFIG_GROUP VARCHAR(50),
    IN p_CONFIG_KEY VARCHAR(100),
    IN p_ACTIVE_ONLY CHAR(1)
)
BEGIN
    SELECT
        ID,
        COMPANY_CD,
        CONFIG_GROUP,
        CONFIG_KEY,
        CONFIG_VALUE,
        DATA_TYPE,
        DESCRIPTION,
        IFNULL(IS_ACTIVE, '1') AS IS_ACTIVE,
        IFNULL(ISDEL, '0') AS ISDEL,
        CREATE_BY,
        CREATE_AT,
        UPDATE_BY,
        UPDATE_AT
    FROM sys_config
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ISDEL, '0') = '0'
      AND (IFNULL(TRIM(p_CONFIG_GROUP), '') = '' OR CONFIG_GROUP = TRIM(p_CONFIG_GROUP))
      AND (IFNULL(TRIM(p_CONFIG_KEY), '') = '' OR CONFIG_KEY = TRIM(p_CONFIG_KEY))
      AND (IFNULL(TRIM(p_ACTIVE_ONLY), '1') <> '1' OR IFNULL(IS_ACTIVE, '1') = '1')
    ORDER BY CONFIG_GROUP, CONFIG_KEY;
END//
DELIMITER ;

