      COALESCE(NULLIF(TRIM(source.TEMPLATE_ID), ''), 'DEFAULT') AS TEMPLATE_ID,
      COALESCE(
        NULLIF(TRIM(MAX(CASE WHEN source.COMPANY_CD = v_company_cd AND source.USER_ID = v_user_id THEN source.TEMPLATE_NAME END)), ''),
        NULLIF(TRIM(MAX(source.TEMPLATE_NAME)), ''),
        COALESCE(NULLIF(TRIM(source.TEMPLATE_ID), ''), 'DEFAULT')
      ) AS TEMPLATE_NAME,
      MAX(CASE WHEN source.IS_DEFAULT_TEMPLATE = '1' THEN '1' ELSE '0' END) AS IS_DEFAULT_TEMPLATE,
      CASE
        WHEN SUM(CASE WHEN source.COMPANY_CD = v_company_cd AND source.USER_ID = v_user_id THEN 1 ELSE 0 END) > 0 THEN '0'
        ELSE '1'
      END AS IS_SYSTEM_TEMPLATE,
      COUNT(*) AS COLUMN_COUNT
    FROM (
      SELECT
        CASE WHEN u.ID IS NULL THEN d.COMPANY_CD ELSE u.COMPANY_CD END AS COMPANY_CD,
        CASE WHEN u.ID IS NULL THEN d.USER_ID ELSE u.USER_ID END AS USER_ID,
        CASE WHEN u.ID IS NULL THEN d.SCREEN_CD ELSE u.SCREEN_CD END AS SCREEN_CD,
        CASE WHEN u.ID IS NULL THEN d.GRID_ID ELSE u.GRID_ID END AS GRID_ID,
        COALESCE(NULLIF(TRIM(CASE WHEN u.ID IS NULL THEN d.TEMPLATE_ID ELSE u.TEMPLATE_ID END), ''), 'DEFAULT') AS TEMPLATE_ID,
        CASE WHEN u.ID IS NULL THEN d.TEMPLATE_NAME ELSE u.TEMPLATE_NAME END AS TEMPLATE_NAME,
        CASE WHEN u.ID IS NULL THEN d.IS_DEFAULT_TEMPLATE ELSE u.IS_DEFAULT_TEMPLATE END AS IS_DEFAULT_TEMPLATE,
        CASE WHEN u.ID IS NULL THEN d.COLUMN_NAME ELSE u.COLUMN_NAME END AS COLUMN_NAME,
        CASE WHEN u.ID IS NULL THEN d.ISDEL ELSE u.ISDEL END AS ISDEL
      FROM sys_grid_column_setting d
      LEFT JOIN sys_grid_column_setting u
        ON u.COMPANY_CD = v_company_cd
       AND u.USER_ID = v_user_id
       AND u.SCREEN_CD = d.SCREEN_CD
       AND u.GRID_ID = d.GRID_ID
       AND u.TEMPLATE_ID = d.TEMPLATE_ID
       AND u.COLUMN_NAME = d.COLUMN_NAME
       AND (v_active_only <> '1' OR u.ISDEL = '0')
      WHERE d.COMPANY_CD = ''
        AND d.USER_ID = ''
        AND d.SCREEN_CD = v_screen_cd
        AND d.GRID_ID = v_grid_id
        AND (v_active_only <> '1' OR d.ISDEL = '0')

      UNION ALL

      SELECT
        u.COMPANY_CD,
        u.USER_ID,
        u.SCREEN_CD,
        u.GRID_ID,
        COALESCE(NULLIF(TRIM(u.TEMPLATE_ID), ''), 'DEFAULT') AS TEMPLATE_ID,
        u.TEMPLATE_NAME,
        u.IS_DEFAULT_TEMPLATE,
        u.COLUMN_NAME,
        u.ISDEL
      FROM sys_grid_column_setting u
      WHERE u.COMPANY_CD = v_company_cd
        AND u.USER_ID = v_user_id
        AND u.SCREEN_CD = v_screen_cd
        AND u.GRID_ID = v_grid_id
        AND (v_active_only <> '1' OR u.ISDEL = '0')
        AND NOT EXISTS (
          SELECT 1
          FROM sys_grid_column_setting d2
          WHERE d2.COMPANY_CD = ''
            AND d2.USER_ID = ''
            AND d2.SCREEN_CD = u.SCREEN_CD
            AND d2.GRID_ID = u.GRID_ID
            AND d2.TEMPLATE_ID = u.TEMPLATE_ID
            AND d2.COLUMN_NAME = u.COLUMN_NAME
            AND (v_active_only <> '1' OR d2.ISDEL = '0')
        )
    ) source
    WHERE (v_active_only <> '1' OR source.ISDEL = '0')
    GROUP BY
      COALESCE(NULLIF(TRIM(source.TEMPLATE_ID), ''), 'DEFAULT')
  ) grouped
  ORDER BY
    CASE WHEN grouped.IS_DEFAULT_TEMPLATE = '1' THEN 0 ELSE 1 END,
    CASE WHEN grouped.IS_SYSTEM_TEMPLATE = '1' THEN 0 ELSE 1 END,
    grouped.TEMPLATE_NAME,
    grouped.TEMPLATE_ID;
END//
DELIMITER ;

