    UC.UPDATE_BY,
    UC.CREATE_BY,
    UC.CREATE_AT,
    UC.UPDATE_AT
  FROM user_info UI
  INNER JOIN user_company UC
    ON UC.USER_PK_ID = UI.USER_PK_ID
   AND UC.COMPANY_CD = TRIM(p_COMPANY_CD)
   AND IFNULL(UC.ISDEL, '0') <> '1'
  WHERE IFNULL(UI.ISDEL, '0') <> '1'
    AND (p_USER_PK_ID IS NULL OR p_USER_PK_ID = 0 OR UI.USER_PK_ID = p_USER_PK_ID)
    AND (p_USERID IS NULL OR p_USERID = '' OR UC.USERID = p_USERID)
  ORDER BY UC.USERID, UI.USER_PK_ID;
END//
