-- Dumping structure for procedure am_web_manager.login
DROP PROCEDURE IF EXISTS `login`;
DELIMITER //
CREATE PROCEDURE `login`(
  IN p_COMPANY_KEY VARCHAR(50),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_company_cd VARCHAR(20);
  DECLARE v_userid VARCHAR(50);
  DECLARE v_company_key VARCHAR(50);

  SET v_userid = TRIM(COALESCE(p_USERID, ''));
  SET v_company_key = TRIM(COALESCE(p_COMPANY_KEY, ''));
  SET v_company_cd = NULL;

  IF v_company_key <> '' THEN
    SET v_company_cd = (
      SELECT CI.COMPANY_CD
      FROM company_info CI
      WHERE IFNULL(CI.ISDEL, '0') <> '1'
        AND (
          CI.COMPANY_CD = v_company_key
          OR UPPER(REPLACE(REPLACE(REPLACE(IFNULL(CI.TAX_CD, ''), '-', ''), ' ', ''), '.', ''))
             = UPPER(REPLACE(REPLACE(REPLACE(v_company_key, '-', ''), ' ', ''), '.', ''))
        )
      ORDER BY
        CASE
          WHEN CI.COMPANY_CD = v_company_key THEN 0
          ELSE 1
        END,
        CI.COMPANY_CD
      LIMIT 1
    );
  END IF;

  SELECT
    UI.USER_PK_ID,
    UC.USERID,
    UI.USERNM,
    UI.PASSWD,
    UI.EMAIL,
    UI.MOBILE_NO,
    UI.AVATAR_URL,
    UC.COMPANY_CD,
    UC.USER_COMPANY_ID
  FROM user_company UC
  INNER JOIN user_info UI
    ON UI.USER_PK_ID = UC.USER_PK_ID
   AND IFNULL(UI.ISDEL, '0') <> '1'
   AND IFNULL(UI.IS_ACTIVE, '1') = '1'
  WHERE v_company_cd IS NOT NULL
    AND v_company_cd <> ''
    AND v_userid <> ''
    AND UC.COMPANY_CD = v_company_cd
    AND UC.USERID = v_userid
    AND IFNULL(UC.ISDEL, '0') <> '1'
    AND IFNULL(UC.IS_ACTIVE, '1') = '1'
  LIMIT 1;
END//
DELIMITER ;

