-- Dumping structure for procedure am_web_manager.reset_sys_user_permission
DROP PROCEDURE IF EXISTS `reset_sys_user_permission`;
DELIMITER //
CREATE PROCEDURE `reset_sys_user_permission`(
  IN p_COMPANY_CD VARCHAR(20), IN p_USERID VARCHAR(50), IN p_MENU_CODE VARCHAR(50)
)
BEGIN
  DECLARE v_menu_allowed BOOLEAN DEFAULT FALSE;
  SET p_COMPANY_CD = TRIM(p_COMPANY_CD);
  SET p_USERID = TRIM(p_USERID);
  IF NULLIF(TRIM(p_COMPANY_CD), '') IS NULL OR NULLIF(TRIM(p_USERID), '') IS NULL
     OR NULLIF(TRIM(p_MENU_CODE), '') IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Company, user and menu are required; default is managed separately';
  END IF;
  IF NOT EXISTS (
      SELECT 1 FROM user_company uc
      INNER JOIN user_info ui ON ui.USER_PK_ID = uc.USER_PK_ID
      WHERE uc.COMPANY_CD = TRIM(p_COMPANY_CD) AND uc.USERID = TRIM(p_USERID)
        AND uc.IS_ACTIVE = '1' AND uc.ISDEL = '0'
        AND ui.IS_ACTIVE = '1' AND ui.ISDEL = '0'
    ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Target user has no active company access';
  END IF;
  WITH RECURSIVE eligible AS (
    SELECT
        m.MENU_ID,
        m.MENU_CODE,
        m.MENU_NAME,
        NULLIF(TRIM(m.LABEL_TEXT), '') AS LABEL_TEXT,
        COALESCE(NULLIF(TRIM(m.CAPTION), ''), m.MENU_NAME) AS CAPTION,
        m.PARENT_ID,
        m.ROUTE_PATH,
        m.ICON,
        m.SORT_ORDER,
        m.IS_ACTIVE,
        CASE WHEN company_setting.ID IS NOT NULL
            THEN company_setting.IS_VISIBLE ELSE default_setting.IS_VISIBLE END AS IS_VISIBLE,
        CASE WHEN company_setting.ID IS NOT NULL
            THEN company_setting.IS_DISABLED ELSE default_setting.IS_DISABLED END AS IS_DISABLED
    FROM sys_menu m
    LEFT JOIN company_info company
        ON company.COMPANY_CD = p_COMPANY_CD
    LEFT JOIN sys_menu_company company_setting
        ON company_setting.MENU_ID = m.MENU_ID
       AND company_setting.COMPANY_CD = p_COMPANY_CD
    LEFT JOIN sys_menu_company default_setting
        ON default_setting.MENU_ID = m.MENU_ID
       AND default_setting.COMPANY_CD = ''
    -- Choose by row existence: a hidden/NULL company setting must not inherit default values.
    WHERE p_COMPANY_CD IS NOT NULL
      AND (
          p_COMPANY_CD = ''
          OR company.MENU_MODE = 'ALL'
          OR (company.MENU_MODE IN ('INVOICE', 'AMNOTE')
              AND (m.PRODUCT_SCOPE = 'COMMON' OR m.PRODUCT_SCOPE = company.MENU_MODE))
      )
      AND (company_setting.ID IS NOT NULL OR default_setting.ID IS NOT NULL)
      AND m.IS_ACTIVE = 1
      AND CASE WHEN company_setting.ID IS NOT NULL
          THEN company_setting.IS_VISIBLE ELSE default_setting.IS_VISIBLE END = 1
    ), reachable AS (
        SELECT root.* FROM eligible root WHERE root.PARENT_ID IS NULL
        UNION ALL
        SELECT child.*
        FROM eligible child
        INNER JOIN reachable parent ON child.PARENT_ID = parent.MENU_ID
    )
  SELECT EXISTS (
    SELECT 1 FROM reachable m
    INNER JOIN sys_user_permission def ON CONVERT(def.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(m.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci
      AND def.COMPANY_CD = '' AND def.USERID = '' AND def.ISDEL = '0'
    WHERE CONVERT(m.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(TRIM(p_MENU_CODE) USING utf8mb4) COLLATE utf8mb4_unicode_ci
      AND m.IS_DISABLED = 0
  ) INTO v_menu_allowed;
  IF NOT v_menu_allowed THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Menu is unavailable for company or canonical default is missing';
  END IF;
  DELETE FROM sys_user_permission
  WHERE COMPANY_CD = p_COMPANY_CD AND USERID = p_USERID
    AND CONVERT(MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci
        = CONVERT(TRIM(p_MENU_CODE) USING utf8mb4) COLLATE utf8mb4_unicode_ci;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.resetEInvoiceMessageWorkQueueStuck
DROP PROCEDURE IF EXISTS `resetEInvoiceMessageWorkQueueStuck`;
DELIMITER //
CREATE PROCEDURE `resetEInvoiceMessageWorkQueueStuck`()
BEGIN
  UPDATE einvoice_message_work_queue
     SET WORK_STATUS = 'WAIT_SEND',
         UPDATE_AT = NOW()
   WHERE WORK_STATUS = 'SENDING';

  UPDATE einvoice_message_work_queue
     SET WORK_STATUS = 'WAIT_RESPONSE',
         UPDATE_AT = NOW()
   WHERE WORK_STATUS = 'POLLING';

  SELECT ROW_COUNT() AS AFFECTED_ROWS;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.resetsys_grid_column_setting
DROP PROCEDURE IF EXISTS `resetsys_grid_column_setting`;
DELIMITER //
CREATE PROCEDURE `resetsys_grid_column_setting`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USER_ID VARCHAR(50),
  IN p_GRID_ID VARCHAR(100)
)
BEGIN
  DECLARE v_company_cd VARCHAR(20);
  DECLARE v_user_id VARCHAR(50);
  DECLARE v_grid_id VARCHAR(100);

  SET v_company_cd = TRIM(COALESCE(p_COMPANY_CD, ''));
  SET v_user_id = TRIM(COALESCE(p_USER_ID, ''));
  SET v_grid_id = TRIM(COALESCE(p_GRID_ID, ''));

  IF v_company_cd = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF v_user_id = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'USER_ID is required';
  END IF;

  IF v_grid_id = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GRID_ID is required';
  END IF;

  DELETE FROM sys_grid_template
  WHERE COMPANY_CD = v_company_cd
    AND USER_ID = v_user_id
    AND GRID_ID = v_grid_id;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.revoke_refresh_token_session
DROP PROCEDURE IF EXISTS `revoke_refresh_token_session`;
DELIMITER //
CREATE PROCEDURE `revoke_refresh_token_session`(
  IN p_REFRESH_TOKEN_HASH VARCHAR(255),
  IN p_NOW DATETIME
)
BEGIN
  UPDATE refresh_token_session
  SET REVOKED_AT = p_NOW
  WHERE REFRESH_TOKEN_HASH = p_REFRESH_TOKEN_HASH
    AND REVOKED_AT IS NULL;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rotate_refresh_token_session
DROP PROCEDURE IF EXISTS `rotate_refresh_token_session`;
DELIMITER //
CREATE PROCEDURE `rotate_refresh_token_session`(
  IN p_OLD_REFRESH_TOKEN_HASH VARCHAR(255),
  IN p_NEW_REFRESH_TOKEN_HASH VARCHAR(255),
  IN p_CREATE_AT DATETIME,
  IN p_EXPIRES_AT DATETIME
)
BEGIN
  DECLARE v_USER_ID VARCHAR(50);
  DECLARE v_USER_NAME VARCHAR(255);
  DECLARE v_COMPANY_CD VARCHAR(50);
  DECLARE v_DB_NAME VARCHAR(100);
  DECLARE v_ROLES_JSON TEXT;
  DECLARE v_EXPIRES_AT DATETIME;
  DECLARE v_not_found INT DEFAULT 0;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;

  START TRANSACTION;

  SELECT
    USER_ID,
    USER_NAME,
    COMPANY_CD,
    DB_NAME,
    ROLES_JSON,
    EXPIRES_AT
  INTO
    v_USER_ID,
    v_USER_NAME,
    v_COMPANY_CD,
    v_DB_NAME,
    v_ROLES_JSON,
    v_EXPIRES_AT
  FROM refresh_token_session
  WHERE REFRESH_TOKEN_HASH = p_OLD_REFRESH_TOKEN_HASH
    AND REVOKED_AT IS NULL
    AND REPLACED_BY_HASH IS NULL
    AND EXPIRES_AT > UTC_TIMESTAMP()
    AND EXPIRES_AT = p_EXPIRES_AT
  LIMIT 1 FOR UPDATE;

  IF v_not_found = 1 THEN
    ROLLBACK;
    SELECT 0 AS ROTATED;
  ELSE

    UPDATE refresh_token_session
    SET REPLACED_BY_HASH = p_NEW_REFRESH_TOKEN_HASH
    WHERE REFRESH_TOKEN_HASH = p_OLD_REFRESH_TOKEN_HASH;

      USER_ID,
      USER_NAME,
      COMPANY_CD,
      DB_NAME,
      ROLES_JSON,
      REFRESH_TOKEN_HASH,
      CREATE_AT,
      EXPIRES_AT
    )
    VALUES
    (
      v_USER_ID,
      v_USER_NAME,
      v_COMPANY_CD,
      v_DB_NAME,
      v_ROLES_JSON,
      p_NEW_REFRESH_TOKEN_HASH,
      p_CREATE_AT,
      v_EXPIRES_AT
    );
    COMMIT;
    SELECT 1 AS ROTATED;
  END IF;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rpt_account_detail_s38dn
DROP PROCEDURE IF EXISTS `rpt_account_detail_s38dn`;
DELIMITER //
CREATE PROCEDURE `rpt_account_detail_s38dn`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_ACCOUNT_CD VARCHAR(1000),
    IN p_FC_TYPE VARCHAR(255),
    IN p_LANGUAGE VARCHAR(20)
)
    COMMENT '[C-H] sổ chi tiết tài khoản'
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_before_from_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_account_cd VARCHAR(1000);
    DECLARE v_fc_type VARCHAR(255);
    DECLARE v_currency_text VARCHAR(255);
    DECLARE v_report_period_text VARCHAR(255);
    DECLARE v_amount_unit_text VARCHAR(100);
    DECLARE v_company_cd VARCHAR(20);
    DECLARE v_use_fc TINYINT DEFAULT 0;
    DECLARE v_rows_inserted INT DEFAULT 0;
    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_ymd = DATE_FORMAT(p_FROM_DATE, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_before_from_ymd = DATE_FORMAT(DATE_SUB(p_FROM_DATE, INTERVAL 1 DAY), '%Y%m%d');
    SET v_company_cd = CONVERT(TRIM(IFNULL(p_COMPANY_CD, '')) USING utf8mb4);
    SET v_language = CONVERT(UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET'))) USING utf8mb4);
    SET v_account_cd = CONVERT(REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '') USING utf8mb4);
    SET v_fc_type = CONVERT(REPLACE(UPPER(TRIM(IFNULL(p_FC_TYPE, ''))), ' ', '') USING utf8mb4);

    IF UPPER(v_account_cd) IN ('ALL', '*') THEN
        SET v_account_cd = '';
    END IF;
    DROP TEMPORARY TABLE IF EXISTS tmp_filter_account_cd;
    CREATE TEMPORARY TABLE tmp_filter_account_cd (
      CD VARCHAR(64) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    IF IFNULL(v_account_cd, '') <> '' AND UPPER(IFNULL(v_account_cd, '')) NOT IN ('ALL', '*') THEN
      SELECT DISTINCT TRIM(jt.val)
      FROM JSON_TABLE(
        CONCAT('["', REPLACE(REPLACE(REPLACE(v_account_cd, '|', ','), ' ', ''), ',', '","'), '"]'),
        '$[*]' COLUMNS (val VARCHAR(64) PATH '$')
      ) jt
      WHERE NULLIF(TRIM(jt.val), '') IS NOT NULL
        AND UPPER(TRIM(jt.val)) NOT IN ('ALL', '*');
    END IF;

-- SELECT * from tmp_filter_account_cd; -- -- 11111; 1112 

    IF v_fc_type = 'ALL' THEN
        SET v_fc_type = '';
    END IF;
    DROP TEMPORARY TABLE IF EXISTS tmp_filter_fc_type;
    CREATE TEMPORARY TABLE tmp_filter_fc_type (
      CD VARCHAR(64) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    IF IFNULL(v_fc_type, '') <> '' AND UPPER(IFNULL(v_fc_type, '')) NOT IN ('ALL', '*') THEN
      SELECT DISTINCT TRIM(jt.val)
      FROM JSON_TABLE(
        CONCAT('["', REPLACE(REPLACE(REPLACE(v_fc_type, '|', ','), ' ', ''), ',', '","'), '"]'),
        '$[*]' COLUMNS (val VARCHAR(64) PATH '$')
      ) jt
      WHERE NULLIF(TRIM(jt.val), '') IS NOT NULL
        AND UPPER(TRIM(jt.val)) NOT IN ('ALL', '*');
    END IF;

-- SELECT * from tmp_filter_fc_type;

    SET v_use_fc = CASE WHEN v_fc_type <> '' AND v_fc_type <> 'VND' AND LOCATE(',', v_fc_type) = 0 THEN 1 ELSE 0 END;
    SET v_currency_text = CASE WHEN v_fc_type = '' THEN 'VND' ELSE v_fc_type END;
    SET v_report_period_text = CONCAT('Từ ngày ', DATE_FORMAT(p_FROM_DATE, '%d/%m/%Y'), ' đến ngày ', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y'));
    SET v_amount_unit_text = CASE WHEN v_use_fc = 1 THEN CONCAT('Loại tiền: ', v_currency_text) ELSE 'Đơn vị tính: Đồng' END;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_accounts;
    CREATE TEMPORARY TABLE tmp_account_detail_accounts
    (
        ACCOUNT_SORT INT NOT NULL AUTO_INCREMENT,
        ACC_CD VARCHAR(20) NOT NULL,
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACCOUNT_SORT),
        UNIQUE KEY uq_tmp_account_detail_accounts_01 (ACC_CD)
    ) ENGINE=InnoDB;

    SELECT
        account.ACC_CD,
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN account.ACCTITLE_NM_CHINA
                WHEN 'JAPAN' THEN account.ACCTITLE_NM_JAPAN
                ELSE account.ACCTITLE_NM_VIET
            END), ''),
            NULLIF(TRIM(account.ACCTITLE_NM_VIET), ''),
            NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''),
            account.ACC_CD
        )
    FROM acclist_info account
    INNER JOIN
    (
        SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
        FROM acclist_info
        WHERE COMPANY_CD = v_company_cd
          AND IFNULL(ISDEL, '0')  = '0' 
          AND TRIM(IFNULL(ACC_CD, '')) <> ''
        GROUP BY ACC_CD
    ) latest
        ON latest.ACC_ID = account.ACC_ID
    WHERE account.COMPANY_CD = v_company_cd
      AND IFNULL(account.ISDEL, '0')  = '0' 
      AND (v_account_cd = '' OR EXISTS (SELECT 1 FROM tmp_filter_account_cd f WHERE f.CD = (account.ACC_CD)))
    ORDER BY account.ACC_CD;

-- SELECT * from tmp_account_detail_accounts; -- 99999

    -- Build the selected accounts' real chart-of-accounts ancestry here. The
    -- API and TreeList receive a complete parent key from the procedure.
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_accounts;
    CREATE TEMPORARY TABLE tmp_account_detail_tree_accounts
    (
        ACCOUNT_SORT INT NOT NULL AUTO_INCREMENT,
        ACC_ID INT NOT NULL,
        ACC_PARENT_ID INT NOT NULL DEFAULT 0,
        PARENT_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_LEVEL INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL,
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACCOUNT_SORT),
        UNIQUE KEY uq_tmp_account_detail_tree_id (ACC_ID),
        UNIQUE KEY uq_tmp_account_detail_tree_cd (ACC_CD),
        INDEX idx_tmp_account_detail_tree_parent (ACC_PARENT_ID)
    ) ENGINE=InnoDB;

    SELECT account.ACC_ID, IFNULL(account.ACC_PARENT_ID, 0), IFNULL(parent.ACC_CD, ''), IFNULL(account.ACCOUNT_LEVEL, 0), account.ACC_CD, account.ACCOUNT_NAME
    FROM
    (
        SELECT source.ACC_ID, source.ACC_PARENT_ID, source.LEVEL AS ACCOUNT_LEVEL, source.ACC_CD,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN source.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN source.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN source.ACCTITLE_NM_CHINA
                WHEN 'JAPAN' THEN source.ACCTITLE_NM_JAPAN
                ELSE source.ACCTITLE_NM_VIET
            END), ''), NULLIF(TRIM(source.ACCTITLE_NM_VIET), ''),
                NULLIF(TRIM(source.ACCTITLE_NM_ENG), ''), source.ACC_CD) AS ACCOUNT_NAME
        FROM acclist_info source
        INNER JOIN tmp_account_detail_accounts selected ON selected.ACC_CD = source.ACC_CD
        INNER JOIN
        (
            SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
            FROM acclist_info
            WHERE COMPANY_CD = v_company_cd
              AND IFNULL(ISDEL, '0')  = '0' 
            GROUP BY ACC_CD
        ) latest ON latest.ACC_ID = source.ACC_ID
        WHERE source.COMPANY_CD = v_company_cd
          AND IFNULL(source.ISDEL, '0')  = '0' 
    ) account
    LEFT JOIN acclist_info parent
        ON parent.ACC_ID = account.ACC_PARENT_ID
       AND parent.COMPANY_CD = v_company_cd
       AND IFNULL(parent.ISDEL, '0')  = '0' 
    ORDER BY account.ACC_CD;

 -- SELECT * from tmp_account_detail_tree_accounts; -- 99999

    -- Use separate frontier/candidate tables: MySQL 5.6 cannot reopen a
    -- temporary table that is both the INSERT target and a SELECT source.
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_frontier;
    CREATE TEMPORARY TABLE tmp_account_detail_tree_frontier
    (
        ACC_ID INT NOT NULL,
        PRIMARY KEY (ACC_ID)
    ) ENGINE=InnoDB;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_candidates;
    CREATE TEMPORARY TABLE tmp_account_detail_tree_candidates
    (
        ACC_ID INT NOT NULL,
        ACC_PARENT_ID INT NOT NULL DEFAULT 0,
        PARENT_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_LEVEL INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL,
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_ID),
        UNIQUE KEY uq_tmp_account_detail_tree_candidate_cd (ACC_CD)
    ) ENGINE=InnoDB;

    SELECT ACC_ID FROM tmp_account_detail_tree_accounts;

-- SELECT * from tmp_account_detail_tree_accounts; -- 99999

    SET v_rows_inserted = 1;
    WHILE v_rows_inserted > 0 DO
        DELETE FROM tmp_account_detail_tree_candidates;
        SELECT parent.ACC_ID, IFNULL(parent.ACC_PARENT_ID, 0), IFNULL(grandparent.ACC_CD, ''), IFNULL(parent.LEVEL, 0), parent.ACC_CD,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN parent.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN parent.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN parent.ACCTITLE_NM_CHINA
                WHEN 'JAPAN' THEN parent.ACCTITLE_NM_JAPAN
                ELSE parent.ACCTITLE_NM_VIET
            END), ''), NULLIF(TRIM(parent.ACCTITLE_NM_VIET), ''),
                NULLIF(TRIM(parent.ACCTITLE_NM_ENG), ''), parent.ACC_CD)
        FROM tmp_account_detail_tree_frontier child
        INNER JOIN acclist_info parent ON parent.ACC_ID = child.ACC_ID
        LEFT JOIN acclist_info grandparent ON grandparent.ACC_ID = parent.ACC_PARENT_ID
        WHERE parent.ACC_PARENT_ID > 0
          AND parent.COMPANY_CD = v_company_cd
          AND IFNULL(parent.ISDEL, '0')  = '0' ;

        SELECT ACC_ID, ACC_PARENT_ID, PARENT_CD, ACCOUNT_LEVEL, ACC_CD, ACCOUNT_NAME
        FROM tmp_account_detail_tree_candidates;
        SET v_rows_inserted = ROW_COUNT();

        DELETE FROM tmp_account_detail_tree_frontier;
        SELECT ACC_ID FROM tmp_account_detail_tree_candidates;
    END WHILE;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_candidates;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_frontier;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_account_paths;
    CREATE TEMPORARY TABLE tmp_account_detail_account_paths
    (
        ANCESTOR_ID INT NOT NULL,
        DESCENDANT_ID INT NOT NULL,
        ANCESTOR_CD VARCHAR(20) NOT NULL,
        DESCENDANT_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ANCESTOR_ID, DESCENDANT_ID),
        INDEX idx_tmp_account_detail_path_descendant (DESCENDANT_ID)
    ) ENGINE=InnoDB;

    SELECT tree.ACC_ID, tree.ACC_ID, tree.ACC_CD, tree.ACC_CD
    FROM tmp_account_detail_tree_accounts tree
    INNER JOIN tmp_account_detail_accounts selected ON selected.ACC_CD = tree.ACC_CD;

    -- Keep the recursive frontier separate from the closure table for MySQL 5.6.
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_path_frontier;
    CREATE TEMPORARY TABLE tmp_account_detail_path_frontier
    (
        ANCESTOR_ID INT NOT NULL,
        DESCENDANT_ID INT NOT NULL,
        ANCESTOR_CD VARCHAR(20) NOT NULL,
        DESCENDANT_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ANCESTOR_ID, DESCENDANT_ID)
    ) ENGINE=InnoDB;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_path_candidates;
    CREATE TEMPORARY TABLE tmp_account_detail_path_candidates
    (
        ANCESTOR_ID INT NOT NULL,
        DESCENDANT_ID INT NOT NULL,
        ANCESTOR_CD VARCHAR(20) NOT NULL,
        DESCENDANT_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ANCESTOR_ID, DESCENDANT_ID)
    ) ENGINE=InnoDB;

    SELECT ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD
    FROM tmp_account_detail_account_paths;

    SET v_rows_inserted = 1;
    WHILE v_rows_inserted > 0 DO
        DELETE FROM tmp_account_detail_path_candidates;
        SELECT parent.ACC_ID, paths.DESCENDANT_ID, parent.ACC_CD, paths.DESCENDANT_CD
        FROM tmp_account_detail_path_frontier paths
        INNER JOIN acclist_info child ON child.ACC_ID = paths.ANCESTOR_ID
        INNER JOIN acclist_info parent ON parent.ACC_ID = child.ACC_PARENT_ID
        WHERE child.ACC_PARENT_ID > 0
          AND child.COMPANY_CD = v_company_cd
          AND parent.COMPANY_CD = v_company_cd
          AND IFNULL(child.ISDEL, '0')  = '0' 
          AND IFNULL(parent.ISDEL, '0')  = '0' ;

        SELECT ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD
        FROM tmp_account_detail_path_candidates;
        SET v_rows_inserted = ROW_COUNT();

        DELETE FROM tmp_account_detail_path_frontier;
        SELECT ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD
        FROM tmp_account_detail_path_candidates;
    END WHILE;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_path_candidates;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_path_frontier;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_latest_open;
    CREATE TEMPORARY TABLE tmp_account_detail_latest_open
    (
        ACC_CD VARCHAR(20) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB;

    SELECT account.ACC_CD, IFNULL(MAX(opening.OPEN_YMD), '')
    FROM tmp_account_detail_accounts account
    LEFT JOIN before_states opening
        ON opening.COMPANY_CD = v_company_cd
       AND opening.ACC_CD  = account.ACC_CD 
       AND IFNULL(opening.ISDEL, '0')  = '0' 
       AND IFNULL(opening.OPEN_YMD, '') <= v_before_from_ymd
       AND (v_fc_type = '' OR EXISTS (SELECT 1 FROM tmp_filter_fc_type f WHERE f.CD = (UPPER(IFNULL(opening.FC_TYPE, 'VND')))))
    GROUP BY account.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_opening_base;
    CREATE TEMPORARY TABLE tmp_account_detail_opening_base
    (
        ACC_CD VARCHAR(20) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '00000000',
        DEBIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        CREDIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB;

    SELECT
        account.ACC_CD,
        IFNULL(NULLIF(latest.OPEN_YMD, ''), '00000000'),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.DEBIT_FC ELSE opening.DEBIT END), 0),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.CREDIT_FC ELSE opening.CREDIT END), 0)
    FROM tmp_account_detail_accounts account
    LEFT JOIN tmp_account_detail_latest_open latest
        ON latest.ACC_CD = account.ACC_CD
    LEFT JOIN before_states opening
        ON opening.COMPANY_CD = v_company_cd
       AND opening.ACC_CD  = account.ACC_CD 
       AND opening.OPEN_YMD = latest.OPEN_YMD
       AND IFNULL(opening.ISDEL, '0')  = '0' 
       AND (v_fc_type = '' OR EXISTS (SELECT 1 FROM tmp_filter_fc_type f WHERE f.CD = (UPPER(IFNULL(opening.FC_TYPE, 'VND')))))
    GROUP BY account.ACC_CD, latest.OPEN_YMD;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_movements;
    CREATE TEMPORARY TABLE tmp_account_detail_movements
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACCOUNT_SORT INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        DOCUMENT_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        CSD_ACC_CD VARCHAR(50) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        CREDIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        SORT_NO VARCHAR(50) NOT NULL DEFAULT '',
        SORT_CHIT_ID BIGINT NOT NULL DEFAULT 0,
        SOURCE_CHIT_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        SORT_DETAIL INT NOT NULL DEFAULT 0,
        SORT_SIDE INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_account_detail_movements_01 (ACC_CD, CHIT_YMD, SORT_NO, SORT_CHIT_ID, SORT_DETAIL, SORT_SIDE)
    ) ENGINE=InnoDB;

        ACCOUNT_SORT,
        ACC_CD,
        ACCOUNT_NAME,
        CHIT_YMD,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        CSD_ACC_CD,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        NOTE_TEXT,
        SORT_NO,
        SORT_CHIT_ID,
        SOURCE_CHIT_TYPE,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        account.ACCOUNT_NAME,
        COALESCE(NULLIF(TRIM(IFNULL(h.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(d.CHIT_YMD, '')), ''), ''),
        CASE WHEN IFNULL(h.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(h.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(h.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(h.CHIT_NO), ''), NULLIF(TRIM(h.CHIT_CD), ''), ''),
        CASE
            WHEN COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD) REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(STR_TO_DATE(COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD), '%Y%m%d'), '%d/%m/%Y')
            ELSE COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD)
        END,
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN ddesc_en.DESCRIPTION WHEN 'KOR' THEN ddesc_ko.DESCRIPTION WHEN 'CHINA' THEN ddesc_china.DESCRIPTION ELSE ddesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN hdesc_en.DESCRIPTION WHEN 'KOR' THEN hdesc_ko.DESCRIPTION WHEN 'CHINA' THEN hdesc_china.DESCRIPTION ELSE hdesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(h.PAYER_INFO), ''),
            ''
        ),
        TRIM(IFNULL(d.CREDIT, '')),
        CASE WHEN v_use_fc = 1 THEN IFNULL(d.FC_AMOUNT, 0) ELSE IFNULL(d.AMOUNT, 0) END,
        0,
        IFNULL(d.CHITDETAIL_CD, ''),
        IFNULL(h.CHIT_NO, ''),
        IFNULL(h.CHIT_ID, 0),
        IFNULL(h.CHIT_TYPE, ''),
        IFNULL(d.SORT, 0),
        1
    FROM chitdetailinfo d
    INNER JOIN tmp_account_detail_accounts account
        ON account.ACC_CD  = TRIM(IFNULL(d.DEBIT, '')) 
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = d.COMPANY_CD
       AND h.CHIT_ID = d.CHIT_ID
       AND IFNULL(h.ISDEL, '0')  = '0' 
    LEFT JOIN chitdescriptioninfo hdesc_vi ON hdesc_vi.COMPANY_CD = h.COMPANY_CD AND hdesc_vi.CHIT_ID = h.CHIT_ID AND hdesc_vi.LANG_TYPE = 'VIET'  AND IFNULL(hdesc_vi.ISDEL, '0')  = '0' 
    LEFT JOIN chitdescriptioninfo hdesc_en ON hdesc_en.COMPANY_CD = h.COMPANY_CD AND hdesc_en.CHIT_ID = h.CHIT_ID AND hdesc_en.LANG_TYPE = 'ENG'  AND IFNULL(hdesc_en.ISDEL, '0')  = '0' 
    LEFT JOIN chitdescriptioninfo hdesc_ko ON hdesc_ko.COMPANY_CD = h.COMPANY_CD AND hdesc_ko.CHIT_ID = h.CHIT_ID AND hdesc_ko.LANG_TYPE = 'KOR'  AND IFNULL(hdesc_ko.ISDEL, '0')  = '0' 
    LEFT JOIN chitdescriptioninfo hdesc_china ON hdesc_china.COMPANY_CD = h.COMPANY_CD AND hdesc_china.CHIT_ID = h.CHIT_ID AND hdesc_china.LANG_TYPE = 'CHINA'  AND IFNULL(hdesc_china.ISDEL, '0')  = '0' 
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi ON ddesc_vi.COMPANY_CD = d.COMPANY_CD AND ddesc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_vi.LANG_TYPE = 'VIET'  AND IFNULL(ddesc_vi.ISDEL, '0')  = '0' 
    LEFT JOIN chitdetaildescriptioninfo ddesc_en ON ddesc_en.COMPANY_CD = d.COMPANY_CD AND ddesc_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_en.LANG_TYPE = 'ENG'  AND IFNULL(ddesc_en.ISDEL, '0')  = '0' 
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko ON ddesc_ko.COMPANY_CD = d.COMPANY_CD AND ddesc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_ko.LANG_TYPE = 'KOR'  AND IFNULL(ddesc_ko.ISDEL, '0')  = '0' 
    LEFT JOIN chitdetaildescriptioninfo ddesc_china ON ddesc_china.COMPANY_CD = d.COMPANY_CD AND ddesc_china.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_china.LANG_TYPE = 'CHINA'  AND IFNULL(ddesc_china.ISDEL, '0')  = '0' 
    WHERE d.COMPANY_CD = v_company_cd
      AND IFNULL(d.ISDEL, '0')  = '0' 
      AND IFNULL(d.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(h.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(d.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND (v_fc_type = '' OR EXISTS (SELECT 1 FROM tmp_filter_fc_type f WHERE f.CD = (UPPER(IFNULL(d.FC_TYPE, 'VND')))));

        ACCOUNT_SORT,
        ACC_CD,
        ACCOUNT_NAME,
        CHIT_YMD,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        CSD_ACC_CD,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        NOTE_TEXT,
        SORT_NO,
        SORT_CHIT_ID,
        SOURCE_CHIT_TYPE,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        account.ACCOUNT_NAME,
        COALESCE(NULLIF(TRIM(IFNULL(h.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(d.CHIT_YMD, '')), ''), ''),
        CASE WHEN IFNULL(h.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(h.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(h.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(h.CHIT_NO), ''), NULLIF(TRIM(h.CHIT_CD), ''), ''),
        CASE
            WHEN COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD) REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(STR_TO_DATE(COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD), '%Y%m%d'), '%d/%m/%Y')
            ELSE COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD)
        END,
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN ddesc_en.DESCRIPTION WHEN 'KOR' THEN ddesc_ko.DESCRIPTION WHEN 'CHINA' THEN ddesc_china.DESCRIPTION ELSE ddesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN hdesc_en.DESCRIPTION WHEN 'KOR' THEN hdesc_ko.DESCRIPTION WHEN 'CHINA' THEN hdesc_china.DESCRIPTION ELSE hdesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(h.PAYER_INFO), ''),
            ''
        ),
        TRIM(IFNULL(d.DEBIT, '')),
        0,
        CASE WHEN v_use_fc = 1 THEN IFNULL(d.FC_AMOUNT, 0) ELSE IFNULL(d.AMOUNT, 0) END,
        IFNULL(d.CHITDETAIL_CD, ''),
        IFNULL(h.CHIT_NO, ''),
        IFNULL(h.CHIT_ID, 0),
        IFNULL(h.CHIT_TYPE, ''),
        IFNULL(d.SORT, 0),
        2
    FROM chitdetailinfo d
    INNER JOIN tmp_account_detail_accounts account
        ON account.ACC_CD  = TRIM(IFNULL(d.CREDIT, '')) 
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = d.COMPANY_CD
       AND h.CHIT_ID = d.CHIT_ID
       AND IFNULL(h.ISDEL, '0')  = '0' 
    LEFT JOIN chitdescriptioninfo hdesc_vi ON hdesc_vi.COMPANY_CD = h.COMPANY_CD AND hdesc_vi.CHIT_ID = h.CHIT_ID AND hdesc_vi.LANG_TYPE = 'VIET'  AND IFNULL(hdesc_vi.ISDEL, '0')  = '0' 
    LEFT JOIN chitdescriptioninfo hdesc_en ON hdesc_en.COMPANY_CD = h.COMPANY_CD AND hdesc_en.CHIT_ID = h.CHIT_ID AND hdesc_en.LANG_TYPE = 'ENG'  AND IFNULL(hdesc_en.ISDEL, '0')  = '0' 
    LEFT JOIN chitdescriptioninfo hdesc_ko ON hdesc_ko.COMPANY_CD = h.COMPANY_CD AND hdesc_ko.CHIT_ID = h.CHIT_ID AND hdesc_ko.LANG_TYPE = 'KOR'  AND IFNULL(hdesc_ko.ISDEL, '0')  = '0' 
    LEFT JOIN chitdescriptioninfo hdesc_china ON hdesc_china.COMPANY_CD = h.COMPANY_CD AND hdesc_china.CHIT_ID = h.CHIT_ID AND hdesc_china.LANG_TYPE = 'CHINA'  AND IFNULL(hdesc_china.ISDEL, '0')  = '0' 
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi ON ddesc_vi.COMPANY_CD = d.COMPANY_CD AND ddesc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_vi.LANG_TYPE = 'VIET'  AND IFNULL(ddesc_vi.ISDEL, '0')  = '0' 
    LEFT JOIN chitdetaildescriptioninfo ddesc_en ON ddesc_en.COMPANY_CD = d.COMPANY_CD AND ddesc_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_en.LANG_TYPE = 'ENG'  AND IFNULL(ddesc_en.ISDEL, '0')  = '0' 
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko ON ddesc_ko.COMPANY_CD = d.COMPANY_CD AND ddesc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_ko.LANG_TYPE = 'KOR'  AND IFNULL(ddesc_ko.ISDEL, '0')  = '0' 
    LEFT JOIN chitdetaildescriptioninfo ddesc_china ON ddesc_china.COMPANY_CD = d.COMPANY_CD AND ddesc_china.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_china.LANG_TYPE = 'CHINA'  AND IFNULL(ddesc_china.ISDEL, '0')  = '0' 
    WHERE d.COMPANY_CD = v_company_cd
      AND IFNULL(d.ISDEL, '0')  = '0' 
      AND IFNULL(d.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(h.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(d.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND (v_fc_type = '' OR EXISTS (SELECT 1 FROM tmp_filter_fc_type f WHERE f.CD = (UPPER(IFNULL(d.FC_TYPE, 'VND')))));

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_sums;
    CREATE TEMPORARY TABLE tmp_account_detail_sums
    (
        ACC_CD VARCHAR(20) NOT NULL,
        OPENING_NET DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PERIOD_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PERIOD_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        ENDING_NET DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB;

    SELECT
        account.ACC_CD,
        IFNULL(base.DEBIT_AMOUNT, 0) - IFNULL(base.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(base.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD < v_from_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.CREDIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(base.DEBIT_AMOUNT, 0) - IFNULL(base.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(base.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0)
    FROM tmp_account_detail_accounts account
    LEFT JOIN tmp_account_detail_opening_base base
        ON base.ACC_CD = account.ACC_CD
    LEFT JOIN tmp_account_detail_movements movement
        ON movement.ACC_CD = account.ACC_CD
    GROUP BY account.ACC_CD, base.OPEN_YMD, base.DEBIT_AMOUNT, base.CREDIT_AMOUNT;

    DROP TEMPORARY TABLE IF EXISTS tmp_REPORT_RETURN;
    CREATE TEMPORARY TABLE tmp_REPORT_RETURN
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_KEY VARCHAR(100) NOT NULL DEFAULT '',
        PARENT_ROW_KEY VARCHAR(100) NULL,
        ROW_SORT INT NOT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(100) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        ROW_LEVEL INT NOT NULL DEFAULT 0,
        ACCOUNT_CD_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        ACCOUNT_NAME_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        OBJECT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        CURRENCY_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        DOCUMENT_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        CSD_ACC_CD VARCHAR(50) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,6) NULL,
        CREDIT_AMOUNT DECIMAL(18,6) NULL,
        BALANCE_DEBIT DECIMAL(18,6) NULL,
        BALANCE_CREDIT DECIMAL(18,6) NULL,
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        SOURCE_CHIT_ID BIGINT NULL DEFAULT NULL,
        SOURCE_CHIT_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_REPORT_RETURN_01 (ROW_SORT, ROW_NO)
    ) ENGINE=InnoDB;

    IF (SELECT COUNT(*) FROM tmp_account_detail_accounts) = 0 THEN
            ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION
        )
        VALUES
        (
            'NO_ACCOUNT',
            10,
            v_company_cd,
            'ACCOUNT_DETAIL',
            'EMPTY',
            0,
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Chọn tài khoản để xem sổ chi tiết'
        );
    ELSE
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT,
            BALANCE_DEBIT,
            BALANCE_CREDIT
        )
        SELECT
            CONCAT(account.ACC_CD, '_GROUP'),
            CASE WHEN account.PARENT_CD = '' THEN NULL ELSE CONCAT(account.PARENT_CD, '_GROUP') END,
            account.ACCOUNT_SORT * 1000000 + 1,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'GROUP',
            account.ACCOUNT_LEVEL,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            '',
            ROUND(SUM(IFNULL(sums.PERIOD_DEBIT, 0)), 2),
            ROUND(SUM(IFNULL(sums.PERIOD_CREDIT, 0)), 2),
            ROUND(GREATEST(SUM(IFNULL(sums.ENDING_NET, 0)), 0), 2),
            ROUND(GREATEST(-SUM(IFNULL(sums.ENDING_NET, 0)), 0), 2)
        FROM tmp_account_detail_tree_accounts account
        LEFT JOIN tmp_account_detail_account_paths paths
            ON paths.ANCESTOR_ID = account.ACC_ID
        LEFT JOIN tmp_account_detail_sums sums
            ON sums.ACC_CD = paths.DESCENDANT_CD
        GROUP BY account.ACCOUNT_SORT, account.ACC_ID, account.ACC_PARENT_ID,
            account.PARENT_CD, account.ACC_CD, account.ACCOUNT_NAME, account.ACCOUNT_LEVEL;

            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            BALANCE_DEBIT,
            BALANCE_CREDIT
        )
        SELECT
            CONCAT(account.ACC_CD, '_OPENING'),
            CONCAT(account.ACC_CD, '_GROUP'),
            account.ACCOUNT_SORT * 1000000 + 10,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'OPENING_TOTAL',
            1,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Số dư đầu kỳ',
            ROUND(GREATEST(sums.OPENING_NET, 0), 2),
            ROUND(GREATEST(-sums.OPENING_NET, 0), 2)
        FROM tmp_account_detail_accounts account
        INNER JOIN tmp_account_detail_sums sums
            ON sums.ACC_CD = account.ACC_CD;

            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION
        )
        SELECT
            CONCAT(account.ACC_CD, '_GROUP'), -- _PERIOD_HEADER
            CONCAT(account.ACC_CD, '_GROUP'),
            account.ACCOUNT_SORT * 1000000 + 20,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'SECTION',
            1,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Số phát sinh trong kỳ'
        FROM tmp_account_detail_accounts account;

            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            ENTRY_DATE,
            DOCUMENT_NO,
            DOCUMENT_DATE,
            DESCRIPTION,
            CSD_ACC_CD,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT,
            BALANCE_DEBIT,
            BALANCE_CREDIT,
            NOTE_TEXT,
            SOURCE_CHIT_ID,
            SOURCE_CHIT_TYPE
        )
        SELECT
            CONCAT('DETAIL_', running.ROW_NO),
            CONCAT(running.ACC_CD, '_GROUP'), -- _PERIOD_HEADER
            running.ACCOUNT_SORT * 1000000 + 1000 + running.ROW_NO,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', running.ACCOUNT_SORT, '_', running.ACC_CD),
            'DETAIL',
            2,
            running.ACC_CD,
            running.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            running.ENTRY_DATE,
            running.DOCUMENT_NO,
            running.DOCUMENT_DATE,
            running.DESCRIPTION,
            running.CSD_ACC_CD,
            ROUND(running.DEBIT_AMOUNT, 2),
            ROUND(running.CREDIT_AMOUNT, 2),
            ROUND(GREATEST(running.RUNNING_NET, 0), 2),
            ROUND(GREATEST(-running.RUNNING_NET, 0), 2),
            running.NOTE_TEXT,
            running.SORT_CHIT_ID,
            running.SOURCE_CHIT_TYPE
        FROM
        (
            SELECT
                ordered_movement.*,
                ordered_movement.OPENING_NET
                    + SUM(ordered_movement.DEBIT_AMOUNT - ordered_movement.CREDIT_AMOUNT) OVER (
                        PARTITION BY ordered_movement.ACC_CD
                        ORDER BY
                            ordered_movement.ACCOUNT_SORT,
                            ordered_movement.CHIT_YMD,
                            ordered_movement.SORT_NO,
                            ordered_movement.SORT_CHIT_ID,
                            ordered_movement.SORT_DETAIL,
                            ordered_movement.SORT_SIDE,
                            ordered_movement.ROW_NO
                        ROWS UNBOUNDED PRECEDING
                    ) AS RUNNING_NET
            FROM
            (
                SELECT
                    movement.ROW_NO,
                    movement.ACCOUNT_SORT,
                    movement.ACC_CD,
                    movement.ACCOUNT_NAME,
                    movement.CHIT_YMD,
                    movement.ENTRY_DATE,
                    movement.DOCUMENT_NO,
                    movement.DOCUMENT_DATE,
                    movement.DESCRIPTION,
                    movement.CSD_ACC_CD,
                    movement.DEBIT_AMOUNT,
                    movement.CREDIT_AMOUNT,
                    movement.NOTE_TEXT,
                    movement.SORT_CHIT_ID,
                    movement.SOURCE_CHIT_TYPE,
                    movement.SORT_NO,
                    movement.SORT_DETAIL,
                    movement.SORT_SIDE,
                    sums.OPENING_NET
                FROM tmp_account_detail_movements movement
                INNER JOIN tmp_account_detail_sums sums
                    ON sums.ACC_CD = movement.ACC_CD
                WHERE movement.CHIT_YMD >= v_from_ymd
                  AND movement.CHIT_YMD <= v_to_ymd
            ) ordered_movement
        ) running;

            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            CSD_ACC_CD,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
        )
        SELECT
            CONCAT(account.ACC_CD, '_TOTAL_PERIOD'),
            CONCAT(account.ACC_CD, '_GROUP'),
            account.ACCOUNT_SORT * 1000000 + 900000,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'TOTAL_PERIOD',
            1,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Cộng phát sinh',
            '',
            ROUND(sums.PERIOD_DEBIT, 2),
            ROUND(sums.PERIOD_CREDIT, 2)
        FROM tmp_account_detail_accounts account
        INNER JOIN tmp_account_detail_sums sums
            ON sums.ACC_CD = account.ACC_CD;

            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            CSD_ACC_CD,
            BALANCE_DEBIT,
            BALANCE_CREDIT
        )
        SELECT
            CONCAT(account.ACC_CD, '_ENDING'),
            CONCAT(account.ACC_CD, '_GROUP'),
            account.ACCOUNT_SORT * 1000000 + 900010,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'ENDING_TOTAL',
            1,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Số dư cuối kỳ',
            '',
            ROUND(GREATEST(sums.ENDING_NET, 0), 2),
            ROUND(GREATEST(-sums.ENDING_NET, 0), 2)
        FROM tmp_account_detail_accounts account
        INNER JOIN tmp_account_detail_sums sums
            ON sums.ACC_CD = account.ACC_CD;
    END IF;

    SELECT
        ROW_KEY AS __ROW_KEY,
        PARENT_ROW_KEY AS __PARENT_ROW_KEY,
        0 AS __TREE_EXPAND_ALL,
        ROW_SORT AS __ROW_SORT,
        COMPANY_CD AS __COMPANY_CD,
        REPORT_GROUP_KEY AS __REPORT_GROUP_KEY,
        ROW_TYPE AS __ROW_TYPE,
        ROW_LEVEL AS __ROW_LEVEL,
        
        CONCAT(ACCOUNT_CD_TEXT, '-', ACCOUNT_NAME_TEXT)  AS ACC_CD,
        ACCOUNT_CD_TEXT,
        ACCOUNT_NAME_TEXT,
        OBJECT_TEXT,
        CURRENCY_TEXT AS __CURRENCY_TEXT,
        REPORT_PERIOD_TEXT AS __REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT AS __AMOUNT_UNIT_TEXT,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        CSD_ACC_CD,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        BALANCE_DEBIT,
        BALANCE_CREDIT,
        NOTE_TEXT,
        SOURCE_CHIT_ID AS __CHIT_ID,
        SOURCE_CHIT_TYPE AS __CHIT_TYPE,
        CASE WHEN ROW_TYPE = 'DETAIL' AND IFNULL(SOURCE_CHIT_ID, 0) > 0 THEN 'DOCUMENT' ELSE 'NONE' END AS __LINK_TYPE
    FROM tmp_REPORT_RETURN
    ORDER BY ROW_SORT, ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_REPORT_RETURN;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_account_paths;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_accounts;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_sums;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_movements;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_opening_base;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_latest_open;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_accounts;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rpt_book_ar_invoice
DROP PROCEDURE IF EXISTS `rpt_book_ar_invoice`;
DELIMITER //
CREATE PROCEDURE `rpt_book_ar_invoice`(IN p_TypeACC char(1), IN p_Type char(1), IN p_FROM_DATE varchar(8), IN p_TO_DATE varchar(8), IN p_customerCD varchar(20), IN p_FCType varchar(20), IN p_Acc_CD varchar(20), IN p_COMPANY_CD varchar(20))
BEGIN
	
	SET @sWhereFcType = "",@sHaving="";
	IF(p_FCType != "") THEN
		SET @sPosition = POSITION("|" IN p_FCType);
		IF(@sPosition > 0) THEN
			SET @DCWayCode = SUBSTR(p_FCType,1,@sPosition-1);
			SET p_FCType = SUBSTR(p_FCType,@sPosition+1,3);
			SET @sHaving = CONCAT(" HAVING AMOUNT_CHIT > 0 ");	
			IF(@DCWayCode = 1) THEN
				SET @sWhereFcType = CONCAT(" AND IFNULL(A.FC_TYPE,'') = '",p_FCType,"' ");
				SET @sHaving = CONCAT(" HAVING AMOUNT_CHIT_FC > 0 ");							
			ELSE IF(@DCWayCode = 2) THEN
				SET @sWhereFcType = CONCAT(" AND (IFNULL(A.FC_TYPE,'') = '' OR IFNULL(A.FC_TYPE,'') = '",p_FCType,"') ");	
				SET @sHaving = CONCAT(" HAVING (AMOUNT_CHIT > 0 OR AMOUNT_CHIT_FC > 0) ");	
			END IF;
			END IF;
		END IF;
	END IF;
	
	SET @FC = p_FCType;
	IF(p_FCType = 'VND') THEN 
		SET @FC = 'USD';
	END IF;
	

SET @ACC_DIFF_RATE_131 = CONCAT(" AND  IF(INFO.CHIT_TYPE = 5 AND (IFNULL(CHIT.CREDIT,'') LIKE '131%' OR IFNULL(CHIT.CREDIT,'') LIKE '331%'),CHIT.CUSTOMER_OWN_CD,CHIT.CUSTOMER_CD) = C.CUSTOMER_CD
										 AND COLLECT_CHIT_CD = CHIT.CHIT_CD AND 
										 (IFNULL(CHIT.DEBIT,'') LIKE '635%' 
											 OR IFNULL(CHIT.DEBIT,'') LIKE '413%') 
										AND IFNULL(CHIT.CREDIT,'') LIKE '131%' ");
SET @ACC_DISCOUNT_131 = CONCAT(" AND IF(INFO.CHIT_TYPE = 5 AND (IFNULL(CHIT.CREDIT,'') LIKE '131%' OR IFNULL(CHIT.CREDIT,'') LIKE '331%'),CHIT.CUSTOMER_OWN_CD,CHIT.CUSTOMER_CD) = C.CUSTOMER_CD
										 AND COLLECT_CHIT_CD = CHIT.CHIT_CD AND 
										 ( ((IFNULL(CHIT.DEBIT,'') LIKE '511%' 
												OR IFNULL(CHIT.DEBIT,'') LIKE '521%' 
												OR IFNULL(CHIT.DEBIT,'') LIKE '3331%') 
												AND IFNULL(CHIT.CREDIT,'') LIKE '131%' )
											OR (IFNULL(CHIT.DEBIT,'') LIKE '131%' AND CHIT.AMOUNT < 0))
										 ");
SET @ACC_COLLECT_131 = CONCAT(" AND IF(INFO.CHIT_TYPE = 5 AND (IFNULL(CHIT.CREDIT,'') LIKE '131%' OR IFNULL(CHIT.CREDIT,'') LIKE '331%'),CHIT.CUSTOMER_OWN_CD,CHIT.CUSTOMER_CD) = C.CUSTOMER_CD
										AND COLLECT_CHIT_CD = CHIT.CHIT_CD AND 
										 (
										 (IFNULL(CHIT.DEBIT,'') NOT LIKE '635%' 
										AND IFNULL(CHIT.DEBIT,'') NOT LIKE '413%' 
										AND IFNULL(CHIT.DEBIT,'') NOT LIKE '141%' 
										AND IFNULL(CHIT.DEBIT,'') NOT LIKE '511%'
										AND IFNULL(CHIT.DEBIT,'') NOT LIKE '521%' 
										AND IFNULL(CHIT.DEBIT,'') NOT LIKE '3331%'
										AND IFNULL(CHIT.CREDIT,'') LIKE '131%')
										 
										OR IFNULL(CHIT.CREDIT,'') LIKE '331%') 
										");

SET @ACC_DIFF_RATE_331 = CONCAT(" AND IF(INFO.CHIT_TYPE = 5 AND (IFNULL(CHIT.CREDIT,'') LIKE '131%' OR IFNULL(CHIT.CREDIT,'') LIKE '331%'),CHIT.CUSTOMER_OWN_CD,CHIT.CUSTOMER_CD) = C.CUSTOMER_CD
										AND PAY_CHIT_CD = CHIT.CHIT_CD AND
										 (IFNULL(CHIT.CREDIT,'') LIKE '515%' 
											OR IFNULL(CHIT.CREDIT,'') LIKE '413%') 
										AND IFNULL(CHIT.DEBIT,'') LIKE '331%' ");
SET @ACC_DISCOUNT_331 = CONCAT(" AND IF(INFO.CHIT_TYPE = 5 AND (IFNULL(CHIT.CREDIT,'') LIKE '131%' OR IFNULL(CHIT.CREDIT,'') LIKE '331%'),CHIT.CUSTOMER_OWN_CD,CHIT.CUSTOMER_CD) = C.CUSTOMER_CD
										AND PAY_CHIT_CD = CHIT.CHIT_CD AND 
										( ((IFNULL(CHIT.CREDIT,'') LIKE '152%' 
										OR IFNULL(CHIT.CREDIT,'') LIKE '153%' 
										OR IFNULL(CHIT.CREDIT,'') LIKE '156%' 
										OR IFNULL(CHIT.CREDIT,'') LIKE '211%'
										OR IFNULL(CHIT.CREDIT,'') LIKE '242%'
										OR IFNULL(CHIT.CREDIT,'') LIKE '621%'
										OR IFNULL(CHIT.CREDIT,'') LIKE '627%'
										OR IFNULL(CHIT.CREDIT,'') LIKE '641%'
										OR IFNULL(CHIT.CREDIT,'') LIKE '642%'
										OR IFNULL(CHIT.CREDIT,'') LIKE '1331%'
										) 
										AND IFNULL(CHIT.DEBIT,'') LIKE '331%' )
										 OR (IFNULL(CHIT.CREDIT,'') LIKE '331%' AND CHIT.AMOUNT < 0))
										");
SET @ACC_COLLECT_331 = CONCAT(" AND IF(INFO.CHIT_TYPE = 5 AND (IFNULL(CHIT.CREDIT,'') LIKE '131%' OR IFNULL(CHIT.CREDIT,'') LIKE '331%'),CHIT.CUSTOMER_OWN_CD,CHIT.CUSTOMER_CD) = C.CUSTOMER_CD
										 AND PAY_CHIT_CD = CHIT.CHIT_CD AND 
										(
										(IFNULL(CHIT.CREDIT,'') NOT LIKE '515%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '413%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '152%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '153%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '156%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '211%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '242%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '621%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '627%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '641%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '642%' 
										AND IFNULL(CHIT.CREDIT,'') NOT LIKE '141%' 
										AND IFNULL(CHIT.DEBIT,'') LIKE '331%')
										
										OR IFNULL(CHIT.CREDIT,'') LIKE '131%') ");


SET @SumChit = CONCAT(" SELECT SUM(abs(AMOUNT)) FROM CHITDETAILINFO CHIT WHERE IFNULL(CHIT.ISDEL,'')!='1'  ");
SET @SumChitFC = CONCAT(" SELECT SUM(abs(FC_AMOUNT)) FROM CHITDETAILINFO CHIT WHERE IFNULL(CHIT.ISDEL,'')!='1' ");

SET @sWhereDate = CONCAT(" AND A.chit_ymd <= '",p_TO_DATE,"' ");
IF(p_Type = '1') THEN SET @sWhereDate = CONCAT(" AND A.chit_ymd >= '",p_FROM_DATE,"' AND A.chit_ymd <= '",p_TO_DATE,"' "); END IF;


IF(p_customerCD = 'ALL') THEN
	SET p_customerCD = '999';
END IF;
	
IF(p_TypeACC='1') THEN


		SET @V_SQL = CONCAT_WS("","
		SELECT 
			CUSTOMER_CD,
			CUSTOMER_NM_VIET,
			CUSTOMER_NM_ENG,
			CUSTOMER_NM_KOR,
			CUSTOMER_NM_CHINA,
			CHIT_CD,
			CHIT_TYPE,
			CHIT_YMD,
			CHIT_NO,
			VAT_YMD,
			VAT_CHIT_NO,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			TIME_FOR_PAYMENT,
			(AMOUNT_CHIT) AS AMOUNT_CHIT,
			(AMOUNT_CHIT_FC) AS AMOUNT_CHIT_FC,
			(AMOUNT_DIFF_RATE) AS AMOUNT_DIFF_RATE,
			(AMOUNT_DIFF_RATE_FC) AS AMOUNT_DIFF_RATE_FC,
			(AMOUNT_DISCOUNT) AS AMOUNT_DISCOUNT,
			(AMOUNT_DISCOUNT_FC) AS AMOUNT_DISCOUNT_FC,
			(AMOUNT_OTHER) AS AMOUNT_OTHER,
			(AMOUNT_OTHER_FC) AS AMOUNT_OTHER_FC,
			(AMOUNT_COLLECT - AMOUNT_DIFF_RATE - AMOUNT_DISCOUNT - AMOUNT_OTHER) AS AMOUNT_COLLECT,
			(AMOUNT_COLLECT_FC - AMOUNT_DIFF_RATE_FC - AMOUNT_DISCOUNT_FC - AMOUNT_OTHER_FC ) AS AMOUNT_COLLECT_FC,
			(AMOUNT_CHIT - AMOUNT_COLLECT) AS AMOUNT_ENDING_BALANCE,
			(AMOUNT_CHIT_FC - AMOUNT_COLLECT_FC) AS AMOUNT_ENDING_BALANCE_FC,
			'' AS GROUP_TEXT
		FROM (			
		SELECT 
				A.CUSTOMER_CD,
				CUS1.CUSTOMER_NM AS CUSTOMER_NM_VIET,
				CUS1.CUSTOMER_NM_EN AS CUSTOMER_NM_ENG,
				CUS1.CUSTOMER_NM_KOR AS CUSTOMER_NM_KOR,
				CUS1.CUSTOMER_NM_CN AS CUSTOMER_NM_CHINA,
				CONCAT('OPEN_',A.CUSTOMER_CD,'_331') AS CHIT_CD,
				'' AS CHIT_TYPE,
				'' AS CHIT_YMD,
				'' AS CHIT_NO,
				'' AS VAT_YMD,
				'' AS VAT_CHIT_NO,
				'Số dư đầu kỳ' AS DESCRIPTION_VIET,
				'Openning balance' AS DESCRIPTION_ENG, 	
				'기초잔액' AS DESCRIPTION_KOR,
				'期初余额' AS DESCRIPTION_CHINA,
				'' AS TIME_FOR_PAYMENT,
				IFNULL(AMOUNT,0.0) AS AMOUNT_CHIT,
				IFNULL(FC_AMOUNT,0.0) AS AMOUNT_CHIT_FC,
				0.0 AS AMOUNT_DIFF_RATE,
				0.0 AS AMOUNT_DIFF_RATE_FC,
				0.0 AS AMOUNT_DISCOUNT,
				0.0 AS AMOUNT_DISCOUNT_FC,
				0.0 AS AMOUNT_OTHER,
				0.0 AS AMOUNT_OTHER_FC,
				IFNULL(SUM(P.PAYAMOUNT),0.0) AS AMOUNT_COLLECT,
				IFNULL(SUM(P.PAYAMOUNT_FC),0.0) AS AMOUNT_COLLECT_FC
			FROM (
				SELECT 
					A.CUSTOMER_CD,
					(IFNULL(SUM(A.CREDIT),0.0) - IFNULL(SUM(A.DEBIT),0.0)) AS AMOUNT,
					IFNULL(SUM(A.CREDIT_",@FC,"),0.0) AS FC_AMOUNT
					FROM before_states_customer A
					WHERE A.ACC_CD like '",p_Acc_CD,"%'
					AND ( A.CUSTOMER_CD in (",p_customerCD,") OR '",p_customerCD,"' = '999' )
					AND IFNULL(A.ISDEL,'') !=1
					AND ",p_Type," = '2'
					GROUP BY A.CUSTOMER_CD
				) A
			LEFT JOIN chitpayment P ON ifnull(P.ISDEL,'') != '1' AND P.DEBIT_CHIT_CD = CONCAT('OPEN_',A.CUSTOMER_CD,'_331') AND P.CUSTOMER_CD = A.CUSTOMER_CD
			LEFT JOIN CUSTOMER_INFO CUS1 ON A.CUSTOMER_CD = CUS1.CUSTOMER_CD AND IFNULL(CUS1.ISDEL,'0') != '1'  
			WHERE AMOUNT >0
			GROUP BY A.CUSTOMER_CD
		UNION ALL
		
		SELECT
					IF(B.CHIT_TYPE = 5, CUS2.CUSTOMER_CD, CUS1.CUSTOMER_CD) AS CUSTOMER_CD,
					IF(B.CHIT_TYPE = 5, CUS2.CUSTOMER_NM, CUS1.CUSTOMER_NM) AS CUSTOMER_NM_VIET,
					IF(B.CHIT_TYPE = 5, CUS2.CUSTOMER_NM_EN, CUS1.CUSTOMER_NM_EN) AS CUSTOMER_NM_ENG,
					IF(B.CHIT_TYPE = 5, CUS2.CUSTOMER_NM_KOR, CUS1.CUSTOMER_NM_KOR) AS CUSTOMER_NM_KOR,
					IF(B.CHIT_TYPE = 5, CUS2.CUSTOMER_NM_CN, CUS1.CUSTOMER_NM_CN) AS CUSTOMER_NM_CHINA,
					B.CHIT_CD,
					IFNULL(B.CHIT_TYPE,'') AS CHIT_TYPE,
					IFNULL(B.CHIT_YMD,'') as CHIT_YMD,
					B.CHIT_NO,
				   IFNULL((SELECT C.VAT_YMD FROM chitdetailinfo C WHERE  IFNULL(C.ISDEL,'')!=1 AND IFNULL(C.VAT_CHIT_NO,'')!='' AND C.CHIT_CD = A.CHIT_CD LIMIT 1),'') AS VAT_YMD,
					IFNULL((SELECT C.VAT_CHIT_NO FROM chitdetailinfo C WHERE  IFNULL(C.ISDEL,'')!=1 AND IFNULL(C.VAT_CHIT_NO,'')!='' AND C.CHIT_CD = A.CHIT_CD LIMIT 1),'') AS VAT_CHIT_NO,
					(SELECT DESCRIPTION FROM chitdescriptioninfo WHERE B.CHIT_CD = CHIT_CD and LANG_TYPE = 'VIET' and (ISDEL IS NULL OR ISDEL != '1') limit 1) AS DESCRIPTION_VIET,
					(SELECT DESCRIPTION FROM chitdescriptioninfo WHERE B.CHIT_CD = CHIT_CD and LANG_TYPE = 'ENG' and (ISDEL IS NULL OR ISDEL != '1') limit 1) AS DESCRIPTION_ENG,
					(SELECT DESCRIPTION FROM chitdescriptioninfo WHERE B.CHIT_CD = CHIT_CD and LANG_TYPE = 'KOR' and (ISDEL IS NULL OR ISDEL != '1') limit 1) AS DESCRIPTION_KOR,
					(SELECT DESCRIPTION FROM chitdescriptioninfo WHERE B.CHIT_CD = CHIT_CD and LANG_TYPE = 'CHINA' and (ISDEL IS NULL OR ISDEL != '1') limit 1) AS DESCRIPTION_CHINA,
					IFNULL(B.TIME_FOR_PAYMENT,'') AS TIME_FOR_PAYMENT,
					IFNULL(SUM(A.AMOUNT),0.0) AS AMOUNT_CHIT,
					IFNULL(SUM(A.FC_AMOUNT),0.0) AS AMOUNT_CHIT_FC,
					IFNULL(E.AMOUNT_DIFF_RATE,0.0) AS AMOUNT_DIFF_RATE,
					IFNULL(E.AMOUNT_DIFF_RATE_FC,0.0) AS AMOUNT_DIFF_RATE_FC,
					IFNULL(E.AMOUNT_DISCOUNT,0.0) AS AMOUNT_DISCOUNT,
					IFNULL(E.AMOUNT_DISCOUNT_FC,0.0) AS AMOUNT_DISCOUNT_FC,
					0.0 AS AMOUNT_OTHER,
					0.0 AS AMOUNT_OTHER_FC,
					IFNULL(E.AMOUNT_COLLECT,0.0) AS AMOUNT_COLLECT,
					IFNULL(E.AMOUNT_COLLECT_FC,0.0) AS AMOUNT_COLLECT_FC
				FROM chitdetailinfo A
					LEFT JOIN CHITINFO B ON B.CHIT_CD = A.CHIT_CD AND (B.ISDEL IS NULL OR B.ISDEL != '1')
 
					LEFT JOIN (
							SELECT 
									DEBIT_CHIT_CD AS CHIT_CD,
									C.CUSTOMER_CD ,
									SUM(CASE WHEN IFNULL((",@SumChit,@ACC_DIFF_RATE_331,"),0.0) < C.PAYAMOUNT  THEN IFNULL((",@SumChit,@ACC_DIFF_RATE_331,"),0.0) ELSE C.PAYAMOUNT END) AS AMOUNT_DIFF_RATE,
									SUM(CASE WHEN IFNULL((",@SumChitFC,@ACC_DIFF_RATE_331,"),0.0) < C.PAYAMOUNT_FC  THEN IFNULL((",@SumChitFC,@ACC_DIFF_RATE_331,"),0.0) ELSE C.PAYAMOUNT_FC END) AS AMOUNT_DIFF_RATE_FC,
									SUM(CASE WHEN IFNULL((",@SumChit,@ACC_DISCOUNT_331,"),0.0) < C.PAYAMOUNT  THEN IFNULL((",@SumChit,@ACC_DISCOUNT_331,"),0.0) ELSE C.PAYAMOUNT END) AS AMOUNT_DISCOUNT,
									SUM(CASE WHEN IFNULL((",@SumChitFC,@ACC_DISCOUNT_331,"),0.0) < C.PAYAMOUNT_FC  THEN IFNULL((",@SumChitFC,@ACC_DISCOUNT_331,"),0.0) ELSE C.PAYAMOUNT_FC END) AS AMOUNT_DISCOUNT_FC,
									SUM(C.PAYAMOUNT) AS AMOUNT_COLLECT,
									SUM(C.PAYAMOUNT_FC) AS AMOUNT_COLLECT_FC
							FROM chitpayment C
							LEFT JOIN CHITINFO INFO ON C.PAY_CHIT_CD = INFO.CHIT_CD AND IFNULL(INFO.ISDEL,'') !=1
							WHERE
									ifnull(C.ISDEL,'') != '1' 
									AND(C.CUSTOMER_CD in (",p_customerCD,") OR '",p_customerCD,"' = '999')
							GROUP BY DEBIT_CHIT_CD,C.CUSTOMER_CD
						) E ON A.CUSTOMER_CD = E.CUSTOMER_CD AND (A.CHIT_CD = E.CHIT_CD)
						
					LEFT JOIN CUSTOMER_INFO CUS1 ON A.CUSTOMER_CD = CUS1.CUSTOMER_CD AND IFNULL(CUS1.ISDEL,'0') != '1' 
					LEFT JOIN CUSTOMER_INFO CUS2 ON A.CUSTOMER_OWN_CD = CUS2.CUSTOMER_CD AND IFNULL(CUS2.ISDEL,'0') != '1' 
				WHERE  
					IFNULL(B.CHIT_NO,'')!='' 					
					AND (IF(B.CHIT_TYPE = 5, A.CUSTOMER_OWN_CD, A.CUSTOMER_CD) in (",p_customerCD,") OR '",p_customerCD,"' = '999')
					AND A.CREDIT LIKE '",p_Acc_CD,"%' 
					AND IFNULL(A.ISDEL,'0') != '1' 
					",@sWhereDate," 
					",@sWhereFcType,"
				GROUP BY 
					IF(B.CHIT_TYPE = 5, CUS2.CUSTOMER_CD, CUS1.CUSTOMER_CD),
					B.CHIT_CD,
					E.AMOUNT_DIFF_RATE,
					E.AMOUNT_DIFF_RATE_FC,
					E.AMOUNT_DISCOUNT,
					E.AMOUNT_DISCOUNT_FC,
					E.AMOUNT_COLLECT,
					E.AMOUNT_COLLECT_FC			
	) S 
	WHERE CUSTOMER_CD != ''
	GROUP BY CUSTOMER_CD,CHIT_CD 
	",@sHaving," 
	ORDER BY CUSTOMER_CD,CHIT_YMD,CHIT_NO,CHiT_CD;
				");
				
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;

		SELECT @V_SQL;
		
		
	ELSE
	
	
		SET @V_SQL = CONCAT_WS("","
		
		SELECT 
			CUSTOMER_CD,
			CUSTOMER_NM_VIET,
			CUSTOMER_NM_ENG,
			CUSTOMER_NM_KOR,
			CUSTOMER_NM_CHINA,
			CHIT_CD,
			CHIT_TYPE,
			CHIT_YMD,
			CHIT_NO,
			VAT_YMD,
			VAT_CHIT_NO,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			TIME_FOR_PAYMENT,
			(AMOUNT_CHIT) AS AMOUNT_CHIT,
			(AMOUNT_CHIT_FC) AS AMOUNT_CHIT_FC,
			(AMOUNT_DIFF_RATE) AS AMOUNT_DIFF_RATE,
			(AMOUNT_DIFF_RATE_FC) AS AMOUNT_DIFF_RATE_FC,
			(AMOUNT_DISCOUNT) AS AMOUNT_DISCOUNT,
			(AMOUNT_DISCOUNT_FC) AS AMOUNT_DISCOUNT_FC,
			(AMOUNT_OTHER) AS AMOUNT_OTHER,
			(AMOUNT_OTHER_FC) AS AMOUNT_OTHER_FC,
			(AMOUNT_COLLECT - AMOUNT_DIFF_RATE - AMOUNT_DISCOUNT - AMOUNT_OTHER ) AS AMOUNT_COLLECT,
			(AMOUNT_COLLECT_FC - AMOUNT_DIFF_RATE_FC - AMOUNT_DISCOUNT_FC - AMOUNT_OTHER_FC) AS AMOUNT_COLLECT_FC,
			(AMOUNT_CHIT - AMOUNT_COLLECT) AS AMOUNT_ENDING_BALANCE,
			(AMOUNT_CHIT_FC - AMOUNT_COLLECT_FC) AS AMOUNT_ENDING_BALANCE_FC,
			'' AS GROUP_TEXT
		FROM (			
		SELECT 
				A.CUSTOMER_CD,
				CUS1.CUSTOMER_NM AS CUSTOMER_NM_VIET,
				CUS1.CUSTOMER_NM_EN AS CUSTOMER_NM_ENG,
				CUS1.CUSTOMER_NM_KOR AS CUSTOMER_NM_KOR,
				CUS1.CUSTOMER_NM_CN AS CUSTOMER_NM_CHINA,
				CONCAT('OPEN_',A.CUSTOMER_CD,'_131') AS CHIT_CD,
				'' AS CHIT_TYPE,
				'' AS CHIT_YMD,
				'' AS CHIT_NO,
				'' AS VAT_YMD,
				'' AS VAT_CHIT_NO,
				'Số dư đầu kỳ' AS DESCRIPTION_VIET,
				'Openning balance' AS DESCRIPTION_ENG, 	
				'기초잔액' AS DESCRIPTION_KOR,
				'期初余额' AS DESCRIPTION_CHINA,
				'' AS TIME_FOR_PAYMENT,
				IFNULL(AMOUNT,0.0) AS AMOUNT_CHIT,
				IFNULL(FC_AMOUNT,0.0) AS AMOUNT_CHIT_FC,
				0.0 AS AMOUNT_DIFF_RATE,
				0.0 AS AMOUNT_DIFF_RATE_FC,
				0.0 AS AMOUNT_DISCOUNT,
				0.0 AS AMOUNT_DISCOUNT_FC,
				0.0 AS AMOUNT_OTHER,
				0.0 AS AMOUNT_OTHER_FC,
				IFNULL(SUM(P.COLLECTAMOUNT),0.0) AS AMOUNT_COLLECT,
				IFNULL(SUM(P.COLLECTAMOUNT_FC),0.0) AS AMOUNT_COLLECT_FC
			FROM (
				SELECT 
					A.CUSTOMER_CD,
					IFNULL(SUM(A.DEBIT),0.0) AS AMOUNT,
					IFNULL(SUM(A.DEBIT_",@FC,"),0.0) AS FC_AMOUNT
					FROM before_states_customer A
					WHERE A.ACC_CD like '",p_Acc_CD,"%'
					AND ( A.CUSTOMER_CD in (",p_customerCD,") OR '",p_customerCD,"' = '999' )
					AND IFNULL(A.ISDEL,'') !=1
					AND ",p_Type," = '2'
					GROUP BY A.CUSTOMER_CD
				) A
			LEFT JOIN chitcollect P ON ifnull(P.ISDEL,'') != '1' AND P.RECEIVABLES_CHIT_CD = CONCAT('OPEN_',A.CUSTOMER_CD,'_131') AND P.CUSTOMER_CD = A.CUSTOMER_CD
			LEFT JOIN CUSTOMER_INFO CUS1 ON A.CUSTOMER_CD = CUS1.CUSTOMER_CD AND IFNULL(CUS1.ISDEL,'0') != '1'  
			WHERE AMOUNT >0
			GROUP BY A.CUSTOMER_CD
		UNION ALL
		
		SELECT
					CUS1.CUSTOMER_CD AS CUSTOMER_CD,
					CUS1.CUSTOMER_NM AS CUSTOMER_NM_VIET,
					CUS1.CUSTOMER_NM_EN AS CUSTOMER_NM_ENG,
					CUS1.CUSTOMER_NM_KOR AS CUSTOMER_NM_KOR,
					CUS1.CUSTOMER_NM_CN AS CUSTOMER_NM_CHINA,
					B.CHIT_CD,
					IFNULL(B.CHIT_TYPE,'') AS CHIT_TYPE,
					IFNULL(B.CHIT_YMD,'') as CHIT_YMD,
					B.CHIT_NO,
				   IFNULL((SELECT C.VAT_YMD FROM chitdetailinfo C WHERE  IFNULL(C.ISDEL,'')!=1 AND IFNULL(C.VAT_CHIT_NO,'')!='' AND C.CHIT_CD = A.CHIT_CD LIMIT 1),'') AS VAT_YMD,
					IFNULL((SELECT C.VAT_CHIT_NO FROM chitdetailinfo C WHERE  IFNULL(C.ISDEL,'')!=1 AND IFNULL(C.VAT_CHIT_NO,'')!='' AND C.CHIT_CD = A.CHIT_CD LIMIT 1),'') AS VAT_CHIT_NO,
					(SELECT DESCRIPTION FROM chitdescriptioninfo WHERE B.CHIT_CD = CHIT_CD and LANG_TYPE = 'VIET' and (ISDEL IS NULL OR ISDEL != '1') limit 1) AS DESCRIPTION_VIET,
					(SELECT DESCRIPTION FROM chitdescriptioninfo WHERE B.CHIT_CD = CHIT_CD and LANG_TYPE = 'ENG' and (ISDEL IS NULL OR ISDEL != '1') limit 1) AS DESCRIPTION_ENG,
					(SELECT DESCRIPTION FROM chitdescriptioninfo WHERE B.CHIT_CD = CHIT_CD and LANG_TYPE = 'KOR' and (ISDEL IS NULL OR ISDEL != '1') limit 1) AS DESCRIPTION_KOR,
					(SELECT DESCRIPTION FROM chitdescriptioninfo WHERE B.CHIT_CD = CHIT_CD and LANG_TYPE = 'CHINA' and (ISDEL IS NULL OR ISDEL != '1') limit 1) AS DESCRIPTION_CHINA,
					IFNULL(B.TIME_FOR_PAYMENT,'') AS TIME_FOR_PAYMENT,
					IFNULL(SUM(A.AMOUNT),0.0) AS AMOUNT_CHIT,
					IFNULL(SUM(A.FC_AMOUNT),0.0) AS AMOUNT_CHIT_FC,
					IFNULL(E.AMOUNT_DIFF_RATE,0.0) AS AMOUNT_DIFF_RATE,
					IFNULL(E.AMOUNT_DIFF_RATE_FC,0.0) AS AMOUNT_DIFF_RATE_FC,
					IFNULL(E.AMOUNT_DISCOUNT,0.0) AS AMOUNT_DISCOUNT,
					IFNULL(E.AMOUNT_DISCOUNT_FC,0.0) AS AMOUNT_DISCOUNT_FC,
					0.0 AS AMOUNT_OTHER,
					0.0 AS AMOUNT_OTHER_FC,
					IFNULL(E.AMOUNT_COLLECT,0.0) AS AMOUNT_COLLECT,
					IFNULL(E.AMOUNT_COLLECT_FC,0.0) AS AMOUNT_COLLECT_FC
				FROM chitdetailinfo A
					LEFT JOIN CHITINFO B ON B.CHIT_CD = A.CHIT_CD AND (B.ISDEL IS NULL OR B.ISDEL != '1')
 
					LEFT JOIN (
							SELECT 
									RECEIVABLES_CHIT_CD AS CHIT_CD,
									C.CUSTOMER_CD ,
									SUM(CASE WHEN IFNULL((",@SumChit,@ACC_DIFF_RATE_131,"),0.0) < C.COLLECTAMOUNT  THEN IFNULL((",@SumChit,@ACC_DIFF_RATE_131,"),0.0) ELSE C.COLLECTAMOUNT END) AS AMOUNT_DIFF_RATE,
									SUM(CASE WHEN IFNULL((",@SumChitFC,@ACC_DIFF_RATE_131,"),0.0) < C.COLLECTAMOUNT_FC  THEN IFNULL((",@SumChitFC,@ACC_DIFF_RATE_131,"),0.0) ELSE C.COLLECTAMOUNT_FC END) AS AMOUNT_DIFF_RATE_FC,
									SUM(CASE WHEN IFNULL((",@SumChit,@ACC_DISCOUNT_131,"),0.0) < C.COLLECTAMOUNT  THEN IFNULL((",@SumChit,@ACC_DISCOUNT_131,"),0.0) ELSE C.COLLECTAMOUNT END) AS AMOUNT_DISCOUNT,
									SUM(CASE WHEN IFNULL((",@SumChitFC,@ACC_DISCOUNT_131,"),0.0) < C.COLLECTAMOUNT_FC  THEN IFNULL((",@SumChitFC,@ACC_DISCOUNT_131,"),0.0) ELSE C.COLLECTAMOUNT_FC END) AS AMOUNT_DISCOUNT_FC,
									SUM(C.COLLECTAMOUNT) AS AMOUNT_COLLECT,
									SUM(C.COLLECTAMOUNT_FC) AS AMOUNT_COLLECT_FC
							FROM chitcollect C
							LEFT JOIN CHITINFO INFO ON C.COLLECT_CHIT_CD = INFO.CHIT_CD AND IFNULL(INFO.ISDEL,'') !=1
							WHERE
									ifnull(C.ISDEL,'') != '1' 
									AND(C.CUSTOMER_CD in (",p_customerCD,") OR '",p_customerCD,"' = '999')
							GROUP BY RECEIVABLES_CHIT_CD,C.CUSTOMER_CD
						) E ON A.CUSTOMER_CD = E.CUSTOMER_CD AND (A.CHIT_CD = E.CHIT_CD)
						
					LEFT JOIN CUSTOMER_INFO CUS1 ON A.CUSTOMER_CD = CUS1.CUSTOMER_CD AND IFNULL(CUS1.ISDEL,'0') != '1' 
					LEFT JOIN CUSTOMER_INFO CUS2 ON A.CUSTOMER_OWN_CD = CUS2.CUSTOMER_CD AND IFNULL(CUS2.ISDEL,'0') != '1' 
				WHERE  
					IFNULL(B.CHIT_NO,'')!='' 					
					AND (A.CUSTOMER_CD in (",p_customerCD,") OR '",p_customerCD,"' = '999')
					AND A.DEBIT LIKE '",p_Acc_CD,"%' 
					AND IFNULL(A.ISDEL,'0') != '1' 
					",@sWhereDate," 
					",@sWhereFcType,"
				GROUP BY 
					CUS1.CUSTOMER_CD,
					B.CHIT_CD,
					E.AMOUNT_DIFF_RATE,
					E.AMOUNT_DIFF_RATE_FC,
					E.AMOUNT_DISCOUNT,
					E.AMOUNT_DISCOUNT_FC,
					E.AMOUNT_COLLECT,
					E.AMOUNT_COLLECT_FC			
	) S 
	WHERE CUSTOMER_CD != ''
	GROUP BY CUSTOMER_CD,CHIT_CD 
	",@sHaving," 
	ORDER BY CUSTOMER_CD,CHIT_YMD,CHIT_NO,CHiT_CD;
				");

		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;
		
		SELECT @V_SQL;
		
	END IF;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rpt_cost_list
DROP PROCEDURE IF EXISTS `rpt_cost_list`;
DELIMITER //
CREATE PROCEDURE `rpt_cost_list`(
	IN `p_COMPANY_CD` VARCHAR(20),
	IN `p_FROM_DATE` DATE,
	IN `p_TO_DATE` DATE,
	IN `p_REPORT_VERSION` VARCHAR(20),
	IN `p_UNIT_DIVISOR` DECIMAL(18,6),
	IN `p_LANGUAGE` VARCHAR(20),
	IN `p_INCLUDE_DETAIL` CHAR(1)
)
BEGIN
    DECLARE v_from_date DATE; 
    -- Ngày bắt đầu kỳ báo cáo hiện tại (DATE).
    DECLARE v_to_date DATE; -- Ngày kết thúc kỳ báo cáo hiện tại (DATE).
    DECLARE v_previous_from_date DATE; -- Ngày bắt đầu kỳ so sánh liền trước, có cùng số ngày với kỳ hiện tại.
    DECLARE v_previous_to_date DATE; -- Ngày cuối của kỳ so sánh, bằng ngày trước v_from_date.
    
    DECLARE v_from_ymd VARCHAR(8); -- Ngày bắt đầu  kỳ hiện tại, chuỗi yyyyMMdd để so sánh CHIT_YMD.
    DECLARE v_to_ymd VARCHAR(8); --   Ngày kết thúc kỳ hiện tại, chuỗi yyyyMMdd.
    
    DECLARE v_previous_from_ymd VARCHAR(8); -- Ngày bắt đầu  kỳ trước, chuỗi yyyyMMdd.
    DECLARE v_previous_to_ymd VARCHAR(8);   -- Ngày kết thúc kỳ trước, chuỗi yyyyMMdd.
    
    DECLARE v_current_open_ymd VARCHAR(8); -- Mốc số dư đầu  kỳ hiện tại: ngày trước v_from_date.
    DECLARE v_previous_open_ymd VARCHAR(8); -- Mốc số dư đầu kỳ trước: ngày trước v_previous_from_date.
    
    DECLARE v_period_days INT; -- Chênh lệch số ngày giữa v_to_date và v_from_date (DATEDIFF, không cộng 1).
    DECLARE v_report_version VARCHAR(20); -- Phiên bản mẫu báo cáo COST_LIST.
    DECLARE v_template_company_cd VARCHAR(20); -- Mã công ty sở hữu mẫu, ưu tiên công ty hiện tại rồi mẫu dùng chung.
    DECLARE v_unit_divisor DECIMAL(18,6); -- Đơn vị chia số tiền khi trình bày, 0/NULL mặc định 1.
    DECLARE v_iteration INT DEFAULT 0; -- Bộ đếm số vòng cập nhật công thức lồng nhau.
    DECLARE v_changed_rows INT DEFAULT 0; -- Số dòng công thức vừa thay đổi, để thoát vòng lặp.
    DECLARE v_language VARCHAR(20); -- Ngôn ngữ trình bày VIET/ENG/KOR/CHN.
    DECLARE v_include_detail CHAR(1); -- Cờ cho phép hiển thị dòng chi tiết
	 
	 DECLARE V_closingmonth_close_ymd VARCHAR(8); -- ngày khóa sổ gần nhất
    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;
	
	
    SET v_from_date = p_FROM_DATE;
    SET v_to_date = p_TO_DATE;
    SET v_period_days = DATEDIFF(v_to_date, v_from_date);
    SET v_previous_to_date = DATE_SUB(v_from_date, INTERVAL 1 DAY);
    SET v_previous_from_date = DATE_SUB(v_previous_to_date, INTERVAL v_period_days DAY);
    SET v_from_ymd = DATE_FORMAT(v_from_date, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(v_to_date, '%Y%m%d');
    SET v_previous_from_ymd = DATE_FORMAT(v_previous_from_date, '%Y%m%d');
    SET v_previous_to_ymd = DATE_FORMAT(v_previous_to_date, '%Y%m%d');
    
	 SET v_current_open_ymd = DATE_FORMAT(DATE_SUB(v_from_date, INTERVAL 1 DAY), '%Y%m%d');
    SET v_previous_open_ymd = DATE_FORMAT(DATE_SUB(v_previous_from_date, INTERVAL 1 DAY), '%Y%m%d');
    
    SET v_report_version = IFNULL(NULLIF(TRIM(IFNULL(p_REPORT_VERSION, '')), ''), '2025');
    SET v_unit_divisor = CASE WHEN IFNULL(p_UNIT_DIVISOR, 0) = 0 THEN 1 ELSE p_UNIT_DIVISOR END;
    SET v_language = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));
    
--    set p_INCLUDE_DETAIL = '1'; -- xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
    SET v_include_detail = CASE
        WHEN UPPER(TRIM(IFNULL(p_INCLUDE_DETAIL, '1'))) IN ('0', 'N', 'NO', 'FALSE') THEN '0'
        ELSE '1'
    END;

	
	
	SELECT concat(left(MAX(close_ymd), 6), '31') into V_closingmonth_close_ymd FROM closingmonth_detail WHERE COMPANY_CD = p_COMPANY_CD and isdel <> '1' AND left(close_ymd, 6) < left(v_from_ymd, 6);
	SET V_closingmonth_close_ymd = IFNULL(V_closingmonth_close_ymd, '11110101');

    SELECT COALESCE(
        (
            SELECT template.COMPANY_CD
            FROM report_cost_list template
            WHERE template.REPORT_CODE = 'COST_LIST'
              AND template.REPORT_VERSION = v_report_version
              AND template.COMPANY_CD IN (p_COMPANY_CD, '')
              AND IFNULL(template.ISDEL, '0') = '0'
            ORDER BY CASE WHEN template.COMPANY_CD = p_COMPANY_CD THEN 0 ELSE 1 END
            LIMIT 1
        ),
        ''
    )
    INTO v_template_company_cd;
    

    -- tmp_cl_numbers: Bảng số 1..40, dùng tách chuỗi danh sách tài khoản và công thức theo dấu phân cách.
    DROP TEMPORARY TABLE IF EXISTS tmp_cl_numbers;
    CREATE TEMPORARY TABLE tmp_cl_numbers
    (
        N INT NOT NULL,
        PRIMARY KEY (N)
    ) ENGINE=MEMORY;

    SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
    UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10
    UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15
    UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20
    UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25
    UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30
    UNION ALL SELECT 31 UNION ALL SELECT 32 UNION ALL SELECT 33 UNION ALL SELECT 34 UNION ALL SELECT 35
    UNION ALL SELECT 36 UNION ALL SELECT 37 UNION ALL SELECT 38 UNION ALL SELECT 39 UNION ALL SELECT 40;

    -- tmp_cl_rule: Quy tắc phân bổ ITEM_CODE -> tiền tố tài khoản và cách tính số tiền.
    DROP TEMPORARY TABLE IF EXISTS tmp_cl_rule;
    CREATE TEMPORARY TABLE tmp_cl_rule
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        CALC_METHOD VARCHAR(30) NOT NULL,
        INDEX idx_tmp_cl_rule_01 (ITEM_CODE, ACC_PREFIX)
    ) ENGINE=MEMORY;

    SELECT
        template.ITEM_CODE,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(IFNULL(template.ACCOUNT_RULE, ''), ',', numbers.N), ',', -1)),
        UPPER(IFNULL(template.CALC_METHOD, 'DEBIT_MINUS_CREDIT'))
    FROM report_cost_list template
    INNER JOIN tmp_cl_numbers numbers
        ON numbers.N <= 1 + LENGTH(IFNULL(template.ACCOUNT_RULE, '')) - LENGTH(REPLACE(IFNULL(template.ACCOUNT_RULE, ''), ',', ''))
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'COST_LIST'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'DETAIL'
      AND IFNULL(template.DATA_SOURCE_TYPE, '') = 'ACCOUNT_RULE'
      AND IFNULL(template.ACCOUNT_RULE, '') <> ''
      AND TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(IFNULL(template.ACCOUNT_RULE, ''), ',', numbers.N), ',', -1)) <> '';

    -- tmp_cl_account_turnover: Tổng phát sinh Nợ/Có trong kỳ hiện tại (CURRENT) và kỳ so sánh (PREVIOUS), lấy chứng từ.
    DROP TEMPORARY TABLE IF EXISTS tmp_cl_account_turnover;
    CREATE TEMPORARY TABLE tmp_cl_account_turnover
    (
        ACC_CD VARCHAR(20) NOT NULL,
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        DEBIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        CREDIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD, PERIOD_TYPE)
    ) ENGINE=MEMORY;

    -- CURRENT - Debit / nợ
    SELECT TRIM(d.DEBIT), 'CURRENT', SUM(IFNULL(d.AMOUNT, 0)), 0
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.ISDEL = '0'
      AND h.CHIT_YMD >= v_from_ymd
      AND h.CHIT_YMD <= v_to_ymd
      AND d.DEBIT IS NOT NULL
      AND TRIM(d.DEBIT) <> ''
    GROUP BY TRIM(d.DEBIT);

    -- CURRENT - Credit / có
    SELECT TRIM(d.CREDIT), 'CURRENT', 0, SUM(IFNULL(d.AMOUNT, 0))
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.ISDEL = '0'
      AND h.CHIT_YMD >= v_from_ymd
      AND h.CHIT_YMD <= v_to_ymd
      AND d.CREDIT IS NOT NULL
      AND TRIM(d.CREDIT) <> ''
    GROUP BY TRIM(d.CREDIT)
    ON DUPLICATE KEY UPDATE
        DEBIT_AMOUNT = DEBIT_AMOUNT + VALUES(DEBIT_AMOUNT),
        CREDIT_AMOUNT = CREDIT_AMOUNT + VALUES(CREDIT_AMOUNT);

    --  PREVIOUS - Debit 
    SELECT TRIM(d.DEBIT), 'PREVIOUS', SUM(IFNULL(d.AMOUNT, 0)), 0
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.ISDEL = '0'
      AND h.CHIT_YMD >= v_previous_from_ymd
      AND h.CHIT_YMD <= v_previous_to_ymd
      AND d.DEBIT IS NOT NULL
      AND TRIM(d.DEBIT) <> ''
    GROUP BY TRIM(d.DEBIT);

    -- PREVIOUS - Credit 
    SELECT TRIM(d.CREDIT), 'PREVIOUS', 0, SUM(IFNULL(d.AMOUNT, 0))
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.ISDEL = '0'
      AND h.CHIT_YMD >= v_previous_from_ymd
      AND h.CHIT_YMD <= v_previous_to_ymd
      AND d.CREDIT IS NOT NULL
      AND TRIM(d.CREDIT) <> ''
    GROUP BY TRIM(d.CREDIT)
    ON DUPLICATE KEY UPDATE
        DEBIT_AMOUNT = DEBIT_AMOUNT + VALUES(DEBIT_AMOUNT),
        CREDIT_AMOUNT = CREDIT_AMOUNT + VALUES(CREDIT_AMOUNT);

    -- ================================================================
    -- SO DU TAI 4 MOC: TINH TU SO DU KHOA SO + PHAT SINH SAU KHOA SO
    -- QUY TAC:
    -- 1) Tai moi moc ngay, tim CLOSE_YMD MOI NHAT <= ngay moc cho COMPANY_CD.
    -- 2) Lay DEBIT/CREDIT (so du NOI TE) cua TOAN BO tai khoan va FC_TYPE
    --    tai DUNG CLOSE_YMD da chon; cong gop theo ACC_CD.
    -- 3) Cong phat sinh chung tu co CHIT_YMD > CLOSE_YMD va <= ngay moc.
    --    Neu chua tung khoa so: cong chung tu tu truoc toi ngay moc (nhu cu).
    -- 4) DEBIT_FC/CREDIT_FC la so du NGOAI TE, KHONG cong vao DEBIT/CREDIT
    --    vi bao cao nay tinh theo noi te; neu can ngoai te phai xu ly rieng.
    -- GIA DINH: moi lan khoa so la snapshot DAY DU cac tai khoan tai ngay
    -- CLOSE_YMD; DEBIT/CREDIT da la so du noi te (khong phai phat sinh).
    -- ================================================================
    DROP TEMPORARY TABLE IF EXISTS tmp_cl_account_balance;
    CREATE TEMPORARY TABLE tmp_cl_account_balance
    (
        ACC_CD VARCHAR(20) NOT NULL,
        AS_OF_TYPE VARCHAR(20) NOT NULL,           -- CURRENT_OPEN/CLOSE, PREVIOUS_OPEN/CLOSE
        DEBIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,  -- So du No + phat sinh No sau khoa so
        CREDIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00, -- So du Co + phat sinh Co sau khoa so
        PRIMARY KEY (ACC_CD, AS_OF_TYPE)
    ) ENGINE=MEMORY;

    -- Bang tam moi: moi moc tinh so du va ngay khoa so gan nhat (neu co).
    DROP TEMPORARY TABLE IF EXISTS tmp_cl_balance_cutoff;
    CREATE TEMPORARY TABLE tmp_cl_balance_cutoff
    (
        AS_OF_TYPE VARCHAR(20) NOT NULL PRIMARY KEY,
        AS_OF_YMD CHAR(8) NOT NULL,           -- Moc can tinh so du
        CLOSE_YMD CHAR(8) NULL              -- Lan khoa so moi nhat <= moc; NULL neu chua khoa so
    ) ENGINE=MEMORY;

    SELECT 'CURRENT_OPEN', v_current_open_ymd
    UNION ALL 
	 SELECT 'CURRENT_CLOSE', v_to_ymd
    UNION ALL 
	 SELECT 'PREVIOUS_OPEN', v_previous_open_ymd
    UNION ALL 
	 SELECT 'PREVIOUS_CLOSE', v_previous_to_ymd;

    -- Lay MAX(CLOSE_YMD) theo tung moc, KHONG lay mot ngay khoa so cho ca 4 moc.
    UPDATE tmp_cl_balance_cutoff cutoff
    SET cutoff.CLOSE_YMD =
    (
        SELECT concat(left(MAX(cl.CLOSE_YMD),6),'31')
        FROM closingmonth_detail cl
        WHERE cl.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(cl.ISDEL, '0') = '0'
          AND left(cl.CLOSE_YMD,6) <= left(cutoff.AS_OF_YMD,6)
    );

--   SELECT * FROM tmp_cl_balance_cutoff; -- 99999

    -- INSERT 1: snapshot so du Noi te da khoa so, gop cac FC_TYPE theo ACC_CD.
    -- JOIN theo dung CLOSE_YMD gan nhat de tranh cong lap cac lan khoa so.
    -- Nếu không có kỳ khóa sổ phù hợp, câu SELECT không tạo bản ghi.
    SELECT
        TRIM(cl.ACC_CD),
        cutoff.AS_OF_TYPE,
        SUM(IFNULL(cl.DEBIT, 0)),
        SUM(IFNULL(cl.CREDIT, 0))
    FROM tmp_cl_balance_cutoff cutoff
    	INNER JOIN closingmonth_detail cl        ON cl.COMPANY_CD = p_COMPANY_CD       AND left(cl.CLOSE_YMD,6) = left(cutoff.CLOSE_YMD,6)       AND IFNULL(cl.ISDEL, '0') = '0'
    WHERE cl.ACC_CD IS NOT NULL
      AND TRIM(cl.ACC_CD) <> ''
    GROUP BY cutoff.AS_OF_TYPE, TRIM(cl.ACC_CD);

    -- INSERT 2: phat sinh No sau lan khoa so den tung moc tinh so du.
    -- Neu CLOSE_YMD NULL: lay tat ca chung tu <= AS_OF_YMD (fallback nhu cu).
    SELECT
        TRIM(d.DEBIT),
        cutoff.AS_OF_TYPE,
        SUM(IFNULL(d.AMOUNT, 0)),
        0
    FROM tmp_cl_balance_cutoff cutoff
    INNER JOIN chitinfo h        ON h.COMPANY_CD = p_COMPANY_CD AND h.ISDEL = '0' AND h.CHIT_YMD <= cutoff.AS_OF_YMD AND (cutoff.CLOSE_YMD IS NULL OR h.CHIT_YMD > cutoff.CLOSE_YMD)
    INNER JOIN chitdetailinfo d ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID       AND d.ISDEL = '0'
    WHERE d.DEBIT IS NOT NULL
      AND TRIM(d.DEBIT) <> ''
    GROUP BY cutoff.AS_OF_TYPE, TRIM(d.DEBIT)
    ON DUPLICATE KEY UPDATE
        DEBIT_AMOUNT = DEBIT_AMOUNT + VALUES(DEBIT_AMOUNT),
        CREDIT_AMOUNT = CREDIT_AMOUNT + VALUES(CREDIT_AMOUNT);

    -- INSERT 3: phat sinh Co sau lan khoa so den tung moc tinh so du.
    SELECT
        TRIM(d.CREDIT),
        cutoff.AS_OF_TYPE,
        0,
        SUM(IFNULL(d.AMOUNT, 0))
    FROM tmp_cl_balance_cutoff cutoff
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = p_COMPANY_CD
       AND h.ISDEL = '0'
       AND h.CHIT_YMD <= cutoff.AS_OF_YMD
       AND (cutoff.CLOSE_YMD IS NULL OR h.CHIT_YMD > cutoff.CLOSE_YMD)
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
       AND d.ISDEL = '0'
    WHERE d.CREDIT IS NOT NULL
      AND TRIM(d.CREDIT) <> ''
    GROUP BY cutoff.AS_OF_TYPE, TRIM(d.CREDIT)
    ON DUPLICATE KEY UPDATE
        DEBIT_AMOUNT = DEBIT_AMOUNT + VALUES(DEBIT_AMOUNT),
        CREDIT_AMOUNT = CREDIT_AMOUNT + VALUES(CREDIT_AMOUNT);

    -- Vi du: cutoff=20260331, khoa so moi nhat=20260228 =>
    -- so du 20260331 = so du khoa so 20260228 + PS 20260301..20260331.
    -- Phan UPDATE tmp_cl_report OPENING_BALANCE/CLOSING_BALANCE o duoi
    -- van giu nguyen (DEBIT_AMOUNT - CREDIT_AMOUNT).

    DROP TEMPORARY TABLE IF EXISTS tmp_cl_report;

    CREATE TEMPORARY TABLE tmp_cl_report
    (
        ROW_KEY VARCHAR(80) NOT NULL DEFAULT '',
        ACC_CD VARCHAR(7) NULL,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        SORT_ORDER INT NOT NULL DEFAULT 0,
        ITEM_CODE VARCHAR(50) NULL,
        ITEM_NAME VARCHAR(1000) NULL,
        CAPTION VARCHAR(1000) NULL,
        LABEL_TEXT VARCHAR(200) NULL,
        NOTE VARCHAR(200) NOT NULL DEFAULT '',
        CURRENT_YEAR DECIMAL(18,2) NULL,
        PREVIOUS_YEAR DECIMAL(18,2) NULL,
        LEVEL_NO INT NOT NULL DEFAULT 0,
        FONT_BOLD CHAR(1) NOT NULL DEFAULT '0',
        FONT_ITALIC CHAR(1) NOT NULL DEFAULT '0',
        DATA_SOURCE_TYPE VARCHAR(50) NULL,
        CALC_METHOD VARCHAR(50) NULL,
        FORMULA_EXPR VARCHAR(1000) NULL,
        REPORT_YEAR_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_KEY),
        INDEX idx_tmp_cl_report_01 (ITEM_CODE),
        INDEX idx_tmp_cl_report_02 (SORT_ORDER)
    ) ENGINE=MEMORY;
        ROW_KEY, ACC_CD, COMPANY_CD, ROW_TYPE, SORT_ORDER, ITEM_CODE, ITEM_NAME, CAPTION, LABEL_TEXT, NOTE,
        LEVEL_NO, FONT_BOLD, FONT_ITALIC, DATA_SOURCE_TYPE, CALC_METHOD, FORMULA_EXPR,
        REPORT_YEAR_TEXT, REPORT_PERIOD_TEXT, AMOUNT_UNIT_TEXT
    )
    SELECT *
    from
    (
	    SELECT
	        template.ITEM_KEY AS ROW_KEY,
	        '' AS ACC_CD,
	        p_COMPANY_CD,
	        template.ELEMENT_TYPE, -- ROW_TYPE
	        template.SORT_ORDER, -- SORT_ORDER
	        template.ITEM_CODE, -- ITEM_CODE
	        CONCAT(REPEAT('  ', GREATEST(IFNULL(template.LEVEL_NO, 1) - 1, 0)), IFNULL(template.CAPTION, '')), -- ITEM_NAME
	        template.CAPTION, -- CAPTION, 
	        template.LABEL_TEXT, -- LABEL_TEXT, 
	        CASE
	            WHEN UPPER(IFNULL(template.DATA_SOURCE_TYPE, '')) = 'FORMULA'
	                THEN TRIM(SUBSTRING_INDEX(IFNULL(template.FORMULA_EXPR, ''), '=', -1))
	            ELSE ''
	        END,  -- NOTE,
	        IFNULL(template.LEVEL_NO, 0) AS LEVEL_NO,
	        IFNULL(template.FONT_BOLD, '0') AS FONT_BOLD,
	        IFNULL(template.FONT_ITALIC, '0') AS FONT_ITALIC,
	        IFNULL(template.DATA_SOURCE_TYPE, '') AS DATA_SOURCE_TYPE,
	        UPPER(IFNULL(template.CALC_METHOD, '')) AS CALC_METHOD,
	        template.FORMULA_EXPR,
	        CASE v_language
	            WHEN 'ENG' THEN CONCAT('Year ', YEAR(v_to_date))
	            WHEN 'KOR' THEN CONCAT(YEAR(v_to_date), '년')
	            WHEN 'CHN' THEN CONCAT(YEAR(v_to_date), '年')
	            ELSE CONCAT('Năm ', YEAR(v_to_date))
	        END as REPORT_YEAR_TEXT,
	        CASE v_language
	            WHEN 'ENG' THEN CONCAT(
	                DATE_FORMAT(v_from_date, '%d/%m/%Y'), ' ~ ', DATE_FORMAT(v_to_date, '%d/%m/%Y')
	            )
	            WHEN 'KOR' THEN CONCAT(
	                DATE_FORMAT(v_from_date, '%d/%m/%Y'), ' ~ ', DATE_FORMAT(v_to_date, '%d/%m/%Y')
	            )
	            WHEN 'CHN' THEN CONCAT(
	                DATE_FORMAT(v_from_date, '%d/%m/%Y'), ' ~ ', DATE_FORMAT(v_to_date, '%d/%m/%Y')
	            )
	            ELSE CONCAT(
	                DATE_FORMAT(v_from_date, '%d/%m/%Y'), ' ~ ', DATE_FORMAT(v_to_date, '%d/%m/%Y')
	            )
	        END as REPORT_PERIOD_TEXT,
	        CASE v_language
	            WHEN 'ENG' THEN
	                CASE
	                    WHEN v_unit_divisor = 1000000 THEN 'Unit: million VND'
	                    WHEN v_unit_divisor = 1000 THEN 'Unit: thousand VND'
	                    ELSE 'Unit: VND'
	                END
	            WHEN 'KOR' THEN
	                CASE
	                    WHEN v_unit_divisor = 1000000 THEN '단위: 백만 VND'
	                    WHEN v_unit_divisor = 1000 THEN '단위: 천 VND'
	                    ELSE '단위: VND'
	                END
	            WHEN 'CHN' THEN
	                CASE
	                    WHEN v_unit_divisor = 1000000 THEN '单位：百万越南盾'
	                    WHEN v_unit_divisor = 1000 THEN '单位：千越南盾'
	                    ELSE '单位：越南盾'
	                END
	            ELSE
	                CASE
	                    WHEN v_unit_divisor = 1000000 THEN 'Đơn vị tính: triệu đồng'
	                    WHEN v_unit_divisor = 1000 THEN 'Đơn vị tính: nghìn đồng'
	                    ELSE 'Đơn vị tính: đồng'
	                END
	        END as AMOUNT_UNIT_TEXT
	    FROM report_cost_list template
	    WHERE template.COMPANY_CD = v_template_company_cd
	      AND template.REPORT_CODE = 'COST_LIST'
	      AND template.REPORT_VERSION = v_report_version
	      AND template.SECTION_TYPE = 'DETAIL'
	      AND IFNULL(template.ISDEL, '0') = '0'
	      AND IFNULL(template.IS_VISIBLE, '1') = '1'
	   UNION ALL
		select CONCAT('ITEM_', 1000 + ROW_NUMBER() OVER (ORDER BY ACC_CD)) AS ROW_KEY, 
			ACC_CD,
			p_COMPANY_CD AS COMPANY_CD, 'AMOUNT' AS ROW_TYPE, 
			30 as SORT_ORDER, '' as ITEM_CODE, 
			CONCAT((CASE WHEN v_language = 'KOR' THEN ACCTITLE_NM_KOR WHEN v_language = 'ENG' THEN ACCTITLE_NM_ENG ELSE ACCTITLE_NM_VIET END),'-',ACC_CD) as ITEM_NAME,
			CONCAT((CASE WHEN v_language = 'KOR' THEN ACCTITLE_NM_KOR WHEN v_language = 'ENG' THEN ACCTITLE_NM_ENG ELSE ACCTITLE_NM_VIET END),'-',ACC_CD) as CAPTION, 
			CONCAT((CASE WHEN v_language = 'KOR' THEN ACCTITLE_NM_KOR WHEN v_language = 'ENG' THEN ACCTITLE_NM_ENG ELSE ACCTITLE_NM_VIET END),'-',ACC_CD) as LABEL_TEXT, '' as NOTE,
			2 as LEVEL_NO,
			'0' as FONT_BOLD,
			'0' as FONT_ITALIC,
			'ACCOUNT_RULE' as DATA_SOURCE_TYPE,
			'DEBIT_ONLY' as CALC_METHOD,
			'' as FORMULA_EXPR,
			YEAR(v_to_date) as REPORT_YEAR_TEXT, 
			CONCAT(DATE_FORMAT(v_from_date, '%d/%m/%Y'), ' ~ ', DATE_FORMAT(v_to_date, '%d/%m/%Y')) as REPORT_PERIOD_TEXT, 
				  'AMOUNT_UNIT_TEXT' as AMOUNT_UNIT_TEXT
		-- select *
		from acclist_info acc
		WHERE acc.ISDEL <> '1' and acc_cd like '627%' and company_cd = p_COMPANY_CD
			and v_include_detail = '1'
			AND IFNULL(ISABLEINPUT,'') = '1' 

	)as Item_Basic
		ORDER BY SORT_ORDER, LEVEL_NO, ROW_KEY;
--    ORDER BY template.SORT_ORDER;

	
	
	
    -- Period turnover ACCOUNT_RULE (not opening/closing balance)
    UPDATE tmp_cl_report report
    LEFT JOIN
    (
        SELECT
            rule.ITEM_CODE,
            SUM(CASE WHEN turnover.PERIOD_TYPE = 'CURRENT' THEN
                CASE rule.CALC_METHOD
                    WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                    WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                    WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                    ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                END
                ELSE 0
            END) AS CURRENT_YEAR,
            SUM(CASE WHEN turnover.PERIOD_TYPE = 'PREVIOUS' THEN
                CASE rule.CALC_METHOD
                    WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                    WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                    WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                    ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                END
                ELSE 0
            END) AS PREVIOUS_YEAR
        FROM tmp_cl_rule rule
        	INNER JOIN tmp_cl_account_turnover turnover ON turnover.ACC_CD LIKE CONCAT(rule.ACC_PREFIX, '%')
        WHERE rule.CALC_METHOD NOT IN ('OPENING_BALANCE', 'CLOSING_BALANCE')
        GROUP BY rule.ITEM_CODE
    ) calc
        ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
    SET
        report.CURRENT_YEAR = NULLIF(ROUND(IFNULL(calc.CURRENT_YEAR, 0) / v_unit_divisor, 0), 0),
        report.PREVIOUS_YEAR = NULLIF(ROUND(IFNULL(calc.PREVIOUS_YEAR, 0) / v_unit_divisor, 0), 0)
    WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'ACCOUNT_RULE'
      AND IFNULL(report.CALC_METHOD, '') NOT IN ('OPENING_BALANCE', 'CLOSING_BALANCE');

    -- Opening / closing absolute balances 
    UPDATE tmp_cl_report report
    LEFT JOIN
    (
        SELECT
            rule.ITEM_CODE,
            SUM(CASE
                WHEN rule.CALC_METHOD = 'OPENING_BALANCE' AND bal.AS_OF_TYPE = 'CURRENT_OPEN'
                    THEN bal.DEBIT_AMOUNT - bal.CREDIT_AMOUNT
                WHEN rule.CALC_METHOD = 'CLOSING_BALANCE' AND bal.AS_OF_TYPE = 'CURRENT_CLOSE'
                    THEN bal.DEBIT_AMOUNT - bal.CREDIT_AMOUNT
                ELSE 0
            END) AS CURRENT_YEAR,
            SUM(CASE
                WHEN rule.CALC_METHOD = 'OPENING_BALANCE' AND bal.AS_OF_TYPE = 'PREVIOUS_OPEN'
                    THEN bal.DEBIT_AMOUNT - bal.CREDIT_AMOUNT
                WHEN rule.CALC_METHOD = 'CLOSING_BALANCE' AND bal.AS_OF_TYPE = 'PREVIOUS_CLOSE'
                    THEN bal.DEBIT_AMOUNT - bal.CREDIT_AMOUNT
                ELSE 0
            END) AS PREVIOUS_YEAR
        FROM tmp_cl_rule rule
        INNER JOIN tmp_cl_account_balance bal
            ON bal.ACC_CD LIKE CONCAT(rule.ACC_PREFIX, '%')
        WHERE rule.CALC_METHOD IN ('OPENING_BALANCE', 'CLOSING_BALANCE')
        GROUP BY rule.ITEM_CODE
    ) calc
        ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
    SET
        report.CURRENT_YEAR = NULLIF(ROUND(IFNULL(calc.CURRENT_YEAR, 0) / v_unit_divisor, 0), 0),
        report.PREVIOUS_YEAR = NULLIF(ROUND(IFNULL(calc.PREVIOUS_YEAR, 0) / v_unit_divisor, 0), 0)
    WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'ACCOUNT_RULE'
      AND IFNULL(report.CALC_METHOD, '') IN ('OPENING_BALANCE', 'CLOSING_BALANCE');

-- SELECT V_closingmonth_close_ymd, v_from_ymd; -- 99999
	
-- [đầu kỳ] khi có chọn CHI TIẾT 627
	UPDATE tmp_cl_report report
		SET PREVIOUS_YEAR = (SELECT SUM(d.debit) from closingmonth_detail d WHERE d.COMPANY_CD = p_COMPANY_CD and LEFT(d.close_ymd, 6) = LEFT(V_closingmonth_close_ymd, 6) AND report.ACC_CD = d.ACC_CD )
	WHERE report.ACC_CD LIKE '6%';

	UPDATE tmp_cl_report report
	SET PREVIOUS_YEAR = ifnull(PREVIOUS_YEAR,0) + IFNULL((SELECT SUM(c.AMOUNT) FROM chitdetailinfo c WHERE c.COMPANY_CD = p_COMPANY_CD and isdel <> '1' and c.DEBIT = ACC_CD AND c.CHIT_YMD > V_closingmonth_close_ymd AND c.CHIT_YMD < v_from_ymd),0)
	WHERE report.ACC_CD LIKE '6%';
	/*
	UPDATE tmp_cl_report report
	SET PREVIOUS_YEAR = ifnull(PREVIOUS_YEAR,0) - IFNULL((SELECT SUM(c.AMOUNT) FROM chitdetailinfo c WHERE c.COMPANY_CD = p_COMPANY_CD and isdel <> '1' and c.CREDIT = ACC_CD AND c.CHIT_YMD > V_closingmonth_close_ymd AND c.CHIT_YMD < v_from_ymd),0)
	WHERE report.ACC_CD LIKE '6%';
	*/
	
	-- [trong kỳ] khi có chọn CHI TIẾT 627
	-- tmp_cl_report (627%)
	UPDATE tmp_cl_report report
	SET CURRENT_YEAR = (SELECT SUM(c.AMOUNT) FROM chitdetailinfo c WHERE c.COMPANY_CD = p_COMPANY_CD and isdel <> '1' and c.DEBIT = ACC_CD AND c.CHIT_YMD >= v_from_ymd AND c.CHIT_YMD <= v_to_ymd)
	WHERE ACC_CD LIKE '6%';
	/*
	UPDATE tmp_cl_report report
	SET CURRENT_YEAR = ifnull(CURRENT_YEAR,0) - IFNULL((SELECT SUM(c.AMOUNT) FROM chitdetailinfo c WHERE c.COMPANY_CD = p_COMPANY_CD and isdel <> '1' and c.CREDIT = ACC_CD AND c.CHIT_YMD >= v_from_ymd AND c.CHIT_YMD <= v_to_ymd),0)
	WHERE ACC_CD LIKE '6%';
	*/
		
-- SELECT * FROM tmp_cl_report WHERE ACC_CD LIKE '6%'; -- 999999999999999999999
	
	
    -- tmp_cl_formula_expr: Chuẩn hóa các biểu thức FORMULA: bỏ vế trái dấu =, bỏ khoảng trắng, đổi dấu - thành +-.
    DROP TEMPORARY TABLE IF EXISTS tmp_cl_formula_expr;
    CREATE TEMPORARY TABLE tmp_cl_formula_expr
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        EXPR_TEXT VARCHAR(1000) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY;

    SELECT
        ITEM_CODE,
        REPLACE(
            REPLACE(
                REPLACE(
                    UPPER(SUBSTRING_INDEX(IFNULL(FORMULA_EXPR, ''), '=', -1)),
                    ' ',
                    ''
                ),
                '-',
                '+-'
            ),
            ';',
            '+'
        )
    FROM tmp_cl_report
    WHERE UPPER(IFNULL(DATA_SOURCE_TYPE, '')) = 'FORMULA'
      AND IFNULL(ITEM_CODE, '') <> '';

    -- tmp_cl_formula_term: Tách từng biểu thức thành các mã chỉ tiêu con với hệ số cộng (+1) hoặc trừ (-1).
    DROP TEMPORARY TABLE IF EXISTS tmp_cl_formula_term;
    CREATE TEMPORARY TABLE tmp_cl_formula_term
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        SIGN_FACTOR INT NOT NULL DEFAULT 1,
        CHILD_ITEM_CODE VARCHAR(50) NOT NULL,
        INDEX idx_tmp_cl_formula_term_01 (ITEM_CODE),
        INDEX idx_tmp_cl_formula_term_02 (CHILD_ITEM_CODE)
    ) ENGINE=MEMORY;

    SELECT
        raw.ITEM_CODE,
        CASE WHEN LEFT(raw.TERM_TEXT, 1) = '-' THEN -1 ELSE 1 END,
        REPLACE(raw.TERM_TEXT, '-', '')
    FROM
    (
        SELECT
            formula.ITEM_CODE,
            TRIM(
                SUBSTRING_INDEX(
                    SUBSTRING_INDEX(formula.EXPR_TEXT, '+', numbers.N),
                    '+',
                    -1
                )
            ) AS TERM_TEXT
        FROM tmp_cl_formula_expr formula
        INNER JOIN tmp_cl_numbers numbers
            ON numbers.N <= 1
                + LENGTH(IFNULL(formula.EXPR_TEXT, ''))
                - LENGTH(REPLACE(IFNULL(formula.EXPR_TEXT, ''), '+', ''))
    ) raw
    WHERE raw.TERM_TEXT <> '';

    -- tmp_cl_formula_calc: Tổng hợp giá trị công thức của kỳ hiện tại và kỳ trước, cập nhật vòng lặp vào tmp_cl_report.
    DROP TEMPORARY TABLE IF EXISTS tmp_cl_formula_calc;
    CREATE TEMPORARY TABLE tmp_cl_formula_calc
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        CURRENT_YEAR DECIMAL(18,2) NULL,
        PREVIOUS_YEAR DECIMAL(18,2) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY;

    SET v_iteration = 0;

    formula_loop: WHILE v_iteration < 8 DO
        TRUNCATE TABLE tmp_cl_formula_calc;

        SELECT
            term.ITEM_CODE,
            SUM(term.SIGN_FACTOR * IFNULL(child.CURRENT_YEAR, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.PREVIOUS_YEAR, 0))
        FROM tmp_cl_formula_term term
        INNER JOIN tmp_cl_report child
            ON UPPER(child.ITEM_CODE) = UPPER(term.CHILD_ITEM_CODE)
        GROUP BY term.ITEM_CODE;

        UPDATE tmp_cl_report report
        INNER JOIN tmp_cl_formula_calc calc
            ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
        SET
            report.CURRENT_YEAR = NULLIF(calc.CURRENT_YEAR, 0),
            report.PREVIOUS_YEAR = NULLIF(calc.PREVIOUS_YEAR, 0)
        WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'FORMULA'
          AND
          (
                NOT (report.CURRENT_YEAR <=> NULLIF(calc.CURRENT_YEAR, 0))
             OR NOT (report.PREVIOUS_YEAR <=> NULLIF(calc.PREVIOUS_YEAR, 0))
          );

        SET v_changed_rows = ROW_COUNT();
        SET v_iteration = v_iteration + 1;

        IF v_changed_rows = 0 THEN
            LEAVE formula_loop;
        END IF;
    END WHILE formula_loop;
    
    SELECT
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        ITEM_CODE,
        NOTE,
        CURRENT_YEAR,
        PREVIOUS_YEAR,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    FROM tmp_cl_report
--    WHERE v_include_detail = '1'       OR IFNULL(LEVEL_NO, 1) <= 1
    ORDER BY SORT_ORDER, level_no, ROW_KEY
		;

--  SELECT * FROM tmp_cl_report;
  SELECT p_FROM_DATE, p_TO_DATE, NOW();  
    
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rpt_general_ledger_s02c1dn
DROP PROCEDURE IF EXISTS `rpt_general_ledger_s02c1dn`;
DELIMITER //
CREATE PROCEDURE `rpt_general_ledger_s02c1dn`(
	IN `p_COMPANY_CD` VARCHAR(20),
	IN `p_FROM_DATE` VARCHAR(8),
	IN `p_TO_DATE` VARCHAR(8),
	IN `p_ACCOUNT_CD` VARCHAR(1000),
	IN `p_LANGUAGE` VARCHAR(20)
)
    COMMENT '[C-G] Sổ cái tài khoản'
BEGIN
    DECLARE v_from_date DATE;
    DECLARE v_to_date DATE;
    
    DECLARE v_year_start DATE;
    DECLARE v_quarter_start DATE;
    
	 DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
--    DECLARE v_year_start_ymd VARCHAR(8);
--    DECLARE v_before_year_ymd VARCHAR(8);
--    DECLARE v_quarter_start_ymd VARCHAR(8);
    
    DECLARE v_language VARCHAR(20);
    DECLARE v_account_cd VARCHAR(10000);
    --    DECLARE v_account_cd_text VARCHAR(10000) DEFAULT '';
--    DECLARE v_account_name_text VARCHAR(10000) DEFAULT '';
    DECLARE v_report_year_text VARCHAR(20);
    
    DECLARE v_closing_month_CLOSE_YMD VARCHAR(8) DEFAULT ''; -- ngày khóa sổ gần nhất
    DECLARE v_before_states_OPEN_YMD VARCHAR(8) DEFAULT ''; -- ngày số dư đầu kỳ trong menu B-H
    DECLARE v_before_incurred_YMD VARCHAR(8) DEFAULT ''; -- ngày phát sinh (đầu kỳ)
    
    
    DECLARE v_opening_net DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_period_debit DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_period_credit DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_ending_net DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_quarter_debit DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_quarter_credit DECIMAL(18,2) DEFAULT 0.00;
    
    
    
    IF ifnull(p_FROM_DATE, '') = '' OR ifnull(p_TO_DATE, '') = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_date = p_FROM_DATE;
    SET v_to_date = p_TO_DATE;
    SET v_from_ymd = DATE_FORMAT(v_from_date, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(v_to_date, '%Y%m%d');
    
    SET v_year_start = MAKEDATE(YEAR(v_from_date), 1);
    SET v_quarter_start = DATE_ADD(MAKEDATE(YEAR(v_to_date), 1), INTERVAL ((QUARTER(v_to_date) - 1) * 3) MONTH);    
--    SET v_year_start_ymd = DATE_FORMAT(v_year_start, '%Y%m%d');
    
--    SET v_before_year_ymd = DATE_FORMAT(DATE_SUB(v_year_start, INTERVAL 1 DAY), '%Y%m%d');
--    SET v_quarter_start_ymd = DATE_FORMAT(v_quarter_start, '%Y%m%d');
    
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_account_cd = REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '');
    IF UPPER(v_account_cd) IN ('ALL', '*') THEN
        SET v_account_cd = '';
    END IF;
	 
	 -- v_closing_month_CLOSE_YMD
	 SELECT MAX(c.CLOSE_YMD) INTO v_closing_month_CLOSE_YMD FROM closingmonth_detail c WHERE c.ISDEL <> '1' AND c.COMPANY_CD = p_COMPANY_CD AND left(c.CLOSE_YMD,6) < LEFT(v_from_ymd, 6);
	 
	 
	 -- v_before_states_OPEN_YMD
	 SELECT MAX(c.OPEN_YMD) INTO v_before_states_OPEN_YMD FROM before_states c WHERE c.ISDEL <> '1' AND c.COMPANY_CD = p_COMPANY_CD AND LEFT(c.OPEN_YMD,6) < LEFT(v_from_ymd, 6);

-- SELECT v_closing_month_CLOSE_YMD, v_before_states_OPEN_YMD; -- 99999


    DROP TEMPORARY TABLE IF EXISTS tmp_filter_account_cd;
    CREATE TEMPORARY TABLE tmp_filter_account_cd (
      CD VARCHAR(64) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    IF IFNULL(v_account_cd, '') <> '' AND UPPER(IFNULL(v_account_cd, '')) NOT IN ('ALL', '*') THEN
      SELECT DISTINCT TRIM(jt.val)
      FROM JSON_TABLE(
        CONCAT('["', REPLACE(REPLACE(REPLACE(v_account_cd, '|', ','), ' ', ''), ',', '","'), '"]'),
        '$[*]' COLUMNS (val VARCHAR(64) PATH '$')
      ) jt
      WHERE NULLIF(TRIM(jt.val), '') IS NOT NULL
        AND UPPER(TRIM(jt.val)) NOT IN ('ALL', '*');
    END IF;

    SET v_report_year_text = CAST(YEAR(v_from_date) AS CHAR);

	-- 1.a TẤT CẢ TÀI KHOẢN / ACCLIST_INFO
    DROP TEMPORARY TABLE IF EXISTS tmp_Accounts;
    CREATE TEMPORARY TABLE tmp_Accounts
    (
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB;

    SELECT
        account.ACC_CD,
        (
	        CASE v_language 
				  	WHEN 'KOR' THEN COALESCE(NULLIF(TRIM(account.ACCTITLE_NM_KOR), ''), NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''), NULLIF(TRIM(account.ACCTITLE_NM_VIET), '')) 
				  	WHEN 'ENG' THEN COALESCE(NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''), NULLIF(TRIM(account.ACCTITLE_NM_VIET), '')) 
				  	ELSE account.ACCTITLE_NM_VIET
				END
			) as ACCOUNT_NAME	

    FROM acclist_info account
    WHERE account.COMPANY_CD = p_COMPANY_CD
      AND (v_account_cd = '' OR EXISTS (SELECT 1 FROM tmp_filter_account_cd f WHERE f.CD LIKE CONCAT(account.ACC_CD, '%')))
      AND account.LEVEL = '1'
      AND IFNULL(account.ISDEL, '0') <> '1'
	;
-- SELECT * FROM tmp_filter_account_cd;
-- SELECT * FROM tmp_Accounts;		-- 99999

	-- 1.b TẤT CẢ TÀI KHOẢN con / ACCLIST_INFO
    DROP TEMPORARY TABLE IF EXISTS tmp_Accounts_Child;
    CREATE TEMPORARY TABLE tmp_Accounts_Child
    (
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB;

    SELECT
        account.ACC_CD,
        fn_get_description(p_LANGUAGE, account.ACCTITLE_NM_VIET, account.ACCTITLE_NM_ENG, account.ACCTITLE_NM_KOR) as ACCOUNT_NAME	
		
    FROM acclist_info account
    WHERE account.COMPANY_CD = p_COMPANY_CD
      AND (v_account_cd = '' OR account.ACC_CD REGEXP CONCAT('^(', REPLACE(v_account_cd, ',', '|'), ')'))
      AND account.ISABLEINPUT = '1'
      AND IFNULL(account.ISDEL, '0') <> '1'
	;
-- SELECT * FROM tmp_Accounts;		-- 99999
-- SELECT * FROM tmp_Accounts_Child;
-- select v_account_cd; -- , * from tmp_Accounts;

	-- 2. table ALL DATA // CHỨA TẤT CẢ DỮ LIỆU KẾT QUẢ
    DROP TEMPORARY TABLE IF EXISTS tmp_REPORT_RETURN;
    CREATE TEMPORARY TABLE tmp_REPORT_RETURN
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_KEY VARCHAR(100) NOT NULL DEFAULT '',
        PARENT_ROW_KEY VARCHAR(100) NULL DEFAULT NULL,
        LINE_SORT INT NOT NULL DEFAULT 0,
        ROW_LEVEL INT NOT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(50) NOT NULL DEFAULT '', -- GENERAL_LEDGER
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        ACC_CD VARCHAR(20) NULL DEFAULT '',
        
        CHIT_TYPE VARCHAR(50) NULL DEFAULT 'OT',
        CHIT_ID BIGINT NULL DEFAULT NULL,
        MODULE_CD VARCHAR(20) NULL DEFAULT NULL,
        ACCOUNT_CD VARCHAR(1000) NOT NULL DEFAULT '',
        ACCOUNT_NAME VARCHAR(1000) NOT NULL DEFAULT '',
        REPORT_YEAR_TEXT VARCHAR(20) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        -- ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
		  CHIT_NO VARCHAR(50) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(10) NOT NULL DEFAULT '',
        
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        CSD_ACC_CD VARCHAR(50) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,2) NULL,
        CREDIT_AMOUNT DECIMAL(18,2) NULL,
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        CUSTOMER_ID BIGINT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO)
    ) ENGINE=InnoDB;
	
    
        -- Emit one account node. Transaction rows below reference it as parent,
        -- so the TreeList renders the hierarchy returned by this procedure.
        -- 
		  -- Tạo một nút tài khoản.
			-- Các dòng giao dịch bên dưới sẽ tham chiếu đến nút này như nút cha,
			-- giúp TreeList hiển thị cấu trúc phân cấp do Stored Procedure trả về.
    /*
            ROW_KEY,
            PARENT_ROW_KEY,
            LINE_SORT,
            ROW_LEVEL,
            COMPANY_CD,
            ROW_TYPE,
            ACC_CD,
            ACCOUNT_CD,
            ACCOUNT_NAME,
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            CHIT_TYPE
        )
        SELECT
            CONCAT('ACCOUNT_', account.ACC_CD),
            NULL,
            10,
            0,
            p_COMPANY_CD,
            'GROUP',
            account.ACC_CD,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            v_report_year_text,
            'Đơn vị tính: đồng',
            ''
        FROM tmp_Accounts account;


        SELECT
            GROUP_CONCAT(ACC_CD ORDER BY ACC_CD SEPARATOR ', '),
            GROUP_CONCAT(ACCOUNT_NAME ORDER BY ACC_CD SEPARATOR ', ')
        INTO
            v_account_cd_text,
            v_account_name_text
        FROM tmp_Accounts;

        SET v_account_cd_text = IFNULL(v_account_cd_text, '');
        SET v_account_name_text = IFNULL(v_account_name_text, '');
*/

-- SELECT v_before_year_ymd; -- 99999
			-- 3. ĐẦU KỲ (temp)
/*        DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_latest_open;
        CREATE TEMPORARY TABLE tmp_general_ledger_latest_open
        (
            ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
            OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '',
            PRIMARY KEY (ACC_CD)
        ) ENGINE=INNODB;

        SELECT account.ACC_CD, IFNULL(MAX(opening.OPEN_YMD), '')
        FROM tmp_Accounts account
        	LEFT JOIN before_states opening ON opening.COMPANY_CD = p_COMPANY_CD AND opening.ACC_CD = account.ACC_CD AND IFNULL(opening.ISDEL, '0') <> '1' AND IFNULL(opening.OPEN_YMD, '') <= v_before_year_ymd
        GROUP BY account.ACC_CD;
*/
			-- 4. ĐẦU KỲ
        DROP TEMPORARY TABLE IF EXISTS tmp_OPENNING;
        CREATE TEMPORARY TABLE tmp_OPENNING
        (
            ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
--            OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '00000000',
            DEBIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            CREDIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            PRIMARY KEY (ACC_CD)
        ) ENGINE=InnoDB;
			
			
		  -- 4.A CLOSING MONTH DETAILS     closingmonth_detail
		  if v_closing_month_CLOSE_YMD IS NOT NULL AND LENGTH(v_closing_month_CLOSE_YMD) = 8 then
	        SELECT
	            LEFT(b.ACC_CD,3) AS ACC_CD,
--	            IFNULL(NULLIF(b.close_ymd, ''), '00000000'),
	            IFNULL(SUM(b.DEBIT), 0),
	            IFNULL(SUM(b.CREDIT), 0)
	        FROM closingmonth_detail b 
			  	where b.COMPANY_CD = p_COMPANY_CD AND left(b.close_ymd,6) = LEFT(v_closing_month_CLOSE_YMD, 6) AND IFNULL(b.ISDEL, '0') <> '1'
			  		AND b.ACC_CD IN (SELECT t.ACC_CD from tmp_Accounts_Child t)
	        GROUP BY LEFT(b.ACC_CD,3);
	        
	        SET v_before_incurred_YMD = concat(left(v_closing_month_CLOSE_YMD, 6) + 1, '01'); -- ngày phát sinh đầu kỳ là NGÀY KHÓA SỔ  (lấy ngày 01 của tháng tiếp theo, sau tháng khóa sổ)
        ELSEif v_before_states_OPEN_YMD IS NOT NULL AND length(v_before_states_OPEN_YMD) = 8 then
		  		-- 4.B before_states (4.A NULL)  before_states
	        SELECT
	            LEFT(b.ACC_CD,3),
--	            IFNULL(NULLIF(b.OPEN_YMD, ''), '00000000'),
	            IFNULL(SUM(b.DEBIT), 0),
	            IFNULL(SUM(b.CREDIT), 0)
	        FROM before_states b 
			  	where b.COMPANY_CD = p_COMPANY_CD AND b.OPEN_YMD = v_before_states_OPEN_YMD AND IFNULL(b.ISDEL, '0') <> '1'
			  		AND b.ACC_CD IN (SELECT t.ACC_CD from tmp_Accounts_Child t)
	        GROUP BY LEFT(b.ACC_CD,3); -- , b.OPEN_YMD;
	        
	        SET v_before_incurred_YMD = v_before_states_OPEN_YMD;  -- ngày phát sinh đầu kỳ là NGÀY SỐ DƯ ĐẦU KỲ (trong menu B-H)
        END if;
        
        -- -----------------------------------------------------------------------------------------------------------------------
        -- 4.C PHÁT SINH ĐẦU KỲ (DEBIT)
        SELECT    x.ACC_CD,    x.DEBIT_AMOUNT,    x.CREDIT_AMOUNT
		  FROM (
	        SELECT LEFT(d.DEBIT, 3) AS ACC_CD,
	        	SUM(d.AMOUNT) AS DEBIT_AMOUNT,
	        	0 AS CREDIT_AMOUNT
	        FROM chitdetailinfo d
		        INNER JOIN tmp_Accounts_Child account ON d.DEBIT like account.ACC_CD
		        
	        WHERE d.COMPANY_CD = p_COMPANY_CD
	          AND IFNULL(d.ISDEL, '0') <> '1'          
	          AND  (v_before_incurred_YMD IS NULL OR v_before_incurred_YMD = '' or d.CHIT_YMD >= v_before_incurred_YMD)
	          AND  d.CHIT_YMD < v_from_ymd
	        GROUP BY LEFT(d.DEBIT, 3)
	    ) as x
        ON DUPLICATE KEY UPDATE
	    DEBIT_AMOUNT = tmp_OPENNING.DEBIT_AMOUNT + x.DEBIT_AMOUNT,
	    CREDIT_AMOUNT = tmp_OPENNING.CREDIT_AMOUNT + x.CREDIT_AMOUNT
		  ;
		  
        -- -----------------------------------------------------------------------------------------------------------------------			
        -- 4.d PHÁT SINH ĐẦU KỲ (CREDIT)
        SELECT    x.ACC_CD,    x.DEBIT_AMOUNT,    x.CREDIT_AMOUNT
		  FROM 
		  (	        
	        SELECT LEFT(d.CREDIT, 3) AS ACC_CD,
	        	0 AS DEBIT_AMOUNT,
	        	SUM(d.AMOUNT) AS CREDIT_AMOUNT
	        FROM chitdetailinfo d
		        INNER JOIN tmp_Accounts_Child account ON d.CREDIT like account.ACC_CD
		        
	        WHERE d.COMPANY_CD = p_COMPANY_CD
	          AND IFNULL(d.ISDEL, '0') <> '1'          
	          AND  (v_before_incurred_YMD IS NULL OR v_before_incurred_YMD = '' or d.CHIT_YMD >= v_before_incurred_YMD)
	          AND  d.CHIT_YMD < v_from_ymd
	        GROUP BY LEFT(d.CREDIT, 3)
		  ) as x
        ON DUPLICATE KEY UPDATE
	    DEBIT_AMOUNT = tmp_OPENNING.DEBIT_AMOUNT + x.DEBIT_AMOUNT,
	    CREDIT_AMOUNT = tmp_OPENNING.CREDIT_AMOUNT + x.CREDIT_AMOUNT
		  ;

-- SELECT * FROM tmp_OPENNING; -- 99999
			
            ROW_KEY,
            PARENT_ROW_KEY,
            LINE_SORT,
            ROW_LEVEL,
            COMPANY_CD,
            ROW_TYPE,
            ACCOUNT_CD,
            ACCOUNT_NAME,
            
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
            , REPORT_GROUP_KEY -- GROUP
        )
		  SELECT 'OPENING_BALANCE' AS ROW_KEY,
            '' AS PARENT_ROW_KEY,
            0 AS LINE_SORT,
            0 AS ROW_LEVEL,
            p_COMPANY_CD AS COMPANY_CD,
            'OPENING' AS ROW_TYPE,
            ACC_CD AS ACCOUNT_CD,
            '' AS ACCOUNT_NAME,
            
            v_report_year_text AS REPORT_YEAR_TEXT,
            'Đơn vị tính: đồng' AS AMOUNT_UNIT_TEXT,
            'Số dư đầu KỲ' AS DESCRIPTION,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
            , ACC_CD
		  FROM tmp_OPENNING;

        -- -----------------------------------------------------------------------------------------------------------------------
        -- 5. PHÁT SINH TRONG KỲ
        DROP TEMPORARY TABLE IF EXISTS tmp_DETAILS; -- tmp_general_ledger_movements
        CREATE TEMPORARY TABLE tmp_DETAILS
        (
            ROW_NO INT NOT NULL AUTO_INCREMENT,
            
            ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
            ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
            -- CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
            -- ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
            CHIT_NO VARCHAR(50) NOT NULL DEFAULT '',
            CHIT_YMD VARCHAR(10) NOT NULL DEFAULT '',
            CHIT_ID BIGINT NULL DEFAULT NULL,
            CHIT_TYPE VARCHAR(50) NULL DEFAULT NULL,
            MODULE_CD VARCHAR(20) NULL DEFAULT NULL,
            DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
            
            CSD_ACC_CD VARCHAR(50) NOT NULL DEFAULT '',
            
            DEBIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            CREDIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            SORT_NO VARCHAR(50) NOT NULL DEFAULT '',
            SORT_CHIT_ID BIGINT NOT NULL DEFAULT 0,
            SORT_DETAIL INT NOT NULL DEFAULT 0,
            SORT_SIDE INT NOT NULL DEFAULT 0,
            CUSTOMER_ID BIGINT NULL DEFAULT 0,
            
            PRIMARY KEY (ROW_NO),
            INDEX idx_tmp_DETAILS_01 (ACC_CD, CHIT_YMD)
        ) ENGINE=InnoDB;

        -- 5.A. PHÁT SINH TRONG KỲ (DEBIT)
        SELECT
            account.ACC_CD,
            account.ACCOUNT_NAME,

            h.CHIT_NO,
            h.CHIT_ID,
            h.CHIT_TYPE,
            h.INPUT_TYPE,
            d.CHIT_YMD,
            
            fn_get_description12(v_language, desc2_vi.DESCRIPTION, desc2_en.DESCRIPTION, desc2_kr.DESCRIPTION, 
															desc1_vi.DESCRIPTION, desc1_en.DESCRIPTION, desc1_kr.DESCRIPTION,
															NULLIF(TRIM(h.PAYER_INFO), ''))  as DESCRIPTION2,
                        
            TRIM(IFNULL(d.CREDIT, '')),
            IFNULL(d.AMOUNT, 0),
            0,
            IFNULL(h.CHIT_NO, ''),
            IFNULL(h.CHIT_ID, 0),
            IFNULL(d.SORT, 0),
            1 as SORT_SIDE,
            
            ext.CUSTOMER_ID
        FROM chitdetailinfo d
	        INNER JOIN tmp_Accounts_Child account ON d.DEBIT like account.ACC_CD
	        INNER JOIN chitinfo h ON h.COMPANY_CD = d.COMPANY_CD AND h.CHIT_ID = d.CHIT_ID AND IFNULL(h.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdescriptioninfo desc1_vi ON desc1_vi.COMPANY_CD = h.COMPANY_CD AND desc1_vi.CHIT_ID = h.CHIT_ID AND desc1_vi.LANG_TYPE = 'VIET' AND IFNULL(desc1_vi.ISDEL, '0') <> '1'
	        LEFT JOIN chitdescriptioninfo desc1_en ON desc1_en.COMPANY_CD = h.COMPANY_CD AND desc1_en.CHIT_ID = h.CHIT_ID AND desc1_en.LANG_TYPE = 'ENG' AND IFNULL(desc1_en.ISDEL, '0') <> '1'
	        LEFT JOIN chitdescriptioninfo desc1_kr ON desc1_kr.COMPANY_CD = h.COMPANY_CD AND desc1_kr.CHIT_ID = h.CHIT_ID AND desc1_kr.LANG_TYPE = 'KOR' AND IFNULL(desc1_kr.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdetaildescriptioninfo desc2_vi ON desc2_vi.COMPANY_CD = d.COMPANY_CD AND desc2_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_vi.LANG_TYPE = 'VIET' AND IFNULL(desc2_vi.ISDEL, '0') <> '1'
	        LEFT JOIN chitdetaildescriptioninfo desc2_en ON desc2_en.COMPANY_CD = d.COMPANY_CD AND desc2_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_en.LANG_TYPE = 'ENG' AND IFNULL(desc2_en.ISDEL, '0') <> '1'
	        LEFT JOIN chitdetaildescriptioninfo desc2_kr ON desc2_kr.COMPANY_CD = d.COMPANY_CD AND desc2_kr.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_kr.LANG_TYPE = 'KOR' AND IFNULL(desc2_kr.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID and ext.ISDEL <> '1'
        WHERE d.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(d.ISDEL, '0') <> '1'
          AND IFNULL(d.AMOUNT, 0) <> 0
          AND d.CHIT_YMD BETWEEN v_from_ymd and v_to_ymd;

        -- 5.A. PHÁT SINH TRONG KỲ (CREDIT)
        SELECT
            account.ACC_CD,
            account.ACCOUNT_NAME,
            
            h.CHIT_NO,
            h.CHIT_ID,
            h.CHIT_TYPE,
            h.INPUT_TYPE,
            d.CHIT_YMD,
            COALESCE(
                NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN desc2_en.DESCRIPTION WHEN 'KOR' THEN desc2_kr.DESCRIPTION ELSE desc2_vi.DESCRIPTION END), ''),
                NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN desc1_en.DESCRIPTION WHEN 'KOR' THEN desc1_kr.DESCRIPTION ELSE desc1_vi.DESCRIPTION END), ''),
                NULLIF(TRIM(h.PAYER_INFO), ''),
                ''
            ) as DESCRIPTION,
            TRIM(IFNULL(d.DEBIT, '')),
            0,
            IFNULL(d.AMOUNT, 0),
            IFNULL(h.CHIT_NO, ''),
            IFNULL(h.CHIT_ID, 0),
            IFNULL(d.SORT, 0),
            2 as SORT_SIDE,
            ext.CUSTOMER_ID
        FROM chitdetailinfo d
	        INNER JOIN tmp_Accounts_Child account ON d.CREDIT like account.ACC_CD
	        INNER JOIN chitinfo h            ON h.COMPANY_CD = d.COMPANY_CD           AND h.CHIT_ID = d.CHIT_ID           AND IFNULL(h.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdescriptioninfo desc1_vi ON desc1_vi.COMPANY_CD = h.COMPANY_CD AND desc1_vi.CHIT_ID = h.CHIT_ID AND desc1_vi.LANG_TYPE = 'VIET' AND IFNULL(desc1_vi.ISDEL, '0') <> '1'
	        LEFT JOIN chitdescriptioninfo desc1_en ON desc1_en.COMPANY_CD = h.COMPANY_CD AND desc1_en.CHIT_ID = h.CHIT_ID AND desc1_en.LANG_TYPE = 'ENG' AND IFNULL(desc1_en.ISDEL, '0') <> '1'
	        LEFT JOIN chitdescriptioninfo desc1_kr ON desc1_kr.COMPANY_CD = h.COMPANY_CD AND desc1_kr.CHIT_ID = h.CHIT_ID AND desc1_kr.LANG_TYPE = 'KOR' AND IFNULL(desc1_kr.ISDEL, '0') <> '1'
	        
			  LEFT JOIN chitdetaildescriptioninfo desc2_vi ON desc2_vi.COMPANY_CD = d.COMPANY_CD AND desc2_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_vi.LANG_TYPE = 'VIET' AND IFNULL(desc2_vi.ISDEL, '0') <> '1'
	        LEFT JOIN chitdetaildescriptioninfo desc2_en ON desc2_en.COMPANY_CD = d.COMPANY_CD AND desc2_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_en.LANG_TYPE = 'ENG' AND IFNULL(desc2_en.ISDEL, '0') <> '1'
	        LEFT JOIN chitdetaildescriptioninfo desc2_kr ON desc2_kr.COMPANY_CD = d.COMPANY_CD AND desc2_kr.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_kr.LANG_TYPE = 'KOR' AND IFNULL(desc2_kr.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID and ext.ISDEL <> '1'
        WHERE d.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(d.ISDEL, '0') <> '1'
          AND IFNULL(d.AMOUNT, 0) <> 0
          AND d.CHIT_YMD BETWEEN v_from_ymd and v_to_ymd;

        DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_sums;
        CREATE TEMPORARY TABLE tmp_general_ledger_sums
        (
            ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
            OPENING_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            PERIOD_DEBIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            PERIOD_CREDIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            ENDING_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            QUARTER_DEBIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            QUARTER_CREDIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            PRIMARY KEY (ACC_CD)
        ) ENGINE=InnoDB;
/*
            ACC_CD,
            OPENING_NET,
            PERIOD_DEBIT,
            PERIOD_CREDIT,
            ENDING_NET,
            QUARTER_DEBIT,
            QUARTER_CREDIT
        )
        SELECT
            account.ACC_CD,
            IFNULL(base.DEBIT_AMOUNT, 0) - IFNULL(base.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= IFNULL(base.OPEN_YMD, '00000000')
                 AND movement.CHIT_YMD < v_year_start_ymd
                THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_from_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.DEBIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_from_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(base.DEBIT_AMOUNT, 0) - IFNULL(base.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= IFNULL(base.OPEN_YMD, '00000000')
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_quarter_start_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.DEBIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_quarter_start_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.CREDIT_AMOUNT
                ELSE 0
            END), 0)
        FROM tmp_Accounts account
	        LEFT JOIN tmp_OPENNING base ON base.ACC_CD = account.ACC_CD
	        LEFT JOIN tmp_DETAILS movement ON movement.ACC_CD = account.ACC_CD
        GROUP BY account.ACC_CD, base.OPEN_YMD, base.DEBIT_AMOUNT, base.CREDIT_AMOUNT;

        SELECT
            IFNULL(SUM(OPENING_NET), 0),
            IFNULL(SUM(PERIOD_DEBIT), 0),
            IFNULL(SUM(PERIOD_CREDIT), 0),
            IFNULL(SUM(ENDING_NET), 0),
            IFNULL(SUM(QUARTER_DEBIT), 0),
            IFNULL(SUM(QUARTER_CREDIT), 0)
        INTO
            v_opening_net,
            v_period_debit,
            v_period_credit,
            v_ending_net,
            v_quarter_debit,
            v_quarter_credit
        FROM tmp_general_ledger_sums;


            ROW_KEY,
            PARENT_ROW_KEY,
            LINE_SORT,
            ROW_LEVEL,
            COMPANY_CD,
            ROW_TYPE,
            ACCOUNT_CD,
            ACCOUNT_NAME,
            
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
        )
        VALUES
        (
            'OPENING_BALANCE',
            10,
            p_COMPANY_CD,
            'OPENING',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            
            'Số dư đầu năm',
            NULLIF(ROUND(GREATEST(v_opening_net, 0), 0), 0),
            NULLIF(ROUND(GREATEST(-v_opening_net, 0), 0), 0)
        );
*/
            ROW_KEY,
            PARENT_ROW_KEY,
            LINE_SORT,	-- ORDER BY 2
            ROW_LEVEL,
            COMPANY_CD,
            ROW_TYPE,
            
            ACC_CD, -- ORDER BY 1
            ACCOUNT_CD,
            ACCOUNT_NAME,
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            
            CHIT_NO,
            CHIT_ID,
            CHIT_TYPE,
            MODULE_CD,
            CHIT_YMD,
            DESCRIPTION,
            CSD_ACC_CD,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT,
            CUSTOMER_ID
            , REPORT_GROUP_KEY -- GROUP
        )
        SELECT
            CONCAT('DETAIL_', movement.ROW_NO),
            CONCAT('ACCOUNT_', movement.ACC_CD),
            1000,
            1,
            p_COMPANY_CD,
            'DETAIL',
            
            movement.ACC_CD, -- ACC LEVEL=1
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',

            movement.CHIT_NO,
            movement.CHIT_ID,
            movement.CHIT_TYPE,
            movement.MODULE_CD,
            movement.CHIT_YMD,
            movement.DESCRIPTION,
            movement.CSD_ACC_CD,
            NULLIF(ROUND(movement.DEBIT_AMOUNT, 0), 0),
            NULLIF(ROUND(movement.CREDIT_AMOUNT, 0), 0),
            CUSTOMER_ID
            , A.ACC_CD
        FROM tmp_DETAILS movement
        		INNER JOIN tmp_Accounts A ON movement.ACC_CD LIKE CONCAT(A.ACC_CD, '%')
        WHERE movement.CHIT_YMD >= v_from_ymd AND movement.CHIT_YMD <= v_to_ymd
        ORDER BY movement.CHIT_YMD, movement.SORT_NO, movement.SORT_CHIT_ID, movement.SORT_DETAIL, movement.SORT_SIDE;
-- SELECT * FROM tmp_DETAILS; -- 99999

            ROW_KEY,
            LINE_SORT,
            COMPANY_CD,
            ROW_TYPE,
            ACCOUNT_CD,
            ACCOUNT_NAME,
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
            , REPORT_GROUP_KEY -- GROUP (ACC_CD)
        )
        SELECT 
        		'TOTAL_PERIOD',
            900000,
            p_COMPANY_CD,
            'TOTAL_PERIOD',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            'Cộng phát sinh',
            NULLIF(ROUND(v_period_debit, 0), 0),
            NULLIF(ROUND(v_period_credit, 0), 0)
            , A.ACC_CD
         FROM tmp_DETAILS D
         	INNER JOIN tmp_Accounts A ON D.ACC_CD LIKE CONCAT(A.ACC_CD)
         ;
        /*
        VALUES
        (
            'TOTAL_PERIOD',
            900000,
            p_COMPANY_CD,
            'TOTAL_PERIOD',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            'Cộng số phát sinh trong tháng',
            NULLIF(ROUND(v_period_debit, 0), 0),
            NULLIF(ROUND(v_period_credit, 0), 0)
        ),
        (
            'ENDING_BALANCE',
            900010,
            p_COMPANY_CD,
            'ENDING',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            'Số dư cuối tháng',
            NULLIF(ROUND(GREATEST(v_ending_net, 0), 0), 0),
            NULLIF(ROUND(GREATEST(-v_ending_net, 0), 0), 0)
        )
        , (
            'QUARTER_ACCUMULATED',
            900020,
            p_COMPANY_CD,
            'QUARTER_ACCUMULATED',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            'Cộng lũy kế từ đầu quý',
            NULLIF(ROUND(v_quarter_debit, 0), 0),
            NULLIF(ROUND(v_quarter_credit, 0), 0)
        )*/
		   



    SELECT
        R.ROW_KEY as __ROW_KEY,
        R.PARENT_ROW_KEY AS __PARENT_ROW_KEY,
        R.ROW_NO AS __ROW_SORT,
        R.ROW_LEVEL AS __ROW_LEVEL,
        0 AS __TREE_EXPAND_ALL,
        R.LINE_SORT as __LINE_SORT,
        R.COMPANY_CD as __COMPANY_CD,
        R.REPORT_GROUP_KEY as __REPORT_GROUP_KEY,
        R.ROW_TYPE AS __ROW_TYPE,
        
--        CASE WHEN R.ROW_TYPE = 'GROUP' THEN CONCAT(A.ACC_CD, '-', A.ACCOUNT_NAME) ELSE '' END AS ACC_CD,
        CONCAT(A.ACC_CD, '-', A.ACCOUNT_NAME)  AS ACC_CD,

        R.CHIT_TYPE,
        R.CHIT_ID AS __CHIT_ID,
        R.CHIT_TYPE AS __CHIT_TYPE,
        R.MODULE_CD AS __MODULE_CD,
        CASE WHEN R.ROW_TYPE = 'DETAIL' AND IFNULL(R.CHIT_ID, 0) > 0 THEN 'DOCUMENT' ELSE 'NONE' END AS __LINK_TYPE,
        R.CHIT_NO,
        DATE_FORMAT(STR_TO_DATE(R.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') as CHIT_YMD,
        
--        R.CUSTOMER_ID,
        C.CUSTOMER_CD,
        (
        		CASE v_language 
				  	WHEN 'KOR' THEN COALESCE(NULLIF(TRIM(C.CUSTOMER_NM_KOR), ''), NULLIF(TRIM(C.CUSTOMER_NM_ENG), ''), NULLIF(TRIM(C.CUSTOMER_NM_VIET), '')) 
				  	WHEN 'ENG' THEN COALESCE(NULLIF(TRIM(C.CUSTOMER_NM_ENG), ''), NULLIF(TRIM(C.CUSTOMER_NM_VIET), '')) 
				  	ELSE C.CUSTOMER_NM_VIET
				END
		  )AS CUSTOMER_NM,
        
--        '' AS MG_CD, -- MÃ QUẢN LÝ
--        '' AS MG_DESC,
        
--        '' AS MG_CD_2, -- MÃ QUẢN LÝ 2
--        '' AS MG_DESC_2,
        
--        '' AS MR_DESC, -- TÊN GHI CHÚ
        
--        '' AS DEPARTMENT_CD,
--        '' AS DEPARTMENT_NM,
        
        R.ACCOUNT_CD AS __ACCOUNT_CD,
        R.ACCOUNT_NAME AS __ACCOUNT_NAME_TEXT,
        R.ACCOUNT_CD AS __ACCOUNT_CD_TEXT,

        R.REPORT_YEAR_TEXT as __REPORT_YEAR_TEXT,
        R.AMOUNT_UNIT_TEXT as __AMOUNT_UNIT_TEXT,
        
        R.DESCRIPTION,
--        '' AS DESCRIPTION2,
        
--		  '' AS lblACC_CD, -- TK
--        '' AS ACCTITLE_NM,
        
        R.CSD_ACC_CD, -- TK ĐỐI ỨNG
        (select ACCOUNT_NAME from  tmp_Accounts_Child ac where ac.ACC_CD = R.CSD_ACC_CD) AS CSD_ACCTITLE_NM,
        
        R.DEBIT_AMOUNT,
        R.CREDIT_AMOUNT,
        R.NOTE_TEXT as __NOTE_TEXT
        
        
    FROM tmp_REPORT_RETURN R
    	   LEFT JOIN tmp_Accounts A ON R.REPORT_GROUP_KEY LIKE A.ACC_CD
    	LEFT JOIN customer_info C ON C.COMPANY_CD = R.COMPANY_CD AND C.CUSTOMER_ID = R.CUSTOMER_ID AND IFNULL(C.ISDEL, '0') <> '1'
    ORDER BY A.ACC_CD, R.LINE_SORT, R.ROW_NO;

-- SELECT * FROM tmp_REPORT_RETURN; -- 99999



    DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_sums;
    DROP TEMPORARY TABLE IF EXISTS tmp_DETAILS;
    DROP TEMPORARY TABLE IF EXISTS tmp_OPENNING;
    DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_latest_open;
    DROP TEMPORARY TABLE IF EXISTS tmp_REPORT_RETURN; -- RETURN
    DROP TEMPORARY TABLE IF EXISTS tmp_Accounts;
    DROP TEMPORARY TABLE IF EXISTS tmp_Accounts_Child;
    
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rpt_inventory_detail_account
DROP PROCEDURE IF EXISTS `rpt_inventory_detail_account`;
DELIMITER //
CREATE PROCEDURE `rpt_inventory_detail_account`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_PRODUCT_CD TEXT,
    IN p_ACCOUNT_CD TEXT,
    IN p_FC_TYPE VARCHAR(10),
    IN p_HIDE_NO_MOVEMENT TINYINT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_language VARCHAR(20) DEFAULT UPPER(COALESCE(p_LANGUAGE, 'VIET'));
    DECLARE v_fc_type VARCHAR(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
    DECLARE v_month_start DATE;
    DECLARE v_product_filter TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
    DECLARE v_dimension_filter TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL OR p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid inventory report date range';
    END IF;

    SET v_fc_type = UPPER(TRIM(COALESCE(p_FC_TYPE, '')));
    SET v_month_start = DATE_SUB(p_TO_DATE, INTERVAL (DAYOFMONTH(p_TO_DATE) - 1) DAY);
    SET v_product_filter = TRIM(COALESCE(p_PRODUCT_CD, ''));
    SET v_dimension_filter = TRIM(COALESCE(p_ACCOUNT_CD, ''));

    WITH product_filter AS (
        SELECT TRIM(CODE) AS CODE
        FROM JSON_TABLE(REPLACE(JSON_ARRAY(v_product_filter), ',', '","'),
            '$[*]' COLUMNS (CODE VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH '$')) tokens
    ), dimension_filter AS (
        SELECT TRIM(CODE) AS CODE
        FROM JSON_TABLE(REPLACE(JSON_ARRAY(v_dimension_filter), ',', '","'),
            '$[*]' COLUMNS (CODE VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH '$')) tokens
    ), movement AS (
        SELECT
            'INPUT' AS FLOW_TYPE,
            ii.INPUT_ID AS LINE_ID,
            ii.PRODUCT_ID, ii.PRODUCT_CD, ii.STORE_ID, ii.STORE_CD,
            ii.UNIT_ID, ii.UNIT_CD, ii.SORT,
            COALESCE(NULLIF(ii.CHIT_TYPE, ''), h.CHIT_TYPE, '') AS DOCUMENT_TYPE,
            COALESCE(DATE(ii.INVENTORY_YMD), STR_TO_DATE(NULLIF(h.INVENTORY_YMD, ''), '%Y%m%d')) AS DOCUMENT_DATE,
            COALESCE(NULLIF(h.INVENTORY_NO, ''), NULLIF(chit.CHIT_NO, ''), ii.INVENTORY_CD, '') AS DOCUMENT_NO,
            COALESCE(NULLIF(ii.SUMMARY, ''), h.REMARK, '') AS DESCRIPTION,
            COALESCE(posting.DEBIT, '') AS ACCOUNT_CD,
            COALESCE(posting.CREDIT, '') AS COUNTERPART_ACCOUNT,
            COALESCE(h.INVENTORY_ID, chit.CHIT_ID) AS SOURCE_ID,
            COALESCE(h.CHIT_TYPE, chit.CHIT_TYPE) AS SOURCE_TYPE,
            CAST(ii.QUANTITY AS DECIMAL(24, 6)) AS QUANTITY,
            CAST(COALESCE(NULLIF(ii.AMOUNT_CC, 0), ii.QUANTITY * ii.UNIT_PRICE_CC) AS DECIMAL(24, 6)) AS AMOUNT,
            CAST(CASE WHEN ii.FC_TYPE = v_fc_type THEN ii.AMOUNT_FC END AS DECIMAL(24, 6)) AS AMOUNT_FC,
            CAST(ii.UNIT_PRICE_CC AS DECIMAL(24, 6)) AS UNIT_PRICE,
            CAST(CASE WHEN ii.FC_TYPE = v_fc_type THEN ii.UNIT_PRICE_FC END AS DECIMAL(24, 6)) AS UNIT_PRICE_FC
        FROM chit_inventory_input ii
        LEFT JOIN chit_inventory_info h
            ON h.COMPANY_CD = ii.COMPANY_CD AND h.INVENTORY_ID = ii.INVENTORY_ID
           AND (ii.CHIT_TYPE = h.CHIT_TYPE
                OR (ii.CHIT_TYPE = 'IA' AND h.CHIT_TYPE IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER')))
        LEFT JOIN chitdetailinfo posting
            ON posting.COMPANY_CD = ii.COMPANY_CD AND posting.ISDEL = '0'
           AND posting.CHITDETAIL_ID = ii.CHITDETAIL_ID
        LEFT JOIN chitinfo chit
            ON chit.COMPANY_CD = ii.COMPANY_CD
           AND chit.CHIT_ID = posting.CHIT_ID
        WHERE ii.COMPANY_CD = p_COMPANY_CD AND ii.ISDEL = '0'
          AND (h.INVENTORY_ID IS NULL OR h.ISDEL = '0')
          AND (chit.CHIT_ID IS NULL OR chit.ISDEL = '0')
          AND (ii.INVENTORY_YMD < DATE_ADD(p_TO_DATE, INTERVAL 1 DAY)
               OR (ii.INVENTORY_YMD IS NULL AND h.INVENTORY_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')))
        UNION ALL
        SELECT
            'OUTPUT' AS FLOW_TYPE,
            io.OUTPUT_ID AS LINE_ID,
            io.PRODUCT_ID, io.PRODUCT_CD, io.STORE_ID, io.STORE_CD,
            io.UNIT_ID, io.UNIT_CD, io.SORT,
            COALESCE(NULLIF(io.CHIT_TYPE, ''), h.CHIT_TYPE, '') AS DOCUMENT_TYPE,
            COALESCE(DATE(io.INVENTORY_YMD), STR_TO_DATE(NULLIF(h.INVENTORY_YMD, ''), '%Y%m%d')) AS DOCUMENT_DATE,
            COALESCE(NULLIF(h.INVENTORY_NO, ''), NULLIF(chit.CHIT_NO, ''), io.INVENTORY_CD, '') AS DOCUMENT_NO,
            COALESCE(NULLIF(io.SUMMARY, ''), h.REMARK, '') AS DESCRIPTION,
            COALESCE(posting.CREDIT, '') AS ACCOUNT_CD,
            COALESCE(posting.DEBIT, '') AS COUNTERPART_ACCOUNT,
            COALESCE(h.INVENTORY_ID, chit.CHIT_ID) AS SOURCE_ID,
            COALESCE(h.CHIT_TYPE, chit.CHIT_TYPE) AS SOURCE_TYPE,
            CAST(io.QUANTITY AS DECIMAL(24, 6)) AS QUANTITY,
            CAST(CASE WHEN io.CHIT_TYPE = 'IO' THEN io.AMOUNT_CC
                      ELSE COALESCE(NULLIF(io.AMOUNT_CC, 0), io.QUANTITY * io.UNIT_PRICE_CC) END AS DECIMAL(24, 6)) AS AMOUNT,
            CAST(CASE WHEN io.FC_TYPE = v_fc_type THEN io.AMOUNT_FC END AS DECIMAL(24, 6)) AS AMOUNT_FC,
            CAST(io.UNIT_PRICE_CC AS DECIMAL(24, 6)) AS UNIT_PRICE,
            CAST(CASE WHEN io.FC_TYPE = v_fc_type THEN io.UNIT_PRICE_FC END AS DECIMAL(24, 6)) AS UNIT_PRICE_FC
        FROM chit_inventory_output io
        LEFT JOIN chit_inventory_info h
            ON h.COMPANY_CD = io.COMPANY_CD AND h.INVENTORY_ID = io.INVENTORY_ID
           AND (io.CHIT_TYPE = h.CHIT_TYPE
                OR (io.CHIT_TYPE = 'IA' AND h.CHIT_TYPE IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER')))
        LEFT JOIN chitdetailinfo source_detail
            ON source_detail.COMPANY_CD = io.COMPANY_CD AND source_detail.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND source_detail.ISDEL = '0'
        LEFT JOIN chitdetailinfo posting
            ON posting.COMPANY_CD = io.COMPANY_CD AND posting.ISDEL = '0'
           AND posting.CHITDETAIL_ID = COALESCE(
                CASE WHEN io.CHIT_TYPE = 'IO' THEN COALESCE(
                    NULLIF(io.CHITDETAIL_ID_COGS, 0), NULLIF(h.CHITDETAIL_ID_COGS, 0),
                    (SELECT MIN(legacy.CHITDETAIL_ID)
                     FROM chitdetailinfo legacy
                     WHERE legacy.COMPANY_CD = io.COMPANY_CD AND legacy.CHIT_ID = h.CHIT_ID_COGS
                       AND legacy.SORT = 1 AND legacy.ISDEL = '0')
                ) END,
                io.CHITDETAIL_ID
           )
        LEFT JOIN chitinfo chit
            ON chit.COMPANY_CD = io.COMPANY_CD
           AND chit.CHIT_ID = COALESCE(source_detail.CHIT_ID, posting.CHIT_ID)
        WHERE io.COMPANY_CD = p_COMPANY_CD AND io.ISDEL = '0'
          AND (h.INVENTORY_ID IS NULL OR h.ISDEL = '0')
          AND (chit.CHIT_ID IS NULL OR chit.ISDEL = '0')
          AND (io.INVENTORY_YMD < DATE_ADD(p_TO_DATE, INTERVAL 1 DAY)
               OR (io.INVENTORY_YMD IS NULL AND h.INVENTORY_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')))
    ), catalog AS (
        SELECT m.FLOW_TYPE, m.LINE_ID, m.SORT, m.DOCUMENT_TYPE, m.DOCUMENT_DATE, m.DOCUMENT_NO,
            m.DESCRIPTION, m.ACCOUNT_CD, m.COUNTERPART_ACCOUNT, m.SOURCE_ID, m.SOURCE_TYPE,
            m.QUANTITY, m.AMOUNT, m.AMOUNT_FC, m.UNIT_PRICE, m.UNIT_PRICE_FC,
            COALESCE(NULLIF(m.PRODUCT_CD, ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN product.PRODUCT_NM_ENG WHEN 'KOR' THEN product.PRODUCT_NM_KOR
                WHEN 'CHN' THEN product.PRODUCT_NM_CHINA ELSE product.PRODUCT_NM_VIET END, ''),
                NULLIF(product.PRODUCT_NM_VIET, '')), NULLIF(m.PRODUCT_CD, ''), '') AS PRODUCT_NAME,
            COALESCE(NULLIF(m.STORE_CD, ''), store.STORE_CD, '') AS STORE_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN store.STORE_NM_ENG WHEN 'KOR' THEN store.STORE_NM_KOR
                WHEN 'CHN' THEN store.STORE_NM_CHINA ELSE store.STORE_NM_VIET END, ''),
                NULLIF(store.STORE_NM_VIET, '')), NULLIF(m.STORE_CD, ''), '') AS STORE_NAME,
            COALESCE(NULLIF(unit.UNIT_NM, ''), m.UNIT_CD, '') AS UNIT_NAME,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN account.ACCTITLE_NM_ENG WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
                WHEN 'CHN' THEN account.ACCTITLE_NM_CHINA ELSE account.ACCTITLE_NM_VIET END, ''),
                NULLIF(account.ACCTITLE_NM_VIET, '')), NULLIF(m.ACCOUNT_CD, ''), '') AS ACCOUNT_NAME
        FROM movement m
        LEFT JOIN product_info product
            ON product.COMPANY_CD = p_COMPANY_CD AND product.PRODUCT_ID = m.PRODUCT_ID AND product.ISDEL = '0'
        LEFT JOIN store_info store
            ON store.COMPANY_CD = p_COMPANY_CD AND store.STORE_ID = m.STORE_ID AND store.ISDEL = '0'
        LEFT JOIN product_unit unit
            ON unit.COMPANY_CD = p_COMPANY_CD AND unit.UNIT_ID = m.UNIT_ID AND unit.ISDEL = '0'
        LEFT JOIN acclist_info account
            ON account.COMPANY_CD = p_COMPANY_CD AND account.ACC_ID = (
                SELECT MAX(a.ACC_ID)
                FROM acclist_info a
                WHERE a.COMPANY_CD = p_COMPANY_CD AND a.ACC_CD = m.ACCOUNT_CD AND a.ISDEL = '0'
            )
        WHERE m.DOCUMENT_DATE <= p_TO_DATE
    ), filtered AS (
        SELECT catalog.*,
            UPPER(ACCOUNT_CD) AS DIMENSION_CD,
            UPPER(PRODUCT_CD) AS PRODUCT_GROUP,
            DOCUMENT_DATE >= p_FROM_DATE AS IN_PERIOD,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN QUANTITY ELSE -QUANTITY END AS NET_QTY,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT ELSE -AMOUNT END AS NET_AMOUNT,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT_FC ELSE -AMOUNT_FC END AS NET_FC
        FROM catalog
        WHERE (v_product_filter IN ('', 'all')
               OR EXISTS (SELECT 1 FROM product_filter f WHERE f.CODE = catalog.PRODUCT_CD))
          AND (v_dimension_filter IN ('', 'all')
               OR EXISTS (SELECT 1 FROM dimension_filter f WHERE f.CODE = catalog.ACCOUNT_CD))
    ), totals AS (
        SELECT DIMENSION_CD, PRODUCT_GROUP,
            CONCAT('PRODUCT-', SHA2(JSON_ARRAY(DIMENSION_CD, PRODUCT_GROUP), 256)) AS PRODUCT_KEY,
            CONCAT('DIMENSION-', SHA2(DIMENSION_CD, 256)) AS DIMENSION_KEY,
            MAX(ACCOUNT_NAME) AS DIMENSION_NAME,
            MAX(PRODUCT_NAME) AS PRODUCT_NAME,
            MAX(UNIT_NAME) AS UNIT_NAME,
            SUM(IF(IN_PERIOD, 0, NET_QTY)) AS OPEN_QTY,
            SUM(IF(IN_PERIOD, 0, NET_AMOUNT)) AS OPEN_AMOUNT,
            SUM(IF(IN_PERIOD, NULL, NET_FC)) AS OPEN_FC,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', QUANTITY, 0)) AS IN_QTY,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', AMOUNT, 0)) AS IN_AMOUNT,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', AMOUNT_FC, NULL)) AS IN_FC,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', QUANTITY, 0)) AS OUT_QTY,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', AMOUNT, 0)) AS OUT_AMOUNT,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', AMOUNT_FC, NULL)) AS OUT_FC,
            SUM(NET_QTY) AS END_QTY,
            SUM(NET_AMOUNT) AS END_AMOUNT,
            SUM(NET_FC) AS END_FC,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_QTY WHEN FLOW_TYPE = 'INPUT' THEN QUANTITY ELSE 0 END) AS MONTH_AVAILABLE_QTY,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_AMOUNT WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT ELSE 0 END) AS MONTH_AVAILABLE_AMOUNT,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_FC WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT_FC END) AS MONTH_AVAILABLE_FC,
            SUM(IF(AMOUNT_FC IS NOT NULL, IF(IN_PERIOD, IF(FLOW_TYPE = 'INPUT', QUANTITY, 0), NET_QTY), 0)) AS PERIOD_AVAILABLE_FC_QTY,
            SUM(IF(AMOUNT_FC IS NOT NULL, IF(DOCUMENT_DATE < v_month_start, NET_QTY, IF(FLOW_TYPE = 'INPUT', QUANTITY, 0)), 0)) AS MONTH_AVAILABLE_FC_QTY
        FROM filtered
        GROUP BY DIMENSION_CD, PRODUCT_GROUP
        HAVING COALESCE(p_HIDE_NO_MOVEMENT, 0) = 0 OR SUM(IN_PERIOD AND DOCUMENT_TYPE <> 'IRO') > 0
    ), details AS (
        SELECT f.*, t.PRODUCT_KEY,
            ROW_NUMBER() OVER ledger AS LINE_SORT,
            t.OPEN_QTY + SUM(NET_QTY) OVER ledger AS BALANCE_QTY,
            t.OPEN_AMOUNT + SUM(NET_AMOUNT) OVER ledger AS BALANCE_AMOUNT,
            CASE WHEN t.OPEN_FC IS NOT NULL OR SUM(NET_FC) OVER ledger IS NOT NULL
                THEN COALESCE(t.OPEN_FC, 0) + COALESCE(SUM(NET_FC) OVER ledger, 0) END AS BALANCE_FC
        FROM filtered f
        JOIN totals t USING (DIMENSION_CD, PRODUCT_GROUP)
        WHERE f.IN_PERIOD
        WINDOW ledger AS (PARTITION BY f.DIMENSION_CD, f.PRODUCT_GROUP
            ORDER BY f.DOCUMENT_DATE, f.DOCUMENT_NO, f.SORT, f.FLOW_TYPE, f.LINE_ID ROWS UNBOUNDED PRECEDING)
    ), summary_types AS (
        SELECT 'OPENING' AS ROW_TYPE, 1 AS ROW_SORT, CASE v_language WHEN 'ENG' THEN 'Opening balance' WHEN 'KOR' THEN '기초 잔액' WHEN 'CHN' THEN '期初余额' ELSE 'Chỉ tiêu đầu kỳ' END AS LABEL
        UNION ALL SELECT 'TOTAL', 3, CASE v_language WHEN 'ENG' THEN 'Period movement' WHEN 'KOR' THEN '기간 합계' WHEN 'CHN' THEN '本期发生额' ELSE 'Cộng phát sinh' END
        UNION ALL SELECT 'CLOSING', 4, CASE v_language WHEN 'ENG' THEN 'Closing balance' WHEN 'KOR' THEN '기말 재고' WHEN 'CHN' THEN '期末库存' ELSE 'Hàng tồn kho' END
        UNION ALL SELECT 'PERIOD_AVERAGE', 5, CASE v_language WHEN 'ENG' THEN 'Period average cost' WHEN 'KOR' THEN '기간 평균 단가' WHEN 'CHN' THEN '本期平均单价' ELSE 'Giá trung bình của kỳ này' END
        UNION ALL SELECT 'MONTH_AVERAGE', 6, CASE v_language WHEN 'ENG' THEN 'Month average cost' WHEN 'KOR' THEN '월 평균 단가' WHEN 'CHN' THEN '本月平均单价' ELSE 'Giá trung bình của tháng này' END
    ), report_rows AS (
        SELECT DISTINCT t.DIMENSION_KEY AS ROW_KEY, NULL AS PARENT_KEY, 'GROUP' AS ROW_TYPE, 0 AS ROW_LEVEL,
            t.DIMENSION_CD, '' AS PRODUCT_GROUP, 0 AS SECTION_SORT, 0 AS LINE_SORT,
            CONCAT('Tài khoản: ', t.DIMENSION_CD, IF(t.DIMENSION_CD = '', '', ' '), COALESCE(NULLIF(MAX(t.DIMENSION_NAME) OVER (PARTITION BY t.DIMENSION_CD), ''), '—')) AS DESCRIPTION,
            NULL AS DOCUMENT_NO, NULL AS DOCUMENT_DATE, NULL AS PRODUCT_CD, NULL AS PRODUCT_NAME,
            NULL AS STORE_CD, NULL AS STORE_NAME, NULL AS UNIT_NAME, NULL AS ACCOUNT_CD, NULL AS ACCOUNT_NAME,
            NULL AS COUNTERPART_ACCOUNT, NULL AS UNIT_PRICE, NULL AS UNIT_PRICE_FC,
            NULL AS OPENING_QUANTITY, NULL AS OPENING_AMOUNT, NULL AS OPENING_AMOUNT_FC,
            NULL AS INPUT_QUANTITY, NULL AS INPUT_AMOUNT, NULL AS INPUT_AMOUNT_FC,
            NULL AS OUTPUT_QUANTITY, NULL AS OUTPUT_AMOUNT, NULL AS OUTPUT_AMOUNT_FC,
            NULL AS BALANCE_QUANTITY, NULL AS BALANCE_AMOUNT, NULL AS BALANCE_AMOUNT_FC,
            NULL AS AVERAGE_PRICE, NULL AS AVERAGE_PRICE_FC, NULL AS SOURCE_ID, NULL AS SOURCE_TYPE
        FROM totals t
        UNION ALL
        SELECT t.PRODUCT_KEY AS ROW_KEY, t.DIMENSION_KEY AS PARENT_KEY, 'GROUP' AS ROW_TYPE, 1 AS ROW_LEVEL,
            t.DIMENSION_CD, t.PRODUCT_GROUP, 0 AS SECTION_SORT, 0 AS LINE_SORT,
            CONCAT(t.PRODUCT_GROUP, IF(t.PRODUCT_NAME = t.PRODUCT_GROUP, '', CONCAT(' — ', t.PRODUCT_NAME))) AS DESCRIPTION,
            NULL AS DOCUMENT_NO, NULL AS DOCUMENT_DATE, t.PRODUCT_GROUP AS PRODUCT_CD, t.PRODUCT_NAME,
            NULL AS STORE_CD, NULL AS STORE_NAME, t.UNIT_NAME, NULL AS ACCOUNT_CD, NULL AS ACCOUNT_NAME,
            NULL AS COUNTERPART_ACCOUNT, NULL AS UNIT_PRICE, NULL AS UNIT_PRICE_FC,
            NULL AS OPENING_QUANTITY, NULL AS OPENING_AMOUNT, NULL AS OPENING_AMOUNT_FC,
            NULL AS INPUT_QUANTITY, NULL AS INPUT_AMOUNT, NULL AS INPUT_AMOUNT_FC,
            NULL AS OUTPUT_QUANTITY, NULL AS OUTPUT_AMOUNT, NULL AS OUTPUT_AMOUNT_FC,
            NULL AS BALANCE_QUANTITY, NULL AS BALANCE_AMOUNT, NULL AS BALANCE_AMOUNT_FC,
            NULL AS AVERAGE_PRICE, NULL AS AVERAGE_PRICE_FC, NULL AS SOURCE_ID, NULL AS SOURCE_TYPE
        FROM totals t
        UNION ALL
        SELECT CONCAT(f.FLOW_TYPE, '-', f.LINE_ID), f.PRODUCT_KEY, f.FLOW_TYPE, 2,
            f.DIMENSION_CD, f.PRODUCT_GROUP, 2, f.LINE_SORT, f.DESCRIPTION,
            f.DOCUMENT_NO, f.DOCUMENT_DATE, f.PRODUCT_CD, f.PRODUCT_NAME,
            f.STORE_CD, f.STORE_NAME, f.UNIT_NAME, f.ACCOUNT_CD, f.ACCOUNT_NAME,
            f.COUNTERPART_ACCOUNT, f.UNIT_PRICE, f.UNIT_PRICE_FC,
            NULL, NULL, NULL,
            IF(f.FLOW_TYPE = 'INPUT', f.QUANTITY, NULL), IF(f.FLOW_TYPE = 'INPUT', f.AMOUNT, NULL), IF(f.FLOW_TYPE = 'INPUT', f.AMOUNT_FC, NULL),
            IF(f.FLOW_TYPE = 'OUTPUT', f.QUANTITY, NULL), IF(f.FLOW_TYPE = 'OUTPUT', f.AMOUNT, NULL), IF(f.FLOW_TYPE = 'OUTPUT', f.AMOUNT_FC, NULL),
            f.BALANCE_QTY, f.BALANCE_AMOUNT, f.BALANCE_FC, NULL, NULL, f.SOURCE_ID, f.SOURCE_TYPE
        FROM details f
        UNION ALL
        SELECT CONCAT(t.PRODUCT_KEY, '-', s.ROW_TYPE), t.PRODUCT_KEY, s.ROW_TYPE, 2,
            t.DIMENSION_CD, t.PRODUCT_GROUP, s.ROW_SORT, 0, s.LABEL,
            NULL, NULL, t.PRODUCT_GROUP, t.PRODUCT_NAME, NULL, NULL, t.UNIT_NAME, NULL, NULL,
            NULL, NULL, NULL,
            IF(s.ROW_TYPE = 'OPENING', t.OPEN_QTY, NULL), IF(s.ROW_TYPE = 'OPENING', t.OPEN_AMOUNT, NULL), IF(s.ROW_TYPE = 'OPENING', t.OPEN_FC, NULL),
            IF(s.ROW_TYPE = 'TOTAL', t.IN_QTY, NULL), IF(s.ROW_TYPE = 'TOTAL', t.IN_AMOUNT, NULL), IF(s.ROW_TYPE = 'TOTAL', t.IN_FC, NULL),
            IF(s.ROW_TYPE = 'TOTAL', t.OUT_QTY, NULL), IF(s.ROW_TYPE = 'TOTAL', t.OUT_AMOUNT, NULL), IF(s.ROW_TYPE = 'TOTAL', t.OUT_FC, NULL),
            IF(s.ROW_TYPE = 'CLOSING', t.END_QTY, NULL), IF(s.ROW_TYPE = 'CLOSING', t.END_AMOUNT, NULL), IF(s.ROW_TYPE = 'CLOSING', t.END_FC, NULL),
            CASE s.ROW_TYPE WHEN 'PERIOD_AVERAGE' THEN (t.OPEN_AMOUNT + t.IN_AMOUNT) / NULLIF(t.OPEN_QTY + t.IN_QTY, 0)
                WHEN 'MONTH_AVERAGE' THEN t.MONTH_AVAILABLE_AMOUNT / NULLIF(t.MONTH_AVAILABLE_QTY, 0) END,
            CASE s.ROW_TYPE WHEN 'PERIOD_AVERAGE' THEN
                CASE WHEN t.OPEN_FC IS NOT NULL OR t.IN_FC IS NOT NULL
                    THEN (COALESCE(t.OPEN_FC, 0) + COALESCE(t.IN_FC, 0)) / NULLIF(t.PERIOD_AVAILABLE_FC_QTY, 0) END
                WHEN 'MONTH_AVERAGE' THEN t.MONTH_AVAILABLE_FC / NULLIF(t.MONTH_AVAILABLE_FC_QTY, 0) END,
            NULL, NULL
        FROM totals t CROSS JOIN summary_types s
    )
    SELECT ROW_KEY AS __ROW_KEY, PARENT_KEY AS __PARENT_ROW_KEY, ROW_TYPE AS __ROW_TYPE,
        ROW_LEVEL AS __ROW_LEVEL,
        ROW_NUMBER() OVER (ORDER BY DIMENSION_CD, PRODUCT_GROUP, SECTION_SORT, LINE_SORT, ROW_KEY) AS __ROW_SORT,
        p_COMPANY_CD AS __COMPANY_CD, SOURCE_ID AS __CHIT_ID, SOURCE_TYPE AS __CHIT_TYPE,
        DESCRIPTION, DOCUMENT_NO, DOCUMENT_DATE, DOCUMENT_DATE AS ENTRY_DATE,
        PRODUCT_CD, PRODUCT_NAME, UNIT_NAME, STORE_CD, STORE_NAME, ACCOUNT_CD, ACCOUNT_NAME, COUNTERPART_ACCOUNT,
        UNIT_PRICE, UNIT_PRICE_FC, OPENING_QUANTITY, OPENING_AMOUNT, OPENING_AMOUNT_FC,
        INPUT_QUANTITY, INPUT_AMOUNT, INPUT_AMOUNT_FC, OUTPUT_QUANTITY, OUTPUT_AMOUNT, OUTPUT_AMOUNT_FC,
        BALANCE_QUANTITY, BALANCE_AMOUNT, BALANCE_AMOUNT_FC, AVERAGE_PRICE, AVERAGE_PRICE_FC
    FROM report_rows
    ORDER BY __ROW_SORT;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rpt_inventory_detail_department
DROP PROCEDURE IF EXISTS `rpt_inventory_detail_department`;
DELIMITER //
CREATE PROCEDURE `rpt_inventory_detail_department`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_PRODUCT_CD TEXT,
    IN p_DEPARTMENT_CD TEXT,
    IN p_FC_TYPE VARCHAR(10),
    IN p_HIDE_NO_MOVEMENT TINYINT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_language VARCHAR(20) DEFAULT UPPER(COALESCE(p_LANGUAGE, 'VIET'));
    DECLARE v_fc_type VARCHAR(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
    DECLARE v_month_start DATE;
    DECLARE v_product_filter TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
    DECLARE v_dimension_filter TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL OR p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid inventory report date range';
    END IF;

    SET v_fc_type = UPPER(TRIM(COALESCE(p_FC_TYPE, '')));
    SET v_month_start = DATE_SUB(p_TO_DATE, INTERVAL (DAYOFMONTH(p_TO_DATE) - 1) DAY);
    SET v_product_filter = TRIM(COALESCE(p_PRODUCT_CD, ''));
    SET v_dimension_filter = TRIM(COALESCE(p_DEPARTMENT_CD, ''));

    WITH product_filter AS (
        SELECT TRIM(CODE) AS CODE
        FROM JSON_TABLE(REPLACE(JSON_ARRAY(v_product_filter), ',', '","'),
            '$[*]' COLUMNS (CODE VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH '$')) tokens
    ), dimension_filter AS (
        SELECT TRIM(CODE) AS CODE
        FROM JSON_TABLE(REPLACE(JSON_ARRAY(v_dimension_filter), ',', '","'),
            '$[*]' COLUMNS (CODE VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH '$')) tokens
    ), movement AS (
        SELECT
            'INPUT' AS FLOW_TYPE,
            ii.INPUT_ID AS LINE_ID,
            ii.PRODUCT_ID, ii.PRODUCT_CD, ii.STORE_ID, ii.STORE_CD,
            ii.UNIT_ID, ii.UNIT_CD, ii.SORT,
            COALESCE(NULLIF(ii.CHIT_TYPE, ''), h.CHIT_TYPE, '') AS DOCUMENT_TYPE,
            COALESCE(DATE(ii.INVENTORY_YMD), STR_TO_DATE(NULLIF(h.INVENTORY_YMD, ''), '%Y%m%d')) AS DOCUMENT_DATE,
            COALESCE(NULLIF(h.INVENTORY_NO, ''), NULLIF(chit.CHIT_NO, ''), ii.INVENTORY_CD, '') AS DOCUMENT_NO,
            COALESCE(NULLIF(ii.SUMMARY, ''), h.REMARK, '') AS DESCRIPTION,
            COALESCE(posting.DEBIT, '') AS ACCOUNT_CD,
            COALESCE(posting.CREDIT, '') AS COUNTERPART_ACCOUNT,
            COALESCE(h.INVENTORY_ID, chit.CHIT_ID) AS SOURCE_ID,
            COALESCE(h.CHIT_TYPE, chit.CHIT_TYPE) AS SOURCE_TYPE,
            COALESCE(source_detail.CHITDETAIL_ID, posting.CHITDETAIL_ID) AS DEPARTMENT_DETAIL_ID,
            CAST(ii.QUANTITY AS DECIMAL(24, 6)) AS QUANTITY,
            CAST(COALESCE(NULLIF(ii.AMOUNT_CC, 0), ii.QUANTITY * ii.UNIT_PRICE_CC) AS DECIMAL(24, 6)) AS AMOUNT,
            CAST(CASE WHEN ii.FC_TYPE = v_fc_type THEN ii.AMOUNT_FC END AS DECIMAL(24, 6)) AS AMOUNT_FC,
            CAST(ii.UNIT_PRICE_CC AS DECIMAL(24, 6)) AS UNIT_PRICE,
            CAST(CASE WHEN ii.FC_TYPE = v_fc_type THEN ii.UNIT_PRICE_FC END AS DECIMAL(24, 6)) AS UNIT_PRICE_FC
        FROM chit_inventory_input ii
        LEFT JOIN chit_inventory_info h
            ON h.COMPANY_CD = ii.COMPANY_CD AND h.INVENTORY_ID = ii.INVENTORY_ID
           AND (ii.CHIT_TYPE = h.CHIT_TYPE
                OR (ii.CHIT_TYPE = 'IA' AND h.CHIT_TYPE IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER')))
        LEFT JOIN chitdetailinfo posting
            ON posting.COMPANY_CD = ii.COMPANY_CD AND posting.ISDEL = '0'
           AND posting.CHITDETAIL_ID = ii.CHITDETAIL_ID
        LEFT JOIN chitinfo chit
            ON chit.COMPANY_CD = ii.COMPANY_CD
           AND chit.CHIT_ID = posting.CHIT_ID
        WHERE ii.COMPANY_CD = p_COMPANY_CD AND ii.ISDEL = '0'
          AND (h.INVENTORY_ID IS NULL OR h.ISDEL = '0')
          AND (chit.CHIT_ID IS NULL OR chit.ISDEL = '0')
          AND (ii.INVENTORY_YMD < DATE_ADD(p_TO_DATE, INTERVAL 1 DAY)
               OR (ii.INVENTORY_YMD IS NULL AND h.INVENTORY_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')))
        UNION ALL
        SELECT
            'OUTPUT' AS FLOW_TYPE,
            io.OUTPUT_ID AS LINE_ID,
            io.PRODUCT_ID, io.PRODUCT_CD, io.STORE_ID, io.STORE_CD,
            io.UNIT_ID, io.UNIT_CD, io.SORT,
            COALESCE(NULLIF(io.CHIT_TYPE, ''), h.CHIT_TYPE, '') AS DOCUMENT_TYPE,
            COALESCE(DATE(io.INVENTORY_YMD), STR_TO_DATE(NULLIF(h.INVENTORY_YMD, ''), '%Y%m%d')) AS DOCUMENT_DATE,
            COALESCE(NULLIF(h.INVENTORY_NO, ''), NULLIF(chit.CHIT_NO, ''), io.INVENTORY_CD, '') AS DOCUMENT_NO,
            COALESCE(NULLIF(io.SUMMARY, ''), h.REMARK, '') AS DESCRIPTION,
            COALESCE(posting.CREDIT, '') AS ACCOUNT_CD,
            COALESCE(posting.DEBIT, '') AS COUNTERPART_ACCOUNT,
            COALESCE(h.INVENTORY_ID, chit.CHIT_ID) AS SOURCE_ID,
            COALESCE(h.CHIT_TYPE, chit.CHIT_TYPE) AS SOURCE_TYPE,
            COALESCE(source_detail.CHITDETAIL_ID, posting.CHITDETAIL_ID) AS DEPARTMENT_DETAIL_ID,
            CAST(io.QUANTITY AS DECIMAL(24, 6)) AS QUANTITY,
            CAST(CASE WHEN io.CHIT_TYPE = 'IO' THEN io.AMOUNT_CC
                      ELSE COALESCE(NULLIF(io.AMOUNT_CC, 0), io.QUANTITY * io.UNIT_PRICE_CC) END AS DECIMAL(24, 6)) AS AMOUNT,
            CAST(CASE WHEN io.FC_TYPE = v_fc_type THEN io.AMOUNT_FC END AS DECIMAL(24, 6)) AS AMOUNT_FC,
            CAST(io.UNIT_PRICE_CC AS DECIMAL(24, 6)) AS UNIT_PRICE,
            CAST(CASE WHEN io.FC_TYPE = v_fc_type THEN io.UNIT_PRICE_FC END AS DECIMAL(24, 6)) AS UNIT_PRICE_FC
        FROM chit_inventory_output io
        LEFT JOIN chit_inventory_info h
            ON h.COMPANY_CD = io.COMPANY_CD AND h.INVENTORY_ID = io.INVENTORY_ID
           AND (io.CHIT_TYPE = h.CHIT_TYPE
                OR (io.CHIT_TYPE = 'IA' AND h.CHIT_TYPE IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER')))
        LEFT JOIN chitdetailinfo source_detail
            ON source_detail.COMPANY_CD = io.COMPANY_CD AND source_detail.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND source_detail.ISDEL = '0'
        LEFT JOIN chitdetailinfo posting
            ON posting.COMPANY_CD = io.COMPANY_CD AND posting.ISDEL = '0'
           AND posting.CHITDETAIL_ID = COALESCE(
                CASE WHEN io.CHIT_TYPE = 'IO' THEN COALESCE(
                    NULLIF(io.CHITDETAIL_ID_COGS, 0), NULLIF(h.CHITDETAIL_ID_COGS, 0),
                    (SELECT MIN(legacy.CHITDETAIL_ID)
                     FROM chitdetailinfo legacy
                     WHERE legacy.COMPANY_CD = io.COMPANY_CD AND legacy.CHIT_ID = h.CHIT_ID_COGS
                       AND legacy.SORT = 1 AND legacy.ISDEL = '0')
                ) END,
                io.CHITDETAIL_ID
           )
        LEFT JOIN chitinfo chit
            ON chit.COMPANY_CD = io.COMPANY_CD
           AND chit.CHIT_ID = COALESCE(source_detail.CHIT_ID, posting.CHIT_ID)
        WHERE io.COMPANY_CD = p_COMPANY_CD AND io.ISDEL = '0'
          AND (h.INVENTORY_ID IS NULL OR h.ISDEL = '0')
          AND (chit.CHIT_ID IS NULL OR chit.ISDEL = '0')
          AND (io.INVENTORY_YMD < DATE_ADD(p_TO_DATE, INTERVAL 1 DAY)
               OR (io.INVENTORY_YMD IS NULL AND h.INVENTORY_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')))
    ), catalog AS (
        SELECT m.FLOW_TYPE, m.LINE_ID, m.SORT, m.DOCUMENT_TYPE, m.DOCUMENT_DATE, m.DOCUMENT_NO,
            m.DESCRIPTION, m.ACCOUNT_CD, m.COUNTERPART_ACCOUNT, m.SOURCE_ID, m.SOURCE_TYPE,
            m.QUANTITY, m.AMOUNT, m.AMOUNT_FC, m.UNIT_PRICE, m.UNIT_PRICE_FC,
            COALESCE(NULLIF(m.PRODUCT_CD, ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN product.PRODUCT_NM_ENG WHEN 'KOR' THEN product.PRODUCT_NM_KOR
                WHEN 'CHN' THEN product.PRODUCT_NM_CHINA ELSE product.PRODUCT_NM_VIET END, ''),
                NULLIF(product.PRODUCT_NM_VIET, '')), NULLIF(m.PRODUCT_CD, ''), '') AS PRODUCT_NAME,
            COALESCE(NULLIF(m.STORE_CD, ''), store.STORE_CD, '') AS STORE_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN store.STORE_NM_ENG WHEN 'KOR' THEN store.STORE_NM_KOR
                WHEN 'CHN' THEN store.STORE_NM_CHINA ELSE store.STORE_NM_VIET END, ''),
                NULLIF(store.STORE_NM_VIET, '')), NULLIF(m.STORE_CD, ''), '') AS STORE_NAME,
            COALESCE(NULLIF(unit.UNIT_NM, ''), m.UNIT_CD, '') AS UNIT_NAME,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN account.ACCTITLE_NM_ENG WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
                WHEN 'CHN' THEN account.ACCTITLE_NM_CHINA ELSE account.ACCTITLE_NM_VIET END, ''),
                NULLIF(account.ACCTITLE_NM_VIET, '')), NULLIF(m.ACCOUNT_CD, ''), '') AS ACCOUNT_NAME,
            COALESCE(NULLIF(ext.DEPARTMENT_CD, ''), department.DEPARTMENT_CD, '') AS DEPARTMENT_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN department.DEP_NAME_ENG WHEN 'KOR' THEN department.DEP_NAME_KOR
                WHEN 'CHN' THEN department.DEP_NAME_CHINA ELSE department.DEP_NAME_VIET END, ''),
                NULLIF(department.DEP_NAME_VIET, '')), NULLIF(ext.DEPARTMENT_CD, ''), '') AS DEPARTMENT_NAME
        FROM movement m
        LEFT JOIN product_info product
            ON product.COMPANY_CD = p_COMPANY_CD AND product.PRODUCT_ID = m.PRODUCT_ID AND product.ISDEL = '0'
        LEFT JOIN store_info store
            ON store.COMPANY_CD = p_COMPANY_CD AND store.STORE_ID = m.STORE_ID AND store.ISDEL = '0'
        LEFT JOIN product_unit unit
            ON unit.COMPANY_CD = p_COMPANY_CD AND unit.UNIT_ID = m.UNIT_ID AND unit.ISDEL = '0'
        LEFT JOIN acclist_info account
            ON account.COMPANY_CD = p_COMPANY_CD AND account.ACC_ID = (
                SELECT MAX(a.ACC_ID)
                FROM acclist_info a
                WHERE a.COMPANY_CD = p_COMPANY_CD AND a.ACC_CD = m.ACCOUNT_CD AND a.ISDEL = '0'
            )
        LEFT JOIN chitdetailinfo_ext ext
            ON ext.COMPANY_CD = p_COMPANY_CD AND ext.CHITDETAIL_ID = m.DEPARTMENT_DETAIL_ID AND ext.ISDEL = '0'
        LEFT JOIN department_info department
            ON department.COMPANY_CD = p_COMPANY_CD AND department.DEPARTMENT_ID = ext.DEPARTMENT_ID
           AND COALESCE(department.ISDEL, '0') = '0'
        WHERE m.DOCUMENT_DATE <= p_TO_DATE
    ), filtered AS (
        SELECT catalog.*,
            UPPER(DEPARTMENT_CD) AS DIMENSION_CD,
            UPPER(PRODUCT_CD) AS PRODUCT_GROUP,
            DOCUMENT_DATE >= p_FROM_DATE AS IN_PERIOD,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN QUANTITY ELSE -QUANTITY END AS NET_QTY,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT ELSE -AMOUNT END AS NET_AMOUNT,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT_FC ELSE -AMOUNT_FC END AS NET_FC
        FROM catalog
        WHERE (v_product_filter IN ('', 'all')
               OR EXISTS (SELECT 1 FROM product_filter f WHERE f.CODE = catalog.PRODUCT_CD))
          AND (v_dimension_filter IN ('', 'all')
               OR EXISTS (SELECT 1 FROM dimension_filter f WHERE f.CODE = catalog.DEPARTMENT_CD))
    ), totals AS (
        SELECT DIMENSION_CD, PRODUCT_GROUP,
            CONCAT('PRODUCT-', SHA2(JSON_ARRAY(DIMENSION_CD, PRODUCT_GROUP), 256)) AS PRODUCT_KEY,
            CONCAT('DIMENSION-', SHA2(DIMENSION_CD, 256)) AS DIMENSION_KEY,
            MAX(DEPARTMENT_NAME) AS DIMENSION_NAME,
            MAX(PRODUCT_NAME) AS PRODUCT_NAME,
            MAX(UNIT_NAME) AS UNIT_NAME,
            SUM(IF(IN_PERIOD, 0, NET_QTY)) AS OPEN_QTY,
            SUM(IF(IN_PERIOD, 0, NET_AMOUNT)) AS OPEN_AMOUNT,
            SUM(IF(IN_PERIOD, NULL, NET_FC)) AS OPEN_FC,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', QUANTITY, 0)) AS IN_QTY,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', AMOUNT, 0)) AS IN_AMOUNT,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', AMOUNT_FC, NULL)) AS IN_FC,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', QUANTITY, 0)) AS OUT_QTY,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', AMOUNT, 0)) AS OUT_AMOUNT,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', AMOUNT_FC, NULL)) AS OUT_FC,
            SUM(NET_QTY) AS END_QTY,
            SUM(NET_AMOUNT) AS END_AMOUNT,
            SUM(NET_FC) AS END_FC,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_QTY WHEN FLOW_TYPE = 'INPUT' THEN QUANTITY ELSE 0 END) AS MONTH_AVAILABLE_QTY,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_AMOUNT WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT ELSE 0 END) AS MONTH_AVAILABLE_AMOUNT,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_FC WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT_FC END) AS MONTH_AVAILABLE_FC,
            SUM(IF(AMOUNT_FC IS NOT NULL, IF(IN_PERIOD, IF(FLOW_TYPE = 'INPUT', QUANTITY, 0), NET_QTY), 0)) AS PERIOD_AVAILABLE_FC_QTY,
            SUM(IF(AMOUNT_FC IS NOT NULL, IF(DOCUMENT_DATE < v_month_start, NET_QTY, IF(FLOW_TYPE = 'INPUT', QUANTITY, 0)), 0)) AS MONTH_AVAILABLE_FC_QTY
        FROM filtered
        GROUP BY DIMENSION_CD, PRODUCT_GROUP
        HAVING COALESCE(p_HIDE_NO_MOVEMENT, 0) = 0 OR SUM(IN_PERIOD AND DOCUMENT_TYPE <> 'IRO') > 0
    ), details AS (
        SELECT f.*, t.PRODUCT_KEY,
            ROW_NUMBER() OVER ledger AS LINE_SORT,
            t.OPEN_QTY + SUM(NET_QTY) OVER ledger AS BALANCE_QTY,
            t.OPEN_AMOUNT + SUM(NET_AMOUNT) OVER ledger AS BALANCE_AMOUNT,
            CASE WHEN t.OPEN_FC IS NOT NULL OR SUM(NET_FC) OVER ledger IS NOT NULL
                THEN COALESCE(t.OPEN_FC, 0) + COALESCE(SUM(NET_FC) OVER ledger, 0) END AS BALANCE_FC
        FROM filtered f
        JOIN totals t USING (DIMENSION_CD, PRODUCT_GROUP)
        WHERE f.IN_PERIOD
        WINDOW ledger AS (PARTITION BY f.DIMENSION_CD, f.PRODUCT_GROUP
            ORDER BY f.DOCUMENT_DATE, f.DOCUMENT_NO, f.SORT, f.FLOW_TYPE, f.LINE_ID ROWS UNBOUNDED PRECEDING)
    ), summary_types AS (
        SELECT 'OPENING' AS ROW_TYPE, 1 AS ROW_SORT, CASE v_language WHEN 'ENG' THEN 'Opening balance' WHEN 'KOR' THEN '기초 잔액' WHEN 'CHN' THEN '期初余额' ELSE 'Chỉ tiêu đầu kỳ' END AS LABEL
        UNION ALL SELECT 'TOTAL', 3, CASE v_language WHEN 'ENG' THEN 'Period movement' WHEN 'KOR' THEN '기간 합계' WHEN 'CHN' THEN '本期发生额' ELSE 'Cộng phát sinh' END
        UNION ALL SELECT 'CLOSING', 4, CASE v_language WHEN 'ENG' THEN 'Closing balance' WHEN 'KOR' THEN '기말 재고' WHEN 'CHN' THEN '期末库存' ELSE 'Hàng tồn kho' END
        UNION ALL SELECT 'PERIOD_AVERAGE', 5, CASE v_language WHEN 'ENG' THEN 'Period average cost' WHEN 'KOR' THEN '기간 평균 단가' WHEN 'CHN' THEN '本期平均单价' ELSE 'Giá trung bình của kỳ này' END
        UNION ALL SELECT 'MONTH_AVERAGE', 6, CASE v_language WHEN 'ENG' THEN 'Month average cost' WHEN 'KOR' THEN '월 평균 단가' WHEN 'CHN' THEN '本月平均单价' ELSE 'Giá trung bình của tháng này' END
    ), report_rows AS (
        SELECT DISTINCT t.DIMENSION_KEY AS ROW_KEY, NULL AS PARENT_KEY, 'GROUP' AS ROW_TYPE, 0 AS ROW_LEVEL,
            t.DIMENSION_CD, '' AS PRODUCT_GROUP, 0 AS SECTION_SORT, 0 AS LINE_SORT,
            CONCAT('Đối tượng tập hợp chi phí: ', t.DIMENSION_CD, IF(t.DIMENSION_CD = '', '', ' '), COALESCE(NULLIF(MAX(t.DIMENSION_NAME) OVER (PARTITION BY t.DIMENSION_CD), ''), '—')) AS DESCRIPTION,
            NULL AS DOCUMENT_NO, NULL AS DOCUMENT_DATE, NULL AS PRODUCT_CD, NULL AS PRODUCT_NAME,
            NULL AS STORE_CD, NULL AS STORE_NAME, NULL AS UNIT_NAME, NULL AS ACCOUNT_CD, NULL AS ACCOUNT_NAME,
            NULL AS COUNTERPART_ACCOUNT, NULL AS UNIT_PRICE, NULL AS UNIT_PRICE_FC,
            NULL AS OPENING_QUANTITY, NULL AS OPENING_AMOUNT, NULL AS OPENING_AMOUNT_FC,
            NULL AS INPUT_QUANTITY, NULL AS INPUT_AMOUNT, NULL AS INPUT_AMOUNT_FC,
            NULL AS OUTPUT_QUANTITY, NULL AS OUTPUT_AMOUNT, NULL AS OUTPUT_AMOUNT_FC,
            NULL AS BALANCE_QUANTITY, NULL AS BALANCE_AMOUNT, NULL AS BALANCE_AMOUNT_FC,
            NULL AS AVERAGE_PRICE, NULL AS AVERAGE_PRICE_FC, NULL AS SOURCE_ID, NULL AS SOURCE_TYPE
        FROM totals t
        UNION ALL
        SELECT t.PRODUCT_KEY AS ROW_KEY, t.DIMENSION_KEY AS PARENT_KEY, 'GROUP' AS ROW_TYPE, 1 AS ROW_LEVEL,
            t.DIMENSION_CD, t.PRODUCT_GROUP, 0 AS SECTION_SORT, 0 AS LINE_SORT,
            CONCAT(t.PRODUCT_GROUP, IF(t.PRODUCT_NAME = t.PRODUCT_GROUP, '', CONCAT(' — ', t.PRODUCT_NAME))) AS DESCRIPTION,
            NULL AS DOCUMENT_NO, NULL AS DOCUMENT_DATE, t.PRODUCT_GROUP AS PRODUCT_CD, t.PRODUCT_NAME,
            NULL AS STORE_CD, NULL AS STORE_NAME, t.UNIT_NAME, NULL AS ACCOUNT_CD, NULL AS ACCOUNT_NAME,
            NULL AS COUNTERPART_ACCOUNT, NULL AS UNIT_PRICE, NULL AS UNIT_PRICE_FC,
            NULL AS OPENING_QUANTITY, NULL AS OPENING_AMOUNT, NULL AS OPENING_AMOUNT_FC,
            NULL AS INPUT_QUANTITY, NULL AS INPUT_AMOUNT, NULL AS INPUT_AMOUNT_FC,
            NULL AS OUTPUT_QUANTITY, NULL AS OUTPUT_AMOUNT, NULL AS OUTPUT_AMOUNT_FC,
            NULL AS BALANCE_QUANTITY, NULL AS BALANCE_AMOUNT, NULL AS BALANCE_AMOUNT_FC,
            NULL AS AVERAGE_PRICE, NULL AS AVERAGE_PRICE_FC, NULL AS SOURCE_ID, NULL AS SOURCE_TYPE
        FROM totals t
        UNION ALL
        SELECT CONCAT(f.FLOW_TYPE, '-', f.LINE_ID), f.PRODUCT_KEY, f.FLOW_TYPE, 2,
            f.DIMENSION_CD, f.PRODUCT_GROUP, 2, f.LINE_SORT, f.DESCRIPTION,
            f.DOCUMENT_NO, f.DOCUMENT_DATE, f.PRODUCT_CD, f.PRODUCT_NAME,
            f.STORE_CD, f.STORE_NAME, f.UNIT_NAME, f.ACCOUNT_CD, f.ACCOUNT_NAME,
            f.COUNTERPART_ACCOUNT, f.UNIT_PRICE, f.UNIT_PRICE_FC,
            NULL, NULL, NULL,
            IF(f.FLOW_TYPE = 'INPUT', f.QUANTITY, NULL), IF(f.FLOW_TYPE = 'INPUT', f.AMOUNT, NULL), IF(f.FLOW_TYPE = 'INPUT', f.AMOUNT_FC, NULL),
            IF(f.FLOW_TYPE = 'OUTPUT', f.QUANTITY, NULL), IF(f.FLOW_TYPE = 'OUTPUT', f.AMOUNT, NULL), IF(f.FLOW_TYPE = 'OUTPUT', f.AMOUNT_FC, NULL),
            f.BALANCE_QTY, f.BALANCE_AMOUNT, f.BALANCE_FC, NULL, NULL, f.SOURCE_ID, f.SOURCE_TYPE
        FROM details f
        UNION ALL
        SELECT CONCAT(t.PRODUCT_KEY, '-', s.ROW_TYPE), t.PRODUCT_KEY, s.ROW_TYPE, 2,
            t.DIMENSION_CD, t.PRODUCT_GROUP, s.ROW_SORT, 0, s.LABEL,
            NULL, NULL, t.PRODUCT_GROUP, t.PRODUCT_NAME, NULL, NULL, t.UNIT_NAME, NULL, NULL,
            NULL, NULL, NULL,
            IF(s.ROW_TYPE = 'OPENING', t.OPEN_QTY, NULL), IF(s.ROW_TYPE = 'OPENING', t.OPEN_AMOUNT, NULL), IF(s.ROW_TYPE = 'OPENING', t.OPEN_FC, NULL),
            IF(s.ROW_TYPE = 'TOTAL', t.IN_QTY, NULL), IF(s.ROW_TYPE = 'TOTAL', t.IN_AMOUNT, NULL), IF(s.ROW_TYPE = 'TOTAL', t.IN_FC, NULL),
            IF(s.ROW_TYPE = 'TOTAL', t.OUT_QTY, NULL), IF(s.ROW_TYPE = 'TOTAL', t.OUT_AMOUNT, NULL), IF(s.ROW_TYPE = 'TOTAL', t.OUT_FC, NULL),
            IF(s.ROW_TYPE = 'CLOSING', t.END_QTY, NULL), IF(s.ROW_TYPE = 'CLOSING', t.END_AMOUNT, NULL), IF(s.ROW_TYPE = 'CLOSING', t.END_FC, NULL),
            CASE s.ROW_TYPE WHEN 'PERIOD_AVERAGE' THEN (t.OPEN_AMOUNT + t.IN_AMOUNT) / NULLIF(t.OPEN_QTY + t.IN_QTY, 0)
                WHEN 'MONTH_AVERAGE' THEN t.MONTH_AVAILABLE_AMOUNT / NULLIF(t.MONTH_AVAILABLE_QTY, 0) END,
            CASE s.ROW_TYPE WHEN 'PERIOD_AVERAGE' THEN
                CASE WHEN t.OPEN_FC IS NOT NULL OR t.IN_FC IS NOT NULL
                    THEN (COALESCE(t.OPEN_FC, 0) + COALESCE(t.IN_FC, 0)) / NULLIF(t.PERIOD_AVAILABLE_FC_QTY, 0) END
                WHEN 'MONTH_AVERAGE' THEN t.MONTH_AVAILABLE_FC / NULLIF(t.MONTH_AVAILABLE_FC_QTY, 0) END,
            NULL, NULL
        FROM totals t CROSS JOIN summary_types s
    )
    SELECT ROW_KEY AS __ROW_KEY, PARENT_KEY AS __PARENT_ROW_KEY, ROW_TYPE AS __ROW_TYPE,
        ROW_LEVEL AS __ROW_LEVEL,
        ROW_NUMBER() OVER (ORDER BY DIMENSION_CD, PRODUCT_GROUP, SECTION_SORT, LINE_SORT, ROW_KEY) AS __ROW_SORT,
        p_COMPANY_CD AS __COMPANY_CD, SOURCE_ID AS __CHIT_ID, SOURCE_TYPE AS __CHIT_TYPE,
        DESCRIPTION, DOCUMENT_NO, DOCUMENT_DATE, DOCUMENT_DATE AS ENTRY_DATE,
        PRODUCT_CD, PRODUCT_NAME, UNIT_NAME, STORE_CD, STORE_NAME, ACCOUNT_CD, ACCOUNT_NAME, COUNTERPART_ACCOUNT,
        UNIT_PRICE, UNIT_PRICE_FC, OPENING_QUANTITY, OPENING_AMOUNT, OPENING_AMOUNT_FC,
        INPUT_QUANTITY, INPUT_AMOUNT, INPUT_AMOUNT_FC, OUTPUT_QUANTITY, OUTPUT_AMOUNT, OUTPUT_AMOUNT_FC,
        BALANCE_QUANTITY, BALANCE_AMOUNT, BALANCE_AMOUNT_FC, AVERAGE_PRICE, AVERAGE_PRICE_FC
    FROM report_rows
    ORDER BY __ROW_SORT;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rpt_inventory_detail_product
DROP PROCEDURE IF EXISTS `rpt_inventory_detail_product`;
DELIMITER //
CREATE PROCEDURE `rpt_inventory_detail_product`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_PRODUCT_CD TEXT,
    IN p_FC_TYPE VARCHAR(10),
    IN p_HIDE_NO_MOVEMENT TINYINT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_language VARCHAR(20) DEFAULT UPPER(COALESCE(p_LANGUAGE, 'VIET'));
    DECLARE v_fc_type VARCHAR(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
    DECLARE v_month_start DATE;
    DECLARE v_product_filter TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL OR p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid inventory report date range';
    END IF;

    SET v_fc_type = UPPER(TRIM(COALESCE(p_FC_TYPE, '')));
    SET v_month_start = DATE_SUB(p_TO_DATE, INTERVAL (DAYOFMONTH(p_TO_DATE) - 1) DAY);
    SET v_product_filter = TRIM(COALESCE(p_PRODUCT_CD, ''));

    WITH product_filter AS (
        SELECT TRIM(CODE) AS CODE
        FROM JSON_TABLE(REPLACE(JSON_ARRAY(v_product_filter), ',', '","'),
            '$[*]' COLUMNS (CODE VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH '$')) tokens
    ), movement AS (
        SELECT
            'INPUT' AS FLOW_TYPE,
            ii.INPUT_ID AS LINE_ID,
            ii.PRODUCT_ID, ii.PRODUCT_CD, ii.STORE_ID, ii.STORE_CD,
            ii.UNIT_ID, ii.UNIT_CD, ii.SORT,
            COALESCE(NULLIF(ii.CHIT_TYPE, ''), h.CHIT_TYPE, '') AS DOCUMENT_TYPE,
            COALESCE(DATE(ii.INVENTORY_YMD), STR_TO_DATE(NULLIF(h.INVENTORY_YMD, ''), '%Y%m%d')) AS DOCUMENT_DATE,
            COALESCE(NULLIF(h.INVENTORY_NO, ''), NULLIF(chit.CHIT_NO, ''), ii.INVENTORY_CD, '') AS DOCUMENT_NO,
            COALESCE(NULLIF(ii.SUMMARY, ''), h.REMARK, '') AS DESCRIPTION,
            COALESCE(posting.DEBIT, '') AS ACCOUNT_CD,
            COALESCE(posting.CREDIT, '') AS COUNTERPART_ACCOUNT,
            COALESCE(h.INVENTORY_ID, chit.CHIT_ID) AS SOURCE_ID,
            COALESCE(h.CHIT_TYPE, chit.CHIT_TYPE) AS SOURCE_TYPE,
            CAST(ii.QUANTITY AS DECIMAL(24, 6)) AS QUANTITY,
            CAST(COALESCE(NULLIF(ii.AMOUNT_CC, 0), ii.QUANTITY * ii.UNIT_PRICE_CC) AS DECIMAL(24, 6)) AS AMOUNT,
            CAST(CASE WHEN ii.FC_TYPE = v_fc_type THEN ii.AMOUNT_FC END AS DECIMAL(24, 6)) AS AMOUNT_FC,
            CAST(ii.UNIT_PRICE_CC AS DECIMAL(24, 6)) AS UNIT_PRICE,
            CAST(CASE WHEN ii.FC_TYPE = v_fc_type THEN ii.UNIT_PRICE_FC END AS DECIMAL(24, 6)) AS UNIT_PRICE_FC
        FROM chit_inventory_input ii
        LEFT JOIN chit_inventory_info h
            ON h.COMPANY_CD = ii.COMPANY_CD AND h.INVENTORY_ID = ii.INVENTORY_ID
           AND (ii.CHIT_TYPE = h.CHIT_TYPE
                OR (ii.CHIT_TYPE = 'IA' AND h.CHIT_TYPE IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER')))
        LEFT JOIN chitdetailinfo posting
            ON posting.COMPANY_CD = ii.COMPANY_CD AND posting.ISDEL = '0'
           AND posting.CHITDETAIL_ID = ii.CHITDETAIL_ID
        LEFT JOIN chitinfo chit
            ON chit.COMPANY_CD = ii.COMPANY_CD
           AND chit.CHIT_ID = posting.CHIT_ID
        WHERE ii.COMPANY_CD = p_COMPANY_CD AND ii.ISDEL = '0'
          AND (h.INVENTORY_ID IS NULL OR h.ISDEL = '0')
          AND (chit.CHIT_ID IS NULL OR chit.ISDEL = '0')
          AND (ii.INVENTORY_YMD < DATE_ADD(p_TO_DATE, INTERVAL 1 DAY)
               OR (ii.INVENTORY_YMD IS NULL AND h.INVENTORY_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')))
        UNION ALL
        SELECT
            'OUTPUT' AS FLOW_TYPE,
            io.OUTPUT_ID AS LINE_ID,
            io.PRODUCT_ID, io.PRODUCT_CD, io.STORE_ID, io.STORE_CD,
            io.UNIT_ID, io.UNIT_CD, io.SORT,
            COALESCE(NULLIF(io.CHIT_TYPE, ''), h.CHIT_TYPE, '') AS DOCUMENT_TYPE,
            COALESCE(DATE(io.INVENTORY_YMD), STR_TO_DATE(NULLIF(h.INVENTORY_YMD, ''), '%Y%m%d')) AS DOCUMENT_DATE,
            COALESCE(NULLIF(h.INVENTORY_NO, ''), NULLIF(chit.CHIT_NO, ''), io.INVENTORY_CD, '') AS DOCUMENT_NO,
            COALESCE(NULLIF(io.SUMMARY, ''), h.REMARK, '') AS DESCRIPTION,
            COALESCE(posting.CREDIT, '') AS ACCOUNT_CD,
            COALESCE(posting.DEBIT, '') AS COUNTERPART_ACCOUNT,
            COALESCE(h.INVENTORY_ID, chit.CHIT_ID) AS SOURCE_ID,
            COALESCE(h.CHIT_TYPE, chit.CHIT_TYPE) AS SOURCE_TYPE,
            CAST(io.QUANTITY AS DECIMAL(24, 6)) AS QUANTITY,
            CAST(CASE WHEN io.CHIT_TYPE = 'IO' THEN io.AMOUNT_CC
                      ELSE COALESCE(NULLIF(io.AMOUNT_CC, 0), io.QUANTITY * io.UNIT_PRICE_CC) END AS DECIMAL(24, 6)) AS AMOUNT,
            CAST(CASE WHEN io.FC_TYPE = v_fc_type THEN io.AMOUNT_FC END AS DECIMAL(24, 6)) AS AMOUNT_FC,
            CAST(io.UNIT_PRICE_CC AS DECIMAL(24, 6)) AS UNIT_PRICE,
            CAST(CASE WHEN io.FC_TYPE = v_fc_type THEN io.UNIT_PRICE_FC END AS DECIMAL(24, 6)) AS UNIT_PRICE_FC
        FROM chit_inventory_output io
        LEFT JOIN chit_inventory_info h
            ON h.COMPANY_CD = io.COMPANY_CD AND h.INVENTORY_ID = io.INVENTORY_ID
           AND (io.CHIT_TYPE = h.CHIT_TYPE
                OR (io.CHIT_TYPE = 'IA' AND h.CHIT_TYPE IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER')))
        LEFT JOIN chitdetailinfo source_detail
            ON source_detail.COMPANY_CD = io.COMPANY_CD AND source_detail.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND source_detail.ISDEL = '0'
        LEFT JOIN chitdetailinfo posting
            ON posting.COMPANY_CD = io.COMPANY_CD AND posting.ISDEL = '0'
           AND posting.CHITDETAIL_ID = COALESCE(
                CASE WHEN io.CHIT_TYPE = 'IO' THEN COALESCE(
                    NULLIF(io.CHITDETAIL_ID_COGS, 0), NULLIF(h.CHITDETAIL_ID_COGS, 0),
                    (SELECT MIN(legacy.CHITDETAIL_ID)
                     FROM chitdetailinfo legacy
                     WHERE legacy.COMPANY_CD = io.COMPANY_CD AND legacy.CHIT_ID = h.CHIT_ID_COGS
                       AND legacy.SORT = 1 AND legacy.ISDEL = '0')
                ) END,
                io.CHITDETAIL_ID
           )
        LEFT JOIN chitinfo chit
            ON chit.COMPANY_CD = io.COMPANY_CD
           AND chit.CHIT_ID = COALESCE(source_detail.CHIT_ID, posting.CHIT_ID)
        WHERE io.COMPANY_CD = p_COMPANY_CD AND io.ISDEL = '0'
          AND (h.INVENTORY_ID IS NULL OR h.ISDEL = '0')
          AND (chit.CHIT_ID IS NULL OR chit.ISDEL = '0')
          AND (io.INVENTORY_YMD < DATE_ADD(p_TO_DATE, INTERVAL 1 DAY)
               OR (io.INVENTORY_YMD IS NULL AND h.INVENTORY_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')))
    ), catalog AS (
        SELECT m.FLOW_TYPE, m.LINE_ID, m.SORT, m.DOCUMENT_TYPE, m.DOCUMENT_DATE, m.DOCUMENT_NO,
            m.DESCRIPTION, m.ACCOUNT_CD, m.COUNTERPART_ACCOUNT, m.SOURCE_ID, m.SOURCE_TYPE,
            m.QUANTITY, m.AMOUNT, m.AMOUNT_FC, m.UNIT_PRICE, m.UNIT_PRICE_FC,
            COALESCE(NULLIF(m.PRODUCT_CD, ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN product.PRODUCT_NM_ENG WHEN 'KOR' THEN product.PRODUCT_NM_KOR
                WHEN 'CHN' THEN product.PRODUCT_NM_CHINA ELSE product.PRODUCT_NM_VIET END, ''),
                NULLIF(product.PRODUCT_NM_VIET, '')), NULLIF(m.PRODUCT_CD, ''), '') AS PRODUCT_NAME,
            COALESCE(NULLIF(m.STORE_CD, ''), store.STORE_CD, '') AS STORE_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN store.STORE_NM_ENG WHEN 'KOR' THEN store.STORE_NM_KOR
                WHEN 'CHN' THEN store.STORE_NM_CHINA ELSE store.STORE_NM_VIET END, ''),
                NULLIF(store.STORE_NM_VIET, '')), NULLIF(m.STORE_CD, ''), '') AS STORE_NAME,
            COALESCE(NULLIF(unit.UNIT_NM, ''), m.UNIT_CD, '') AS UNIT_NAME,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN account.ACCTITLE_NM_ENG WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
                WHEN 'CHN' THEN account.ACCTITLE_NM_CHINA ELSE account.ACCTITLE_NM_VIET END, ''),
                NULLIF(account.ACCTITLE_NM_VIET, '')), NULLIF(m.ACCOUNT_CD, ''), '') AS ACCOUNT_NAME
        FROM movement m
        LEFT JOIN product_info product
            ON product.COMPANY_CD = p_COMPANY_CD AND product.PRODUCT_ID = m.PRODUCT_ID AND product.ISDEL = '0'
        LEFT JOIN store_info store
            ON store.COMPANY_CD = p_COMPANY_CD AND store.STORE_ID = m.STORE_ID AND store.ISDEL = '0'
        LEFT JOIN product_unit unit
            ON unit.COMPANY_CD = p_COMPANY_CD AND unit.UNIT_ID = m.UNIT_ID AND unit.ISDEL = '0'
        LEFT JOIN acclist_info account
            ON account.COMPANY_CD = p_COMPANY_CD AND account.ACC_ID = (
                SELECT MAX(a.ACC_ID)
                FROM acclist_info a
                WHERE a.COMPANY_CD = p_COMPANY_CD AND a.ACC_CD = m.ACCOUNT_CD AND a.ISDEL = '0'
            )
        WHERE m.DOCUMENT_DATE <= p_TO_DATE
    ), filtered AS (
        SELECT catalog.*,
            '' AS DIMENSION_CD,
            UPPER(PRODUCT_CD) AS PRODUCT_GROUP,
            DOCUMENT_DATE >= p_FROM_DATE AS IN_PERIOD,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN QUANTITY ELSE -QUANTITY END AS NET_QTY,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT ELSE -AMOUNT END AS NET_AMOUNT,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT_FC ELSE -AMOUNT_FC END AS NET_FC
        FROM catalog
        WHERE (v_product_filter IN ('', 'all')
               OR EXISTS (SELECT 1 FROM product_filter f WHERE f.CODE = catalog.PRODUCT_CD))
    ), totals AS (
        SELECT DIMENSION_CD, PRODUCT_GROUP,
            CONCAT('PRODUCT-', SHA2(JSON_ARRAY(DIMENSION_CD, PRODUCT_GROUP), 256)) AS PRODUCT_KEY,
            MAX(PRODUCT_NAME) AS PRODUCT_NAME,
            MAX(UNIT_NAME) AS UNIT_NAME,
            SUM(IF(IN_PERIOD, 0, NET_QTY)) AS OPEN_QTY,
            SUM(IF(IN_PERIOD, 0, NET_AMOUNT)) AS OPEN_AMOUNT,
            SUM(IF(IN_PERIOD, NULL, NET_FC)) AS OPEN_FC,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', QUANTITY, 0)) AS IN_QTY,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', AMOUNT, 0)) AS IN_AMOUNT,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', AMOUNT_FC, NULL)) AS IN_FC,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', QUANTITY, 0)) AS OUT_QTY,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', AMOUNT, 0)) AS OUT_AMOUNT,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', AMOUNT_FC, NULL)) AS OUT_FC,
            SUM(NET_QTY) AS END_QTY,
            SUM(NET_AMOUNT) AS END_AMOUNT,
            SUM(NET_FC) AS END_FC,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_QTY WHEN FLOW_TYPE = 'INPUT' THEN QUANTITY ELSE 0 END) AS MONTH_AVAILABLE_QTY,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_AMOUNT WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT ELSE 0 END) AS MONTH_AVAILABLE_AMOUNT,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_FC WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT_FC END) AS MONTH_AVAILABLE_FC,
            SUM(IF(AMOUNT_FC IS NOT NULL, IF(IN_PERIOD, IF(FLOW_TYPE = 'INPUT', QUANTITY, 0), NET_QTY), 0)) AS PERIOD_AVAILABLE_FC_QTY,
            SUM(IF(AMOUNT_FC IS NOT NULL, IF(DOCUMENT_DATE < v_month_start, NET_QTY, IF(FLOW_TYPE = 'INPUT', QUANTITY, 0)), 0)) AS MONTH_AVAILABLE_FC_QTY
        FROM filtered
        GROUP BY DIMENSION_CD, PRODUCT_GROUP
        HAVING COALESCE(p_HIDE_NO_MOVEMENT, 0) = 0 OR SUM(IN_PERIOD AND DOCUMENT_TYPE <> 'IRO') > 0
    ), details AS (
        SELECT f.*, t.PRODUCT_KEY,
            ROW_NUMBER() OVER ledger AS LINE_SORT,
            t.OPEN_QTY + SUM(NET_QTY) OVER ledger AS BALANCE_QTY,
            t.OPEN_AMOUNT + SUM(NET_AMOUNT) OVER ledger AS BALANCE_AMOUNT,
            CASE WHEN t.OPEN_FC IS NOT NULL OR SUM(NET_FC) OVER ledger IS NOT NULL
                THEN COALESCE(t.OPEN_FC, 0) + COALESCE(SUM(NET_FC) OVER ledger, 0) END AS BALANCE_FC
        FROM filtered f
        JOIN totals t USING (DIMENSION_CD, PRODUCT_GROUP)
        WHERE f.IN_PERIOD
        WINDOW ledger AS (PARTITION BY f.DIMENSION_CD, f.PRODUCT_GROUP
            ORDER BY f.DOCUMENT_DATE, f.DOCUMENT_NO, f.SORT, f.FLOW_TYPE, f.LINE_ID ROWS UNBOUNDED PRECEDING)
    ), summary_types AS (
        SELECT 'OPENING' AS ROW_TYPE, 1 AS ROW_SORT, CASE v_language WHEN 'ENG' THEN 'Opening balance' WHEN 'KOR' THEN '기초 잔액' WHEN 'CHN' THEN '期初余额' ELSE 'Chỉ tiêu đầu kỳ' END AS LABEL
        UNION ALL SELECT 'TOTAL', 3, CASE v_language WHEN 'ENG' THEN 'Period movement' WHEN 'KOR' THEN '기간 합계' WHEN 'CHN' THEN '本期发生额' ELSE 'Cộng phát sinh' END
        UNION ALL SELECT 'CLOSING', 4, CASE v_language WHEN 'ENG' THEN 'Closing balance' WHEN 'KOR' THEN '기말 재고' WHEN 'CHN' THEN '期末库存' ELSE 'Hàng tồn kho' END
        UNION ALL SELECT 'PERIOD_AVERAGE', 5, CASE v_language WHEN 'ENG' THEN 'Period average cost' WHEN 'KOR' THEN '기간 평균 단가' WHEN 'CHN' THEN '本期平均单价' ELSE 'Giá trung bình của kỳ này' END
        UNION ALL SELECT 'MONTH_AVERAGE', 6, CASE v_language WHEN 'ENG' THEN 'Month average cost' WHEN 'KOR' THEN '월 평균 단가' WHEN 'CHN' THEN '本月平均单价' ELSE 'Giá trung bình của tháng này' END
    ), report_rows AS (
        SELECT t.PRODUCT_KEY AS ROW_KEY, NULL AS PARENT_KEY, 'GROUP' AS ROW_TYPE, 0 AS ROW_LEVEL,
            t.DIMENSION_CD, t.PRODUCT_GROUP, 0 AS SECTION_SORT, 0 AS LINE_SORT,
            CONCAT(t.PRODUCT_GROUP, IF(t.PRODUCT_NAME = t.PRODUCT_GROUP, '', CONCAT(' — ', t.PRODUCT_NAME))) AS DESCRIPTION,
            NULL AS DOCUMENT_NO, NULL AS DOCUMENT_DATE, t.PRODUCT_GROUP AS PRODUCT_CD, t.PRODUCT_NAME,
            NULL AS STORE_CD, NULL AS STORE_NAME, t.UNIT_NAME, NULL AS ACCOUNT_CD, NULL AS ACCOUNT_NAME,
            NULL AS COUNTERPART_ACCOUNT, NULL AS UNIT_PRICE, NULL AS UNIT_PRICE_FC,
            NULL AS OPENING_QUANTITY, NULL AS OPENING_AMOUNT, NULL AS OPENING_AMOUNT_FC,
            NULL AS INPUT_QUANTITY, NULL AS INPUT_AMOUNT, NULL AS INPUT_AMOUNT_FC,
            NULL AS OUTPUT_QUANTITY, NULL AS OUTPUT_AMOUNT, NULL AS OUTPUT_AMOUNT_FC,
            NULL AS BALANCE_QUANTITY, NULL AS BALANCE_AMOUNT, NULL AS BALANCE_AMOUNT_FC,
            NULL AS AVERAGE_PRICE, NULL AS AVERAGE_PRICE_FC, NULL AS SOURCE_ID, NULL AS SOURCE_TYPE
        FROM totals t
        UNION ALL
        SELECT CONCAT(f.FLOW_TYPE, '-', f.LINE_ID), f.PRODUCT_KEY, f.FLOW_TYPE, 1,
            f.DIMENSION_CD, f.PRODUCT_GROUP, 2, f.LINE_SORT, f.DESCRIPTION,
            f.DOCUMENT_NO, f.DOCUMENT_DATE, f.PRODUCT_CD, f.PRODUCT_NAME,
            f.STORE_CD, f.STORE_NAME, f.UNIT_NAME, f.ACCOUNT_CD, f.ACCOUNT_NAME,
            f.COUNTERPART_ACCOUNT, f.UNIT_PRICE, f.UNIT_PRICE_FC,
            NULL, NULL, NULL,
            IF(f.FLOW_TYPE = 'INPUT', f.QUANTITY, NULL), IF(f.FLOW_TYPE = 'INPUT', f.AMOUNT, NULL), IF(f.FLOW_TYPE = 'INPUT', f.AMOUNT_FC, NULL),
            IF(f.FLOW_TYPE = 'OUTPUT', f.QUANTITY, NULL), IF(f.FLOW_TYPE = 'OUTPUT', f.AMOUNT, NULL), IF(f.FLOW_TYPE = 'OUTPUT', f.AMOUNT_FC, NULL),
            f.BALANCE_QTY, f.BALANCE_AMOUNT, f.BALANCE_FC, NULL, NULL, f.SOURCE_ID, f.SOURCE_TYPE
        FROM details f
        UNION ALL
        SELECT CONCAT(t.PRODUCT_KEY, '-', s.ROW_TYPE), t.PRODUCT_KEY, s.ROW_TYPE, 1,
            t.DIMENSION_CD, t.PRODUCT_GROUP, s.ROW_SORT, 0, s.LABEL,
            NULL, NULL, t.PRODUCT_GROUP, t.PRODUCT_NAME, NULL, NULL, t.UNIT_NAME, NULL, NULL,
            NULL, NULL, NULL,
            IF(s.ROW_TYPE = 'OPENING', t.OPEN_QTY, NULL), IF(s.ROW_TYPE = 'OPENING', t.OPEN_AMOUNT, NULL), IF(s.ROW_TYPE = 'OPENING', t.OPEN_FC, NULL),
            IF(s.ROW_TYPE = 'TOTAL', t.IN_QTY, NULL), IF(s.ROW_TYPE = 'TOTAL', t.IN_AMOUNT, NULL), IF(s.ROW_TYPE = 'TOTAL', t.IN_FC, NULL),
            IF(s.ROW_TYPE = 'TOTAL', t.OUT_QTY, NULL), IF(s.ROW_TYPE = 'TOTAL', t.OUT_AMOUNT, NULL), IF(s.ROW_TYPE = 'TOTAL', t.OUT_FC, NULL),
            IF(s.ROW_TYPE = 'CLOSING', t.END_QTY, NULL), IF(s.ROW_TYPE = 'CLOSING', t.END_AMOUNT, NULL), IF(s.ROW_TYPE = 'CLOSING', t.END_FC, NULL),
            CASE s.ROW_TYPE WHEN 'PERIOD_AVERAGE' THEN (t.OPEN_AMOUNT + t.IN_AMOUNT) / NULLIF(t.OPEN_QTY + t.IN_QTY, 0)
                WHEN 'MONTH_AVERAGE' THEN t.MONTH_AVAILABLE_AMOUNT / NULLIF(t.MONTH_AVAILABLE_QTY, 0) END,
            CASE s.ROW_TYPE WHEN 'PERIOD_AVERAGE' THEN
                CASE WHEN t.OPEN_FC IS NOT NULL OR t.IN_FC IS NOT NULL
                    THEN (COALESCE(t.OPEN_FC, 0) + COALESCE(t.IN_FC, 0)) / NULLIF(t.PERIOD_AVAILABLE_FC_QTY, 0) END
                WHEN 'MONTH_AVERAGE' THEN t.MONTH_AVAILABLE_FC / NULLIF(t.MONTH_AVAILABLE_FC_QTY, 0) END,
            NULL, NULL
        FROM totals t CROSS JOIN summary_types s
    )
    SELECT ROW_KEY AS __ROW_KEY, PARENT_KEY AS __PARENT_ROW_KEY, ROW_TYPE AS __ROW_TYPE,
        ROW_LEVEL AS __ROW_LEVEL,
        ROW_NUMBER() OVER (ORDER BY DIMENSION_CD, PRODUCT_GROUP, SECTION_SORT, LINE_SORT, ROW_KEY) AS __ROW_SORT,
        p_COMPANY_CD AS __COMPANY_CD, SOURCE_ID AS __CHIT_ID, SOURCE_TYPE AS __CHIT_TYPE,
        DESCRIPTION, DOCUMENT_NO, DOCUMENT_DATE, DOCUMENT_DATE AS ENTRY_DATE,
        PRODUCT_CD, PRODUCT_NAME, UNIT_NAME, STORE_CD, STORE_NAME, ACCOUNT_CD, ACCOUNT_NAME, COUNTERPART_ACCOUNT,
        UNIT_PRICE, UNIT_PRICE_FC, OPENING_QUANTITY, OPENING_AMOUNT, OPENING_AMOUNT_FC,
        INPUT_QUANTITY, INPUT_AMOUNT, INPUT_AMOUNT_FC, OUTPUT_QUANTITY, OUTPUT_AMOUNT, OUTPUT_AMOUNT_FC,
        BALANCE_QUANTITY, BALANCE_AMOUNT, BALANCE_AMOUNT_FC, AVERAGE_PRICE, AVERAGE_PRICE_FC
    FROM report_rows
    ORDER BY __ROW_SORT;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.rpt_inventory_detail_store
DROP PROCEDURE IF EXISTS `rpt_inventory_detail_store`;
DELIMITER //
CREATE PROCEDURE `rpt_inventory_detail_store`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_PRODUCT_CD TEXT,
    IN p_STORE_CD TEXT,
    IN p_FC_TYPE VARCHAR(10),
    IN p_HIDE_NO_MOVEMENT TINYINT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_language VARCHAR(20) DEFAULT UPPER(COALESCE(p_LANGUAGE, 'VIET'));
    DECLARE v_fc_type VARCHAR(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
    DECLARE v_month_start DATE;
    DECLARE v_product_filter TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
    DECLARE v_dimension_filter TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL OR p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid inventory report date range';
    END IF;

    SET v_fc_type = UPPER(TRIM(COALESCE(p_FC_TYPE, '')));
    SET v_month_start = DATE_SUB(p_TO_DATE, INTERVAL (DAYOFMONTH(p_TO_DATE) - 1) DAY);
    SET v_product_filter = TRIM(COALESCE(p_PRODUCT_CD, ''));
    SET v_dimension_filter = TRIM(COALESCE(p_STORE_CD, ''));

    WITH product_filter AS (
        SELECT TRIM(CODE) AS CODE
        FROM JSON_TABLE(REPLACE(JSON_ARRAY(v_product_filter), ',', '","'),
            '$[*]' COLUMNS (CODE VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH '$')) tokens
    ), dimension_filter AS (
        SELECT TRIM(CODE) AS CODE
        FROM JSON_TABLE(REPLACE(JSON_ARRAY(v_dimension_filter), ',', '","'),
            '$[*]' COLUMNS (CODE VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH '$')) tokens
    ), movement AS (
        SELECT
            'INPUT' AS FLOW_TYPE,
            ii.INPUT_ID AS LINE_ID,
            ii.PRODUCT_ID, ii.PRODUCT_CD, ii.STORE_ID, ii.STORE_CD,
            ii.UNIT_ID, ii.UNIT_CD, ii.SORT,
            COALESCE(NULLIF(ii.CHIT_TYPE, ''), h.CHIT_TYPE, '') AS DOCUMENT_TYPE,
            COALESCE(DATE(ii.INVENTORY_YMD), STR_TO_DATE(NULLIF(h.INVENTORY_YMD, ''), '%Y%m%d')) AS DOCUMENT_DATE,
            COALESCE(NULLIF(h.INVENTORY_NO, ''), NULLIF(chit.CHIT_NO, ''), ii.INVENTORY_CD, '') AS DOCUMENT_NO,
            COALESCE(NULLIF(ii.SUMMARY, ''), h.REMARK, '') AS DESCRIPTION,
            COALESCE(posting.DEBIT, '') AS ACCOUNT_CD,
            COALESCE(posting.CREDIT, '') AS COUNTERPART_ACCOUNT,
            COALESCE(h.INVENTORY_ID, chit.CHIT_ID) AS SOURCE_ID,
            COALESCE(h.CHIT_TYPE, chit.CHIT_TYPE) AS SOURCE_TYPE,
            CAST(ii.QUANTITY AS DECIMAL(24, 6)) AS QUANTITY,
            CAST(COALESCE(NULLIF(ii.AMOUNT_CC, 0), ii.QUANTITY * ii.UNIT_PRICE_CC) AS DECIMAL(24, 6)) AS AMOUNT,
            CAST(CASE WHEN ii.FC_TYPE = v_fc_type THEN ii.AMOUNT_FC END AS DECIMAL(24, 6)) AS AMOUNT_FC,
            CAST(ii.UNIT_PRICE_CC AS DECIMAL(24, 6)) AS UNIT_PRICE,
            CAST(CASE WHEN ii.FC_TYPE = v_fc_type THEN ii.UNIT_PRICE_FC END AS DECIMAL(24, 6)) AS UNIT_PRICE_FC
        FROM chit_inventory_input ii
        LEFT JOIN chit_inventory_info h
            ON h.COMPANY_CD = ii.COMPANY_CD AND h.INVENTORY_ID = ii.INVENTORY_ID
           AND (ii.CHIT_TYPE = h.CHIT_TYPE
                OR (ii.CHIT_TYPE = 'IA' AND h.CHIT_TYPE IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER')))
        LEFT JOIN chitdetailinfo posting
            ON posting.COMPANY_CD = ii.COMPANY_CD AND posting.ISDEL = '0'
           AND posting.CHITDETAIL_ID = ii.CHITDETAIL_ID
        LEFT JOIN chitinfo chit
            ON chit.COMPANY_CD = ii.COMPANY_CD
           AND chit.CHIT_ID = posting.CHIT_ID
        WHERE ii.COMPANY_CD = p_COMPANY_CD AND ii.ISDEL = '0'
          AND (h.INVENTORY_ID IS NULL OR h.ISDEL = '0')
          AND (chit.CHIT_ID IS NULL OR chit.ISDEL = '0')
          AND (ii.INVENTORY_YMD < DATE_ADD(p_TO_DATE, INTERVAL 1 DAY)
               OR (ii.INVENTORY_YMD IS NULL AND h.INVENTORY_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')))
        UNION ALL
        SELECT
            'OUTPUT' AS FLOW_TYPE,
            io.OUTPUT_ID AS LINE_ID,
            io.PRODUCT_ID, io.PRODUCT_CD, io.STORE_ID, io.STORE_CD,
            io.UNIT_ID, io.UNIT_CD, io.SORT,
            COALESCE(NULLIF(io.CHIT_TYPE, ''), h.CHIT_TYPE, '') AS DOCUMENT_TYPE,
            COALESCE(DATE(io.INVENTORY_YMD), STR_TO_DATE(NULLIF(h.INVENTORY_YMD, ''), '%Y%m%d')) AS DOCUMENT_DATE,
            COALESCE(NULLIF(h.INVENTORY_NO, ''), NULLIF(chit.CHIT_NO, ''), io.INVENTORY_CD, '') AS DOCUMENT_NO,
            COALESCE(NULLIF(io.SUMMARY, ''), h.REMARK, '') AS DESCRIPTION,
            COALESCE(posting.CREDIT, '') AS ACCOUNT_CD,
            COALESCE(posting.DEBIT, '') AS COUNTERPART_ACCOUNT,
            COALESCE(h.INVENTORY_ID, chit.CHIT_ID) AS SOURCE_ID,
            COALESCE(h.CHIT_TYPE, chit.CHIT_TYPE) AS SOURCE_TYPE,
            CAST(io.QUANTITY AS DECIMAL(24, 6)) AS QUANTITY,
            CAST(CASE WHEN io.CHIT_TYPE = 'IO' THEN io.AMOUNT_CC
                      ELSE COALESCE(NULLIF(io.AMOUNT_CC, 0), io.QUANTITY * io.UNIT_PRICE_CC) END AS DECIMAL(24, 6)) AS AMOUNT,
            CAST(CASE WHEN io.FC_TYPE = v_fc_type THEN io.AMOUNT_FC END AS DECIMAL(24, 6)) AS AMOUNT_FC,
            CAST(io.UNIT_PRICE_CC AS DECIMAL(24, 6)) AS UNIT_PRICE,
            CAST(CASE WHEN io.FC_TYPE = v_fc_type THEN io.UNIT_PRICE_FC END AS DECIMAL(24, 6)) AS UNIT_PRICE_FC
        FROM chit_inventory_output io
        LEFT JOIN chit_inventory_info h
            ON h.COMPANY_CD = io.COMPANY_CD AND h.INVENTORY_ID = io.INVENTORY_ID
           AND (io.CHIT_TYPE = h.CHIT_TYPE
                OR (io.CHIT_TYPE = 'IA' AND h.CHIT_TYPE IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER')))
        LEFT JOIN chitdetailinfo source_detail
            ON source_detail.COMPANY_CD = io.COMPANY_CD AND source_detail.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND source_detail.ISDEL = '0'
        LEFT JOIN chitdetailinfo posting
            ON posting.COMPANY_CD = io.COMPANY_CD AND posting.ISDEL = '0'
           AND posting.CHITDETAIL_ID = COALESCE(
                CASE WHEN io.CHIT_TYPE = 'IO' THEN COALESCE(
                    NULLIF(io.CHITDETAIL_ID_COGS, 0), NULLIF(h.CHITDETAIL_ID_COGS, 0),
                    (SELECT MIN(legacy.CHITDETAIL_ID)
                     FROM chitdetailinfo legacy
                     WHERE legacy.COMPANY_CD = io.COMPANY_CD AND legacy.CHIT_ID = h.CHIT_ID_COGS
                       AND legacy.SORT = 1 AND legacy.ISDEL = '0')
                ) END,
                io.CHITDETAIL_ID
           )
        LEFT JOIN chitinfo chit
            ON chit.COMPANY_CD = io.COMPANY_CD
           AND chit.CHIT_ID = COALESCE(source_detail.CHIT_ID, posting.CHIT_ID)
        WHERE io.COMPANY_CD = p_COMPANY_CD AND io.ISDEL = '0'
          AND (h.INVENTORY_ID IS NULL OR h.ISDEL = '0')
          AND (chit.CHIT_ID IS NULL OR chit.ISDEL = '0')
          AND (io.INVENTORY_YMD < DATE_ADD(p_TO_DATE, INTERVAL 1 DAY)
               OR (io.INVENTORY_YMD IS NULL AND h.INVENTORY_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')))
    ), catalog AS (
        SELECT m.FLOW_TYPE, m.LINE_ID, m.SORT, m.DOCUMENT_TYPE, m.DOCUMENT_DATE, m.DOCUMENT_NO,
            m.DESCRIPTION, m.ACCOUNT_CD, m.COUNTERPART_ACCOUNT, m.SOURCE_ID, m.SOURCE_TYPE,
            m.QUANTITY, m.AMOUNT, m.AMOUNT_FC, m.UNIT_PRICE, m.UNIT_PRICE_FC,
            COALESCE(NULLIF(m.PRODUCT_CD, ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN product.PRODUCT_NM_ENG WHEN 'KOR' THEN product.PRODUCT_NM_KOR
                WHEN 'CHN' THEN product.PRODUCT_NM_CHINA ELSE product.PRODUCT_NM_VIET END, ''),
                NULLIF(product.PRODUCT_NM_VIET, '')), NULLIF(m.PRODUCT_CD, ''), '') AS PRODUCT_NAME,
            COALESCE(NULLIF(m.STORE_CD, ''), store.STORE_CD, '') AS STORE_CD,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN store.STORE_NM_ENG WHEN 'KOR' THEN store.STORE_NM_KOR
                WHEN 'CHN' THEN store.STORE_NM_CHINA ELSE store.STORE_NM_VIET END, ''),
                NULLIF(store.STORE_NM_VIET, '')), NULLIF(m.STORE_CD, ''), '') AS STORE_NAME,
            COALESCE(NULLIF(unit.UNIT_NM, ''), m.UNIT_CD, '') AS UNIT_NAME,
            COALESCE(COALESCE(NULLIF(CASE v_language
                WHEN 'ENG' THEN account.ACCTITLE_NM_ENG WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
                WHEN 'CHN' THEN account.ACCTITLE_NM_CHINA ELSE account.ACCTITLE_NM_VIET END, ''),
                NULLIF(account.ACCTITLE_NM_VIET, '')), NULLIF(m.ACCOUNT_CD, ''), '') AS ACCOUNT_NAME
        FROM movement m
        LEFT JOIN product_info product
            ON product.COMPANY_CD = p_COMPANY_CD AND product.PRODUCT_ID = m.PRODUCT_ID AND product.ISDEL = '0'
        LEFT JOIN store_info store
            ON store.COMPANY_CD = p_COMPANY_CD AND store.STORE_ID = m.STORE_ID AND store.ISDEL = '0'
        LEFT JOIN product_unit unit
            ON unit.COMPANY_CD = p_COMPANY_CD AND unit.UNIT_ID = m.UNIT_ID AND unit.ISDEL = '0'
        LEFT JOIN acclist_info account
            ON account.COMPANY_CD = p_COMPANY_CD AND account.ACC_ID = (
                SELECT MAX(a.ACC_ID)
                FROM acclist_info a
                WHERE a.COMPANY_CD = p_COMPANY_CD AND a.ACC_CD = m.ACCOUNT_CD AND a.ISDEL = '0'
            )
        WHERE m.DOCUMENT_DATE <= p_TO_DATE
    ), filtered AS (
        SELECT catalog.*,
            UPPER(STORE_CD) AS DIMENSION_CD,
            UPPER(PRODUCT_CD) AS PRODUCT_GROUP,
            DOCUMENT_DATE >= p_FROM_DATE AS IN_PERIOD,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN QUANTITY ELSE -QUANTITY END AS NET_QTY,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT ELSE -AMOUNT END AS NET_AMOUNT,
            CASE WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT_FC ELSE -AMOUNT_FC END AS NET_FC
        FROM catalog
        WHERE (v_product_filter IN ('', 'all')
               OR EXISTS (SELECT 1 FROM product_filter f WHERE f.CODE = catalog.PRODUCT_CD))
          AND (v_dimension_filter IN ('', 'all')
               OR EXISTS (SELECT 1 FROM dimension_filter f WHERE f.CODE = catalog.STORE_CD))
    ), totals AS (
        SELECT DIMENSION_CD, PRODUCT_GROUP,
            CONCAT('PRODUCT-', SHA2(JSON_ARRAY(DIMENSION_CD, PRODUCT_GROUP), 256)) AS PRODUCT_KEY,
            CONCAT('DIMENSION-', SHA2(DIMENSION_CD, 256)) AS DIMENSION_KEY,
            MAX(STORE_NAME) AS DIMENSION_NAME,
            MAX(PRODUCT_NAME) AS PRODUCT_NAME,
            MAX(UNIT_NAME) AS UNIT_NAME,
            SUM(IF(IN_PERIOD, 0, NET_QTY)) AS OPEN_QTY,
            SUM(IF(IN_PERIOD, 0, NET_AMOUNT)) AS OPEN_AMOUNT,
            SUM(IF(IN_PERIOD, NULL, NET_FC)) AS OPEN_FC,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', QUANTITY, 0)) AS IN_QTY,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', AMOUNT, 0)) AS IN_AMOUNT,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'INPUT', AMOUNT_FC, NULL)) AS IN_FC,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', QUANTITY, 0)) AS OUT_QTY,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', AMOUNT, 0)) AS OUT_AMOUNT,
            SUM(IF(IN_PERIOD AND FLOW_TYPE = 'OUTPUT', AMOUNT_FC, NULL)) AS OUT_FC,
            SUM(NET_QTY) AS END_QTY,
            SUM(NET_AMOUNT) AS END_AMOUNT,
            SUM(NET_FC) AS END_FC,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_QTY WHEN FLOW_TYPE = 'INPUT' THEN QUANTITY ELSE 0 END) AS MONTH_AVAILABLE_QTY,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_AMOUNT WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT ELSE 0 END) AS MONTH_AVAILABLE_AMOUNT,
            SUM(CASE WHEN DOCUMENT_DATE < v_month_start THEN NET_FC WHEN FLOW_TYPE = 'INPUT' THEN AMOUNT_FC END) AS MONTH_AVAILABLE_FC,
            SUM(IF(AMOUNT_FC IS NOT NULL, IF(IN_PERIOD, IF(FLOW_TYPE = 'INPUT', QUANTITY, 0), NET_QTY), 0)) AS PERIOD_AVAILABLE_FC_QTY,
            SUM(IF(AMOUNT_FC IS NOT NULL, IF(DOCUMENT_DATE < v_month_start, NET_QTY, IF(FLOW_TYPE = 'INPUT', QUANTITY, 0)), 0)) AS MONTH_AVAILABLE_FC_QTY
        FROM filtered
        GROUP BY DIMENSION_CD, PRODUCT_GROUP
        HAVING COALESCE(p_HIDE_NO_MOVEMENT, 0) = 0 OR SUM(IN_PERIOD AND DOCUMENT_TYPE <> 'IRO') > 0
    ), details AS (
        SELECT f.*, t.PRODUCT_KEY,
            ROW_NUMBER() OVER ledger AS LINE_SORT,
            t.OPEN_QTY + SUM(NET_QTY) OVER ledger AS BALANCE_QTY,
            t.OPEN_AMOUNT + SUM(NET_AMOUNT) OVER ledger AS BALANCE_AMOUNT,
            CASE WHEN t.OPEN_FC IS NOT NULL OR SUM(NET_FC) OVER ledger IS NOT NULL
                THEN COALESCE(t.OPEN_FC, 0) + COALESCE(SUM(NET_FC) OVER ledger, 0) END AS BALANCE_FC
        FROM filtered f
        JOIN totals t USING (DIMENSION_CD, PRODUCT_GROUP)
        WHERE f.IN_PERIOD
        WINDOW ledger AS (PARTITION BY f.DIMENSION_CD, f.PRODUCT_GROUP
            ORDER BY f.DOCUMENT_DATE, f.DOCUMENT_NO, f.SORT, f.FLOW_TYPE, f.LINE_ID ROWS UNBOUNDED PRECEDING)
    ), summary_types AS (
        SELECT 'OPENING' AS ROW_TYPE, 1 AS ROW_SORT, CASE v_language WHEN 'ENG' THEN 'Opening balance' WHEN 'KOR' THEN '기초 잔액' WHEN 'CHN' THEN '期初余额' ELSE 'Chỉ tiêu đầu kỳ' END AS LABEL
        UNION ALL SELECT 'TOTAL', 3, CASE v_language WHEN 'ENG' THEN 'Period movement' WHEN 'KOR' THEN '기간 합계' WHEN 'CHN' THEN '本期发生额' ELSE 'Cộng phát sinh' END
        UNION ALL SELECT 'CLOSING', 4, CASE v_language WHEN 'ENG' THEN 'Closing balance' WHEN 'KOR' THEN '기말 재고' WHEN 'CHN' THEN '期末库存' ELSE 'Hàng tồn kho' END
        UNION ALL SELECT 'PERIOD_AVERAGE', 5, CASE v_language WHEN 'ENG' THEN 'Period average cost' WHEN 'KOR' THEN '기간 평균 단가' WHEN 'CHN' THEN '本期平均单价' ELSE 'Giá trung bình của kỳ này' END
        UNION ALL SELECT 'MONTH_AVERAGE', 6, CASE v_language WHEN 'ENG' THEN 'Month average cost' WHEN 'KOR' THEN '월 평균 단가' WHEN 'CHN' THEN '本月平均单价' ELSE 'Giá trung bình của tháng này' END
    ), report_rows AS (
        SELECT DISTINCT t.DIMENSION_KEY AS ROW_KEY, NULL AS PARENT_KEY, 'GROUP' AS ROW_TYPE, 0 AS ROW_LEVEL,
            t.DIMENSION_CD, '' AS PRODUCT_GROUP, 0 AS SECTION_SORT, 0 AS LINE_SORT,
            CONCAT('Kho: ', t.DIMENSION_CD, IF(t.DIMENSION_CD = '', '', ' '), COALESCE(NULLIF(MAX(t.DIMENSION_NAME) OVER (PARTITION BY t.DIMENSION_CD), ''), '—')) AS DESCRIPTION,
            NULL AS DOCUMENT_NO, NULL AS DOCUMENT_DATE, NULL AS PRODUCT_CD, NULL AS PRODUCT_NAME,
            NULL AS STORE_CD, NULL AS STORE_NAME, NULL AS UNIT_NAME, NULL AS ACCOUNT_CD, NULL AS ACCOUNT_NAME,
            NULL AS COUNTERPART_ACCOUNT, NULL AS UNIT_PRICE, NULL AS UNIT_PRICE_FC,
            NULL AS OPENING_QUANTITY, NULL AS OPENING_AMOUNT, NULL AS OPENING_AMOUNT_FC,
            NULL AS INPUT_QUANTITY, NULL AS INPUT_AMOUNT, NULL AS INPUT_AMOUNT_FC,
            NULL AS OUTPUT_QUANTITY, NULL AS OUTPUT_AMOUNT, NULL AS OUTPUT_AMOUNT_FC,
            NULL AS BALANCE_QUANTITY, NULL AS BALANCE_AMOUNT, NULL AS BALANCE_AMOUNT_FC,
            NULL AS AVERAGE_PRICE, NULL AS AVERAGE_PRICE_FC, NULL AS SOURCE_ID, NULL AS SOURCE_TYPE
        FROM totals t
        UNION ALL
        SELECT t.PRODUCT_KEY AS ROW_KEY, t.DIMENSION_KEY AS PARENT_KEY, 'GROUP' AS ROW_TYPE, 1 AS ROW_LEVEL,
            t.DIMENSION_CD, t.PRODUCT_GROUP, 0 AS SECTION_SORT, 0 AS LINE_SORT,
            CONCAT(t.PRODUCT_GROUP, IF(t.PRODUCT_NAME = t.PRODUCT_GROUP, '', CONCAT(' — ', t.PRODUCT_NAME))) AS DESCRIPTION,
            NULL AS DOCUMENT_NO, NULL AS DOCUMENT_DATE, t.PRODUCT_GROUP AS PRODUCT_CD, t.PRODUCT_NAME,
            NULL AS STORE_CD, NULL AS STORE_NAME, t.UNIT_NAME, NULL AS ACCOUNT_CD, NULL AS ACCOUNT_NAME,
            NULL AS COUNTERPART_ACCOUNT, NULL AS UNIT_PRICE, NULL AS UNIT_PRICE_FC,
            NULL AS OPENING_QUANTITY, NULL AS OPENING_AMOUNT, NULL AS OPENING_AMOUNT_FC,
            NULL AS INPUT_QUANTITY, NULL AS INPUT_AMOUNT, NULL AS INPUT_AMOUNT_FC,
            NULL AS OUTPUT_QUANTITY, NULL AS OUTPUT_AMOUNT, NULL AS OUTPUT_AMOUNT_FC,
            NULL AS BALANCE_QUANTITY, NULL AS BALANCE_AMOUNT, NULL AS BALANCE_AMOUNT_FC,
            NULL AS AVERAGE_PRICE, NULL AS AVERAGE_PRICE_FC, NULL AS SOURCE_ID, NULL AS SOURCE_TYPE
        FROM totals t
        UNION ALL
        SELECT CONCAT(f.FLOW_TYPE, '-', f.LINE_ID), f.PRODUCT_KEY, f.FLOW_TYPE, 2,
            f.DIMENSION_CD, f.PRODUCT_GROUP, 2, f.LINE_SORT, f.DESCRIPTION,
            f.DOCUMENT_NO, f.DOCUMENT_DATE, f.PRODUCT_CD, f.PRODUCT_NAME,
            f.STORE_CD, f.STORE_NAME, f.UNIT_NAME, f.ACCOUNT_CD, f.ACCOUNT_NAME,
            f.COUNTERPART_ACCOUNT, f.UNIT_PRICE, f.UNIT_PRICE_FC,
            NULL, NULL, NULL,
            IF(f.FLOW_TYPE = 'INPUT', f.QUANTITY, NULL), IF(f.FLOW_TYPE = 'INPUT', f.AMOUNT, NULL), IF(f.FLOW_TYPE = 'INPUT', f.AMOUNT_FC, NULL),
            IF(f.FLOW_TYPE = 'OUTPUT', f.QUANTITY, NULL), IF(f.FLOW_TYPE = 'OUTPUT', f.AMOUNT, NULL), IF(f.FLOW_TYPE = 'OUTPUT', f.AMOUNT_FC, NULL),
            f.BALANCE_QTY, f.BALANCE_AMOUNT, f.BALANCE_FC, NULL, NULL, f.SOURCE_ID, f.SOURCE_TYPE
        FROM details f
        UNION ALL
        SELECT CONCAT(t.PRODUCT_KEY, '-', s.ROW_TYPE), t.PRODUCT_KEY, s.ROW_TYPE, 2,
            t.DIMENSION_CD, t.PRODUCT_GROUP, s.ROW_SORT, 0, s.LABEL,
            NULL, NULL, t.PRODUCT_GROUP, t.PRODUCT_NAME, NULL, NULL, t.UNIT_NAME, NULL, NULL,
            NULL, NULL, NULL,
            IF(s.ROW_TYPE = 'OPENING', t.OPEN_QTY, NULL), IF(s.ROW_TYPE = 'OPENING', t.OPEN_AMOUNT, NULL), IF(s.ROW_TYPE = 'OPENING', t.OPEN_FC, NULL),
            IF(s.ROW_TYPE = 'TOTAL', t.IN_QTY, NULL), IF(s.ROW_TYPE = 'TOTAL', t.IN_AMOUNT, NULL), IF(s.ROW_TYPE = 'TOTAL', t.IN_FC, NULL),
            IF(s.ROW_TYPE = 'TOTAL', t.OUT_QTY, NULL), IF(s.ROW_TYPE = 'TOTAL', t.OUT_AMOUNT, NULL), IF(s.ROW_TYPE = 'TOTAL', t.OUT_FC, NULL),
            IF(s.ROW_TYPE = 'CLOSING', t.END_QTY, NULL), IF(s.ROW_TYPE = 'CLOSING', t.END_AMOUNT, NULL), IF(s.ROW_TYPE = 'CLOSING', t.END_FC, NULL),
            CASE s.ROW_TYPE WHEN 'PERIOD_AVERAGE' THEN (t.OPEN_AMOUNT + t.IN_AMOUNT) / NULLIF(t.OPEN_QTY + t.IN_QTY, 0)
                WHEN 'MONTH_AVERAGE' THEN t.MONTH_AVAILABLE_AMOUNT / NULLIF(t.MONTH_AVAILABLE_QTY, 0) END,
            CASE s.ROW_TYPE WHEN 'PERIOD_AVERAGE' THEN
                CASE WHEN t.OPEN_FC IS NOT NULL OR t.IN_FC IS NOT NULL
                    THEN (COALESCE(t.OPEN_FC, 0) + COALESCE(t.IN_FC, 0)) / NULLIF(t.PERIOD_AVAILABLE_FC_QTY, 0) END
                WHEN 'MONTH_AVERAGE' THEN t.MONTH_AVAILABLE_FC / NULLIF(t.MONTH_AVAILABLE_FC_QTY, 0) END,
            NULL, NULL
        FROM totals t CROSS JOIN summary_types s
    )
    SELECT ROW_KEY AS __ROW_KEY, PARENT_KEY AS __PARENT_ROW_KEY, ROW_TYPE AS __ROW_TYPE,
        ROW_LEVEL AS __ROW_LEVEL,
        ROW_NUMBER() OVER (ORDER BY DIMENSION_CD, PRODUCT_GROUP, SECTION_SORT, LINE_SORT, ROW_KEY) AS __ROW_SORT,
        p_COMPANY_CD AS __COMPANY_CD, SOURCE_ID AS __CHIT_ID, SOURCE_TYPE AS __CHIT_TYPE,
        DESCRIPTION, DOCUMENT_NO, DOCUMENT_DATE, DOCUMENT_DATE AS ENTRY_DATE,
        PRODUCT_CD, PRODUCT_NAME, UNIT_NAME, STORE_CD, STORE_NAME, ACCOUNT_CD, ACCOUNT_NAME, COUNTERPART_ACCOUNT,
        UNIT_PRICE, UNIT_PRICE_FC, OPENING_QUANTITY, OPENING_AMOUNT, OPENING_AMOUNT_FC,
        INPUT_QUANTITY, INPUT_AMOUNT, INPUT_AMOUNT_FC, OUTPUT_QUANTITY, OUTPUT_AMOUNT, OUTPUT_AMOUNT_FC,
        BALANCE_QUANTITY, BALANCE_AMOUNT, BALANCE_AMOUNT_FC, AVERAGE_PRICE, AVERAGE_PRICE_FC
    FROM report_rows
    ORDER BY __ROW_SORT;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.save_exchange_revaluation_result
DROP PROCEDURE IF EXISTS `save_exchange_revaluation_result`;
DELIMITER //
CREATE PROCEDURE `save_exchange_revaluation_result`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_MODULE_CD VARCHAR(10),
    IN p_RATE_DATE DATE,
    IN p_FC_TYPE VARCHAR(255),
    IN p_CHIT_YMD_FROM VARCHAR(8),
    IN p_CHIT_YMD_TO VARCHAR(8),
    IN p_CREATE_BY VARCHAR(50)
)
BEGIN
    DECLARE v_first_result_id BIGINT DEFAULT 0;
    DECLARE v_saved_count INT DEFAULT 0;
    DROP TEMPORARY TABLE IF EXISTS tmp_filter_fc_type;
    CREATE TEMPORARY TABLE tmp_filter_fc_type (
      CD VARCHAR(64) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    IF IFNULL(TRIM(IFNULL(p_FC_TYPE, '')), '') <> '' AND UPPER(IFNULL(TRIM(IFNULL(p_FC_TYPE, '')), '')) NOT IN ('ALL', '*') THEN
      SELECT DISTINCT TRIM(jt.val)
      FROM JSON_TABLE(
        CONCAT('["', REPLACE(REPLACE(REPLACE(TRIM(IFNULL(p_FC_TYPE, '')), '|', ','), ' ', ''), ',', '","'), '"]'),
        '$[*]' COLUMNS (val VARCHAR(64) PATH '$')
      ) jt
      WHERE NULLIF(TRIM(jt.val), '') IS NOT NULL
        AND UPPER(TRIM(jt.val)) NOT IN ('ALL', '*');
    END IF;

DROP TEMPORARY TABLE IF EXISTS tmp_exchange_revaluation_result;
    CREATE TEMPORARY TABLE tmp_exchange_revaluation_result (
        MODULE_CD VARCHAR(10) NOT NULL,
        COMPANY_CD VARCHAR(20) NOT NULL,
        CHIT_ID BIGINT(20) NOT NULL,
        CHITDETAIL_ID BIGINT(20) NOT NULL,
        RATE_DATE DATE NOT NULL,
        CHIT_CD VARCHAR(50) NULL,
        CHIT_NO VARCHAR(50) NULL,
        CHIT_YMD VARCHAR(8) NULL,
        CHIT_TYPE VARCHAR(20) NULL,
        CHITDETAIL_CD VARCHAR(50) NULL,
        DEBIT VARCHAR(20) NULL,
        CREDIT VARCHAR(20) NULL,
        FC_TYPE VARCHAR(10) NOT NULL,
        FC_AMOUNT DECIMAL(18,2) NOT NULL,
        OLD_RATE DECIMAL(18,6) NOT NULL,
        NEW_RATE DECIMAL(18,6) NOT NULL,
        OLD_AMOUNT DECIMAL(18,2) NOT NULL,
        NEW_AMOUNT DECIMAL(18,2) NOT NULL,
        EXCHANGE_DIFF DECIMAL(18,2) NOT NULL,
        DIFF_TYPE VARCHAR(20) NOT NULL,
        PRIMARY KEY (COMPANY_CD, CHITDETAIL_ID)
    ) ENGINE=InnoDB;

        MODULE_CD,
        COMPANY_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        RATE_DATE,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        NEW_RATE,
        OLD_AMOUNT,
        NEW_AMOUNT,
        EXCHANGE_DIFF,
        DIFF_TYPE
    )
    SELECT
        UPPER(IFNULL(h.INPUT_TYPE, '')),
        h.COMPANY_CD,
        h.CHIT_ID,
        d.CHITDETAIL_ID,
        p_RATE_DATE,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_TYPE,
        d.CHITDETAIL_CD,
        d.DEBIT,
        d.CREDIT,
        IFNULL(d.FC_TYPE, ''),
        IFNULL(d.FC_AMOUNT, 0),
        IFNULL(d.FC_RATE, 0),
        IFNULL(d.FC_RATE, 0),
        IFNULL(d.AMOUNT, 0),
        CAST(IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0) AS DECIMAL(18,2)),
        CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)),
        CASE
            WHEN CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) > 0 THEN 'GAIN'
            WHEN CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) < 0 THEN 'LOSS'
            ELSE 'NONE'
        END
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND UPPER(IFNULL(h.INPUT_TYPE, '')) IN ('AR', 'AP')
      AND (IFNULL(p_MODULE_CD, '') = '' OR UPPER(p_MODULE_CD) = 'ALL' OR UPPER(IFNULL(h.INPUT_TYPE, '')) = UPPER(p_MODULE_CD))
      AND (IFNULL(p_FC_TYPE, '') = '' OR EXISTS (SELECT 1 FROM tmp_filter_fc_type f WHERE f.CD = (TRIM(IFNULL(d.FC_TYPE, '')))))
      AND (IFNULL(p_CHIT_YMD_FROM, '') = '' OR IFNULL(h.CHIT_YMD, '') >= p_CHIT_YMD_FROM)
      AND (IFNULL(p_CHIT_YMD_TO, '') = '' OR IFNULL(h.CHIT_YMD, '') <= p_CHIT_YMD_TO)
      AND IFNULL(d.FC_AMOUNT, 0) <> 0
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0';

        COMPANY_CD,
        MODULE_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        RATE_DATE,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        NEW_RATE,
        OLD_AMOUNT,
        NEW_AMOUNT,
        EXCHANGE_DIFF,
        DIFF_TYPE,
        CREATE_BY
    )
    SELECT
        COMPANY_CD,
        MODULE_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        RATE_DATE,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        NEW_RATE,
        OLD_AMOUNT,
        NEW_AMOUNT,
        EXCHANGE_DIFF,
        DIFF_TYPE,
        p_CREATE_BY
    FROM tmp_exchange_revaluation_result;

    SET v_first_result_id = LAST_INSERT_ID();
    SET v_saved_count = ROW_COUNT();

    UPDATE chitdetailinfo d
    INNER JOIN tmp_exchange_revaluation_result r
        ON d.COMPANY_CD = r.COMPANY_CD
       AND d.CHITDETAIL_ID = r.CHITDETAIL_ID
    SET d.AMOUNT = r.NEW_AMOUNT,
        d.UPDATE_BY = p_CREATE_BY,
        d.UPDATE_AT = NOW()
    WHERE IFNULL(d.ISDEL, '0') = '0';

    UPDATE chitinfo h
    INNER JOIN (
        SELECT
            d.COMPANY_CD,
            d.CHIT_ID,
            SUM(IFNULL(d.AMOUNT, 0)) AS HEADER_AMOUNT
        FROM chitdetailinfo d
        INNER JOIN (
            SELECT DISTINCT COMPANY_CD, CHIT_ID
            FROM tmp_exchange_revaluation_result
        ) affected
            ON affected.COMPANY_CD = d.COMPANY_CD
           AND affected.CHIT_ID = d.CHIT_ID
        WHERE IFNULL(d.ISDEL, '0') = '0'
        GROUP BY d.COMPANY_CD, d.CHIT_ID
    ) x
        ON h.COMPANY_CD = x.COMPANY_CD
       AND h.CHIT_ID = x.CHIT_ID
    SET h.AMOUNT = x.HEADER_AMOUNT,
        h.UPDATE_BY = p_CREATE_BY,
        h.UPDATE_AT = NOW()
    WHERE IFNULL(h.ISDEL, '0') = '0';

    SELECT
        r.RESULT_ID,
        r.COMPANY_CD,
        r.MODULE_CD,
        r.CHIT_ID,
        r.CHITDETAIL_ID,
        r.CHIT_CD,
        r.CHIT_NO,
        r.CHIT_YMD,
        r.CHIT_TYPE,
        r.CHITDETAIL_CD,
        r.DEBIT,
        r.CREDIT,
        r.FC_TYPE,
        DATE_FORMAT(r.RATE_DATE, '%Y-%m-%d') AS RATE_DATE,
        r.FC_AMOUNT,
        r.OLD_RATE,
        r.NEW_RATE,
        r.OLD_AMOUNT,
        r.NEW_AMOUNT,
        r.EXCHANGE_DIFF,
        r.DIFF_TYPE,
        r.CREATE_BY,
        r.CREATE_AT
    FROM exchange_revaluation_result r
    WHERE v_saved_count > 0
      AND r.RESULT_ID >= v_first_result_id
      AND r.RESULT_ID < v_first_result_id + v_saved_count
      AND IFNULL(r.ISDEL, '0') = '0'
    ORDER BY r.RESULT_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_exchange_revaluation_result;
END//
DELIMITER ;

