-- Dumping structure for procedure am_web_manager.seed_sys_grid_column_default
DROP PROCEDURE IF EXISTS `seed_sys_grid_column_default`;
DELIMITER //
CREATE PROCEDURE `seed_sys_grid_column_default`(
  IN p_GRID_ID VARCHAR(100),
  IN p_FIELD_NAME VARCHAR(100),
  IN p_LABEL_TEXT VARCHAR(100),
  IN p_CAPTION VARCHAR(255),
  IN p_IS_VISIBLE CHAR(1),
  IN p_VISIBLE_INDEX INT,
  IN p_COLUMN_WIDTH INT,
  IN p_IS_FIXED CHAR(1),
  IN p_FIXED_POSITION VARCHAR(10),
  IN p_ALLOW_HIDING CHAR(1),
  IN p_SORT_ORDER VARCHAR(10),
  IN p_SORT_INDEX INT,
  IN p_UPDATE_BY VARCHAR(50)
)
BEGIN
  DECLARE v_grid_id VARCHAR(100);
  DECLARE v_field_name VARCHAR(100);
  DECLARE v_label_text VARCHAR(100);
  DECLARE v_caption VARCHAR(255);
  DECLARE v_is_visible CHAR(1);
  DECLARE v_visible_index INT;
  DECLARE v_column_width INT;
  DECLARE v_is_fixed CHAR(1);
  DECLARE v_fixed_position VARCHAR(10);
  DECLARE v_allow_hiding CHAR(1);
  DECLARE v_sort_order VARCHAR(10);
  DECLARE v_sort_index INT;
  DECLARE v_update_by VARCHAR(50);
  DECLARE v_existing_id BIGINT;

  SET v_grid_id = TRIM(COALESCE(p_GRID_ID, ''));
  SET v_field_name = TRIM(COALESCE(p_FIELD_NAME, ''));
  SET v_label_text = NULLIF(TRIM(COALESCE(p_LABEL_TEXT, '')), '');
  IF v_label_text IS NULL THEN
    SET v_label_text = NULLIF(v_field_name, '');
  END IF;
  SET v_caption = TRIM(COALESCE(p_CAPTION, ''));
  SET v_is_visible = IF(COALESCE(p_IS_VISIBLE, '1') = '0', '0', '1');
  SET v_visible_index = p_VISIBLE_INDEX;
  SET v_column_width = p_COLUMN_WIDTH;
  IF v_column_width IS NOT NULL AND v_column_width <= 0 THEN
    SET v_column_width = NULL;
  END IF;
  SET v_is_fixed = IF(COALESCE(p_IS_FIXED, '0') = '1', '1', '0');
  SET v_fixed_position = LOWER(NULLIF(TRIM(COALESCE(p_FIXED_POSITION, '')), ''));
  SET v_allow_hiding = IF(COALESCE(p_ALLOW_HIDING, '1') = '0', '0', '1');
  SET v_sort_order = LOWER(NULLIF(TRIM(COALESCE(p_SORT_ORDER, '')), ''));
  SET v_sort_index = p_SORT_INDEX;
  SET v_update_by = NULLIF(TRIM(COALESCE(p_UPDATE_BY, '')), '');

  IF v_update_by IS NULL THEN
    SET v_update_by = 'SYSTEM';
  END IF;

  IF v_grid_id = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GRID_ID is required';
  END IF;

  IF v_fixed_position NOT IN ('left', 'right') THEN
    SET v_fixed_position = NULL;
  END IF;

  IF v_is_fixed = '0' THEN
    SET v_fixed_position = NULL;
  END IF;

  IF v_sort_order NOT IN ('asc', 'desc') THEN
    SET v_sort_order = NULL;
  END IF;

  IF v_field_name <> '' THEN
    SET v_existing_id = NULL;

    SELECT ID
      INTO v_existing_id
    FROM sys_grid_column
    WHERE GRID_ID = v_grid_id
      AND FIELD_NAME = v_field_name
      AND ISDEL = '0'
    LIMIT 1;

    IF v_existing_id IS NULL THEN
        GRID_ID, FIELD_NAME, LABEL_TEXT, CAPTION,
        IS_VISIBLE, VISIBLE_INDEX, COLUMN_WIDTH, IS_FIXED, FIXED_POSITION,
        ALLOW_HIDING, ALIGN, FORMAT_TYPE, SORT_ORDER, SORT_INDEX,
        CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT, ISDEL
      )
      VALUES
      (
        v_grid_id, v_field_name, v_label_text, v_caption,
        v_is_visible, v_visible_index, COALESCE(v_column_width, 120), v_is_fixed, v_fixed_position,
        v_allow_hiding, NULL, NULL, v_sort_order, v_sort_index,
        v_update_by, NOW(), v_update_by, NOW(), '0'
      );
    ELSE
      UPDATE sys_grid_column
      SET
        LABEL_TEXT = IF(LABEL_TEXT IS NULL OR TRIM(LABEL_TEXT) = '', v_label_text, LABEL_TEXT),
        COLUMN_WIDTH = IF(COLUMN_WIDTH IS NULL OR COLUMN_WIDTH <= 0, COALESCE(v_column_width, 120), COLUMN_WIDTH),
        UPDATE_BY = v_update_by,
        UPDATE_AT = NOW()
      WHERE ID = v_existing_id
        AND (
          LABEL_TEXT IS NULL
          OR TRIM(LABEL_TEXT) = ''
          OR COLUMN_WIDTH IS NULL
          OR COLUMN_WIDTH <= 0
        );
    END IF;
  END IF;

  SELECT
    c.ID,
    c.GRID_ID,
    c.FIELD_NAME,
    c.LABEL_TEXT,
    c.CAPTION,
    c.IS_VISIBLE,
    c.VISIBLE_INDEX,
    c.COLUMN_WIDTH,
    c.IS_FIXED,
    c.FIXED_POSITION,
    c.ALLOW_HIDING,
    c.ALIGN,
    c.FORMAT_TYPE,
    c.SORT_ORDER,
    c.SORT_INDEX
  FROM sys_grid_column c
  WHERE c.GRID_ID = v_grid_id
    AND c.ISDEL = '0'
  ORDER BY CASE WHEN c.VISIBLE_INDEX IS NULL THEN 1 ELSE 0 END, c.VISIBLE_INDEX, c.FIELD_NAME;
END//
DELIMITER ;

