    IN p_WIDTH INT,
    IN p_WIDTH_PERCENT DECIMAL(5,2),
    IN p_ALIGN_HEADER VARCHAR(20),
    IN p_ALIGN_DATA VARCHAR(20),
    IN p_ALIGN VARCHAR(20),
    IN p_DATA_TYPE VARCHAR(50),
    IN p_FORMAT_STRING VARCHAR(50),
    IN p_IS_SUMMARY CHAR(1),
    IN p_SUMMARY_TYPE VARCHAR(20),
    IN p_FONT_SIZE DECIMAL(5,2),
    IN p_IS_BOLD CHAR(1),
    IN p_IS_ITALIC CHAR(1),
    IN p_IS_VISIBLE CHAR(1)
)
BEGIN
    DECLARE v_id BIGINT DEFAULT NULL;

    IF IFNULL(p_ID, 0) > 0 THEN
        SET v_id = p_ID;
    ELSE
        SELECT ID
          INTO v_id
        FROM company_report_element
        WHERE COMPANY_CD = TRIM(IFNULL(p_COMPANY_CD, ''))
          AND REPORT_KEY = TRIM(p_REPORT_KEY)
          AND SECTION_TYPE = TRIM(p_SECTION_TYPE)
          AND ITEM_KEY = TRIM(p_ITEM_KEY)
        ORDER BY ID DESC
        LIMIT 1;
    END IF;

    IF v_id IS NULL THEN
            COMPANY_CD,
            REPORT_KEY,
            SECTION_TYPE,
            ELEMENT_TYPE,
            AREA_CODE,
            ITEM_KEY,
            LABEL_TEXT,
            CAPTION,
            VALUE_SOURCE,
            VALUE_FIELD,
            ROW_NO,
            COL_NO,
            COL_SPAN,
            SORT_ORDER,
            VISIBLE_INDEX,
            WIDTH,
            WIDTH_PERCENT,
            ALIGN_HEADER,
            ALIGN_DATA,
            ALIGN,
            DATA_TYPE,
            FORMAT_STRING,
            IS_SUMMARY,
            SUMMARY_TYPE,
            FONT_SIZE,
            IS_BOLD,
            IS_ITALIC,
            IS_VISIBLE,
            ISDEL,
            CREATE_AT,
            UPDATE_AT
        )
        VALUES
        (
            TRIM(IFNULL(p_COMPANY_CD, '')),
            TRIM(p_REPORT_KEY),
            TRIM(p_SECTION_TYPE),
            TRIM(p_ELEMENT_TYPE),
            IFNULL(NULLIF(TRIM(IFNULL(p_AREA_CODE, '')), ''), 'LEFT'),
            TRIM(p_ITEM_KEY),
            NULLIF(TRIM(IFNULL(p_LABEL_TEXT, '')), ''),
            NULLIF(TRIM(IFNULL(p_CAPTION, '')), ''),
            IFNULL(NULLIF(TRIM(IFNULL(p_VALUE_SOURCE, '')), ''), 'FIXED_TEXT'),
            NULLIF(TRIM(IFNULL(p_VALUE_FIELD, '')), ''),
            IFNULL(p_ROW_NO, 1),
            IFNULL(p_COL_NO, 1),
            IFNULL(p_COL_SPAN, 1),
            IFNULL(p_SORT_ORDER, 0),
            p_VISIBLE_INDEX,
            p_WIDTH,
            p_WIDTH_PERCENT,
            IFNULL(NULLIF(TRIM(IFNULL(p_ALIGN_HEADER, '')), ''), 'CENTER'),
            IFNULL(NULLIF(TRIM(IFNULL(p_ALIGN_DATA, '')), ''), 'LEFT'),
            IFNULL(NULLIF(TRIM(IFNULL(p_ALIGN, '')), ''), 'LEFT'),
            IFNULL(NULLIF(TRIM(IFNULL(p_DATA_TYPE, '')), ''), 'TEXT'),
            NULLIF(TRIM(IFNULL(p_FORMAT_STRING, '')), ''),
            IFNULL(NULLIF(TRIM(IFNULL(p_IS_SUMMARY, '')), ''), '0'),
            NULLIF(TRIM(IFNULL(p_SUMMARY_TYPE, '')), ''),
            p_FONT_SIZE,
            IFNULL(NULLIF(TRIM(IFNULL(p_IS_BOLD, '')), ''), '0'),
            IFNULL(NULLIF(TRIM(IFNULL(p_IS_ITALIC, '')), ''), '0'),
            IFNULL(NULLIF(TRIM(IFNULL(p_IS_VISIBLE, '')), ''), '1'),
            '0',
            NOW(),
            NOW()
        );
    ELSE
        UPDATE company_report_element
        SET
            COMPANY_CD = TRIM(IFNULL(p_COMPANY_CD, '')),
            REPORT_KEY = TRIM(p_REPORT_KEY),
            SECTION_TYPE = TRIM(p_SECTION_TYPE),
            ELEMENT_TYPE = TRIM(p_ELEMENT_TYPE),
            AREA_CODE = IFNULL(NULLIF(TRIM(IFNULL(p_AREA_CODE, '')), ''), 'LEFT'),
            ITEM_KEY = TRIM(p_ITEM_KEY),
            LABEL_TEXT = NULLIF(TRIM(IFNULL(p_LABEL_TEXT, '')), ''),
            CAPTION = NULLIF(TRIM(IFNULL(p_CAPTION, '')), ''),
            VALUE_SOURCE = IFNULL(NULLIF(TRIM(IFNULL(p_VALUE_SOURCE, '')), ''), 'FIXED_TEXT'),
            VALUE_FIELD = NULLIF(TRIM(IFNULL(p_VALUE_FIELD, '')), ''),
            ROW_NO = IFNULL(p_ROW_NO, 1),
            COL_NO = IFNULL(p_COL_NO, 1),
            COL_SPAN = IFNULL(p_COL_SPAN, 1),
            SORT_ORDER = IFNULL(p_SORT_ORDER, 0),
            VISIBLE_INDEX = p_VISIBLE_INDEX,
            WIDTH = p_WIDTH,
            WIDTH_PERCENT = p_WIDTH_PERCENT,
            ALIGN_HEADER = IFNULL(NULLIF(TRIM(IFNULL(p_ALIGN_HEADER, '')), ''), 'CENTER'),
            ALIGN_DATA = IFNULL(NULLIF(TRIM(IFNULL(p_ALIGN_DATA, '')), ''), 'LEFT'),
            ALIGN = IFNULL(NULLIF(TRIM(IFNULL(p_ALIGN, '')), ''), 'LEFT'),
            DATA_TYPE = IFNULL(NULLIF(TRIM(IFNULL(p_DATA_TYPE, '')), ''), 'TEXT'),
            FORMAT_STRING = NULLIF(TRIM(IFNULL(p_FORMAT_STRING, '')), ''),
            IS_SUMMARY = IFNULL(NULLIF(TRIM(IFNULL(p_IS_SUMMARY, '')), ''), '0'),
            SUMMARY_TYPE = NULLIF(TRIM(IFNULL(p_SUMMARY_TYPE, '')), ''),
            FONT_SIZE = p_FONT_SIZE,
            IS_BOLD = IFNULL(NULLIF(TRIM(IFNULL(p_IS_BOLD, '')), ''), '0'),
            IS_ITALIC = IFNULL(NULLIF(TRIM(IFNULL(p_IS_ITALIC, '')), ''), '0'),
            IS_VISIBLE = IFNULL(NULLIF(TRIM(IFNULL(p_IS_VISIBLE, '')), ''), '1'),
            ISDEL = '0',
            UPDATE_AT = NOW()
        WHERE ID = v_id;
    END IF;
END//
