            NULLIF(TRIM(IFNULL(p_DATA_SOURCE_REF, '')), ''),
            NULLIF(TRIM(IFNULL(p_DATA_SET_NAME, '')), ''),
            IFNULL(NULLIF(TRIM(IFNULL(p_PARAM_MODE, '')), ''), 'QUERYSTRING'),
            IFNULL(NULLIF(TRIM(IFNULL(p_IS_ACTIVE, '')), ''), '1'),
