-- Dumping structure for procedure am_web_manager.set_sys_user_permission
DROP PROCEDURE IF EXISTS `set_sys_user_permission`;
DELIMITER //
CREATE PROCEDURE `set_sys_user_permission`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USERID VARCHAR(50),
  IN p_MENU_CODE VARCHAR(50),
  IN p_CAN_VIEW CHAR(1),
  IN p_CAN_ADD CHAR(1),
  IN p_CAN_EDIT CHAR(1),
  IN p_CAN_DELETE CHAR(1),
  IN p_CAN_PRINT CHAR(1),
  IN p_CAN_EXPORT CHAR(1),
  IN p_CAN_IMPORT CHAR(1),
  IN p_CAN_APPROVE CHAR(1),
  IN p_USERID_MODIFY VARCHAR(50)
)
BEGIN
  DECLARE v_menu_allowed BOOLEAN DEFAULT FALSE;
  SET p_COMPANY_CD = TRIM(p_COMPANY_CD);
  SET p_USERID = TRIM(p_USERID);
  IF NULLIF(TRIM(p_COMPANY_CD), '') IS NULL OR NULLIF(TRIM(p_USERID), '') IS NULL
     OR NULLIF(TRIM(p_MENU_CODE), '') IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Company, user and menu are required; default is managed separately';
  END IF;
  IF NOT EXISTS (
      SELECT 1 FROM user_company uc
      INNER JOIN user_info ui ON ui.USER_PK_ID = uc.USER_PK_ID
      WHERE uc.COMPANY_CD = TRIM(p_COMPANY_CD) AND uc.USERID = TRIM(p_USERID)
        AND uc.IS_ACTIVE = '1' AND uc.ISDEL = '0'
        AND ui.IS_ACTIVE = '1' AND ui.ISDEL = '0'
    ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Target user has no active company access';
  END IF;
  WITH RECURSIVE eligible AS (
    SELECT
        m.MENU_ID,
        m.MENU_CODE,
        m.MENU_NAME,
        NULLIF(TRIM(m.LABEL_TEXT), '') AS LABEL_TEXT,
        COALESCE(NULLIF(TRIM(m.CAPTION), ''), m.MENU_NAME) AS CAPTION,
        m.PARENT_ID,
        m.ROUTE_PATH,
        m.ICON,
        m.SORT_ORDER,
        m.IS_ACTIVE,
        CASE WHEN company_setting.ID IS NOT NULL
            THEN company_setting.IS_VISIBLE ELSE default_setting.IS_VISIBLE END AS IS_VISIBLE,
        CASE WHEN company_setting.ID IS NOT NULL
            THEN company_setting.IS_DISABLED ELSE default_setting.IS_DISABLED END AS IS_DISABLED
    FROM sys_menu m
    LEFT JOIN company_info company
        ON company.COMPANY_CD = p_COMPANY_CD
    LEFT JOIN sys_menu_company company_setting
        ON company_setting.MENU_ID = m.MENU_ID
       AND company_setting.COMPANY_CD = p_COMPANY_CD
    LEFT JOIN sys_menu_company default_setting
        ON default_setting.MENU_ID = m.MENU_ID
       AND default_setting.COMPANY_CD = ''
    -- Choose by row existence: a hidden/NULL company setting must not inherit default values.
    WHERE p_COMPANY_CD IS NOT NULL
      AND (
          p_COMPANY_CD = ''
          OR company.MENU_MODE = 'ALL'
          OR (company.MENU_MODE IN ('INVOICE', 'AMNOTE')
              AND (m.PRODUCT_SCOPE = 'COMMON' OR m.PRODUCT_SCOPE = company.MENU_MODE))
      )
      AND (company_setting.ID IS NOT NULL OR default_setting.ID IS NOT NULL)
      AND m.IS_ACTIVE = 1
      AND CASE WHEN company_setting.ID IS NOT NULL
          THEN company_setting.IS_VISIBLE ELSE default_setting.IS_VISIBLE END = 1
    ), reachable AS (
        SELECT root.* FROM eligible root WHERE root.PARENT_ID IS NULL
        UNION ALL
        SELECT child.*
        FROM eligible child
        INNER JOIN reachable parent ON child.PARENT_ID = parent.MENU_ID
    )
  SELECT EXISTS (
    SELECT 1 FROM reachable m
    INNER JOIN sys_user_permission def ON CONVERT(def.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(m.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci
      AND def.COMPANY_CD = '' AND def.USERID = '' AND def.ISDEL = '0'
    WHERE CONVERT(m.MENU_CODE USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(TRIM(p_MENU_CODE) USING utf8mb4) COLLATE utf8mb4_unicode_ci
      AND m.IS_DISABLED = 0
  ) INTO v_menu_allowed;
  IF NOT v_menu_allowed THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Menu is unavailable for company or canonical default is missing';
  END IF;
  IF COALESCE(p_CAN_VIEW, '0') NOT IN ('0', '1') OR COALESCE(p_CAN_ADD, '0') NOT IN ('0', '1') OR COALESCE(p_CAN_EDIT, '0') NOT IN ('0', '1') OR COALESCE(p_CAN_DELETE, '0') NOT IN ('0', '1') OR COALESCE(p_CAN_PRINT, '0') NOT IN ('0', '1') OR COALESCE(p_CAN_EXPORT, '0') NOT IN ('0', '1') OR COALESCE(p_CAN_IMPORT, '0') NOT IN ('0', '1') OR COALESCE(p_CAN_APPROVE, '0') NOT IN ('0', '1') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Permission flags must be 0 or 1';
  END IF;

    COMPANY_CD,
    USERID,
    MENU_CODE,
    CAN_VIEW,
    CAN_ADD,
    CAN_EDIT,
    CAN_DELETE,
    CAN_PRINT,
    CAN_EXPORT,
    CAN_IMPORT,
    CAN_APPROVE,
    USERID_INPUT,
    INPUT_YMD,
    USERID_MODIFY,
    MODIFY_YMD,
    ISDEL
  )
  VALUES
  (
    TRIM(p_COMPANY_CD),
    TRIM(p_USERID),
    TRIM(p_MENU_CODE),
    COALESCE(p_CAN_VIEW, '0'),
    COALESCE(p_CAN_ADD, '0'),
    COALESCE(p_CAN_EDIT, '0'),
    COALESCE(p_CAN_DELETE, '0'),
    COALESCE(p_CAN_PRINT, '0'),
    COALESCE(p_CAN_EXPORT, '0'),
    COALESCE(p_CAN_IMPORT, '0'),
    COALESCE(p_CAN_APPROVE, '0'),
    p_USERID_MODIFY,
    NOW(),
    p_USERID_MODIFY,
    NOW(),
    '0'
  )
  AS incoming
  ON DUPLICATE KEY UPDATE
    CAN_VIEW = incoming.CAN_VIEW,
    CAN_ADD = incoming.CAN_ADD,
    CAN_EDIT = incoming.CAN_EDIT,
    CAN_DELETE = incoming.CAN_DELETE,
    CAN_PRINT = incoming.CAN_PRINT,
    CAN_EXPORT = incoming.CAN_EXPORT,
    CAN_IMPORT = incoming.CAN_IMPORT,
    CAN_APPROVE = incoming.CAN_APPROVE,
    USERID_MODIFY = incoming.USERID_MODIFY,
    MODIFY_YMD = NOW(),
    ISDEL = '0';
END//
DELIMITER ;

