-- Dumping structure for procedure am_web_manager.setCompanySignatureInfo
DROP PROCEDURE IF EXISTS `setCompanySignatureInfo`;
DELIMITER //
CREATE PROCEDURE `setCompanySignatureInfo`(
  IN p_ID BIGINT(20),
  IN p_COMPANY_CD VARCHAR(20),
  IN p_SIGN_CODE VARCHAR(50),
  IN p_DISPLAY_LABEL VARCHAR(255),
  IN p_SIGN_NAME VARCHAR(255),
  IN p_SIGN_TITLE VARCHAR(255),
  IN p_SIGN_IMAGE_URL VARCHAR(500),
  IN p_SORT_ORDER INT,
  IN p_IS_ACTIVE CHAR(1),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_sign_code VARCHAR(50);
  DECLARE v_sign_name VARCHAR(255);
  DECLARE v_display_label VARCHAR(255);
  DECLARE v_existing_id BIGINT(20) DEFAULT NULL;
  DECLARE v_source_company_cd VARCHAR(20) DEFAULT NULL;
  DECLARE v_next_num INT DEFAULT 0;
  DECLARE v_target_id BIGINT(20) DEFAULT NULL;
    SET v_display_label = NULLIF(TRIM(COALESCE(p_DISPLAY_LABEL, '')), '');
  SET v_sign_name = TRIM(COALESCE(p_SIGN_NAME, ''));

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'COMPANY_CD is required for company signature changes';
  END IF;

  IF v_display_label IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'DISPLAY_LABEL is required';
  END IF;

  IF p_ID IS NOT NULL AND p_ID > 0 THEN
    SELECT COMPANY_CD, SIGN_CODE
      INTO v_source_company_cd, v_sign_code
    FROM company_signature_info
    WHERE ID = p_ID
      AND COMPANY_CD IN (p_COMPANY_CD, '')
    LIMIT 1
    FOR UPDATE;

    IF v_sign_code IS NULL OR v_sign_code = '' THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Signature not found';
    END IF;

    IF v_source_company_cd = p_COMPANY_CD THEN
      SET v_target_id = p_ID;
    ELSE
      -- Reuse an existing override if another autosave request already created it.
      SELECT ID INTO v_existing_id
      FROM company_signature_info
      WHERE COMPANY_CD = p_COMPANY_CD
        AND SIGN_CODE = v_sign_code
      LIMIT 1
      FOR UPDATE;

      IF v_existing_id IS NOT NULL THEN
        SET v_target_id = v_existing_id;
      ELSE
          COMPANY_CD, SIGN_CODE, DISPLAY_LABEL, SIGN_NAME, SIGN_TITLE,
          SIGN_IMAGE_URL, SORT_ORDER, IS_ACTIVE,
          CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
        )
        VALUES
        (
          p_COMPANY_CD, v_sign_code, v_display_label, v_sign_name,
          NULLIF(TRIM(COALESCE(p_SIGN_TITLE, '')), ''),
          NULLIF(TRIM(COALESCE(p_SIGN_IMAGE_URL, '')), ''),
          CASE WHEN p_SORT_ORDER IS NULL OR p_SORT_ORDER <= 0 THEN 0 ELSE p_SORT_ORDER END,
          COALESCE(p_IS_ACTIVE, '1'),
          p_USERID, NOW(), p_USERID, NOW()
        );
        SET v_target_id = LAST_INSERT_ID();
      END IF;
    END IF;

    IF v_source_company_cd = p_COMPANY_CD OR v_existing_id IS NOT NULL THEN
      UPDATE company_signature_info
      SET
        DISPLAY_LABEL = v_display_label,
        SIGN_NAME = v_sign_name,
        SIGN_TITLE = NULLIF(TRIM(COALESCE(p_SIGN_TITLE, '')), ''),
        SIGN_IMAGE_URL = NULLIF(TRIM(COALESCE(p_SIGN_IMAGE_URL, '')), ''),
        SORT_ORDER = CASE
          WHEN p_SORT_ORDER IS NULL OR p_SORT_ORDER <= 0 THEN SORT_ORDER
          ELSE p_SORT_ORDER
        END,
        IS_ACTIVE = COALESCE(p_IS_ACTIVE, '1'),
        UPDATE_BY = p_USERID,
        UPDATE_AT = NOW()
      WHERE COMPANY_CD = p_COMPANY_CD
        AND ID = v_target_id;
    END IF;
  ELSE
    SELECT GREATEST(COALESCE(MAX(CAST(SIGN_CODE AS UNSIGNED)), 0), 6) + 1
      INTO v_next_num
    FROM company_signature_info
    WHERE COMPANY_CD IN (p_COMPANY_CD, '')
      AND SIGN_CODE REGEXP '^[0-9]+$';

    SET v_sign_code = CASE
      WHEN v_next_num < 100 THEN LPAD(v_next_num, 2, '0')
      ELSE CAST(v_next_num AS CHAR(50))
    END;

    -- Never reuse a deleted code still referenced by a report, including inactive mappings.
    WHILE EXISTS (
      SELECT 1
      FROM company_report_mapping crm
      INNER JOIN JSON_TABLE(
        CONCAT('["', REPLACE(REPLACE(REPLACE(IFNULL(crm.SIGN_IDS, ''), '|', ','), ' ', ''), ',', '","'), '"]'),
        '$[*]' COLUMNS (SIGN_CODE VARCHAR(64) PATH '$')
      ) sign_item
        ON sign_item.SIGN_CODE = v_sign_code
      WHERE crm.COMPANY_CD IN (p_COMPANY_CD, '')
    ) DO
      SET v_next_num = v_next_num + 1;
      SET v_sign_code = CASE
        WHEN v_next_num < 100 THEN LPAD(v_next_num, 2, '0')
        ELSE CAST(v_next_num AS CHAR(50))
      END;
    END WHILE;

      COMPANY_CD, SIGN_CODE, DISPLAY_LABEL, SIGN_NAME, SIGN_TITLE,
      SIGN_IMAGE_URL, SORT_ORDER, IS_ACTIVE,
      CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
    )
    VALUES
    (
      p_COMPANY_CD, v_sign_code, v_display_label, v_sign_name,
      NULLIF(TRIM(COALESCE(p_SIGN_TITLE, '')), ''),
      NULLIF(TRIM(COALESCE(p_SIGN_IMAGE_URL, '')), ''),
      CASE WHEN p_SORT_ORDER IS NULL OR p_SORT_ORDER <= 0 THEN v_next_num ELSE p_SORT_ORDER END,
      COALESCE(p_IS_ACTIVE, '1'),
      p_USERID, NOW(), p_USERID, NOW()
    );
    SET v_target_id = LAST_INSERT_ID();
  END IF;

  SELECT COALESCE(v_target_id, 0) AS ID;
END//
DELIMITER ;

