  IN p_COMPANY_CD VARCHAR(20),
  IN p_PBAN VARCHAR(10),
  IN p_MNGUI VARCHAR(20),
  IN p_MNNHAN VARCHAR(20),
  IN p_MLTDIEP VARCHAR(20),
  IN p_MTDIEP VARCHAR(100),
  IN p_MTDTCHIEU VARCHAR(100),
  IN p_MST VARCHAR(14),
  IN p_SLUONG INT,
  IN p_RESPONSE_XML LONGTEXT,
  IN p_ERROR_MESSAGE VARCHAR(1000),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_REF_MTDIEP VARCHAR(100) DEFAULT '';
  DECLARE v_MTRA_CUU VARCHAR(100) DEFAULT '';

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_MTDIEP IS NULL OR TRIM(p_MTDIEP) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MTDIEP is required';
  END IF;

  IF p_RESPONSE_XML IS NULL OR TRIM(p_RESPONSE_XML) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RESPONSE_XML is required';
  END IF;

  SET v_REF_MTDIEP = IFNULL(NULLIF(TRIM(p_MTDTCHIEU), ''), TRIM(p_MTDIEP));
  SET v_MTRA_CUU = IFNULL((
    SELECT TRIM(w.SEND_MTDIEP)
      FROM einvoice_message_work_queue w
     WHERE w.COMPANY_CD = TRIM(p_COMPANY_CD)
       AND w.SEND_MTDIEP = v_REF_MTDIEP
     ORDER BY w.CREATE_AT DESC, w.WORK_ID DESC
     LIMIT 1
  ), v_REF_MTDIEP);

  IF v_MTRA_CUU = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MTRA_CUU is required';
  END IF;

    COMPANY_CD,
    PBAN,
    MNGUI,
    MNNHAN,
    MLTDIEP,
    MTDIEP,
    MTDTCHIEU,
    MTRA_CUU,
    MST,
    SLUONG,
    RESPONSE_XML,
    ERROR_MESSAGE,
    CREATE_BY,
    CREATE_AT
  ) VALUES (
    TRIM(p_COMPANY_CD),
    IFNULL(TRIM(p_PBAN), ''),
    IFNULL(TRIM(p_MNGUI), ''),
    IFNULL(TRIM(p_MNNHAN), ''),
    IFNULL(TRIM(p_MLTDIEP), ''),
    TRIM(p_MTDIEP),
    IFNULL(TRIM(p_MTDTCHIEU), ''),
    v_MTRA_CUU,
    IFNULL(TRIM(p_MST), ''),
    IFNULL(p_SLUONG, 0),
    p_RESPONSE_XML,
    IFNULL(TRIM(p_ERROR_MESSAGE), ''),
    IFNULL(TRIM(p_USERID), ''),
    NOW()
  );

  SELECT LAST_INSERT_ID() AS RECEIVE_ID;
END//
DELIMITER ;

