-- Dumping structure for procedure am_web_manager.setMailSetting
DROP PROCEDURE IF EXISTS `setMailSetting`;
DELIMITER //
CREATE PROCEDURE `setMailSetting`(
  IN p_MAIL_ID BIGINT,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_MAIL_CD VARCHAR(50),
  IN p_MAIL_NM VARCHAR(255),
  IN p_SMTP_HOST VARCHAR(255),
  IN p_SMTP_PORT INT,
  IN p_SECURITY_TYPE VARCHAR(20),
  IN p_AUTH_TYPE VARCHAR(20),
  IN p_USERNAME VARCHAR(255),
  IN p_PASSWORD_ENC TEXT,
  IN p_FROM_EMAIL VARCHAR(255),
  IN p_FROM_NAME VARCHAR(255),
  IN p_REPLY_TO_EMAIL VARCHAR(255),
  IN p_CONFIG_JSON LONGTEXT,
  IN p_IS_DEFAULT TINYINT,
  IN p_IS_ACTIVE TINYINT,
  IN p_USER_ID VARCHAR(50)
)
BEGIN
  DECLARE v_company_cd VARCHAR(20) DEFAULT '';
  DECLARE v_mail_cd VARCHAR(50) DEFAULT 'DEFAULT';
  DECLARE v_mail_id BIGINT DEFAULT 0;

  SET v_company_cd = IFNULL(TRIM(p_COMPANY_CD), '');
  SET v_mail_cd = UPPER(IFNULL(NULLIF(TRIM(p_MAIL_CD), ''), 'DEFAULT'));
  SET v_mail_id = IFNULL(NULLIF(p_MAIL_ID, 0), 0);

  IF v_mail_id > 0 THEN
    UPDATE mail_setting
    SET
      MAIL_NM = IFNULL(p_MAIL_NM, ''),
      SMTP_HOST = IFNULL(p_SMTP_HOST, ''),
      SMTP_PORT = IFNULL(NULLIF(p_SMTP_PORT, 0), 587),
      SECURITY_TYPE = IFNULL(NULLIF(TRIM(p_SECURITY_TYPE), ''), 'STARTTLS'),
      AUTH_TYPE = IFNULL(NULLIF(TRIM(p_AUTH_TYPE), ''), 'PASSWORD'),
      USERNAME = p_USERNAME,
      PASSWORD_ENC = CASE
        WHEN p_PASSWORD_ENC IS NOT NULL AND TRIM(p_PASSWORD_ENC) <> '' THEN p_PASSWORD_ENC
        ELSE PASSWORD_ENC
      END,
      FROM_EMAIL = IFNULL(p_FROM_EMAIL, ''),
      FROM_NAME = p_FROM_NAME,
      REPLY_TO_EMAIL = p_REPLY_TO_EMAIL,
      CONFIG_JSON = p_CONFIG_JSON,
      IS_DEFAULT = IFNULL(p_IS_DEFAULT, 0),
      IS_ACTIVE = IFNULL(p_IS_ACTIVE, 1),
      ISDEL = 0,
      UPDATE_BY = p_USER_ID,
      UPDATE_AT = CURRENT_TIMESTAMP
    WHERE MAIL_ID = v_mail_id
      AND IFNULL(TRIM(COMPANY_CD), '') = v_company_cd
      AND MAIL_CD = v_mail_cd
      AND IFNULL(ISDEL, 0) = 0;

    IF ROW_COUNT() = 0 THEN
      SET v_mail_id = 0;
    END IF;
  END IF;

  IF v_mail_id <= 0 THEN
      COMPANY_CD,
      MAIL_CD,
      MAIL_NM,
      SMTP_HOST,
      SMTP_PORT,
      SECURITY_TYPE,
      AUTH_TYPE,
      USERNAME,
      PASSWORD_ENC,
      FROM_EMAIL,
      FROM_NAME,
      REPLY_TO_EMAIL,
      CONFIG_JSON,
      IS_DEFAULT,
      IS_ACTIVE,
      ISDEL,
      CREATE_BY,
      UPDATE_BY
    )
    VALUES (
      v_company_cd,
      v_mail_cd,
      IFNULL(p_MAIL_NM, ''),
      IFNULL(p_SMTP_HOST, ''),
      IFNULL(NULLIF(p_SMTP_PORT, 0), 587),
      IFNULL(NULLIF(TRIM(p_SECURITY_TYPE), ''), 'STARTTLS'),
      IFNULL(NULLIF(TRIM(p_AUTH_TYPE), ''), 'PASSWORD'),
      p_USERNAME,
      p_PASSWORD_ENC,
      IFNULL(p_FROM_EMAIL, ''),
      p_FROM_NAME,
      p_REPLY_TO_EMAIL,
      p_CONFIG_JSON,
      IFNULL(p_IS_DEFAULT, 0),
      IFNULL(p_IS_ACTIVE, 1),
      0,
      p_USER_ID,
      p_USER_ID
    )
    ON DUPLICATE KEY UPDATE
      MAIL_NM = VALUES(MAIL_NM),
      SMTP_HOST = VALUES(SMTP_HOST),
      SMTP_PORT = VALUES(SMTP_PORT),
      SECURITY_TYPE = VALUES(SECURITY_TYPE),
      AUTH_TYPE = VALUES(AUTH_TYPE),
      USERNAME = VALUES(USERNAME),
      PASSWORD_ENC = CASE
        WHEN VALUES(PASSWORD_ENC) IS NOT NULL AND TRIM(VALUES(PASSWORD_ENC)) <> '' THEN VALUES(PASSWORD_ENC)
        ELSE PASSWORD_ENC
      END,
      FROM_EMAIL = VALUES(FROM_EMAIL),
      FROM_NAME = VALUES(FROM_NAME),
      REPLY_TO_EMAIL = VALUES(REPLY_TO_EMAIL),
      CONFIG_JSON = VALUES(CONFIG_JSON),
      IS_DEFAULT = VALUES(IS_DEFAULT),
      IS_ACTIVE = VALUES(IS_ACTIVE),
      ISDEL = 0,
      UPDATE_BY = VALUES(UPDATE_BY),
      UPDATE_AT = CURRENT_TIMESTAMP;

    SET v_mail_id = LAST_INSERT_ID();
    IF v_mail_id <= 0 THEN
      SELECT MAIL_ID
      INTO v_mail_id
      FROM mail_setting
      WHERE IFNULL(TRIM(COMPANY_CD), '') = v_company_cd
        AND MAIL_CD = v_mail_cd
        AND IFNULL(ISDEL, 0) = 0
      ORDER BY MAIL_ID DESC
      LIMIT 1;
    END IF;
  END IF;

  CALL getMailSetting(v_company_cd, v_mail_cd);
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.setsys_config
DROP PROCEDURE IF EXISTS `setsys_config`;
DELIMITER //
CREATE PROCEDURE `setsys_config`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CONFIG_GROUP VARCHAR(50),
    IN p_CONFIG_KEY VARCHAR(100),
    IN p_CONFIG_VALUE VARCHAR(500),
    IN p_DATA_TYPE VARCHAR(20),
    IN p_DESCRIPTION VARCHAR(255),
    IN p_IS_ACTIVE CHAR(1),
    IN p_UPDATE_BY VARCHAR(50)
)
BEGIN
    DECLARE v_id BIGINT DEFAULT 0;

    SELECT ID
      INTO v_id
    FROM sys_config
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CONFIG_GROUP = p_CONFIG_GROUP
      AND CONFIG_KEY = p_CONFIG_KEY
    LIMIT 1;

    IF IFNULL(v_id, 0) = 0 THEN
            COMPANY_CD,
            CONFIG_GROUP,
            CONFIG_KEY,
            CONFIG_VALUE,
            DATA_TYPE,
            DESCRIPTION,
            IS_ACTIVE,
            ISDEL,
            CREATE_BY,
            CREATE_AT,
            UPDATE_BY,
            UPDATE_AT
        )
        VALUES
        (
            p_COMPANY_CD,
            p_CONFIG_GROUP,
            p_CONFIG_KEY,
            NULLIF(p_CONFIG_VALUE, ''),
            IFNULL(NULLIF(p_DATA_TYPE, ''), 'string'),
            NULLIF(p_DESCRIPTION, ''),
            IFNULL(NULLIF(p_IS_ACTIVE, ''), '1'),
            '0',
            NULLIF(p_UPDATE_BY, ''),
            NOW(),
            NULLIF(p_UPDATE_BY, ''),
            NOW()
        );
    ELSE
        UPDATE sys_config
        SET CONFIG_VALUE = NULLIF(p_CONFIG_VALUE, ''),
            DATA_TYPE = IFNULL(NULLIF(p_DATA_TYPE, ''), DATA_TYPE),
            DESCRIPTION = NULLIF(p_DESCRIPTION, ''),
            IS_ACTIVE = IFNULL(NULLIF(p_IS_ACTIVE, ''), IFNULL(IS_ACTIVE, '1')),
            ISDEL = '0',
            UPDATE_BY = NULLIF(p_UPDATE_BY, ''),
            UPDATE_AT = NOW()
        WHERE ID = v_id;
    END IF;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.setsys_grid_column_setting
DROP PROCEDURE IF EXISTS `setsys_grid_column_setting`;
DELIMITER //
CREATE PROCEDURE `setsys_grid_column_setting`(
  IN p_TEMPLATE_ID BIGINT,
  IN p_GRID_ID VARCHAR(100),
  IN p_FIELD_NAME VARCHAR(100),
  IN p_LABEL_TEXT VARCHAR(100),
  IN p_CAPTION VARCHAR(255),
  IN p_IS_VISIBLE CHAR(1),
  IN p_VISIBLE_INDEX INT,
  IN p_COLUMN_WIDTH INT,
  IN p_IS_FIXED CHAR(1),
  IN p_FIXED_POSITION VARCHAR(10),
  IN p_ALLOW_HIDING CHAR(1),
  IN p_SORT_ORDER VARCHAR(10),
  IN p_SORT_INDEX INT,
  IN p_UPDATE_BY VARCHAR(50)
)
BEGIN
  DECLARE v_template_id BIGINT;
  DECLARE v_grid_id VARCHAR(100);
  DECLARE v_field_name VARCHAR(100);
  DECLARE v_fixed_position VARCHAR(10);
  DECLARE v_sort_order VARCHAR(10);
  DECLARE v_update_by VARCHAR(50);
  DECLARE v_existing_id BIGINT;
  DECLARE v_all_null TINYINT;

  SET v_template_id = COALESCE(p_TEMPLATE_ID, 0);
  SET v_grid_id = TRIM(COALESCE(p_GRID_ID, ''));
  SET v_field_name = TRIM(COALESCE(p_FIELD_NAME, ''));
  SET v_fixed_position = LOWER(TRIM(COALESCE(p_FIXED_POSITION, '')));
  SET v_sort_order = LOWER(TRIM(COALESCE(p_SORT_ORDER, '')));
  SET v_update_by = NULLIF(TRIM(COALESCE(p_UPDATE_BY, '')), '');

  IF v_template_id <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TEMPLATE_ID is required';
  END IF;

  IF v_grid_id = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GRID_ID is required';
  END IF;

  IF v_field_name = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FIELD_NAME is required';
  END IF;

  IF v_fixed_position NOT IN ('', 'left', 'right') THEN
    SET v_fixed_position = '';
  END IF;

  IF v_sort_order NOT IN ('', 'asc', 'desc') THEN
    SET v_sort_order = '';
  END IF;

  SET v_all_null = IF(
    p_LABEL_TEXT IS NULL
    AND p_CAPTION IS NULL
    AND p_IS_VISIBLE IS NULL
    AND p_VISIBLE_INDEX IS NULL
    AND p_COLUMN_WIDTH IS NULL
    AND p_IS_FIXED IS NULL
    AND p_FIXED_POSITION IS NULL
    AND p_ALLOW_HIDING IS NULL
    AND p_SORT_ORDER IS NULL
    AND p_SORT_INDEX IS NULL,
    1, 0
  );

  SET v_existing_id = NULL;

  SELECT ID
    INTO v_existing_id
  FROM sys_grid_column_setting
  WHERE TEMPLATE_ID = v_template_id
    AND GRID_ID = v_grid_id
    AND FIELD_NAME = v_field_name
    AND ISDEL = '0'
  LIMIT 1;

  IF v_all_null = 1 THEN
    IF v_existing_id IS NOT NULL THEN
      DELETE FROM sys_grid_column_setting WHERE ID = v_existing_id;
    END IF;
  ELSEIF v_existing_id IS NULL THEN
      TEMPLATE_ID, GRID_ID, FIELD_NAME, LABEL_TEXT, CAPTION,
      IS_VISIBLE, VISIBLE_INDEX, COLUMN_WIDTH, IS_FIXED, FIXED_POSITION,
      ALLOW_HIDING, SORT_ORDER, SORT_INDEX,
      CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT, ISDEL
    )
    VALUES
    (
      v_template_id, v_grid_id, v_field_name, p_LABEL_TEXT, p_CAPTION,
      p_IS_VISIBLE, p_VISIBLE_INDEX, p_COLUMN_WIDTH, p_IS_FIXED,
      IF(p_FIXED_POSITION IS NULL, NULL, v_fixed_position),
      p_ALLOW_HIDING,
      IF(p_SORT_ORDER IS NULL, NULL, v_sort_order),
      p_SORT_INDEX,
      COALESCE(v_update_by, ''), NOW(), COALESCE(v_update_by, ''), NOW(), '0'
    );
  ELSE
    UPDATE sys_grid_column_setting
    SET
      LABEL_TEXT = p_LABEL_TEXT,
      CAPTION = p_CAPTION,
      IS_VISIBLE = p_IS_VISIBLE,
      VISIBLE_INDEX = p_VISIBLE_INDEX,
      COLUMN_WIDTH = p_COLUMN_WIDTH,
      IS_FIXED = p_IS_FIXED,
      FIXED_POSITION = IF(p_FIXED_POSITION IS NULL, NULL, v_fixed_position),
      ALLOW_HIDING = p_ALLOW_HIDING,
      SORT_ORDER = IF(p_SORT_ORDER IS NULL, NULL, v_sort_order),
      SORT_INDEX = p_SORT_INDEX,
      UPDATE_BY = COALESCE(v_update_by, UPDATE_BY),
      UPDATE_AT = NOW(),
      ISDEL = '0'
    WHERE ID = v_existing_id;
  END IF;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.setsys_grid_column_visible
