      AND GRID_ID = p_GRID_ID
      AND COLUMN_NAME = p_COLUMN_NAME
      AND IFNULL(ISDEL, '0') <> '1';

    SELECT ROW_COUNT() AS AFFECTED_ROWS;
END//
