-- Dumping structure for procedure am_web_manager.setsys_grid_template
DROP PROCEDURE IF EXISTS `setsys_grid_template`;
DELIMITER //
CREATE PROCEDURE `setsys_grid_template`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USER_ID VARCHAR(50),
  IN p_GRID_ID VARCHAR(100),
  IN p_TEMPLATE_ID BIGINT,
  IN p_TEMPLATE_NAME VARCHAR(100),
  IN p_IS_DEFAULT_TEMPLATE CHAR(1),
  IN p_UPDATE_BY VARCHAR(50)
)
BEGIN
  DECLARE v_company_cd VARCHAR(20);
  DECLARE v_user_id VARCHAR(50);
  DECLARE v_grid_id VARCHAR(100);
  DECLARE v_template_id BIGINT;
  DECLARE v_template_name VARCHAR(100);
  DECLARE v_is_default CHAR(1);
  DECLARE v_update_by VARCHAR(50);

  SET v_company_cd = TRIM(COALESCE(p_COMPANY_CD, ''));
  SET v_user_id = TRIM(COALESCE(p_USER_ID, ''));
  SET v_grid_id = TRIM(COALESCE(p_GRID_ID, ''));
  SET v_template_id = COALESCE(p_TEMPLATE_ID, 0);
  SET v_template_name = NULLIF(TRIM(COALESCE(p_TEMPLATE_NAME, '')), '');
  SET v_is_default = IF(COALESCE(p_IS_DEFAULT_TEMPLATE, '0') = '1', '1', '0');
  SET v_update_by = NULLIF(TRIM(COALESCE(p_UPDATE_BY, '')), '');

  IF v_update_by IS NULL THEN
    SET v_update_by = v_user_id;
  END IF;

  IF v_company_cd = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF v_user_id = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'USER_ID is required';
  END IF;

  IF v_grid_id = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GRID_ID is required';
  END IF;

  IF v_template_id > 0 THEN
    UPDATE sys_grid_template
    SET
      TEMPLATE_NAME = COALESCE(v_template_name, TEMPLATE_NAME),
      IS_DEFAULT_TEMPLATE = IF(v_is_default = '1', '1', IS_DEFAULT_TEMPLATE),
      UPDATE_BY = v_update_by,
      UPDATE_AT = NOW(),
      ISDEL = '0'
    WHERE TEMPLATE_ID = v_template_id
      AND COMPANY_CD = v_company_cd
      AND USER_ID = v_user_id
      AND GRID_ID = v_grid_id;

    IF ROW_COUNT() = 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TEMPLATE_ID not found';
    END IF;
  ELSE
    SET v_template_id = NULL;

    SELECT TEMPLATE_ID
      INTO v_template_id
    FROM sys_grid_template
    WHERE COMPANY_CD = v_company_cd
      AND USER_ID = v_user_id
      AND GRID_ID = v_grid_id
      AND ISDEL = '0'
      AND (
        (v_template_name IS NOT NULL AND TEMPLATE_NAME = v_template_name)
        OR (v_template_name IS NULL AND IS_DEFAULT_TEMPLATE = '1')
      )
    ORDER BY IS_DEFAULT_TEMPLATE DESC, TEMPLATE_ID
    LIMIT 1;

    IF v_template_id IS NULL THEN
      IF v_template_name IS NULL THEN
        SET v_template_name = 'Máº·c Ä‘á»‹nh';
      END IF;

      IF NOT EXISTS (
        SELECT 1
        FROM sys_grid_template
        WHERE COMPANY_CD = v_company_cd
          AND USER_ID = v_user_id
          AND GRID_ID = v_grid_id
          AND ISDEL = '0'
          AND IS_DEFAULT_TEMPLATE = '1'
      ) THEN
        SET v_is_default = '1';
      END IF;

        COMPANY_CD, USER_ID, GRID_ID, TEMPLATE_NAME, IS_DEFAULT_TEMPLATE,
        CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT, ISDEL
      )
      VALUES
      (
        v_company_cd, v_user_id, v_grid_id, v_template_name, v_is_default,
        v_update_by, NOW(), v_update_by, NOW(), '0'
      );

      SET v_template_id = LAST_INSERT_ID();
    ELSEIF v_template_name IS NOT NULL THEN
      UPDATE sys_grid_template
      SET
        TEMPLATE_NAME = v_template_name,
        UPDATE_BY = v_update_by,
        UPDATE_AT = NOW()
      WHERE TEMPLATE_ID = v_template_id;
    END IF;
  END IF;

  IF v_is_default = '1' THEN
    UPDATE sys_grid_template
    SET
      IS_DEFAULT_TEMPLATE = IF(TEMPLATE_ID = v_template_id, '1', '0'),
      UPDATE_BY = v_update_by,
      UPDATE_AT = NOW()
    WHERE COMPANY_CD = v_company_cd
      AND USER_ID = v_user_id
      AND GRID_ID = v_grid_id
      AND ISDEL = '0';
  END IF;

  SELECT
    t.TEMPLATE_ID,
    t.COMPANY_CD,
    t.USER_ID,
    t.GRID_ID,
    t.TEMPLATE_NAME,
    t.IS_DEFAULT_TEMPLATE,
    t.CREATE_BY,
    t.CREATE_AT,
    t.UPDATE_BY,
    t.UPDATE_AT,
    t.ISDEL
  FROM sys_grid_template t
  WHERE t.TEMPLATE_ID = v_template_id;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.setUserInfo
DROP PROCEDURE IF EXISTS `setUserInfo`;
DELIMITER //
CREATE PROCEDURE `setUserInfo`(
  IN p_USER_PK_ID BIGINT(20),
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USERID VARCHAR(50),
  IN p_PASSWD VARCHAR(255),
  IN p_USERNM VARCHAR(255),
  IN p_EMAIL VARCHAR(255),
  IN p_MOBILE_NO VARCHAR(50),
  IN p_AVATAR_URL VARCHAR(500),
  IN p_USERLV INT,
  IN p_ROLE_CODE VARCHAR(50),
  IN p_DEFAULT_YN CHAR(1),
  IN p_IS_ACTIVE CHAR(1),
  IN p_ISDEL CHAR(1),
  IN p_MODIFIER_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_user_pk_id BIGINT(20);
  DECLARE v_modifier VARCHAR(50);
  DECLARE v_userlv INT;
  DECLARE v_role_code VARCHAR(50);

  SET v_user_pk_id = NULLIF(IFNULL(p_USER_PK_ID, 0), 0);
  SET v_modifier = COALESCE(NULLIF(TRIM(p_MODIFIER_USERID), ''), '0');
  IF p_USERLV IS NOT NULL AND p_USERLV NOT IN (10, 20, 30, 40) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'USERLV: 10 ADMIN, 20 MANAGER, 30 STAFF, 40 VIEW';
  END IF;
  SET v_userlv = COALESCE(p_USERLV, (
    SELECT UC.USERLV FROM user_company UC
    WHERE UC.USER_PK_ID=v_user_pk_id AND UC.COMPANY_CD=TRIM(p_COMPANY_CD)
  ), 40);
  IF v_userlv NOT IN (10, 20, 30, 40) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Existing USERLV is invalid; normalize user_company before updating';
  END IF;
  SET v_role_code = CASE v_userlv
    WHEN 10 THEN 'ADMIN'
    WHEN 20 THEN 'MANAGER'
    WHEN 30 THEN 'STAFF'
    WHEN 40 THEN 'VIEW'
  END;
  IF NULLIF(TRIM(p_ROLE_CODE), '') IS NOT NULL AND TRIM(p_ROLE_CODE)<>v_role_code THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ROLE_CODE does not match USERLV';
  END IF;

  IF v_user_pk_id IS NULL THEN
      PASSWD,
      USERNM,
      EMAIL,
      MOBILE_NO,
      AVATAR_URL,
      IS_ACTIVE,
      ISDEL,
      UPDATE_BY,
      CREATE_BY,
      CREATE_AT,
      UPDATE_AT
    )
    VALUES
    (
      p_PASSWD,
      TRIM(COALESCE(p_USERNM, '')),
      NULLIF(TRIM(COALESCE(p_EMAIL, '')), ''),
      NULLIF(TRIM(COALESCE(p_MOBILE_NO, '')), ''),
      NULLIF(TRIM(COALESCE(p_AVATAR_URL, '')), ''),
      COALESCE(p_IS_ACTIVE, '1'),
      COALESCE(p_ISDEL, '0'),
      v_modifier,
      v_modifier,
      NOW(),
      NOW()
    );

    SET v_user_pk_id = LAST_INSERT_ID();
  ELSE
    UPDATE user_info
    SET
      PASSWD = CASE WHEN p_PASSWD IS NULL OR p_PASSWD = '' THEN PASSWD ELSE p_PASSWD END,
      USERNM = TRIM(COALESCE(p_USERNM, USERNM)),
      EMAIL = NULLIF(TRIM(COALESCE(p_EMAIL, '')), ''),
      MOBILE_NO = NULLIF(TRIM(COALESCE(p_MOBILE_NO, '')), ''),
      AVATAR_URL = NULLIF(TRIM(COALESCE(p_AVATAR_URL, '')), ''),
      IS_ACTIVE = COALESCE(p_IS_ACTIVE, IS_ACTIVE, '1'),
      ISDEL = COALESCE(p_ISDEL, ISDEL, '0'),
      UPDATE_BY = v_modifier,
      UPDATE_AT = NOW()
    WHERE USER_PK_ID = v_user_pk_id;
  END IF;

  IF COALESCE(p_DEFAULT_YN, '0') = '1' THEN
    UPDATE user_company
    SET DEFAULT_YN = '0',
        UPDATE_BY = v_modifier,
        UPDATE_AT = NOW()
    WHERE USER_PK_ID = v_user_pk_id
      AND COMPANY_CD <> TRIM(p_COMPANY_CD);
  END IF;

    USER_PK_ID,
    COMPANY_CD,
    USERID,
    USERLV,
    ROLE_CODE,
    DEFAULT_YN,
    IS_ACTIVE,
    ISDEL,
    UPDATE_BY,
    CREATE_BY,
    CREATE_AT,
    UPDATE_AT
  )
  VALUES
  (
    v_user_pk_id,
    TRIM(p_COMPANY_CD),
    TRIM(p_USERID),
    v_userlv,
    v_role_code,
    COALESCE(p_DEFAULT_YN, '0'),
    COALESCE(p_IS_ACTIVE, '1'),
    COALESCE(p_ISDEL, '0'),
    v_modifier,
    v_modifier,
    NOW(),
    NOW()
  )
  ON DUPLICATE KEY UPDATE
    USERID = VALUES(USERID),
    USERLV = VALUES(USERLV),
    ROLE_CODE = VALUES(ROLE_CODE),
    DEFAULT_YN = VALUES(DEFAULT_YN),
    IS_ACTIVE = VALUES(IS_ACTIVE),
    ISDEL = VALUES(ISDEL),
    UPDATE_BY = VALUES(UPDATE_BY),
    UPDATE_AT = NOW();

  -- New users inherit canonical defaults. Saving a profile must not create permission overrides.
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.setUserProfile
DROP PROCEDURE IF EXISTS `setUserProfile`;
DELIMITER //
CREATE PROCEDURE `setUserProfile`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USERID VARCHAR(50),
  IN p_USERNM VARCHAR(255),
  IN p_EMPLOYEE_CD VARCHAR(50),
  IN p_EMPLOYEE_NM VARCHAR(255),
  IN p_EMPLOYEE_NM_ENG VARCHAR(255),
  IN p_DEPARTMENT_ID BIGINT(20),
  IN p_DEPARTMENT_CD VARCHAR(50),
  IN p_POSITION_ID BIGINT(20),
  IN p_POSITION_CD VARCHAR(50),
  IN p_BRANCH_ID BIGINT(20),
  IN p_BRANCH_CD VARCHAR(50),
  IN p_EMAIL VARCHAR(255),
  IN p_MOBILE_NO VARCHAR(50),
  IN p_TEL_NO VARCHAR(50),
  IN p_ADDRESS VARCHAR(500),
  IN p_BIRTHDAY DATE,
  IN p_GENDER CHAR(1),
  IN p_AVATAR_URL VARCHAR(500),
  IN p_SIGN_IMAGE_URL VARCHAR(500),
  IN p_NOTE VARCHAR(1000),
  IN p_MODIFIER_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_user_pk_id BIGINT(20);
  DECLARE v_modifier VARCHAR(50);

  SET v_modifier = COALESCE(NULLIF(TRIM(p_MODIFIER_USERID), ''), '0');

  SELECT UC.USER_PK_ID
    INTO v_user_pk_id
  FROM user_company UC
  INNER JOIN user_info UI
    ON UI.USER_PK_ID = UC.USER_PK_ID
   AND IFNULL(UI.ISDEL, '0') <> '1'
  WHERE UC.COMPANY_CD = TRIM(p_COMPANY_CD)
    AND UC.USERID = TRIM(COALESCE(p_USERID, ''))
    AND IFNULL(UC.ISDEL, '0') <> '1'
  LIMIT 1;

  IF v_user_pk_id IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'User not found';
  END IF;

  UPDATE user_info
  SET
    USERNM = TRIM(COALESCE(p_USERNM, USERNM)),
    EMAIL = NULLIF(TRIM(COALESCE(p_EMAIL, '')), ''),
    MOBILE_NO = NULLIF(TRIM(COALESCE(p_MOBILE_NO, '')), ''),
    TEL_NO = NULLIF(TRIM(COALESCE(p_TEL_NO, '')), ''),
    ADDRESS = NULLIF(TRIM(COALESCE(p_ADDRESS, '')), ''),
    BIRTHDAY = p_BIRTHDAY,
    GENDER = NULLIF(TRIM(COALESCE(p_GENDER, '')), ''),
    AVATAR_URL = NULLIF(TRIM(COALESCE(p_AVATAR_URL, '')), ''),
    NOTE = NULLIF(TRIM(COALESCE(p_NOTE, '')), ''),
    UPDATE_BY = v_modifier,
    UPDATE_AT = NOW()
  WHERE USER_PK_ID = v_user_pk_id;

  UPDATE user_company
  SET
    EMPLOYEE_CD = NULLIF(TRIM(COALESCE(p_EMPLOYEE_CD, '')), ''),
    EMPLOYEE_NM = NULLIF(TRIM(COALESCE(p_EMPLOYEE_NM, '')), ''),
    EMPLOYEE_NM_ENG = NULLIF(TRIM(COALESCE(p_EMPLOYEE_NM_ENG, '')), ''),
    DEPARTMENT_ID = p_DEPARTMENT_ID,
    DEPARTMENT_CD = NULLIF(TRIM(COALESCE(p_DEPARTMENT_CD, '')), ''),
    POSITION_ID = p_POSITION_ID,
    POSITION_CD = NULLIF(TRIM(COALESCE(p_POSITION_CD, '')), ''),
    BRANCH_ID = p_BRANCH_ID,
    BRANCH_CD = NULLIF(TRIM(COALESCE(p_BRANCH_CD, '')), ''),
    SIGN_IMAGE_URL = NULLIF(TRIM(COALESCE(p_SIGN_IMAGE_URL, '')), ''),
    NOTE = NULLIF(TRIM(COALESCE(p_NOTE, '')), ''),
    UPDATE_BY = v_modifier,
    UPDATE_AT = NOW()
  WHERE USER_PK_ID = v_user_pk_id
    AND COMPANY_CD = TRIM(p_COMPANY_CD);
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.sp_get_menu_by_company
DROP PROCEDURE IF EXISTS `sp_get_menu_by_company`;
DELIMITER //
CREATE PROCEDURE `sp_get_menu_by_company`(
    IN p_COMPANY_CD VARCHAR(50)
)
BEGIN
    -- ALL preserves legacy rows while PRODUCT_SCOPE is being classified.
    -- A missing company must never inherit ALL. Empty company is internal default lookup.
    WITH RECURSIVE eligible AS (
    SELECT
        m.MENU_ID,
        m.MENU_CODE,
        m.MENU_NAME,
        NULLIF(TRIM(m.LABEL_TEXT), '') AS LABEL_TEXT,
        COALESCE(NULLIF(TRIM(m.CAPTION), ''), m.MENU_NAME) AS CAPTION,
        m.PARENT_ID,
        m.ROUTE_PATH,
        m.ICON,
        m.SORT_ORDER,
        m.IS_ACTIVE,
        CASE WHEN company_setting.ID IS NOT NULL
            THEN company_setting.IS_VISIBLE ELSE default_setting.IS_VISIBLE END AS IS_VISIBLE,
        CASE WHEN company_setting.ID IS NOT NULL
            THEN company_setting.IS_DISABLED ELSE default_setting.IS_DISABLED END AS IS_DISABLED
    FROM sys_menu m
    LEFT JOIN company_info company
        ON company.COMPANY_CD = p_COMPANY_CD
    LEFT JOIN sys_menu_company company_setting
        ON company_setting.MENU_ID = m.MENU_ID
       AND company_setting.COMPANY_CD = p_COMPANY_CD
    LEFT JOIN sys_menu_company default_setting
        ON default_setting.MENU_ID = m.MENU_ID
       AND default_setting.COMPANY_CD = ''
    -- Choose by row existence: a hidden/NULL company setting must not inherit default values.
    WHERE p_COMPANY_CD IS NOT NULL
      AND (
          p_COMPANY_CD = ''
          OR company.MENU_MODE = 'ALL'
          OR (company.MENU_MODE IN ('INVOICE', 'AMNOTE')
              AND (m.PRODUCT_SCOPE = 'COMMON' OR m.PRODUCT_SCOPE = company.MENU_MODE))
      )
      AND (company_setting.ID IS NOT NULL OR default_setting.ID IS NOT NULL)
      AND m.IS_ACTIVE = 1
      AND CASE WHEN company_setting.ID IS NOT NULL
          THEN company_setting.IS_VISIBLE ELSE default_setting.IS_VISIBLE END = 1
    ), reachable AS (
        SELECT root.* FROM eligible root WHERE root.PARENT_ID IS NULL
        UNION ALL
        SELECT child.*
        FROM eligible child
        INNER JOIN reachable parent ON child.PARENT_ID = parent.MENU_ID
    )
    -- Do not promote orphan children when an ancestor is hidden or outside the product.
    SELECT m.* FROM reachable m
    ORDER BY
        IFNULL(m.PARENT_ID, m.MENU_ID),
        m.SORT_ORDER;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.sp_period_lock_current_status_get
DROP PROCEDURE IF EXISTS `sp_period_lock_current_status_get`;
DELIMITER //
CREATE PROCEDURE `sp_period_lock_current_status_get`(
    IN p_COMPANY_CD VARCHAR(20)
)
BEGIN
    /*
      Mục đích:
      - Lấy kỳ đã khóa hiện tại của công ty.
      - Không phụ thuộc năm đang xem trên combobox.
      - Dùng nội bộ cho API overview.
    */

    DECLARE v_CURRENT_LOCKED_YM CHAR(6);

    SELECT MAX(PERIOD_YM)
    INTO v_CURRENT_LOCKED_YM
    FROM acc_period_lock_month
    WHERE COMPANY_CD = p_COMPANY_CD
      AND STATUS = 'LOCKED'
      AND IFNULL(ISDEL, '0') = '0';

    SELECT
        IFNULL(v_CURRENT_LOCKED_YM, '') AS CurrentLockedPeriodYm,
        CASE
            WHEN v_CURRENT_LOCKED_YM IS NULL OR v_CURRENT_LOCKED_YM = ''
            THEN 'Chưa khóa kỳ nào'
            ELSE CONCAT(SUBSTRING(v_CURRENT_LOCKED_YM, 5, 2), '/', SUBSTRING(v_CURRENT_LOCKED_YM, 1, 4))
        END AS CurrentLockedPeriodLabel;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.sp_period_lock_get_actual_from_period
DROP PROCEDURE IF EXISTS `sp_period_lock_get_actual_from_period`;
DELIMITER //
CREATE PROCEDURE `sp_period_lock_get_actual_from_period`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FISCAL_START_YEAR INT,
    IN p_TO_PERIOD_YM CHAR(6)
)
BEGIN
    /*
      Mục đích:
      - Tìm kỳ bắt đầu khóa sổ thực tế.
      - Nếu có kỳ LOCKED gần nhất <= kỳ đích thì lấy tháng kế tiếp.
      - Nếu chưa có kỳ LOCKED nào thì lấy tháng 01 của năm đầu kỳ.
    */

    DECLARE v_LAST_LOCKED_YM CHAR(6);
    DECLARE v_FROM_PERIOD_YM CHAR(6);
    DECLARE v_LAST_DATE DATE;

    SELECT MAX(PERIOD_YM)
    INTO v_LAST_LOCKED_YM
    FROM acc_period_lock_month
    WHERE COMPANY_CD = p_COMPANY_CD
      AND STATUS = 'LOCKED'
      AND IFNULL(ISDEL, '0') = '0'
      AND PERIOD_YM <= p_TO_PERIOD_YM;

    IF v_LAST_LOCKED_YM IS NULL OR v_LAST_LOCKED_YM = '' THEN
        SET v_FROM_PERIOD_YM = CONCAT(p_FISCAL_START_YEAR, '01');
    ELSE
        SET v_LAST_DATE = STR_TO_DATE(CONCAT(v_LAST_LOCKED_YM, '01'), '%Y%m%d');
        SET v_FROM_PERIOD_YM = DATE_FORMAT(DATE_ADD(v_LAST_DATE, INTERVAL 1 MONTH), '%Y%m');
    END IF;

    SELECT v_FROM_PERIOD_YM AS FromPeriodYm;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.sp_period_lock_job_get_progress
DROP PROCEDURE IF EXISTS `sp_period_lock_job_get_progress`;
DELIMITER //
CREATE PROCEDURE `sp_period_lock_job_get_progress`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_JOB_ID VARCHAR(100)
)
BEGIN
    SELECT
        JOB_ID AS JobId,
        PERCENT_VALUE AS Percent,
        TOTAL_STEPS AS TotalSteps,
        DONE_STEPS AS DoneSteps,
        IFNULL(CURRENT_PERIOD_YM, '') AS CurrentPeriodYm,
        CASE
            WHEN CURRENT_PERIOD_YM IS NULL OR CURRENT_PERIOD_YM = ''
            THEN '-'
            ELSE CONCAT(SUBSTRING(CURRENT_PERIOD_YM, 5, 2), '/', SUBSTRING(CURRENT_PERIOD_YM, 1, 4))
        END AS CurrentPeriodLabel,
        IFNULL(CURRENT_STEP_CODE, '') AS CurrentStepCode,
        IFNULL(CURRENT_STEP_NAME, '-') AS CurrentStepName,
        IFNULL(MESSAGE, '') AS Message,
        STATUS AS Status
    FROM acc_period_lock_job
    WHERE COMPANY_CD = p_COMPANY_CD
      AND JOB_ID = p_JOB_ID
    LIMIT 1;
END//
DELIMITER ;

