-- Dumping structure for procedure am_web_manager.sys_decimal_field_setting_get
DROP PROCEDURE IF EXISTS `sys_decimal_field_setting_get`;
DELIMITER //
CREATE PROCEDURE `sys_decimal_field_setting_get`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_FIELD_NAME` VARCHAR(100),
    IN `p_SETTING_TYPE` VARCHAR(30)
)
BEGIN
    SELECT
        IFNULL(cs.`ID`, IFNULL(ds.`ID`, 0)) AS `ID`,
        IFNULL(cs.`COMPANY_CD`, IFNULL(ds.`COMPANY_CD`, '')) AS `COMPANY_CD`,
        fm.`FIELD_NAME`,
        fm.`LABEL_TEXT`,
        fm.`CAPTION`,
        fm.`SETTING_TYPE`,
        IFNULL(
            cs.`DECIMAL_PLACES`,
            IFNULL(
                ds.`DECIMAL_PLACES`,
                CASE fm.`SETTING_TYPE`
                    WHEN 'QUANTITY' THEN 3
                    WHEN 'EXCHANGE_RATE' THEN 6
                    ELSE 2
                END
            )
        ) AS `DECIMAL_PLACES`,
        IFNULL(cs.`ROUNDING_MODE`, IFNULL(ds.`ROUNDING_MODE`, 'ROUND')) AS `ROUNDING_MODE`,
        IFNULL(cs.`USE_THOUSAND_SEPARATOR`, IFNULL(ds.`USE_THOUSAND_SEPARATOR`, '1')) AS `USE_THOUSAND_SEPARATOR`,
        IFNULL(cs.`IS_ACTIVE`, IFNULL(ds.`IS_ACTIVE`, fm.`IS_ACTIVE`)) AS `IS_ACTIVE`,
        IFNULL(NULLIF(cs.`NOTE`, ''), IFNULL(NULLIF(ds.`NOTE`, ''), fm.`NOTE`)) AS `NOTE`,
        '0' AS `ISDEL`,
        IFNULL(cs.`CREATE_AT`, IFNULL(ds.`CREATE_AT`, fm.`CREATE_AT`)) AS `CREATE_AT`,
        IFNULL(cs.`CREATE_BY`, IFNULL(ds.`CREATE_BY`, fm.`CREATE_BY`)) AS `CREATE_BY`,
        IFNULL(cs.`UPDATE_AT`, IFNULL(ds.`UPDATE_AT`, fm.`UPDATE_AT`)) AS `UPDATE_AT`,
        IFNULL(cs.`UPDATE_BY`, IFNULL(ds.`UPDATE_BY`, fm.`UPDATE_BY`)) AS `UPDATE_BY`,
        CASE
            WHEN cs.`ID` IS NOT NULL THEN 'COMPANY'
            WHEN ds.`ID` IS NOT NULL THEN 'SYSTEM'
            ELSE 'FIELD_MAP'
        END AS `APPLY_SCOPE`
    FROM `sys_decimal_field_map` fm
    LEFT JOIN `sys_decimal_setting` cs
        ON cs.`ISDEL` = '0'
       AND cs.`COMPANY_CD` = p_COMPANY_CD
       AND cs.`SETTING_TYPE` = fm.`SETTING_TYPE`
    LEFT JOIN `sys_decimal_setting` ds
        ON ds.`ISDEL` = '0'
       AND ds.`COMPANY_CD` = ''
       AND ds.`SETTING_TYPE` = fm.`SETTING_TYPE`
    WHERE fm.`ISDEL` = '0'
      AND fm.`IS_ACTIVE` = '1'
      AND (p_FIELD_NAME IS NULL OR p_FIELD_NAME = '' OR fm.`FIELD_NAME` = p_FIELD_NAME)
      AND (p_SETTING_TYPE IS NULL OR p_SETTING_TYPE = '' OR fm.`SETTING_TYPE` = p_SETTING_TYPE)
    ORDER BY FIELD(fm.`SETTING_TYPE`, 'QUANTITY', 'UNIT_PRICE', 'AMOUNT', 'FC_AMOUNT', 'FC_UNIT_PRICE', 'EXCHANGE_RATE', 'PERCENT'), fm.`FIELD_NAME`;
END//
DELIMITER ;

