-- Dumping structure for procedure am_web_manager.sys_decimal_setting_get
DROP PROCEDURE IF EXISTS `sys_decimal_setting_get`;
DELIMITER //
CREATE PROCEDURE `sys_decimal_setting_get`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_SETTING_TYPE` VARCHAR(30)
)
BEGIN
    SELECT
        s.`ID`,
        s.`COMPANY_CD`,
        s.`SETTING_TYPE`,
        s.`DECIMAL_PLACES`,
        s.`ROUNDING_MODE`,
        s.`USE_THOUSAND_SEPARATOR`,
        s.`IS_ACTIVE`,
        s.`NOTE`,
        s.`ISDEL`,
        s.`CREATE_AT`,
        s.`CREATE_BY`,
        s.`UPDATE_AT`,
        s.`UPDATE_BY`,
        CASE WHEN s.`COMPANY_CD` = '' THEN 'SYSTEM' ELSE 'COMPANY' END AS `APPLY_SCOPE`
    FROM `sys_decimal_setting` s
    WHERE s.`ISDEL` = '0'
      AND (s.`COMPANY_CD` = p_COMPANY_CD OR s.`COMPANY_CD` = '')
      AND (p_SETTING_TYPE IS NULL OR p_SETTING_TYPE = '' OR s.`SETTING_TYPE` = p_SETTING_TYPE)
      AND NOT EXISTS (
          SELECT 1
          FROM `sys_decimal_setting` c
          WHERE c.`ISDEL` = '0'
            AND p_COMPANY_CD <> ''
            AND c.`COMPANY_CD` = p_COMPANY_CD
            AND c.`SETTING_TYPE` = s.`SETTING_TYPE`
            AND s.`COMPANY_CD` = ''
      )
    ORDER BY FIELD(s.`SETTING_TYPE`, 'QUANTITY', 'UNIT_PRICE', 'AMOUNT', 'FC_AMOUNT', 'FC_UNIT_PRICE', 'EXCHANGE_RATE', 'PERCENT'), s.`SETTING_TYPE`;
END//
DELIMITER ;

-- Dumping structure for procedure am_web_manager.sys_decimal_setting_set
DROP PROCEDURE IF EXISTS `sys_decimal_setting_set`;
DELIMITER //
CREATE PROCEDURE `sys_decimal_setting_set`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_SETTING_TYPE` VARCHAR(30),
    IN `p_DECIMAL_PLACES` INT,
    IN `p_ROUNDING_MODE` VARCHAR(20),
    IN `p_USE_THOUSAND_SEPARATOR` CHAR(1),
    IN `p_IS_ACTIVE` CHAR(1),
    IN `p_NOTE` VARCHAR(500),
    IN `p_USER_ID` VARCHAR(50)
)
BEGIN
    ON DUPLICATE KEY UPDATE
        `DECIMAL_PLACES` = VALUES(`DECIMAL_PLACES`),
        `ROUNDING_MODE` = VALUES(`ROUNDING_MODE`),
        `USE_THOUSAND_SEPARATOR` = VALUES(`USE_THOUSAND_SEPARATOR`),
        `IS_ACTIVE` = VALUES(`IS_ACTIVE`),
        `NOTE` = VALUES(`NOTE`),
        `ISDEL` = '0',
        `UPDATE_BY` = VALUES(`UPDATE_BY`);

    SELECT
        s.`ID`,
        s.`COMPANY_CD`,
        s.`SETTING_TYPE`,
        s.`DECIMAL_PLACES`,
        s.`ROUNDING_MODE`,
        s.`USE_THOUSAND_SEPARATOR`,
        s.`IS_ACTIVE`,
        s.`NOTE`,
        s.`ISDEL`,
        s.`CREATE_AT`,
        s.`CREATE_BY`,
        s.`UPDATE_AT`,
        s.`UPDATE_BY`,
        'COMPANY' AS `APPLY_SCOPE`
    FROM `sys_decimal_setting` s
    WHERE s.`ISDEL` = '0'
      AND s.`COMPANY_CD` = p_COMPANY_CD
      AND s.`SETTING_TYPE` = p_SETTING_TYPE
    LIMIT 1;
END//
DELIMITER ;

