-- Dumping structure for procedure am_web_manager.sys_working_calendar_get
DROP PROCEDURE IF EXISTS `sys_working_calendar_get`;
DELIMITER //
CREATE PROCEDURE `sys_working_calendar_get`(
  IN p_FROM_DATE DATE,
  IN p_TO_DATE DATE
)
BEGIN
  IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Date range is required';
  END IF;

  IF p_FROM_DATE > p_TO_DATE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FROM_DATE must be earlier than or equal to TO_DATE';
  END IF;

  SELECT
    CALENDAR_DATE,
    IS_WORKING_DAY,
    NOTE
  FROM sys_working_calendar
  WHERE CALENDAR_DATE BETWEEN p_FROM_DATE AND p_TO_DATE
  ORDER BY CALENDAR_DATE;
END//
DELIMITER ;

